window.__HRC_SHARD({"shard":"dprk-accountability-project-ohchr","builtAt":"2026-07-19T18:52:42+00:00","documents":[{"rec_id":"reclB9o2qRUijlc2L","doc_id":"DPRK accountability project (OHCHR) - Official report - 22.01.2007","symbol":"A/HRC/4/60","title":"Report of the United Nations High Commissioner for Human Rights on the human rights situation in the Democratic People’s Republic of Korea","type":"Official report","date":"2007-01-22","year":2007,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":5,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 22-01-2007 - Official report - A_HRC_4_60 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"receZvbHCHXSESWDt","doc_id":"DPRK accountability project (OHCHR) - Official report - 22.02.2008","symbol":"A/HRC/7/47","title":"Report of the United Nations High Commissioner for Human Rights on the human rights situation in the Democratic People’s Republic of Korea","type":"Official report","date":"2008-02-22","year":2008,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":7,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 22-02-2008 - Official report - A_HRC_7_47 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"reciqsEXvCzDo7u03","doc_id":"DPRK accountability project (OHCHR) - Official report - 01.02.2016","symbol":"A/HRC/31/38","title":"Role and achievements of the Office of the United Nations High Commissioner for Human Rights with regard to the situation of human rights in the Democratic People’s Republic of Korea","type":"Official report","date":"2016-02-01","year":2016,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":64,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 01-02-2016 - Official report - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recYzXZ0Byq8lrIa3","doc_id":"DPRK accountability project (OHCHR) - Official report - 24.02.2017","symbol":"A/HRC/34/66/Add.1","title":"Report of the group of independent experts on accountability","type":"Official report","date":"2017-02-24","year":2017,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":88,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 24-02-2017 - Official report - A_HRC_34_66_Add.1 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"rec4xPAP8TEWkUXnU","doc_id":"DPRK accountability project (OHCHR) - Official report - 07.03.2019","symbol":"A/HRC/40/36","title":"Promoting accountability in the Democratic People’s Republic of Korea","type":"Official report","date":"2019-03-07","year":2019,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":60,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 07-03-2019 - Official report - A_HRC_40_36 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"reclgNaRVziEBKGmt","doc_id":"DPRK accountability project (OHCHR) - Official report - 11.01.2021","symbol":"A/HRC/46/52","title":"Promoting accountability in the Democratic People’s Republic of Korea","type":"Official report","date":"2021-01-11","year":2021,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":76,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 11-01-2021 - Official report - A_HRC_46_52 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recNdg7R5ytkg5iSC","doc_id":"DPRK accountability project (OHCHR) - Official report - 18.01.2023","symbol":"A/HRC/52/64","title":"Promoting accountability in the Democratic People’s Republic of Korea","type":"Official report","date":"2023-01-18","year":2023,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":60,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 18-01-2023 - Official report - A_HRC_52_64 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recBme0CBp75YznOj","doc_id":"DPRK accountability project (OHCHR) - Official report - 14.01.2025","symbol":"A/HRC/58/61","title":"Promoting accountability in the Democratic People’s Republic of Korea","type":"Official report","date":"2025-01-14","year":2025,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":64,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 14-01-2025 - Official report - A_HRC_58_61 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recvHCxw7qUn8ck5o","doc_id":"DPRK accountability project (OHCHR) - Official report - 04.09.2025","symbol":"A/HRC/60/58","title":"Situation of human rights in the Democratic People’s Republic of Korea","type":"Official report","date":"2025-09-04","year":2025,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":71,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 04-09-2025 - Official report - A_HRC_60_58 - EN.md","extractor":"pdftotext -layout"},{"rec_id":"recEDz6CHpXPbGwLs","doc_id":"DPRK accountability project (OHCHR) - Official report - 16.02.2026","symbol":"A/HRC/61/55","title":"Report of the United Nations High Commissioner for Human Rights on promoting accountability and supporting justice in the Democratic People’s Republic of Korea","type":"Official report","date":"2026-02-16","year":2026,"bodies":["DPRK accountability project (OHCHR)"],"paragraphCount":78,"unnumbered":false,"gaps":[],"source_md":"HUMAN RIGHTS COUNCIL MECHANISMS/2. Official Reports/DPRK accountability project (OHCHR) - 16-02-2026 - Official report - A_HRC_61_55 - EN.md","extractor":"pdftotext -layout"}],"paragraphs":[{"id":"a-hrc-4-60-p0001","rec_id":"reclB9o2qRUijlc2L","symbol":"A/HRC/4/60","n":"1","seq":0,"section":null,"text":"This note has been prepared further to Human Rights Council decision 2/102 requesting\nthe United Nations High Commissioner for Human Rights to continue with the fulfilment of her\nactivities, in accordance with all previous decisions adopted by the Commission on Human\nRights and to update the relevant reports and studies. In paragraph 9 of its resolution 2005/11\nthe Commission on Human Rights requested the High Commissioner to continue her efforts to\nengage in a comprehensive dialogue with the authorities of the Democratic People's Republic of\nKorea with a view to establishing technical cooperation programmes in the field of human rights\nand to submit her findings and recommendations to the Commission."},{"id":"a-hrc-4-60-p0002","rec_id":"reclB9o2qRUijlc2L","symbol":"A/HRC/4/60","n":"2","seq":1,"section":null,"text":"In line with standard policy and practice developed pursuant to General Assembly\nresolution 926 (X) of 14 December 1955, which established the United Nations programme of\nadvisory services and technical cooperation in the field of human rights, various forms of\nassistance in the area of human rights are at the disposal of Member States upon their request."},{"id":"a-hrc-4-60-p0003","rec_id":"reclB9o2qRUijlc2L","symbol":"A/HRC/4/60","n":"3","seq":2,"section":null,"text":"It will be recalled that, with a view to exploring ways of initiating technical cooperation\nbetween the Office of the United Nations High Commissioner for Human Rights and the\nDemocratic People's Republic of Korea, the High Commissioner invited the Permanent\nRepresentative of the Democratic People's Republic of Korea to the United Nations Office at\nGeneva for a meeting. Upon receipt of the acceptance of the invitation by the Permanent\nRepresentative, a meeting was scheduled for 6 December 2006.\nGE.07-10350 (E) 290107\npage 2"},{"id":"a-hrc-4-60-p0004","rec_id":"reclB9o2qRUijlc2L","symbol":"A/HRC/4/60","n":"4","seq":3,"section":null,"text":"During the meeting, the High Commissioner raised the possibility of exploring ways of\nengaging in technical cooperation activities, and made several proposals for technical\ncooperation activities, such as activities in the area of human rights treaty implementation."},{"id":"a-hrc-4-60-p0005","rec_id":"reclB9o2qRUijlc2L","symbol":"A/HRC/4/60","n":"5","seq":4,"section":null,"text":"The Permanent Representative stated that his Government did not recognize the\nresolution adopted by the Commission on Human Rights on the situation of human rights\nin the Democratic People's Republic of Korea and was therefore unable to accept the\nHigh Commissioner's offer. The Permanent Representative nonetheless stated that he had\ntaken note of the High Commissioner's willingness to offer technical assistance. No further\nresponse has been received from the Government on this matter.\n-----"},{"id":"a-hrc-7-47-u0000","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":null,"seq":0,"section":null,"text":"UNITED                                    A\nNATIONS\nDistr.\nGeneral Assembly  GENERAL\nA/HRC/7/47\nHUMAN RIGHTS COUNCIL            22 February 2008\nSeventh session                 Original: ENGLISH\nAgenda item 2","unnumbered":true},{"id":"a-hrc-7-47-p0001","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":"1","seq":1,"section":null,"text":"The present note has been prepared further to Human Rights Council decision 2/102\nrequesting the United Nations High Commissioner for Human Rights to continue with the\nfulfilment of her activities, in accordance with all previous decisions adopted by the\nCommission on Human Rights and to update the relevant reports and studies. The Commission\non Human Rights, in paragraph 9 of its resolution 2005/11, requested the High Commissioner for\nHuman Rights to continue her efforts to engage in a comprehensive dialogue with the authorities\nof the Democratic People's Republic of Korea with a view to establishing technical cooperation\nprogrammes in the field of human rights and to submit her findings and recommendations to the\nCommission."},{"id":"a-hrc-7-47-p0002","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":"2","seq":2,"section":null,"text":"In line with standard policy and practice developed pursuant to General Assembly\nresolution 926 (X) of 14 December 1955, which established the United Nations programme of\nadvisory services and technical cooperation in the field of human rights, various forms of\nassistance in the area of human rights are at the disposal of Member States upon their request.\n* The present report was submitted late to reflect the most recent information.\nGE.08-10722 (E) 260208\npage 2"},{"id":"a-hrc-7-47-p0003","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":"3","seq":3,"section":null,"text":"With a view to exploring ways of initiating technical cooperation between the Office of the\nUnited Nations High Commissioner for Human Rights (OHCHR) and the Democratic People's\nRepublic of Korea, the High Commissioner invited the Permanent Representative of the\nDemocratic People's Republic of Korea to the United Nations Office at Geneva to meet and\nexplore avenues of future cooperation."},{"id":"a-hrc-7-47-p0004","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":"4","seq":4,"section":null,"text":"During the meeting held on 11 February 2008, the High Commissioner welcomed the\nrecent submission of the combined third and fourth periodic report of the Democratic People's\nRepublic of Korea to the Committee on the Rights of the Child (CRC/C/PRK/4) and encouraged\ncontinued activities in relation to reporting to the treaty bodies."},{"id":"a-hrc-7-47-p0005","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":"5","seq":5,"section":null,"text":"The High Commissioner proposed discussions on a future technical assistance programme\nthat could be offered to the Government of the Democratic People's Republic of Korea,\nparticularly in light of the forthcoming review of the Democratic People's Republic of Korea\nunder the Human Rights Council's Universal Periodic Review mechanism (scheduled to take\nplace in 2009). Such a programme could for example offer assistance in the areas of treaty body\nreporting and ratification of core human rights treaties. The High Commissioner suggested that\nan OHCHR assessment mission could visit the Democratic People's Republic of Korea with a\nview to exploring such possibilities with relevant officials on the ground."},{"id":"a-hrc-7-47-p0006","rec_id":"receZvbHCHXSESWDt","symbol":"A/HRC/7/47","n":"6","seq":6,"section":null,"text":"The Permanent Representative of the Democratic People's Republic of Korea reiterated\nthat his Government does not recognize the resolutions adopted by the Human Rights Council\nand the General Assembly on the situation of human rights in the Democratic People's Republic\nof Korea. The Government considers these resolutions as selective, politicized and reflecting\ndouble-standards. The Permanent Representative stated that his Government was therefore\nunable to accept the High Commissioner's offer. He nonetheless stated that he had taken note of\nthe High Commissioner's willingness to offer technical assistance and that his Government\nwould continue to respect its treaty obligations and cooperate with the treaty bodies. Since the\n11 February meeting, no further response has been received from the Government on this matter.\n-----"},{"id":"a-hrc-31-38-u0000","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":null,"seq":0,"section":null,"text":"United Nations                                                                                         A/HRC/31/38\nGeneral Assembly                                                             Distr.: General\n1 February 2016","unnumbered":true},{"id":"a-hrc-31-38-u0001","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":null,"seq":1,"section":null,"text":"Human Rights Council\nThirty-first session\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-31-38-u0002","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":null,"seq":2,"section":null,"text":"Summary\nThe present report, submitted pursuant to Human Rights Council resolution 28/22,\nprovides updated information about the situation of human rights in the Democratic\nPeople’s Republic of Korea and the activities of the Office of the United Nations High\nCommissioner for Human Rights in Seoul between 1 April and 31 December 2015.","unnumbered":true},{"id":"a-hrc-31-38-p0001","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"1","seq":3,"section":"I. Introduction","text":"On 28 March 2014, the Human Rights Council adopted resolution 25/25, in which it\nrequested the Office of the United Nations High Commissioner for Human Rights\n(OHCHR) to establish a field-based structure to follow up on the recommendations made in\nthe report of the commission of inquiry on human rights in the Democratic People’s\nRepublic of Korea (see A/HRC/25/63), and to provide the Special Rapporteur on the\nsituation of human rights in the Democratic People’s Republic of Korea with increased\nsupport. In the resolution, the Council mandated the field-based structure to strengthen\nmonitoring and documentation of the situation of human rights in the Democratic People’s\nRepublic of Korea, to ensure accountability, to enhance engagement and capacity-building\nwith the Governments of all States concerned, civil society and other stakeholders, and to\nmaintain visibility of the situation of human rights in the Democratic People’s Republic of\nKorea, including through sustained communications, advocacy and outreach initiatives."},{"id":"a-hrc-31-38-p0002","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"2","seq":4,"section":"I. Introduction","text":"The present report is submitted pursuant to Human Rights Council resolution 28/22,\nin which the Council requested OHCHR to submit a comprehensive report at its thirty-first\nsession on the role and achievements of the Office, including on the field-based structure,\nwith respect to the situation of human rights in the Democratic People’s Republic of Korea.\nThe report covers the period from 1 April to 31 December 2015."},{"id":"a-hrc-31-38-p0003","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"3","seq":5,"section":"I. Introduction","text":"On 22 May 2015, the Government of the Republic of Korea signed an interim host\ncountry agreement with OHCHR for the establishment of the field-based structure in Seoul.\nThe High Commissioner formally opened OHCHR (Seoul) on 23 June 2015."},{"id":"a-hrc-31-38-p0004","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"4","seq":6,"section":"I. Introduction","text":"During the reporting period, OHCHR was not granted access to the Democratic\nPeople’s Republic of Korea. Thus, the information contained in the report is gathered from\nvarious reliable sources, including Governments, non-governmental organizations (NGOs),\nacademics and individuals who have left the Democratic People’s Republic of Korea.\nInformation contained in the report was cross-checked to the extent possible. However, the\nlack of access of independent human rights monitors to the Democratic People’s Republic\nof Korea is a challenge to independent verification."},{"id":"a-hrc-31-38-p0005","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"5","seq":7,"section":"II. Regional and political context","text":"Despite reports of an improving economy, particularly in Pyongyang, the political\nand economic situation in the Democratic People’s Republic of Korea remains fragile. The\nrisk of increased regional tensions is exacerbated by the fact that no progress has been made\non issues affecting the region at large, including the alleged abduction of Japanese nationals\nby the Government of the Democratic People’s Republic of Korea."},{"id":"a-hrc-31-38-p0006","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"6","seq":8,"section":"II. Regional and political context","text":"The leadership of the Democratic People’s Republic of Korea continues to focus on\nenhancing its military capability, which has been the central aspect of its communication\nwith the population and with the outside world. The prioritization of military expenditure is\nthe most visible demonstration of an inadequate use of resources in a country that depends\non humanitarian assistance."},{"id":"a-hrc-31-38-p0007","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"7","seq":9,"section":"II. Regional and political context","text":"In 2015, there were reports of a continued practice of institutional purges and\nsanctions targeting some members of the political leadership. The most recent example has\nbeen the reported “re-education” sentence that was received for unknown reasons by the\nSecretary of the Workers’ Party, Choe Ryong Hae, in November 2015."},{"id":"a-hrc-31-38-p0008","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"8","seq":10,"section":"II. Regional and political context","text":"In August 2015, tensions escalated between the Democratic People’s Republic of\nKorea and the Republic of Korea after two soldiers from the Republic of Korea were\nseriously injured by landmines on 4 August in the demilitarized zone. On 25 August, the\nGovernment of the Democratic People’s Republic of Korea and the Government of the\nRepublic of Korea reached an agreement in which the former expressed regret over the\nmine explosion and committed to lifting the state of “semi-war” that it had declared, while\nthe latter agreed to stop broadcasting propaganda over loudspeaker along the demilitarized\nzone. The two Governments also agreed to hold further talks to improve ties, resume family\nreunions and encourage exchanges between NGOs in various fields. Family reunions took\nplace from 20 to 26 October 2015 (see para. 38 below)."},{"id":"a-hrc-31-38-p0009","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"9","seq":11,"section":"II. Regional and political context","text":"On 30 October 2015, the Korean Central News Agency, the official news outlet of\nthe Democratic People’s Republic of Korea, announced that the Central Committee of the\nKorean Workers’ Party had decided to organize the seventh Workers’ Party Congress in\nMay 2016, the first congress of the Party since October 1980. The Congress will help\nindicate the future direction of public policy, and it may lead to the adoption of new\nregulations or the appointment of new officials."},{"id":"a-hrc-31-38-p0010","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"10","seq":12,"section":"III. Cooperation of the Government of the Democratic People’s","text":"In September 2015, discussions on possible steps towards technical cooperation\nbetween the Democratic People’s Republic of Korea and OHCHR resumed. In December\n2014, the Government had decided to suspend such talks, following the adoption of General\nAssembly resolution 69/188 and the Security Council meeting on 22 December on human\nrights in the Democratic People’s Republic of Korea."},{"id":"a-hrc-31-38-p0011","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"11","seq":13,"section":"III. Cooperation of the Government of the Democratic People’s","text":"On 21 September 2015, during the thirtieth session of the Human Rights Council,\nand as decided by the Council in its resolution 28/22, OHCHR organized a panel discussion\non the situation of human rights in the Democratic People’s Republic of Korea, including\nthe issue of international abductions, enforced disappearances and related matters. Many\nMember States expressed support for the steps taken by OHCHR to implement the\nrecommendations of the commission of inquiry on human rights in the Democratic People’s\nRepublic of Korea, including the establishment of OHCHR (Seoul). The Government of the\nDemocratic People’s Republic of Korea expressed disagreement with the holding of the\npanel, stating that it constituted a politically motivated attempt to change the political\nsystem of its country. Some Member States expressed opposition to the country-specific\nnature of the panel, and pointed to the universal periodic review as the suitable forum for\ncountry-specific discussions."},{"id":"a-hrc-31-38-p0012","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"12","seq":14,"section":"III. Cooperation of the Government of the Democratic People’s","text":"OHCHR has been seeking to engage with the Government of the Democratic\nPeople’s Republic of Korea to discuss human rights. In late 2015, the Government gave\nsigns that it was making efforts in that regard. In particular, the High Commissioner\nwelcomes the invitation to visit the country that was extended by the Minister of Foreign\nAffairs in September 2015."},{"id":"a-hrc-31-38-p0013","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"13","seq":15,"section":"III. Cooperation of the Government of the Democratic People’s","text":"On 10 December 2015, the Security Council held a debate on the situation of human\nrights in the Democratic People’s Republic of Korea. The High Commissioner was invited\nto brief the Council and recalled the ongoing nature of serious human rights violations in\nthe country. He emphasized that accountability must go hand in hand with an open dialogue\nto encourage the Government to undertake reforms. The Government of the Democratic\nPeople’s Republic of Korea issued a statement in which it strongly denounced the\nconvocation of the debate.1"},{"id":"a-hrc-31-38-p0014","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"14","seq":16,"section":"III. Cooperation of the Government of the Democratic People’s","text":"On 17 December 2015, the General Assembly adopted resolution 70/172 (119\nMember States voted in favour, 19 against and 48 abstained). In line with resolution\n69/188, the Assembly encouraged the Security Council to continue its consideration of the\nrelevant conclusions and recommendations of the commission of inquiry and take\nappropriate action to ensure accountability, including through consideration of referral of\nthe situation in the Democratic People’s Republic of Korea to the International Criminal\nCourt and consideration of the scope for targeted sanctions against those who appear to be\nmost responsible for acts that the commission has said may constitute crimes against\nhumanity."},{"id":"a-hrc-31-38-p0015","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"15","seq":17,"section":"III. Cooperation of the Government of the Democratic People’s","text":"The Democratic People’s Republic of Korea is party to four international human\nrights treaties: the International Covenant on Civil and Political Rights, the International\nCovenant on Economic, Social and Cultural Rights, the Convention on the Elimination of\nAll Forms of Discrimination against Women and the Convention on the Rights of the\nChild. In November 2014, the Government ratified the Optional Protocol to the Convention\non the Rights of the Child on the sale of children, child prostitution and child pornography.\nIn September 2014, it accepted recommendations made in the context of the universal\nperiodic review to expedite the ratification of the Convention on the Rights of Persons with\nDisabilities, which it had signed in July 2013."},{"id":"a-hrc-31-38-p0016","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"16","seq":18,"section":"III. Cooperation of the Government of the Democratic People’s","text":"In 2014, the Government accepted 113 of the 268 recommendations received during\nthe second cycle of the universal periodic review, as well as 81 recommendations from the\nfirst review. They included recommendations to submit reports to United Nations human\nrights treaty bodies, notably the Committee on the Rights of the Child and the Committee\non the Elimination of Discrimination against Women. OHCHR has offered to provide\ntechnical assistance to facilitate the implementation of the accepted recommendations.\nOther accepted recommendations relate to economic and social rights, the rights of women\nand children, human rights education, a rights-based approach to development and family\nreunification."},{"id":"a-hrc-31-38-p0017","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"17","seq":19,"section":"III. Cooperation of the Government of the Democratic People’s","text":"The mandate of the Special Rapporteur on the situation of human rights in the\nDemocratic People’s Republic of Korea was established in 2004 by the United Nations\nCommission on Human Rights. The current mandate holder is Marzuki Darusman, whose\nterm expires in July 2016. None of the successive Special Rapporteurs has been granted\naccess to visit the Democratic People’s Republic of Korea. In addition, at the end of 2015,\nrequests from five special procedures to visit the country remained unanswered.2 The\nSpecial Rapporteur on the situation of human rights in the Democratic People’s Republic of\nKorea conducted two visits to Seoul during the period covered in the present report, from 7\nto 10 September 2015 and from 23 to 27 November."},{"id":"a-hrc-31-38-p0018","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"18","seq":20,"section":"A. Rights to life, liberty and security of the person","text":"During the period under review, OHCHR received reports of executions, apparently\namounting to arbitrary executions. The Criminal Code of the Democratic People’s Republic\nof Korea prescribes the death penalty for a wide range of offences, as do, reportedly,\nseveral promulgations and instructions issued by the political leadership."},{"id":"a-hrc-31-38-p0019","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"19","seq":21,"section":"A. Rights to life, liberty and security of the person","text":"In May 2015, the then Minister of Defence, Hyon Yong Choi, was reported to have\nbeen executed for alleged treason. In August, it was reported that Vice Premier, Choe Yong\nGon, had been executed in May 2015 for expressing disagreement with the Supreme Leader\nover the forestation policy. Owing to the lack of information on those executions and the\nuse of capital punishment in general, it is extremely difficult to verify such reports."},{"id":"a-hrc-31-38-p0020","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"20","seq":22,"section":"A. Rights to life, liberty and security of the person","text":"Reports that particularly cruel methods, including anti-aircraft guns, are used to\ncarry out executions raise additional serious concerns. In April 2015, the Committee for\nHuman Rights in North Korea, an NGO based in Washington, D.C., released satellite\nimages allegedly showing the execution in October 2014 of several officers by anti-aircraft\nmachine guns.3"},{"id":"a-hrc-31-38-p0021","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"21","seq":23,"section":"A. Rights to life, liberty and security of the person","text":"The Korea Institute for National Unification has noted a remarkable rise over the\npast few years in the use of the death penalty in the Democratic People’s Republic of Korea\nfor watching or distributing videos from the Republic of Korea and for smuggling or\ntrafficking narcotics.4 OHCHR received reports that three women were executed in August\n2015 in Hyesan City, Ryanggang Province, allegedly for using their mobile phones to\nwatch and distribute soap operas from the Republic of Korea. The executions were\nallegedly carried out to set an example and deter the viewing of foreign materials, which\nare considered to be illegal. Although that was an extreme case, it was reportedly part of a\ntrend towards harsher punishments for those illegally accessing news sources and other\nforeign materials."},{"id":"a-hrc-31-38-p0022","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"22","seq":24,"section":"A. Rights to life, liberty and security of the person","text":"Large political prison camps appear to remain in operation in at least four locations.5\nThere were credible reports of poor conditions in political prisons and other places of\ndetention and imprisonment. Conditions were reportedly particularly severe in temporary\ndetention centres where suspects were allegedly held at the early stage of their arrest. Some\nvictims reported to OHCHR that they were forced to sit in a restricted position for hours\nand threatened with physical punishment if they moved. They also reported that access to\nfood was grossly insufficient, with many detainees depending for their survival on their\nrelatives bringing food. Former detainees also reported a lack of access to independent\nlawyers."},{"id":"a-hrc-31-38-p0023","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"23","seq":25,"section":"A. Rights to life, liberty and security of the person","text":"Moreover, ill-treatment and torture is reportedly routinely used during the initial\ninterrogation stage, apparently with the aim of obtaining a confession that conforms to the\nauthorities’ version of events. Information gathered by OHCHR from various sources\nreferred to cases of beating and kicking, sleep deprivation and verbal abuse. Cases were\nalso reported of solitary confinement for several days in a cell so small that the detainee\nwas unable to sit down."},{"id":"a-hrc-31-38-p0024","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"24","seq":26,"section":"A. Rights to life, liberty and security of the person","text":"On the occasions of the seventieth anniversary of the liberation from Japanese\ncolonial rule, in August 2015, and of the foundation day of the Workers’ Party, in October\n2015, the Government reportedly released a large number of prisoners. However, allegedly\nthat did not appear to include political prisoners. In 2015, the Government repatriated at\nleast four nationals of the Republic of Korea who had been detained in the Democratic\nPeople’s Republic of Korea. Two citizens of the Republic of Korea who had been convicted\nfor espionage in June 2015 reportedly continued to serve life sentences, as did a third\ncitizen of the Republic of Korea who had been sentenced to life imprisonment in 2014 for\nespionage and setting up an underground church. The three individuals were reportedly\nmissionaries. In December 2015, a Canadian pastor, Hyeon Soo Lim, was reportedly\nconvicted of crimes against the State and sentenced to life imprisonment with hard labour."},{"id":"a-hrc-31-38-p0025","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"25","seq":27,"section":"B. Rights to freedom of expression, peaceful assembly and freedom of","text":"Severe restrictions on the rights to freedom of expression, including the right to\ninformation, peaceful assembly and freedom of association remained in place. While article\n67 of the Constitution of the Democratic People’s Republic of Korea guarantees citizens\n“freedom of speech, press, assembly, demonstration and association”, in practice, there is\nno protection for those rights. In their annual report on global Internet usage for 2014, the\nInternational Telecommunication Union (ITU) and the United Nations Educational,\nScientific and Cultural Organization (UNESCO) ranked the Democratic People’s Republic\nof Korea at the bottom of 191 countries, with a zero percentage of individuals using the\nInternet.6"},{"id":"a-hrc-31-38-p0026","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"26","seq":28,"section":"B. Rights to freedom of expression, peaceful assembly and freedom of","text":"Some external bodies took steps to improve access to information inside the\nDemocratic People’s Republic of Korea. For example, in November 2015, the British\nBroadcasting Corporation announced plans to expand its radio coverage to the country.\nSeveral radio stations based in Seoul, some of which are staffed with people who have left\nthe Democratic People’s Republic of Korea, continued to broadcast programmes for the\nDemocratic People’s Republic of Korea. The audience for those programmes is reportedly\nsignificant, particularly in the border regions, but no official data can be obtained on the\nnumber of listeners. That is in part owing to the difficulty of conducting surveys inside the\nDemocratic People’s Republic of Korea and to the risk of persecution that listeners face if\nthey are caught by the authorities."},{"id":"a-hrc-31-38-p0027","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"27","seq":29,"section":"B. Rights to freedom of expression, peaceful assembly and freedom of","text":"During the reporting period, there appears to have been an increased crackdown by\nthe authorities on the clandestine use of Chinese mobile phones along the border with\nChina. Where it was previously reportedly relatively easy to communicate with the outside\nworld through such mobile phones, interference with mobile phone signals has reportedly\nbecome more effective. There were credible reports that conversations on mobile phones\nwith those inside the country were becoming more infrequent even compared to 2014.\nWhen they take place, conversations on mobile phones reportedly tend to end quickly as\nusers fear being detected by the authorities."},{"id":"a-hrc-31-38-p0028","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"28","seq":30,"section":"C. Freedom of movement and the right to seek asylum","text":"In order to travel within the Democratic People’s Republic of Korea, citizens are\nrequired to obtain a permit from local authorities. Such permits are said to be valid for only\none trip, for which the destination and purpose must be explicitly clarified. Some\nindividuals are reportedly able to circumvent that requirement by paying bribes."},{"id":"a-hrc-31-38-p0029","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"29","seq":31,"section":"C. Freedom of movement and the right to seek asylum","text":"Citizens of the Democratic People’s Republic of Korea are also prohibited from\nleaving the country without permission. Information from people who have left the country\nindicates that controls along the border between the Democratic People’s Republic of\nKorea and China have tightened since 2011. That information appears to be supported by a\nnotable decrease in the number of nationals of the Democratic People’s Republic of Korea\nwho reach the Republic of Korea. In 2015, some 1,276 persons reportedly arrived in the\nRepublic of Korea (80 per cent of them women), as opposed to 1,397 in 2014. Other\nfactors, such as the rotation of guards along the border, the reported increase in the cost of\nengaging a broker to secure passage and, in some areas, possible increased economic\nopportunities domestically, may have contributed to the decrease. Some people also partly\nattribute the situation to increasing difficulties with mobile communications, which makes\nit problematic to arrange brokers. In 2014, the authorities reportedly warned residents in the\nborder areas that they and their families would face severe punishment for assisting\nindividuals who were planning or attempting to cross the border, or for failing to report\nsuch cases."},{"id":"a-hrc-31-38-p0030","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"30","seq":32,"section":"C. Freedom of movement and the right to seek asylum","text":"In past years, a large number of brokers, many of them operating mainly for\nfinancial gain, have assisted citizens of the Democratic People’s Republic of Korea to cross\nthe border. The fees charged by brokers have reportedly increased as movement across the\nborder has become more difficult. Additionally, women who wish to leave the Democratic\nPeople’s Republic of Korea with the assistance of a broker remain vulnerable to human\ntrafficking, which, unlike passage using a broker, is coercive. Reportedly, some women\nwere indeed subjected to trafficking in that context."},{"id":"a-hrc-31-38-p0031","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"31","seq":33,"section":"C. Freedom of movement and the right to seek asylum","text":"Individuals repatriated to the Democratic People’s Republic of Korea from China\nand other counties are at risk of prolonged unlawful detention, ill-treatment and torture.\nThose found to have sought to defect to the Republic of Korea or to have been in\ncommunication with Christian organizations suffer particularly harsh punishment and risk\nimprisonment in political prison camps, as they are regarded as having committed\nparticularly serious political crimes."},{"id":"a-hrc-31-38-p0032","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"32","seq":34,"section":"C. Freedom of movement and the right to seek asylum","text":"Despite the risk of torture and other violations facing those who are returned to the\ncountry, some neighbouring States have refouled refugees to the Democratic People’s\nRepublic of Korea. On 22 October 2015, a group of nine refugees, including an infant and a\nteenager, were arrested in Viet Nam and transferred to China. They were reportedly\ntransferred to a town close to the border with the Democratic People’s Republic of Korea,\nindicating that they were at risk of being forcibly repatriated. 7 In a statement issued on 3\nDecember 2015, the Government of China reiterated that it considered those who had fled\nthe Democratic People’s Republic of Korea as illegal immigrants rather than refugees."},{"id":"a-hrc-31-38-p0033","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"33","seq":35,"section":"C. Freedom of movement and the right to seek asylum","text":"The Committee against Torture, in its concluding observations on the fifth periodic\nreport of China, expressed concern at the rigorous policy of China of forcibly repatriating\nall nationals of the Democratic People’s Republic of Korea on the ground that they had\nillegally crossed the border solely for economic reasons. The Committee took note of over\n100 testimonies received by United Nations sources indicating that persons forcibly\nrepatriated to the Democratic People’s Republic of Korea had been systematically subjected\nto torture and ill-treatment. The Committee recommended that the Government of China\nshould immediately cease forcible repatriation of undocumented migrants and victims of\ntrafficking to the Democratic People’s Republic of Korea, and allow personnel of the\nOffice of the United Nations High Commissioner for Refugees unimpeded access to\nnationals of the Democratic People’s Republic of Korea who had crossed the border, in\norder to determine if they qualified for refugee status (see CAT/C/CHN/CO/5, paras. 46\nand 47)."},{"id":"a-hrc-31-38-p0034","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"34","seq":36,"section":"C. Freedom of movement and the right to seek asylum","text":"While illegal crossings at the border have declined, from January to September\n2015, some 139,700 citizens of the Democratic People’s Republic of Korea, 117,900 of\nwhom were male, reportedly crossed legally into China. Such international travel requires\npermission from the Government of the Democratic People’s Republic of Korea. 8 Tens of\nthousands of workers have reportedly been contracted by the Government of the\nDemocratic People’s Republic of Korea to work in foreign companies in China, the Russian\nFederation and other countries, mostly in construction and other manual jobs. Those\nworkers reportedly live in poor conditions, are subject to lengthy working hours and\noversight and limitations on their movement. They reportedly receive only a fraction of\ntheir pay, as the hiring companies pay the Government of the Democratic People’s\nRepublic of Korea directly."},{"id":"a-hrc-31-38-p0035","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"35","seq":37,"section":"D. Discrimination against women","text":"Discrimination against women continued to limit their full participation in economic\nand social life. Married women are traditionally exempted from holding official jobs.\nFollowing the surge of private economic activities in the late 1990s, most such activities\nhave been carried out by married women. They can more easily engage in the informal\nmarket and in informal trade because, unlike men, they do not have to take up official State\nemployment. Thus, women who engage in cross-border trading activities with China have\nreportedly been disproportionately affected by restrictions at the border area."},{"id":"a-hrc-31-38-p0036","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"36","seq":38,"section":"D. Discrimination against women","text":"There were credible reports of trafficking in women from the Democratic People’s\nRepublic of Korea into China. In some cases, that reportedly resulted in forced marriage to\nChinese men and other forms of sexual exploitation. Those women are extremely\nvulnerable in China; they are at a constant risk of forced repatriation to the Democratic\nPeople’s Republic of Korea. Children born to those women and fathered by Chinese men\nare stateless as they are recognized by neither of the Governments of their parents’\ncountries. The women rarely have family support to draw on, and their illegal status and\nfear of being returned to the Democratic People’s Republic of Korea make them highly\nunlikely to contact the authorities if they or their children are abused."},{"id":"a-hrc-31-38-p0037","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"37","seq":39,"section":"D. Discrimination against women","text":"Pregnant women who were returned to the Democratic People’s Republic of Korea\nwere reportedly detained and forced to have abortions. In most cases, abortions were\nreportedly carried out to prevent the women from giving birth to children that were half\nChinese.9"},{"id":"a-hrc-31-38-p0038","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"38","seq":40,"section":"E. Separated families","text":"From 20 to 26 October 2015, the Governments of the Democratic People’s Republic\nof Korea and the Republic of Korea organized family reunions, pursuant to their 25 August\n2015 agreement. During the reunions, around 90 individuals from the Republic of Korea\nand 96 individuals from the Democratic People’s Republic of Korea met with relatives\nfrom the other country."},{"id":"a-hrc-31-38-p0039","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"39","seq":41,"section":"E. Separated families","text":"The Special Rapporteur on the situation of human rights in the Democratic People’s\nRepublic of Korea has recommended that the Government allow separated families to\nreunite without delay and to use unmonitored communication facilities, such as telephone,\nmail and e-mail (see A/70/362, para. 81 (f)). The issue of separated families calls for an\nurgent resolution. The remaining family members on each side of the border are elderly,\nand in the Republic of Korea alone, over 60,000 people have died without having had a\nchance to be reunited with or to see their loved ones. The current format of reunion, which\nallows people to meet for only a few hours, with no hope of ongoing contact or meeting\nagain, is a source of psychological suffering. The separation of families must be seen as not\nonly a humanitarian issue, but also a violation of human rights affecting people at multiple\nlevels, including the rights to family life, to freedom of movement and to the truth."},{"id":"a-hrc-31-38-p0040","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"40","seq":42,"section":"F. International abductions","text":"It is estimated that between 80,000 and 100,000 civilians were abducted from the\nsouthern part of the Korean peninsula to the north during the Korean War. In addition, after\nthe armistice, the Government of the Democratic People’s Republic of Korea carried out\ninternational abductions, primarily in the Republic of Korea and Japan, although a number\nof individuals were reportedly abducted from other countries. The Government of the\nRepublic of Korea estimates that some 500 persons who were abducted after the end of the\nKorean War remain in the Democratic People’s Republic of Korea."},{"id":"a-hrc-31-38-p0041","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"41","seq":43,"section":"F. International abductions","text":"The Government of Japan has officially recognized 17 Japanese citizens as\nabductees, 5 of whom returned to Japan in 2002. In Japan, as of November 2015, national\ninvestigations continued into the fate of approximately 870 missing individuals in whose\ncases the possibility of abduction could not be ruled out. Relatives of victims, including the\nparents of Megumi Yokota, who was abducted from Japan in 1977 when she was 13 years\nold, met with representatives of OHCHR (Seoul) in October 2015 and conveyed\ninformation on their long-standing efforts to bring their loved ones back to Japan."},{"id":"a-hrc-31-38-p0042","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"42","seq":44,"section":"F. International abductions","text":"In late May 2014, the Governments of the Democratic People’s Republic of Korea\nand Japan agreed to take steps towards resolving the issue of Japanese nationals who had\nbeen abducted, to identify and return the remains of those who had died in the jurisdiction\nof the Democratic People’s Republic of Korea, and to address the case of Japanese spouses\nwho had accompanied their husband or wife to the Democratic People’s Republic of Korea.\nThe Government of the Democratic People’s Republic of Korea agreed to establish a\nspecial investigation committee to conduct comprehensive investigations, while the\nGovernment of Japan agreed to lift some bilateral sanctions. However, as at December\n2015, the outcome of the investigation by the committee had not been published."},{"id":"a-hrc-31-38-p0043","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"43","seq":45,"section":"F. International abductions","text":"During its sessions in March and May 2015, the Working Group on Enforced or\nInvoluntary Disappearances transmitted six cases of alleged abductions to the Government\nof the Democratic People’s Republic of Korea (see A/HRC/WGEID/105/1, para. 36, and\nA/HRC/WGEID/106/1, para. 22). The victims of the alleged abductions reportedly\ndisappeared in 2003 and 2011. As at December 2015, the Government had not responded to\nthose letters of allegation."},{"id":"a-hrc-31-38-p0044","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"44","seq":46,"section":"A. Establishment of the Office of the United Nations High Commissioner","text":"On 28 March 2014, the Human Rights Council adopted resolution 25/25, in which it\nrequested OHCHR to follow up urgently on the recommendations made by the commission\nof inquiry on human rights in the Democratic People’s Republic of Korea in its report, and\nto provide the Special Rapporteur on the situation of human rights in the Democratic\nPeople’s Republic of Korea with increased support, including through the establishment of\na field-based structure."},{"id":"a-hrc-31-38-p0045","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"45","seq":47,"section":"A. Establishment of the Office of the United Nations High Commissioner","text":"In paragraph 10 of resolution 25/25, the Council mandated the field-based structure\nto strengthen monitoring and documentation of the situation of human rights in the\nDemocratic People’s Republic of Korea, to ensure accountability, to enhance engagement\nand capacity-building with the Governments of all States concerned, civil society and other\nstakeholders, and to maintain visibility of the situation of human rights in the Democratic\nPeople’s Republic of Korea, including through sustained communications, advocacy and\noutreach initiatives."},{"id":"a-hrc-31-38-p0046","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"46","seq":48,"section":"A. Establishment of the Office of the United Nations High Commissioner","text":"On 22 May 2015, the Government of the Republic of Korea and OHCHR concluded\nan interim host country agreement for the establishment of the field-based structure in\nSeoul."},{"id":"a-hrc-31-38-p0047","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"47","seq":49,"section":"A. Establishment of the Office of the United Nations High Commissioner","text":"On 23 June 2015, the United Nations High Commissioner for Human Rights\ninaugurated the field-based structure in Seoul during his four-day visit to the Republic of\nKorea; he also met with government officials, representatives of civil society and people\nwho had left the Democratic People’s Republic of Korea. During his visit, the High\nCommissioner emphasized the importance of addressing fundamental human rights as an\nintegral part of ensuring peace and stability in the Korean peninsula."},{"id":"a-hrc-31-38-p0048","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"48","seq":50,"section":"A. Establishment of the Office of the United Nations High Commissioner","text":"An initial team of human rights officers began implementing the mandate of\nOHCHR (Seoul) immediately after the inauguration of the office, which comprises six staff\nmembers: the office Representative and Deputy Representative, two human rights officers,\none administrative member of staff and one interpreter."},{"id":"a-hrc-31-38-p0049","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"49","seq":51,"section":"A. Establishment of the Office of the United Nations High Commissioner","text":"OHCHR (Seoul) is funded from the regular budget of the United Nations and hosted\nby Seoul metropolitan government. Additional funding is sought to carry out core office\nactivities outlined in Council resolution 25/25, including monitoring, capacity-building and\noutreach activities."},{"id":"a-hrc-31-38-p0050","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"50","seq":52,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"In accordance with Council resolution 25/25, OHCHR (Seoul) has carried out\nmonitoring and documentation of the situation of human rights in the Democratic People’s\nRepublic of Korea, outreach and capacity-building. It has been engaging with\nGovernments, civil society and people who have left the Democratic People’s Republic of\nKorea, as well as with United Nations entities and humanitarian workers operating inside\nthe Democratic People’s Republic of Korea, and other stakeholders."},{"id":"a-hrc-31-38-p0051","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"51","seq":53,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"The work of OHCHR (Seoul) builds on the work of the commission of inquiry. The\nfield office has been gathering individual testimonies to contribute to possible future\naccountability processes and other transitional justice mechanisms. As of December 2015,\nit had interviewed 35 individuals who have left the Democratic People’s Republic of Korea."},{"id":"a-hrc-31-38-p0052","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"52","seq":54,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"During a mission to Japan, from 9 to 13 November 2015, staff from OHCHR\n(Seoul) met in Tokyo and Osaka with representatives of the Government and civil society,\nincluding researchers. They also met individuals who had left the Democratic People’s\nRepublic of Korea, and relatives of victims and of possible victims of abductions. In\naddition, they interviewed individuals who had left Japan for the Democratic People’s\nRepublic of Korea during the “Paradise on Earth” campaign, from 1958 to 1984, and had\nsuffered serious human rights violations in that context."},{"id":"a-hrc-31-38-p0053","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"53","seq":55,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"OHCHR (Seoul) worked closely with Governments, the diplomatic community in\nSeoul, civil society and others to raise awareness of the human rights situation in the\nDemocratic People’s Republic of Korea. Office staff made presentations at civil society\nseminars, including a Korean Bar Association seminar on human rights in the Democratic\nPeople’s Republic of Korea, on 30 June; the Asia Human Rights Forum on regional\ncooperation for transitional justice in Asia and human rights in North Korea, on\n18 September; the North Korea Human Rights and Peace Forum at Seoul National\nUniversity, on 1 October; the Seoul Dialogue for Human Rights, on 11 November; the\nUnited Nations human rights monitoring mechanisms and the Democratic People’s\nRepublic of Korea, organized by Human Asia, on 12 November; the Korean War\nAbductees Family Union Conference on Transitional Justice, on 30 November; and the\ntenth anniversary of the Radio Broadcasting for North Korea Initiative, on 10 December.\nStaff from the office also addressed the fourth North Korean Human Rights Forum in\nEurope, organized on 19 October in Spain by the Korea Institute for National Unification;\nand the International symposium on international cooperation towards resolution of the\nabduction issue, organized by the Government of Japan in Tokyo, on 12 December."},{"id":"a-hrc-31-38-p0054","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"54","seq":56,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"On 27 November 2015, the Representative of OHCHR (Seoul) addressed the third\nNorth Korean human rights symposium at the National Assembly of the Republic of Korea,\norganized by the Ministry of Justice, the National Assembly Human Rights Forum and the\nInternational Parliamentarians’ Coalition for Asian Human Rights. The OHCHR\nRepresentative provided an overview of the work of the office and of its cooperation with\nthe Government of the Republic of Korea."},{"id":"a-hrc-31-38-p0055","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"55","seq":57,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"On 10 December 2015, OHCHR (Seoul) organized an event in Seoul on human\nrights and separated families, gathering members of such families who spoke about the\npainful experience of separation, as elderly family members’ health deteriorates and\nchances to be reunited with their loved ones decrease. Individuals whose relatives were\nabducted to the Democratic People’s Republic of Korea described the challenges they faced\nafter the abduction. Other speakers included representatives of the Ministry of Unification,\nuniversity researchers and members of NGOs working with separated families, as well as\nthe current and former ambassadors for human rights of the Republic of Korea. Those\naffected by the issue called for increased action at the national and multilateral levels to\nhelp resolve the problem."},{"id":"a-hrc-31-38-p0056","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"56","seq":58,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"On 14 December 2015, the Judicial Policy Research Institute of Korea and OHCHR\n(Seoul) co-hosted a seminar on human rights and legal assistance for individuals from the\nDemocratic People’s Republic of Korea. The event examined possibilities to move forward\nin legal approaches to addressing human rights violations in the Democratic People’s\nRepublic of Korea. Participants included representatives of the Government of the Republic\nof Korea, the diplomatic community and civil society."},{"id":"a-hrc-31-38-p0057","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"57","seq":59,"section":"B. Activities of the Office of the United Nations High Commissioner for","text":"OHCHR (Seoul) has been active on social media. Its website is available in English\nand Korean at seoul.ohchr.org and is regularly updated. OHCHR (Seoul) has also\nestablished several social media platforms. Its Twitter account (@UNrightsSeoul) and the\nFacebook page have attracted more than 3,000 subscribers. The Representative of OHCHR\n(Seoul) has regularly conducted interviews with the media in the Republic of Korea and\nelsewhere."},{"id":"a-hrc-31-38-p0058","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"58","seq":60,"section":"A. Conclusions","text":"During the period under review, the human rights situation in the Democratic\nPeople’s Republic of Korea remained of serious concern, with reports of arbitrary\nkillings, torture and unlawful detention; continued discrimination and violence\nagainst women; and persistent and severe restrictions on freedoms of expression\n(including access to information), association and movement."},{"id":"a-hrc-31-38-p0059","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"59","seq":61,"section":"A. Conclusions","text":"OHCHR (Seoul) began carrying out its mandate after its inauguration on 23\nJune 2015. Lack of access to the Democratic People’s Republic of Korea is a major\nobstacle, and it is hoped that the invitation that has been extended to the High\nCommissioner to visit the country will constitute a first step towards addressing the\nissues of access and dialogue."},{"id":"a-hrc-31-38-p0060","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"60","seq":62,"section":"B. Recommendations","text":"The High Commissioner recommends that the Government of the Democratic\nPeople’s Republic of Korea:\n(a)    Engage constructively with the United Nations system, including\nOHCHR and its office in Seoul, and collaborate with OHCHR to develop a concrete\nplan of technical assistance for the promotion and protection of human rights in the\ncountry;\n(b)    Cooperate with United Nations human rights treaty bodies, including by\nsubmitting reports to the relevant treaty bodies;\n(c)    Invite the Special Rapporteur on the situation of human rights in the\nDemocratic People’s Republic of Korea and other special procedure mandate holders\nto visit the country;\n(d) Develop a strategy to implement the universal periodic review\nrecommendations it has accepted, with support from OHCHR and other relevant\nbodies;\n(e)    Halt all executions and declare and implement a moratorium on the\ndeath penalty;\n(f)  Provide international humanitarian organizations and human rights\nmonitors with unhindered access throughout the country, including to all places of\ndetention;\n(g)    Dismantle all political prison camps and release all political prisoners;\n(h)     Provide the families and countries of origin of all individuals who have\nbeen abducted or forcibly disappeared with full information on their fate and\nwhereabouts; allow survivors and their descendants to return immediately to their\ncountries of origin; and identify and repatriate the physical remains of those who have\ndied, working in close cooperation with their families and the authorities of their\ncountries of origin;\n(i)   Lift all restrictions on the rights to freedom of expression, peaceful\nassembly and freedom of association that are incompatible with international law, and\ndecriminalize any acts that constitute the legitimate exercise of such rights, including\ngaining access to external sources of information through satellite television channels,\nforeign media and the Internet;\n(j)   Lift all restrictions and penalties on freedom of movement, including\nprosecution, extrajudicial punishment and torture, of those who seek to leave or have\nleft the country without permission;\n(k)   Prosecute and bring to justice individuals responsible for alleged crimes\nagainst humanity; ratify the Rome Statute of the International Criminal Court; and\nensure that victims of crimes against humanity and their families are provided with\nadequate, prompt and effective reparation and remedies, including telling them the\ntruth about the violations concerned."},{"id":"a-hrc-31-38-p0061","rec_id":"reciqsEXvCzDo7u03","symbol":"A/HRC/31/38","n":"61","seq":63,"section":"B. Recommendations","text":"The High Commissioner recommends that the international community strictly\nadhere to the principle of non-refoulement. No country should repatriate individuals\nto the Democratic People’s Republic of Korea, where they are likely to face torture or\nother serious human rights violations."},{"id":"a-hrc-34-66-add-1-p0001","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"1","seq":0,"section":"I. Introduction","text":"The present report is presented pursuant to Human Rights Council resolution 31/18,\nin which the Council requested the United Nations High Commissioner for Human Rights\nto designate two existing independent experts in support of the work of the Special\nRapporteur on the situation of human rights in the Democratic People's Republic of Korea\nto focus on issues of accountability for human rights violations in the country, in particular\nwhere such violations amount to crimes against humanity, as found by the commission of\ninquiry. The High Commissioner designated Sonja Biserko (Serbia) and Sara Hossain\n(Bangladesh)."},{"id":"a-hrc-34-66-add-1-p0002","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"2","seq":1,"section":"A. Interpretation of the mandate","text":"In its resolution the Council requested the group of independent experts, taking into\naccount existing international law and prevailing State practices with regard to\naccountability: (a) to explore appropriate approaches to seek accountability for human\nrights violations in the Democratic People's Republic of Korea, in particular where such\nviolations amount to crimes against humanity, as found by the commission of inquiry on\nhuman rights in the Democratic People's Republic of Korea; and (b) to recommend\npractical mechanisms of accountability to secure truth and justice for the victims of possible\ncrimes against humanity in the Democratic People's Republic of Korea, including the\nInternational Criminal Court."},{"id":"a-hrc-34-66-add-1-p0003","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"3","seq":2,"section":"A. Interpretation of the mandate","text":"Given that in the resolution the Council referred to \"human rights violations ...\nfound by the commission of inquiry\", the group considered that its mandate covered all\nsuch violations, 1 notably systematic, widespread and gross human rights violations,\nincluding abductions which took place outside the Democratic People's Republic of Korea\nand led to enforced disappearances continuing in the country. The group did not undertake\nany fact-finding (including on specific allegations brought to its attention);2 its meetings\nfocused on approaches and processes of accountability."},{"id":"a-hrc-34-66-add-1-p0004","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"4","seq":3,"section":"B. Non-cooperation by the Democratic People's Republic of Korea","text":"Through communications dated 20 September, 14 October and 6 December 2016\nand 17 January 2017, the group of independent experts conveyed to the Government of the\nDemocratic People's Republic of Korea that it was committed to a fully independent and\nimpartial approach, sought meetings with its Permanent Representatives in Geneva and\nNew York, requested permission to visit the country, and solicited the Government's views\nand any information on the country's accountability processes. The group regrets that the\nmeeting requests were denied, and the other requests remained unanswered. The group\nremains committed to engaging with the Democratic People's Republic of Korea to discuss\nthe findings of the present report.\nA/HRC/34/66/Add.1"},{"id":"a-hrc-34-66-add-1-p0005","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"5","seq":4,"section":"C. Methods of work","text":"In 2016, the group of independent experts undertook missions to Geneva (20-23\nSeptember), The Hague (24-26 October), Seoul (21-25 November), Tokyo (28-29\nNovember) and New York (12-14 December). During these missions, the group met with\nand received information from government officials, officials at international tribunals,\nincluding the International Criminal Court, United Nations entities, humanitarian actors,\nlegal practitioners and experts, the National Human Rights Commission of Korea, and\nnational and international civil society groups. In Seoul and Tokyo, the group met victims\nof human rights violations in the Democratic People's Republic of Korea, civil society\ngroups representing victims, individuals who had lived in the Democratic People's\nRepublic of Korea and others directly affected by the human rights situation there. The\ngroup received 16 written submissions, including those from civil society organizations,\nlegal experts and individuals.3 The group expresses its sincere appreciation to those who\nshared their views and provided information."},{"id":"a-hrc-34-66-add-1-p0006","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"6","seq":5,"section":"C. Methods of work","text":"The group received advice and support from the Office of the United Nations High\nCommissioner for Human Rights (OHCHR), including its field-based structure in Seoul,\nand interacted with special procedure mandate holders. Finally, the group coordinated its\nwork with the Special Rapporteur on the situation of human rights in the Democratic\nPeople's Republic of Korea, including through joint meetings in Geneva and Seoul."},{"id":"a-hrc-34-66-add-1-p0007","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"7","seq":6,"section":"III. Previous recommendations on accountability for human","text":"The commission of inquiry, Special Rapporteurs on the situation of human rights in\nthe Democratic People's Republic of Korea and others have made repeated and strong calls\nand recommendations for accountability for human rights violations in the country."},{"id":"a-hrc-34-66-add-1-p0008","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"8","seq":7,"section":"III. Previous recommendations on accountability for human","text":"The commission of inquiry considered issues of institutional and individual criminal\naccountability.4 It reflected on the accepted responsibility of the international community to\nprotect the population of every State from crimes against humanity,5 and deemed that given\nthe commission's findings, it is incumbent on the international community to ensure that\nthe perpetrators are brought to justice.6 The commission called for the United Nations to\nensure that those most responsible for crimes against humanity in the Democratic People's\nRepublic of Korea are held accountable, and for the Security Council to refer the situation\nto the International Criminal Court or establish an ad hoc international tribunal.7"},{"id":"a-hrc-34-66-add-1-p0009","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"9","seq":8,"section":"III. Previous recommendations on accountability for human","text":"Subsequently, the General Assembly decided to submit the report of the commission\nof inquiry to the Security Council, and encouraged the Council to consider the relevant\nconclusions and recommendations and take appropriate action to ensure accountability,\nincluding considering a referral of the situation in the Democratic People's Republic of\nKorea to the International Criminal Court.8 The Council has since held three meetings on\n3 See www.ohchr.org/en/NewsEvents/Pages/DisplayNews.aspx?NewsID=20890&LangID=E;\nhttp://ohchr.org/EN/HRBodies/SP/CountriesMandates/KP/Pages/GroupofIndependentExpertsonAcco\nuntability.aspx.\n4 \"Report of the detailed findings\", paras. 1167-1194;1195-1199.\n5 Ibid., para. 1166.\n6 Ibid., para. 1199.\n7 Ibid., paras. 1218; 1225.\n8 See resolutions 69/188, 70/172; 71/202.\nA/HRC/34/66/Add.1\nthe human rights situation in the country, during which several States called for\naccountability,9 but has not yet referred the situation to the Court."},{"id":"a-hrc-34-66-add-1-p0010","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"10","seq":9,"section":"III. Previous recommendations on accountability for human","text":"Accountability for human rights violations has been a consistent focus of the\nmandate of the Special Rapporteur on the situation of human rights in the Democratic\nPeople's Republic of Korea. In his reports, the first Special Rapporteur concluded that\n\"there are a variety of discrepancies and transgressions -- several of an egregious nature --\nin the implementation of human rights in the country, calling for immediate action to\nprevent further abuses and provide redress\" by national authorities as well as the\ninternational community. 10 Another former Special Rapporteur equally urged the\ninternational community to take bold steps to address crimes against humanity in the\nDemocratic People's Republic of Korea while recalling the duty of the international\ncommunity to prosecute such crimes.11 The current Special Rapporteur has emphasized the\nimportance of ensuring accountability for human rights violations, in the interests of justice\nand as a deterrent for further violations.12"},{"id":"a-hrc-34-66-add-1-p0011","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"11","seq":10,"section":"A. International law and practice","text":"The Human Rights Council requested the group of independent experts to take into\naccount existing international law and prevailing State practices with regard to\naccountability. Under international law and practice, accountability for gross human rights\nviolations is not a matter of choice or convenience, but of legal obligation. International\nnorms and standards articulate the requirement for a State to meet this obligation and to\nensure an adequate response to allegations of gross human rights violations."},{"id":"a-hrc-34-66-add-1-p0012","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"12","seq":11,"section":"A. International law and practice","text":"States are under a duty to investigate and prosecute human rights violations that\namount to crimes under national or international law, in particular genocide, war crimes,\ncrimes against humanity or other gross violations of human rights.13 Article 2 (3) of the\nInternational Covenant on Civil and Political Rights guarantees every victim of a human\nrights violation the right to remedy. This requires States to investigate allegations of\nviolations promptly, thoroughly and effectively through independent and impartial bodies\nand, where the investigations reveal violations of certain Covenant rights, bring those\nresponsible to justice. A failure to investigate and bring to justice perpetrators of such\nviolations could in and of itself give rise to a separate breach of the Covenant. 14 The\nDemocratic People's Republic of Korea acceded to the Covenant in 1981 and is legally\nbound by its provisions. With respect to crimes against humanity, in 1984, the Democratic\nPeople's Republic of Korea acceded to the Convention on the Non-Applicability of\nStatutory Limitations to War Crimes and Crimes Against Humanity, which emphasizes the\nimportance of punishing perpetrators of such crimes."},{"id":"a-hrc-34-66-add-1-p0013","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"13","seq":12,"section":"A. International law and practice","text":"The prohibition of crimes against humanity is a rule of binding international\ncustomary law. The duty of States to ensure accountability for such crimes is widely\naccepted and has been referenced in international treaties, including the Rome Statute of the\nInternational Criminal Court, and regularly reiterated in resolutions and other soft law\nA/HRC/34/66/Add.1\ninstruments. 15 Additionally, States have a responsibility to prevent the commission of\ncrimes against humanity. The international community has declared that when States are\n\"manifestly failing\" in their responsibility to protect their populations from such crimes, it\nis prepared to take collective action, in a \"timely and decisive manner\", and bearing in mind\nthe principles of the Charter of the United Nations and international law.16"},{"id":"a-hrc-34-66-add-1-p0014","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"14","seq":13,"section":"A. International law and practice","text":"Ensuring accountability for gross human rights violations goes beyond establishing\nindividual criminal responsibility. A comprehensive approach also requires measures\ntowards the realization of the right to know the truth about violations and the right to\nadequate, effective and prompt reparation, as grounded in international law,17 and further\narticulated in the updated set of principles for the protection and promotion of human rights\nthrough action to combat impunity18 and the Basic Principles and Guidelines on the Right\nto a Remedy and Reparation for Victims of Gross Violations of International Human Rights\nLaw and Serious Violations of International Humanitarian Law.19"},{"id":"a-hrc-34-66-add-1-p0015","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"15","seq":14,"section":"A. International law and practice","text":"The occurrence of a human rights violation gives rise to a right to receive reparation\nfor or on behalf of the victim or their beneficiaries, and a duty on the part of the State to\nmake reparation and provide a possibility for the victim to seek redress from the\nperpetrator.20 The right to the truth entitles the victims, their relatives and the public at large\nto seek and obtain all relevant information concerning the commission of the alleged\nviolation, the fate and whereabouts of the victim and, where appropriate, the process by\nwhich the alleged violation was officially authorized,21 as well as the extent and pattern of\npast violations, and their root causes. It requires States to establish processes that lead to the\nrevelation of the truth about what took place. Such processes contribute to the fight against\nimpunity, the reinstatement of the rule of law and, ultimately, reconciliation. 22 Truth-\nseeking processes also contribute to the prevention of violations through specific\nrecommendations, including on reparations and reforms. In this regard, education, 23\nmeasures of memorialization, trauma counselling and psychosocial support are crucial."},{"id":"a-hrc-34-66-add-1-p0016","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"16","seq":15,"section":"A. International law and practice","text":"The group notes the critical importance of eschewing one-size-fits-all models,24 and\nthat diverse mechanisms and measures have been implemented to address gross human\nrights violations: international tribunals, hybrid courts, domestic courts with or without\ninternational support, truth commissions, parliamentary inquiries, civil society-driven\nprocesses (including mock trials/tribunals, consultations, memorialization and education\ninitiatives), reparations schemes (including psychosocial support) and vetting programmes,\nas well as legal and policy measures seeking to guarantee non-recurrence. 25 The\nmanagement and preservation of existing and future archives has also proven to be of\nparamount importance.26\n15 For example, General Assembly resolution 67/1.\n16 General Assembly resolution 60/1.\n17 On the right to the truth, see E/CN.4/2006/91, A/HRC/5/7, A/HRC/12/19 and A/HRC/15/33; on\nreparations, see OHCHR, Rule-of-Law Tools for Post-Conflict States: Reparations Programmes.\n18 E/CN.4/2005/102/Add.1.\n19 General Assembly resolution 60/147.\n20 E/CN.4/2005/102/Add.1, principle 31.\n21 A/HRC/24/42, para. 20.\n22 Ibid.\n23 See www.ictj.org/publication/education-transitional-justice-opportunities-challenges-peacebuilding.\n24 See the reports of the Special Rapporteur on the promotion of truth, justice, reparation and guarantees\nof non-recurrence and OHCHR, Rule-of-Law Tools for Post-Conflict States.\n25 A/HRC/30/42.\n26 A/HRC/17/21; A/HRC/30/42; OHCHR, Rule-of-Law Tools for Post-Conflict States: Archives.\nA/HRC/34/66/Add.1"},{"id":"a-hrc-34-66-add-1-p0017","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"17","seq":16,"section":"A. International law and practice","text":"The group further recalls that under various sources of international law and United\nNations policy,27 amnesties are impermissible if they prevent prosecution of individuals\nwho may be criminally responsible for war crimes, genocide, crimes against humanity or\nother gross violations of human rights; interfere with victims' right to an effective remedy,\nincluding reparation; or restrict victims' and societies' right to know the truth about\nviolations of human rights and humanitarian law."},{"id":"a-hrc-34-66-add-1-p0018","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"18","seq":17,"section":"B. Framework for accountability for human rights violations in the","text":"Given the severity and complexity of the human rights situation in the Democratic\nPeople's Republic of Korea, a comprehensive and multi-pronged approach is required to\naddress violations, in line with international norms and standards. Investigation and\nprosecution of serious crimes are critical. Additionally, the approach must comprise\nmeasures to ensure the right of victims to reparations, the right of victims and society to\nknow the truth about violations and guarantees of non-recurrence; it must be tailored to the\nspecificities of the situation in the country."},{"id":"a-hrc-34-66-add-1-p0019","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"19","seq":18,"section":"B. Framework for accountability for human rights violations in the","text":"Further, the approach to and measures of accountability must be human rights-based,\nensuring that the rights and needs of victims are at the centre of their design and\nimplementation. They must enable acknowledgement of and reparation for injustice, allow\nfor a dialogue that fosters an understanding of the past, and educate individuals on the\nimportance of justice and human rights. These goals can only be achieved through a fully\nparticipatory process: accountability measures must reflect the experiences and views of\nthose who lived or live in the Democratic People's Republic of Korea and other victims of\nhuman rights violations in the country."},{"id":"a-hrc-34-66-add-1-p0020","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"20","seq":19,"section":"B. Framework for accountability for human rights violations in the","text":"Consultations are particularly effective for victims and affected communities to\nshare priorities for achieving accountability and to ensure ownership and effectiveness of\nmechanisms subsequently established.28 Currently, the lack of access to the country, as well\nas restrictions on the rights to liberty of movement, peaceful assembly, and freedom of\nassociation and expression within the Democratic People's Republic of Korea present\nparticular challenges to conducting consultations among and with those living there.\nNonetheless, awareness-raising, capacity-building and consultation can commence with\nthose who lived in the country and other victims living outside it. The group has sought\nviews on accountability for human rights violations committed in the country from victims\nand affected communities, including individuals who lived in the Democratic People's\nRepublic of Korea and organizations which represent them, and has sought to give voice to\ntheir views in the present report. Considering its limited number of interlocutors within the\nshort duration of its mandate, the group urges that this work continue."},{"id":"a-hrc-34-66-add-1-p0021","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"21","seq":20,"section":"B. Framework for accountability for human rights violations in the","text":"The following paragraphs present some of the key issues and challenges identified\nby the group, to be considered in the design and implementation of any accountability\nmechanisms.\nA/HRC/34/66/Add.1\n1. Unwillingness of the authorities to address the past, and safety concerns"},{"id":"a-hrc-34-66-add-1-p0022","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"22","seq":21,"section":"B. Framework for accountability for human rights violations in the","text":"The Government of the Democratic People's Republic of Korea categorically\nrejected the findings of the commission of inquiry,29 and has not engaged with the group of\nindependent experts. Where there is no demonstrable willingness to address allegations of\nhuman rights violations, and where gross violations are purportedly ongoing,30 efforts to\nensure accountability face serious challenges. These include severe limitations on the\nprocesses of information or evidence gathering, and consulting with victims, affected\ncommunities and civil society within the country, while -- critically -- ensuring their\nsafety. Several interlocutors expressed deep concerns about the safety and well-being of\ntheir relatives and friends in the country, and how this constrained them in pursuing an\naccountability agenda. In the view of the group, any accountability measures must be\npremised on a sound assessment and plans for mitigation of the security risks for victims\nand witnesses.\n2. Different groups of victims, with different needs and expectations"},{"id":"a-hrc-34-66-add-1-p0023","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"23","seq":22,"section":"B. Framework for accountability for human rights violations in the","text":"The Secretary-General,31 the Special Rapporteur on the human rights situation in the\nDemocratic People's Republic of Korea,32 the commission of inquiry, OHCHR33 and civil\nsociety organizations have reported a wide range of gross human rights violations in the\nDemocratic People's Republic of Korea spanning several decades. The group of\nindependent experts highlights the need to acknowledge that different groups of victims\nmay seek different kinds of redress, and to take into consideration these perspectives in\ndesigning appropriate accountability measures while ensuring a non-discriminatory\napproach.34"},{"id":"a-hrc-34-66-add-1-p0024","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"24","seq":23,"section":"B. Framework for accountability for human rights violations in the","text":"Victims underscored the importance of receiving acknowledgment and recognition\nof the wrongs done and the suffering caused to them. Several interlocutors expressed fears\nthat their suffering would be forgotten, and emphasized that addressing impunity and\nproviding redress for violations, whether ongoing or past, are and must be continuing\nconcerns for the international community.\n3. Limited exposure to human rights concepts and practice"},{"id":"a-hrc-34-66-add-1-p0025","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"25","seq":24,"section":"B. Framework for accountability for human rights violations in the","text":"While the Democratic People's Republic of Korea has ratified a number of core\ninternational human rights treaties35 and guarantees some human rights in its Constitution,\npeople within the country are said to have very limited exposure to human rights concepts\nas internationally understood. Furthermore, interlocutors noted that there was minimal\nexperience within the country of seeking accountability for human rights violations before\neffective redress mechanisms."},{"id":"a-hrc-34-66-add-1-p0026","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"26","seq":25,"section":"B. Framework for accountability for human rights violations in the","text":"It is not uncommon for accountability demands to be raised in a context where those\nthat have been most affected have a limited understanding of their rights and of their status\nas rights holders. Such challenges can be overcome by conducting awareness-raising\n29 See http://webtv.un.org/meetings-events/human-rights-council/regular-sessions/25th-\nsession/watch/id-commission-of-inquiry-on-dprk-31st-meeting-25th-regular-session-of-human-rights-\ncouncil/3350537719001.\n30 A/HRC/34/66.\n31 A/71/439.\n32 See www.ohchr.org/EN/HRBodies/SP/CountriesMandates/KP/Pages/SRDPRKorea.aspx;\nA/HRC/22/57.\n33 See http://ohchr.org/Documents/Publications/Report_TORN_APART.pdf.\n34 A/HRC/34/62, para 29.\nA/HRC/34/66/Add.1\ninitiatives, providing information to and undertaking capacity-building of those concerned,\nincluding duty bearers, and by working with representatives of victims' groups.36 In the\ncontext of the Democratic People's Republic of Korea, steps may be initiated despite the\nlack of opportunity to engage with or among individuals within the country, including with\npersons who have left the country. In addition, further reflection is needed on how to make\ninformation available to people within the country about human rights and redress\nmechanisms.37\n4. Complexity of accountability in the Democratic People's Republic of Korea"},{"id":"a-hrc-34-66-add-1-p0027","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"27","seq":26,"section":"B. Framework for accountability for human rights violations in the","text":"Several interlocutors, in particular individuals who have left the Democratic\nPeople's Republic of Korea, highlighted the complexity of attributing responsibility for\nhuman rights violations in the country given their scale, duration and systemic nature.\nThere may be vast numbers of perpetrators, and distinctions between \"perpetrator\" and\n\"victim\" may not always be clear-cut, given that many may have participated in the broader\nsystem of abuse. The group heard of individuals who were compelled to commit crimes to\nensure their own survival, and of different motivations and circumstances that might have\nled to the commission of crimes. Various interlocutors strongly articulated the need for\ndeeper reflection on the concept of responsibility in such a context, and a consequent\ndifferentiation or gradation in the assessment of individual culpability. Some noted that the\nfocus should be on ensuring criminal accountability for those who are responsible for the\nestablishment and maintenance of the system of abuse and that some leniency could be\nshown for others."},{"id":"a-hrc-34-66-add-1-p0028","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"28","seq":27,"section":"B. Framework for accountability for human rights violations in the","text":"Crimes under international law are committed by individuals. However, the pursuit\nof accountability in the Democratic People's Republic of Korea requires a comprehensive\nanalysis of the underlying systems and policies of abuse and the identification both of\nindividuals and institutions directly involved in the commission of heinous acts, and of\nthose who ordered, oversaw, allowed or supported such crimes, in line with internationally\naccepted modes of liability. Such analysis must ultimately feed into a prosecutorial (and\nbroader accountability) strategy that adequately takes into account the range and scope of\nviolations, types and impacts of victimization, and degrees of liability.38\n5. Broader regional dynamics"},{"id":"a-hrc-34-66-add-1-p0029","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"29","seq":28,"section":"B. Framework for accountability for human rights violations in the","text":"Several interlocutors indicated that the human rights situation in the Democratic\nPeople's Republic of Korea is to some extent rooted in or explained by the history of the\nKorean peninsula, and that addressing this situation comprehensively requires a full and\nimpartial examination of historic events on the peninsula and in the subregion, including of\nany allegations of human rights violations."},{"id":"a-hrc-34-66-add-1-p0030","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"30","seq":29,"section":"B. Framework for accountability for human rights violations in the","text":"The group's mandate is limited to accountability issues pertaining to violations\ncommitted in the Democratic People's Republic of Korea. While historic events and actions\nof others may provide important contextual information, they cannot be invoked as a\njustification for any party committing human rights violations or crimes under international\nlaw. That said, the group also believes that the path towards long-term peace and stability\non the Korean peninsula and the broader region is through a genuine, joint and\ncomprehensive accountability exercise involving all regional actors.39\nA/HRC/34/66/Add.1"},{"id":"a-hrc-34-66-add-1-p0031","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"31","seq":30,"section":"V. Mapping of options for accountability for human rights","text":"With a view to making practical recommendations for seeking accountability for\nhuman rights violations in the Democratic People's Republic of Korea, the group of\nindependent experts mapped out certain options."},{"id":"a-hrc-34-66-add-1-p0032","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"32","seq":31,"section":"A. In the Democratic People's Republic of Korea","text":"The Democratic People's Republic of Korea is the primary duty holder of the\nobligation to hold accountable perpetrators of human rights violations committed in the\ncountry. As recalled, States must respond to allegations of human rights violations with a\nprompt, thorough and effective investigation through independent and impartial bodies, and\nbring those found responsible for such violations to justice. Domestic responses and\nremedies are generally preferable, considering their proximity to the victims and access to\nevidence. A review of domestic accountability options is therefore imperative."},{"id":"a-hrc-34-66-add-1-p0033","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"33","seq":32,"section":"A. In the Democratic People's Republic of Korea","text":"The commission of inquiry had questioned whether it was a viable option to seek\naccountability within the country's criminal justice system, as it found that crimes against\nhumanity had been committed pursuant to policies established at the highest level of the\nState.40 The commission found that the security and justice apparatus of the country was\nand remained implicated in human rights violations, including those amounting to crimes\nagainst humanity.41 It highlighted that both the Office of the Prosecutor and the court\nsystem had important functions in legitimizing human rights violations, as they were used\nto prosecute and punish persons for political wrongdoing in a legal process involving\nfundamentally unfair trials, and therefore also carried institutional responsibility. 42 It\ndetermined that, absent profound institutional reforms, the country's institutions were\nneither willing nor able to effectively investigate and prosecute crimes against humanity.43"},{"id":"a-hrc-34-66-add-1-p0034","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"34","seq":33,"section":"A. In the Democratic People's Republic of Korea","text":"The Human Rights Committee also raised serious concerns regarding the country's\njustice system and its response to allegations of human rights violations. These related, inter\nalia, to the constitutional and legislative provisions that endanger the impartiality and\nindependence of the judiciary; the vague and subjective formulation of certain crimes, in\nparticular where they are punishable with the death penalty; the \"consistent and\nsubstantiated\" allegations of ill-treatment and torture by law enforcement personnel; and\nthe compatibility of pretrial detention practices and investigation procedures with the\nInternational Covenant on Civil and Political Rights.44"},{"id":"a-hrc-34-66-add-1-p0035","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"35","seq":34,"section":"A. In the Democratic People's Republic of Korea","text":"The group of independent experts acknowledges that in 2016, the Democratic\nPeople's Republic of Korea ratified the Convention on the Rights of Persons with\nDisabilities; submitted its combined second, third and fourth periodic reports to the\nconference to consider a final peaceful settlement. \"Report of the detailed findings\", paras. 1222;\n1225 (j).\n40 Ibid., para. 1160.\n41 Ibid., para. 1167.\n42 Ibid., paras. 1173-1174.\n43 Ibid., para. 1199.\n44 CCPR/CO/72/PRK. The commission of inquiry similarly referred to constitutional and legal\nprovisions that violate the principle of legality and severely affect the independence and impartiality\nof the judiciary (paras. 123-124). See also Korea Institute for National Unification, 2016 White Paper\non Human Rights in North Korea, pp. 142-169.\nA/HRC/34/66/Add.1\nCommittee on the Elimination of Discrimination against Women,45 and its combined fifth\nand sixth reports to the Committee on the Rights of the Child. 46 The common core\ndocument states that \"there is a system of compensation for damage for the citizens whose\nrights are violated, which are civil compensation and criminal compensation\".47 Further, in\nthe strategic framework for cooperation between the United Nations and the Democratic\nPeople's Republic of Korea 2017-2021,48 the Government and the United Nations agreed\nthat a human rights-based approach will be applied in the formulation and implementation\nof United Nations programmes and projects. It also provides for United Nations support to\nthe Government in implementing its commitments under a variety of human rights\nconventions and processes."},{"id":"a-hrc-34-66-add-1-p0036","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"36","seq":35,"section":"A. In the Democratic People's Republic of Korea","text":"The group also notes that in 2014, the Democratic People's Republic of Korea\naccepted recommendations made during the second universal periodic review that are\ndirectly related to the issue of accountability. For example, it committed to take all\nnecessary measures to prevent or punish violations of human rights, and ensure the fight\nagainst impunity for the perpetrators of crimes, acts of violence and all human rights\nviolations; create a national mechanism for the review of complaints of the population\nconcerning human rights violations; enshrine fully the right to fair trial and due process\nguarantees; and further strengthen the independence of the judiciary.49"},{"id":"a-hrc-34-66-add-1-p0037","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"37","seq":36,"section":"A. In the Democratic People's Republic of Korea","text":"In 2014, the Government agreed to set up a special investigation committee to\nconduct comprehensive investigations on all Japanese nationals in the country, including\nvictims of abductions and other missing persons, and committed to the objectivity and\ntransparency of the investigation. 50 Although this committee commenced its work, it\nappears that no substantial progress or investigative results had been communicated to\nJapan by early 2016. Following the January 2016 nuclear tests and the February launch by\nthe Democratic People's Republic of Korea using ballistic missile technology, and the\nadoption of \"autonomous measures\" by Japan in response 51 , the Democratic People's\nRepublic of Korea stated that it would stop the comprehensive investigation and that the\ncommittee would be dissolved.52"},{"id":"a-hrc-34-66-add-1-p0038","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"38","seq":37,"section":"A. In the Democratic People's Republic of Korea","text":"In conclusion, despite the commitments described above, the group has no\ninformation indicating that viable domestic options for seeking accountability for human\nrights violations currently exist or have been used in the Democratic People's Republic of\nKorea. Furthermore, the range of acts criminalized under domestic law appears\ninsufficiently broad to capture the gravity of the allegations contained in the report of the\ncommission of inquiry. For example, while the law in the Democratic People's Republic of\nKorea treats some of the underlying acts of crimes against humanity as criminal offences,\nsuch as murder,53 deprivation of liberty,54 rape55 or abduction,56 it contains no provisions\nA/HRC/34/66/Add.1\ncapturing the specific context and nature of crimes against humanity (i.e., acts committed in\nthe context of a widespread or systematic attack against any civilian population)."},{"id":"a-hrc-34-66-add-1-p0039","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"39","seq":38,"section":"B. In other domestic systems","text":"The group of independent experts examined whether other domestic legal systems\nprovide avenues for redressing human rights violations in the Democratic People's\nRepublic of Korea, in particular crimes against humanity.\n1. Republic of Korea, Japan and China"},{"id":"a-hrc-34-66-add-1-p0040","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"40","seq":39,"section":"B. In other domestic systems","text":"In considering accountability options for violations in the Democratic People's\nRepublic of Korea, possible avenues within the legal systems of the Republic of Korea,\nJapan and China merit particular attention, given that nationals of these countries have been\nvictims of human rights violations in the Democratic People's Republic of Korea; that\nviolations may have been (partially) committed on their territories; and/or that they host\nsizeable groups of people who have lived in the Democratic People's Republic of Korea,\nincluding potential victims and perpetrators of and witnesses to human rights violations.\nThe group met with stakeholders in Seoul and Tokyo to seek information about\naccountability processes in those countries. It regrets that the Permanent Representatives of\nChina in Geneva and New York were not able to meet with it, and that its request for\npermission to visit China remained unanswered.57\nCriminal justice"},{"id":"a-hrc-34-66-add-1-p0041","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"41","seq":40,"section":"B. In other domestic systems","text":"The criminal laws of all three States include relevant substantive legal provisions.\nThe Republic of Korea ratified the Rome Statute of the International Criminal Court on 13\nNovember 2002 and Japan acceded to it on 17 July 2007, and both countries adopted\nimplementing domestic legislation regulating cooperation with the Court.58 Whereas the\nRepublic of Korea incorporated the crimes contained in the Rome Statute (genocide, crimes\nagainst humanity and war crimes) into domestic criminal law, Japan deemed that its Penal\nCode already covered them under its common criminal law provisions. China has not\nratified the Rome Statute, nor does its Criminal Code cover genocide, crimes against\nhumanity and the full range of war crimes.59 Whereas all three countries have ratified or\nacceded to the Convention against Torture and Other Cruel, Inhuman or Degrading\nTreatment or Punishment, United Nations treaty bodies have raised concerns with respect to\nthe definition of torture (or the lack thereof) in their domestic laws.60 Japan is the only one\nto have ratified the International Convention for the Protection of All Persons from\nEnforced Disappearance, although the crime of \"enforced disappearance\" does not appear\nto be expressly incorporated in its domestic legislation. 61 While common criminal law\nprovisions such as murder, rape or kidnapping could be invoked to prosecute certain human\nrights violations committed in the Democratic People's Republic of Korea, they may not\nalways adequately cover the extent or specificity of the facts, in particular where these\n57 Letter dated 24 October 2016.\n58 Republic of Korea: Act on the Punishment, etc. of Crimes within the Jurisdiction of the International\nCriminal Court (Law No. 8719, 21 December 2007); Japan: Act on Cooperation with the International\nCriminal Court (Act No. 37, 11 May 2007).\n59 China ratified the Convention on the Prevention and Punishment of the Crime of Genocide in 1983\nand its Criminal Code includes a number of war crimes (arts. 446; 448).\n60 CAT/C/KOR/CO/2, para. 4; CCPR/C/KOR/CO/4, para 26; CAT/C/JPN/CO/2, para. 7;\nCAT/C/CHN/CO/5, para. 7.\n61 See www.ohchr.org/Documents/HRBodies/CED/StatesReportsarticle29/Japan22July2016.pdf.\nA/HRC/34/66/Add.1\namount to crimes against humanity. The group therefore encourages the Republic of Korea,\nJapan and China to ensure that all crimes under international law are fully incorporated into\ntheir domestic laws."},{"id":"a-hrc-34-66-add-1-p0042","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"42","seq":41,"section":"B. In other domestic systems","text":"All three legal systems allow courts to exercise criminal jurisdiction further to the\nprinciples of territoriality and active personality, meaning that crimes committed (in whole\nor in part) on their territories, as well as crimes committed by their nationals on the territory\nof the Democratic People's Republic of Korea, could be prosecuted. 62 The Japanese\nauthorities have thus conducted investigations into certain abductions (from Japan) of\nJapanese citizens involving the Democratic People's Republic of Korea and into other\nalleged disappearances in which the possibility of such abduction could not be ruled out,\nand issued some arrest warrants.63 Interlocutors highlighted the potential implication of the\nprinciples of territoriality and active personality in the Republic of Korea given that the\ncountry's Constitution and laws provide that the entire Korean peninsula forms part of its\nterritory and that all Koreans are nationals of the Republic of Korea. However, prosecution\non this basis alone seems tenuous as the Democratic People's Republic of Korea is\nrecognized as a sovereign State under international law and a State Member of the United\nNations, and inter-Korean political agreements state that the two countries acknowledge\neach other as parties aiming for peaceful unification.64"},{"id":"a-hrc-34-66-add-1-p0043","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"43","seq":42,"section":"B. In other domestic systems","text":"All three legal systems also allow prosecution in their courts when the victim of the\ncrime is their national (passive personality), 65 and recognize some form of universal\njurisdiction. On the basis of the passive personality principle, Japan could open\ninvestigations into crimes against its nationals in the Democratic People's Republic of\nKorea, but the group is unaware of any such instances. Japanese law also recognizes the\nprinciple of universal jurisdiction for a limited range of crimes.66 Through its International\nCriminal Court implementation law, the Republic of Korea provided for jurisdiction for\nRome Statute crimes committed by a foreign national outside the Republic of Korea where\nthe perpetrator is present in the country.67 While the Chinese Criminal Code also includes a\nuniversal jurisdiction clause with respect to crimes stipulated in international treaties\nconcluded or acceded to by China,68 crimes against humanity, enforced disappearances and\ntorture do not currently fall into this category.69"},{"id":"a-hrc-34-66-add-1-p0044","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"44","seq":43,"section":"B. In other domestic systems","text":"Additional challenges remain with regard to the investigation and prosecution of\ncrimes in these jurisdictions pertaining to human rights violations in the Democratic\nPeople's Republic of Korea. The first concerns the compromised access to evidence and\nsuspects. Despite the Japanese authorities having identified a number of suspects in the\nA/HRC/34/66/Add.1\nabduction cases, prosecutions cannot be initiated until the suspects are apprehended or\nextradited, given that Japanese courts do not hold in absentia trials.70 Similar challenges\narise in the Republic of Korea. For example, a petition that sought the release of relatives of\nthe petitioners allegedly detained in the Democratic People's Republic of Korea was\ndismissed on the grounds that the petition had to be filed in the district court of the\ndetainee's locality, that it could not meet the legal requirements with respect to hearing the\npetition, and that any ruling granting the petition could not be enforced.71"},{"id":"a-hrc-34-66-add-1-p0045","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"45","seq":44,"section":"B. In other domestic systems","text":"Second, challenges arise given the application of statutes of limitations for some\ncrimes (in particular where they cannot be framed as crimes against humanity). Third, the\nexistence of immunities and a narrower range of modes of liability in domestic law, in\nparticular with respect to command and superior responsibility, may present challenges in\nbringing cases against higher-level officials. Finally, all three jurisdictions retain the death\npenalty, which may constitute an obstacle for any future collaboration with United Nations-\nassisted accountability mechanisms.72\nOther accountability mechanisms"},{"id":"a-hrc-34-66-add-1-p0046","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"46","seq":45,"section":"B. In other domestic systems","text":"In Japan, victims of human rights infringements and other relevant parties may file\nrequests for relief with the Japan Federation of Bar Associations, which can issue a\nwarning, recommendation or request to the infringing institution or organization. Such\npronouncements are considered to have a strong influence, and the procedure is not limited\nby statutes of limitations, as criminal proceedings may be.73"},{"id":"a-hrc-34-66-add-1-p0047","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"47","seq":46,"section":"B. In other domestic systems","text":"In the Republic of Korea, the National Human Rights Commission established a\ncentre for human rights violations and a human rights archive to systematically document\nand maintain records of human rights violations in the Democratic People's Republic of\nKorea for use in future accountability and reparations processes and for human rights\neducation. While the Commission may receive complaints from individuals who have left\nthe Democratic People's Republic of Korea, it cannot consider them without access to the\nsuspected perpetrator."},{"id":"a-hrc-34-66-add-1-p0048","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"48","seq":47,"section":"B. In other domestic systems","text":"The new North Korean Human Rights Act of the Republic of Korea established,\ninter alia, the Centre for Investigation and Documentation on Human Rights in North\nKorea, to collect, research, preserve, publish or otherwise deal with materials and\ninformation pertaining to human rights in the Democratic People's Republic of Korea.\nThese materials must be transferred to the Ministry of Justice every three months, including\nfor possible future legal proceedings. Several civil society organizations, including in the\nRepublic of Korea and Japan, also work with people who have left the Democratic People's\nRepublic of Korea to collect testimonies and undertake valuable research with respect to\nhuman rights violations in that country."},{"id":"a-hrc-34-66-add-1-p0049","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"49","seq":48,"section":"B. In other domestic systems","text":"In anticipation of their use in possible future criminal proceedings or other\naccountability processes, the group encourages all organizations and institutions that gather\ninformation concerning human rights violations in the Democratic People's Republic of\n70 The group was informed that in absentia trials may be problematic owing to article 32 of the\nConstitution, which guarantees the right of access of persons to courts.\n71 Seoul Central District Court, case No. 2016IN3, judgment of 24 October 2016.\n72 United Nations Juridical Yearbook 2007, part two, chap. VI.A.8(a), paras. 6-7.\n73 See, for example, the petition by 12 individuals, against, inter alia, Japan and the Democratic People's\nRepublic of Korea, to request an investigative committee to examine the causes of human rights\nviolations associated with the repatriation programme for Korean residents in Japan that began in\n1959 (\"Paradise on Earth\") and make recommendations for reparations. The matter remains under\nconsideration. See http://koreaofall.com/summary2.php?&lang=en.\nA/HRC/34/66/Add.1\nKorea to coordinate their efforts and ensure that sound methodologies and protocols for the\ncollection of evidentiary materials are in place, that protection concerns of victims and\nwitnesses are fully met and that their consent is adequately sought and recorded.\n2. In other States"},{"id":"a-hrc-34-66-add-1-p0050","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"50","seq":49,"section":"B. In other domestic systems","text":"Courts in other States may provide avenues to seek accountability for crimes under\ninternational law committed in the Democratic People's Republic of Korea,74 including\nwhere the principle of universal jurisdiction is recognized. However, most States require at\nleast the presence of a suspected perpetrator on their territory to activate an investigation or\nprosecution. Another possible avenue would be through strategic litigation in foreign\njurisdictions 75 or in regional courts, for example in relation to human rights abuses\ncommitted outside the Democratic People's Republic of Korea by third parties, including\nbusiness enterprises, if these are attributable to the State76 and initiated within the country.\nThe group encourages civil society and public interest lawyers to explore such possibilities,\nin particular where they involve violations committed in the Democratic People's Republic\nof Korea."},{"id":"a-hrc-34-66-add-1-p0051","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"51","seq":50,"section":"C. International and internationally assisted courts","text":"Strong calls continue to be made for the Security Council to refer the situation in the\nDemocratic People's Republic of Korea to the International Criminal Court,77 arguing that\nrecourse to an existing institution provides the most expedient approach to achieve\naccountability for human rights violations committed in the country."},{"id":"a-hrc-34-66-add-1-p0052","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"52","seq":51,"section":"C. International and internationally assisted courts","text":"Even without such a referral, 78 or the Democratic People's Republic of Korea\nratifying the Rome Statute or accepting the Court's jurisdiction, the Court may exercise\njurisdiction following referral of a State party79 or at the initiative of the Prosecutor,80\nincluding on the basis of communications received from civil society. For example, the\nOffice of the Prosecutor evaluated whether two incidents in 2010 in the Yellow Sea could\namount to war crimes under the jurisdiction of the Court. The Prosecutor concluded that the\nrequirements for seeking authorization from the Trial Chamber to initiate an investigation\nof the situation in the Republic of Korea had in this case not been satisfied.81"},{"id":"a-hrc-34-66-add-1-p0053","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"53","seq":52,"section":"C. International and internationally assisted courts","text":"Regardless of how the International Criminal Court acquires jurisdiction of the\nsituation in the Democratic People's Republic of Korea, practical challenges -- including\nresource constraints and the number of cases that can be examined -- will imply that many\nserious crimes will not be tried. Additionally, since the Court has jurisdiction only with\nA/HRC/34/66/Add.1\nrespect to crimes committed after the entry into force of the Rome Statute,82 on 1 July 2002,\nit cannot address a considerable number of crimes against humanity described in the\ncommission of inquiry's report that occurred earlier. In this regard, several interlocutors\nraised a question as to whether the Court could exercise jurisdiction over crimes that had\ncommenced prior to the entry into force of the Rome Statute but were continuing (e.g., with\nrespect to enforced disappearances, considering that the detention or abduction has not been\nacknowledged, or that the fate of the victim has not been clarified).83"},{"id":"a-hrc-34-66-add-1-p0054","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"54","seq":53,"section":"C. International and internationally assisted courts","text":"This legal question is contested but not settled.84 With respect to the crime against\nhumanity of enforced disappearance specifically, some refer to note 24 of the elements of\ncrime of the Rome Statute85 to argue that the jurisdiction of the International Criminal\nCourt is limited to cases where the initial arrest, detention or abduction occurred after the\nentry into force of the Statute.86 Others highlight that the language in the elements of crime\nwas a careful compromise and that proposed language to explicitly state that the arrest,\ndetention, abduction and refusal all had to occur after the entry into force of the Rome\nStatute did not find general agreement.87 The compromise text therefore states that what\nmust occur after the entry into force is the \"widespread or systematic attack on any civilian\npopulation\", i.e., the broader context of the crime against humanity. An argument could\ntherefore be made that the International Criminal Court has jurisdiction in cases where part\nof the conduct occurred prior to entry into force of the Rome Statute, as long as it forms\npart of an \"attack\" on the civilian population that took place, or continued, after its entry\ninto force.88 The group encourages further examination of this question, including by the\nOffice of the Prosecutor.89\n2. Hybrid or internationally assisted justice mechanisms"},{"id":"a-hrc-34-66-add-1-p0055","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"55","seq":54,"section":"C. International and internationally assisted courts","text":"The commission of inquiry dismissed the option of a hybrid court (involving\ninternational and Democratic People's Republic of Korea prosecutors and judges) as in its\nview consent from the concerned country would be unlikely, and judges of the Democratic\nPeople's Republic of Korea would lack the impartiality and independence necessary to\n82 Rome Statute, art. 11.\n83 See, e.g., Working Group on Enforced or Involuntary Disappearances (A/HRC/16/48, para. 39);\nCommittee on Enforced Disappearances (A/69/56); Human Rights Committee, communication No.\n1033/2001, Singarasa v. Sri Lanka, views adopted on 21 July 2004, para. 6.3.\n84 W. Schabas, The International Criminal Court: A Commentary on the Rome Statute (Oxford\nUniversity Press, 2016), p. 557.\n85 \"This crime falls under the jurisdiction of the Court only if the [widespread or systematic attack\ndirected against a civilian population, of which the conduct forms part] occurs after the entry into\nforce of the Statute.\"\n86 Schabas, The International Criminal Court, p. 342.\n87 G. Witschel and W. R�ckert, \"Article 7 (1) (I) - Crime against humanity of enforced disappearance of\npersons\", in R.S. Lee, ed., The International Criminal Court, Elements of Crimes and Rules of\nProcedure and Evidence (Transnational Publishers, 2001), p. 102.\n88 A. Nissel, \"Continuing crimes in the Rome Statute\", Michigan Journal of International Law, vol. 25\n(2004), p. 670. See also http://lib.kinu.or.kr//wonmun/007/0001477557.pdf. Additionally, the\ncommission of inquiry noted that no such jurisdictional limits apply to the crime against humanity of\nimprisonment and other severe deprivations of liberty in violation of fundamental rules of\ninternational law, which are often also committed in connection with international abductions. On this\nbasis, crimes against humanity related to international abductions could also potentially fall under the\njurisdiction of the International Criminal Court (\"Report of the detailed findings\", note 1673).\n89 Some interlocutors also suggested that certain countries could consider a separate or joint referral to\nthe International Criminal Court regarding abductions that occurred on their territories, arguing that\nthe crimes have continued beyond 2002.\nA/HRC/34/66/Add.1\ncarry out criminal trials that would likely involve senior officials as defendants.90 The group\nhas not received information indicating that this situation has changed, and deems that any\nhybrid tribunal involving personnel from the Democratic People's Republic of Korea\njustice system would first require complete reform of the system."},{"id":"a-hrc-34-66-add-1-p0056","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"56","seq":55,"section":"C. International and internationally assisted courts","text":"The group notes that the Democratic People's Republic of Korea and the Republic\nof Korea have adopted official State policies that aim for unification and that reflection is\nongoing as to the implications of unification on the two justice systems. 91 The group\nrecommends that a comprehensive accountability agenda be included in those reflections\nand that international expertise on best practice be sought where needed, including on a\npossible internationally assisted domestic court in a unification scenario."},{"id":"a-hrc-34-66-add-1-p0057","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"57","seq":56,"section":"C. International and internationally assisted courts","text":"Hybrid or internationally assisted courts involving domestic justice systems other\nthan that of the Democratic People's Republic of Korea could also be considered. However,\nthis would require addressing potential legitimacy concerns, in particular if its jurisdiction\nwere to include crimes committed entirely in the Democratic People's Republic of Korea.\nFor example, the creation of an international hybrid court involving countries whose\nnationals have been victims of abductions involving the Democratic People's Republic of\nKorea may merit further reflection, in particular in the absence of a referral of the situation\nin the country to the International Criminal Court or the creation of an ad hoc international\ntribunal.\n3. Ad hoc international tribunal"},{"id":"a-hrc-34-66-add-1-p0058","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"58","seq":57,"section":"C. International and internationally assisted courts","text":"The commission of inquiry recommended that the Security Council create an ad hoc\ninternational tribunal should the situation in the Democratic People's Republic of Korea not\nbe referred to the International Criminal Court,92 with jurisdiction extending prior to July\n2002 to comprehensively address crimes against humanity in the Democratic People's\nRepublic of Korea. It also highlighted the required substantial resource commitments and\ninstitutional planning.93 The Special Rapporteur has also raised the option of an ad hoc\ninternational tribunal.94 Given the limitations and challenges identified above in seeking\naccountability in domestic systems or through hybrid tribunals involving the Democratic\nPeople's Republic of Korea, the group concurs that the creation of an ad hoc international\ntribunal must be examined."},{"id":"a-hrc-34-66-add-1-p0059","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"59","seq":58,"section":"C. International and internationally assisted courts","text":"A dedicated international tribunal for the Democratic People's Republic of Korea\nwould allow the temporal, territorial, personal and subject-matter jurisdiction to be\ncalibrated to meet the needs and aspirations of the victims, without the jurisdictional\nconstraints of the International Criminal Court or domestic courts. It could function as a\nrepository of information and evidence, and serve as a catalyst for other justice initiatives at\ndomestic level.95 If the tribunal were to undertake real outreach96 to communities across the\nDemocratic People's Republic of Korea, it would enable much-needed awareness-raising\nA/HRC/34/66/Add.1\nand education on human rights and justice issues, thereby contributing to the transformation\nof society in the Democratic People's Republic of Korea into one based on the rule of law."},{"id":"a-hrc-34-66-add-1-p0060","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"60","seq":59,"section":"C. International and internationally assisted courts","text":"However, the establishment of an ad hoc international tribunal would face several\nchallenges. Firstly, the concerned country may not consent to its creation, or collaborate\nwith it. Proceeding in such circumstances is not unprecedented, 97 but the tribunal's\neffectiveness in collecting evidence and accessing suspects, and ultimately in bringing\ncases to trial, may be hampered. 98 The security of victims and witnesses, as well as\nmeaningful outreach and domestic impact, could also be affected."},{"id":"a-hrc-34-66-add-1-p0061","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"61","seq":60,"section":"C. International and internationally assisted courts","text":"Secondly, international tribunals are costly and lengthy endeavours. The genuine\nand sustained commitment of the international community from the outset would be\ncritical, including in terms of funding. Thirdly, initiatives will be required to ensure that,\ngiven the historical and regional context, the tribunal is perceived as legitimate. This\nincludes ensuring that sources of funding for the tribunal and the selection of judges,\nprosecutors and staff do not compromise its legitimacy. The same concern applies to\nidentifying an appropriate location for the tribunal, ensuring it is as close as possible to the\nsources of evidence, including victims and witnesses, while taking into account security\nconcerns."},{"id":"a-hrc-34-66-add-1-p0062","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"62","seq":61,"section":"D. International human rights mechanisms","text":"International human rights mechanisms, including the Human Rights Council and its\nspecial procedure mandate holders, the universal periodic review and bodies created under\nthe international human rights treaties to monitor States parties' compliance with their\ntreaty obligations, can contribute to accountability for human rights violations in the\nDemocratic People's Republic of Korea."},{"id":"a-hrc-34-66-add-1-p0063","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"63","seq":62,"section":"D. International human rights mechanisms","text":"Forthcoming concluding observations adopted pursuant to the examination of State\nreports to the treaty bodies mentioned above will include practical advice on steps to\nimplement the rights contained in each particular treaty. Further, mandate holders can\nintervene directly with the country on allegations of human rights violations that come\nwithin the respective mandates by means of letters.99 The Working Group on Arbitrary\nDetention has adopted opinions on cases concerning the Democratic People's Republic of\nKorea, 100 and the Working Group has indicated that there are 110 outstanding cases\ntransmitted to the Government concerning persons allegedly abducted from a number of\ncountries, including in the 1950s.101"},{"id":"a-hrc-34-66-add-1-p0064","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"64","seq":63,"section":"E. Sanctions regimes","text":"Sanctions regimes have been imposed on the Democratic People's Republic of\nKorea by the Security Council in response to its nuclear and ballistic missile tests,102 as well\n97 See establishment of the International Criminal Tribunal for the Former Yugoslavia or the Security\nCouncil referrals of the Sudan (Darfur) and Libya to the International Criminal Court.\n98 Experience with conducting in absentia trials before international tribunals is limited and their\neffectiveness is debated. See, for example, M. Trad, \"Trials in absentia at the Special Tribunal for\nLebanon: an effective measure of expediency or an inconsistence with fair trial standards?\", SOAS\nLaw Journal, vol. 3, No. 1 (February 2016), p. 38.\n99 See, for example, A/HRC/32/53; A/HRC/26/21; A/HRC/22/67; A/HRC/18/51.\n100 See, for example, A/HRC/WGAD/2015/29; A/HRC/WGAD/2015/32.\n101 A/HRC/33/51; A/HRC/WGEID/110/1.\n102 Most recently in resolution 2321 (2016).\nA/HRC/34/66/Add.1\nas by the Republic of Korea, Japan, the European Union and the United States, among\nothers. Additionally, the United States has announced specific sanctions targeting\nindividuals and entities it deems responsible for human rights violations in the Democratic\nPeople's Republic of Korea.103"},{"id":"a-hrc-34-66-add-1-p0065","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"65","seq":64,"section":"E. Sanctions regimes","text":"The group recalls the recommendation of the commission of inquiry that the\nSecurity Council adopt targeted sanctions against those who appear to be most responsible\nfor crimes against humanity, and that the commission did not support sanctions imposed by\nthe Council or introduced bilaterally that are targeted against the population or the economy\nas a whole.104 Subsequently, the General Assembly encouraged the Council to consider the\nscope for effective targeted sanctions against those who appear to be most responsible for\nacts that the commission had said might constitute crimes against humanity.105"},{"id":"a-hrc-34-66-add-1-p0066","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"66","seq":65,"section":"F. Office of the United Nations High Commissioner for Human Rights","text":"OHCHR has an important role to play with regard to taking steps towards ensuring\naccountability for human rights violations in the Democratic People's Republic of Korea, as\nan independent and impartial office that can collect, preserve and analyse information,\nincluding for the international community.106 It also supports international human rights\nmechanisms. In addition, it has established a field-based structure in Seoul pursuant to\nHuman Rights Council resolution 25/25, to conduct monitoring and documentation of the\nsituation of human rights in the country to ensure accountability; to enhance engagement\nand capacity-building with the Governments of all States concerned, civil society and other\nstakeholders; and to maintain visibility of the situation of human rights."},{"id":"a-hrc-34-66-add-1-p0067","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"67","seq":66,"section":"G. Civil society and public interest group initiatives","text":"Civil society and public interest groups regionally and internationally play an\nimportant role in advocating for accountability measures. They can assist victims in\nbringing complaints about human rights violations; convene expert meetings to inform\ndiscussions about accountability measures, including drawing on similar experiences in the\nregion or internationally; and hold mock trials or people's tribunals to raise public\nawareness of the scope of allegations.107 Civil society organizations also have a role in\nhuman rights education and awareness-raising on human rights, and providing psychosocial\nassistance. Such efforts help create conditions conducive to individuals formulating justice\ndemands.\nA/HRC/34/66/Add.1"},{"id":"a-hrc-34-66-add-1-p0068","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"68","seq":67,"section":"VI. Conclusions and recommendations","text":"International norms and standards require that those responsible for human\nrights violations in the Democratic People's Republic of Korea, in particular for\ncrimes against humanity, be held accountable. Accountability is a legal requirement.\nIn addition, accountability processes hold the potential to restore the position of\nvictims in society as rights holders and to transform society into one based on the rule\nof law and respect for the dignity of all, and thereby contribute to long-term peace\nand stability. Ensuring accountability for such crimes \"is an international as much as\na Korean challenge and requires the international community to play a role\".108"},{"id":"a-hrc-34-66-add-1-p0069","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"69","seq":68,"section":"VI. Conclusions and recommendations","text":"The approach to pursuing accountability for human rights violations in the\nDemocratic People's Republic of Korea must be multi-pronged and comprehensive,\nand in line with international norms and standards. Investigation and prosecution of\nserious crimes are indispensable, as are measures to ensure the right of victims and\nsocieties to know the truth about violations, the right of victims to reparations, and\nguarantees of non-recurrence of violations. It will require coordinated efforts in\nmultiple forums, including courts. All accountability measures must be based on solid\ndocumentation."},{"id":"a-hrc-34-66-add-1-p0070","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"70","seq":69,"section":"VI. Conclusions and recommendations","text":"International human rights law and practice in other States indicate that\nreflections on accountability should start at an early stage, and that they should place\nvictims at the centre of the design and implementation of accountability measures. It\nis imperative for any accountability measure to take into account the experiences and\nviews of persons within the Democratic People's Republic of Korea, those who have\nleft the country and other victims of human rights violations committed in the\ncountry. Specific attention should be paid to groups identified by the commission of\ninquiry and others as having been particularly affected, including women. 109\nConsultations are an effective way to allow victims and affected communities to share\ntheir priorities for achieving accountability, and to ensure ownership, legitimacy and\neffectiveness of the mechanisms that are subsequently established."},{"id":"a-hrc-34-66-add-1-p0071","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"71","seq":70,"section":"VI. Conclusions and recommendations","text":"The pursuit of accountability is particularly challenging in the context of the\nDemocratic People's Republic of Korea. The Government denies allegations of human\nrights violations and refuses to collaborate with the international community in\naddressing them. The lack of access to the country, restrictions on the rights to\nfreedom of movement and expression of its people, and the security risks for those\nliving in the Democratic People's Republic of Korea must be factored into reflections\non accountability measures. The severity, duration, complexity and systemic nature of\nthe alleged violations present unique challenges."},{"id":"a-hrc-34-66-add-1-p0072","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"72","seq":71,"section":"VI. Conclusions and recommendations","text":"The group of independent experts has no information indicating that viable\noptions for accountability exist or have been used in the Democratic People's Republic\nof Korea. A fundamental reform of its justice system would be needed, including\nchanges to legislative and institutional frameworks and safeguards, and a vetting\nprocess of law enforcement and justice officials."},{"id":"a-hrc-34-66-add-1-p0073","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"73","seq":72,"section":"VI. Conclusions and recommendations","text":"Hybrid models involving the Democratic People's Republic of Korea or its\njustice personnel cannot currently be envisaged given the lack of impartiality and\nindependence of the judiciary and its alleged implication in the commission of human\nrights violations.\n108 A/HRC/31/70 and Corr.1, para. 23.\n109 For example, A/HRC/25/63, paras. 35-36.\nA/HRC/34/66/Add.1"},{"id":"a-hrc-34-66-add-1-p0074","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"74","seq":73,"section":"VI. Conclusions and recommendations","text":"While other domestic legal systems, in particular in the Republic of Korea,\nJapan and China, offer some legal bases for investigations and prosecutions of crimes\ncommitted in whole or in part in the Democratic People's Republic of Korea, they face\nlegal, political and practical challenges."},{"id":"a-hrc-34-66-add-1-p0075","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"75","seq":74,"section":"VI. Conclusions and recommendations","text":"The International Criminal Court could initiate investigations and prosecutions\nof some high-level perpetrators, notably upon referral by the Security Council. This\navenue must continue to be pursued. The Court is an existing institution created for\naddressing situations such as the one in the Democratic People's Republic of Korea,\nwhere crimes against humanity are alleged to have occurred and where national\nauthorities are unable and/or unwilling to respond adequately. The Court provides an\nimportant avenue to hold accountable those most responsible for gross human rights\nviolations that may amount to crimes under the Rome Statute, particularly\nconsidering its experience with evidence gathering in challenging environments and its\nvictim and witness protection schemes."},{"id":"a-hrc-34-66-add-1-p0076","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"76","seq":75,"section":"VI. Conclusions and recommendations","text":"The crimes described in the report of the commission of inquiry are of a gravity\nrarely seen, involving systems of abuse that have been operating for decades. These\ncrimes are of international concern and cannot go unpunished. Considering the sheer\nnumber of crimes and perpetrators, the prosecution of some high-level perpetrators at\nthe International Criminal Court must be complemented by other criminal\naccountability processes."},{"id":"a-hrc-34-66-add-1-p0077","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"77","seq":76,"section":"VI. Conclusions and recommendations","text":"The group of independent experts believes that the unique context in the\nDemocratic People's Republic of Korea requires the international community to\nenhance efforts to lay the groundwork for future criminal trials. Regardless of the\nchallenges, the international community should also duly consider the scope for\nestablishment of an ad hoc international tribunal for the Democratic People's\nRepublic of Korea, including as a deterrent for future crimes and a signal that victims\nwill be heard. Preparatory and practical steps are laid out below.110"},{"id":"a-hrc-34-66-add-1-p0078","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"78","seq":77,"section":"VI. Conclusions and recommendations","text":"Within a comprehensive strategy to account for the past, truth-seeking\nprocesses serve an important role. While the conditions are not yet in place to\nconsider designing a truth-seeking mechanism in the Democratic People's Republic of\nKorea itself, including with respect to political will and the possibility for victims to\nparticipate in a secure environment, 111 reflection and broad consultation on such\nfuture processes must commence."},{"id":"a-hrc-34-66-add-1-p0079","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"79","seq":78,"section":"VI. Conclusions and recommendations","text":"The group of independent experts recalls the commission of inquiry's\nrecommendations regarding sanctions, and equally cautions against any unilateral\nmeasure not in accordance with international law or that impedes the full realization\nof human rights in the Democratic People's Republic of Korea.112"},{"id":"a-hrc-34-66-add-1-p0080","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"80","seq":79,"section":"VI. Conclusions and recommendations","text":"The group of independent experts identified the following practical steps that\ncan be taken immediately to contribute to a comprehensive approach towards\naccountability in the Democratic People's Republic of Korea, in line with\ninternational standards:\nA/HRC/34/66/Add.1\n(a) Adopting a human rights-based and comprehensive approach to\naccountability, placing the rights and needs of victims at the centre of the design and\nimplementation of accountability processes;\n(b) Raising awareness of victims and affected communities about their\nrights, notably the right to effective remedy for human rights violations, including\nthrough media, communications and education campaigns, enabling them to\nformulate demands for justice in line with international norms and standards;\n(c) Undertaking coordinated and comprehensive consultations with victims\nand other relevant stakeholders, starting with those living outside the Democratic\nPeople's Republic of Korea, to seek their views on accountability for human rights\nviolations in the country, while taking measures to ensure the security of participants\nand minimize the risk of retraumatization;\n(d) Placing the issue of accountability for human rights violations in the\nDemocratic People's Republic of Korea into broader regional debates on\naccountability and strengthening of the rule of law, including by providing regional\nplatforms for discussion and development of expertise in addressing past violations,\nfostering regional awareness and cooperation, as well as opportunities for people-to-\npeople dialogue;113\n(e) Ensuring continued information and evidence gathering, using sound\nmethodologies and protocols that respect international norms and standards,\nincluding with regard to victim and witness protection, consent and confidentiality;\n(f) Preserving and storing information and evidence gathered in a central\nand independent repository to channel information to appropriate accountability\nmechanisms;\n(g) Undertaking an assessment of available information and evidence from a\ncriminal procedure perspective, identifying gaps and developing possible investigation\nand prosecution strategies and blueprints for suitable international court models;\n(h) Amending relevant domestic legal frameworks, including by\nincorporating crimes under international law into domestic legislation and ensuring\nthat criminal procedural and extradition laws are in line with international norms and\nstandards; considering the possibility of universal jurisdiction for such crimes;\nbuilding the capacity of legal professionals in the investigation, prosecution and\nadjudication of crimes under international law; and considering abolishing the death\npenalty;114\n(i) Creating a fund to support future accountability mechanisms, including\nenabling victims to participate in accountability processes by addressing their safety\nand well-being concerns."},{"id":"a-hrc-34-66-add-1-p0081","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"81","seq":80,"section":"VI. Conclusions and recommendations","text":"The group of independent experts makes the following specific\nrecommendations."},{"id":"a-hrc-34-66-add-1-p0082","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"82","seq":81,"section":"VI. Conclusions and recommendations","text":"The Democratic People's Republic of Korea should:\n(a) Continue to engage with international human rights treaty bodies and\ncooperate with United Nations human rights mechanisms, including the mandate of\nthe Special Rapporteur on the situation of human rights in the Democratic People's\nRepublic of Korea, notably by granting them access to the country;\n113 \"Report of the detailed findings\", para. 1223.\n114 See paragraph 45.\nA/HRC/34/66/Add.1\n(b) Implement the recommendations made by United Nations human rights\nmechanisms, notably the commission of inquiry and the Special Rapporteur, including\ntaking immediate and effective steps to end gross human rights violations and\nensuring that allegations of human rights violations are addressed in line with\ninternational norms and standards;\n(c) Reform its criminal justice legislation and rule of law institutions,\nincluding its judiciary and law enforcement and corrections systems, in line with\ninternational human rights norms and standards and in furtherance of its\ncommitments made during the second cycle of the universal periodic review to fight\nimpunity for human rights violations;\n(d) Seek technical assistance from the United Nations and other\ninternational partners where needed to ensure that human rights are protected,\nincluding pursuant to the strategic framework for cooperation between the United\nNations and the Government of the Democratic People's Republic of Korea 2017-\n2021;\n(e) Create an enabling environment for national dialogue to promote human\nrights awareness among the population of the Democratic People's Republic of Korea,\nincluding by ensuring the rights to liberty of movement, peaceful assembly, freedom\nof association and expression, including through access to information."},{"id":"a-hrc-34-66-add-1-p0083","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"83","seq":82,"section":"VI. Conclusions and recommendations","text":"All stakeholders should:\n(a) Ensure implementation of previous recommendations on accountability\nfor human rights violations in the Democratic People's Republic of Korea made by\nthe commission of inquiry and international human rights mechanisms, including\nspecial procedure mandate holders, notably that accountability for crimes against\nhumanity must be part of any discussion about the future of the Korean peninsula;\n(b) Specifically, adopt a human rights-based and comprehensive approach\nto accountability and firmly integrate human rights and accountability into any\npolitical process for the Korean peninsula, acknowledging that peace and justice are\nmutually reinforcing imperatives."},{"id":"a-hrc-34-66-add-1-p0084","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"84","seq":83,"section":"VI. Conclusions and recommendations","text":"Member States should:\n(a) Bearing in mind the responsibility to protect, take further steps towards\nachieving accountability for those responsible for human rights violations in the\nDemocratic People's Republic of Korea, including through referral by the Security\nCouncil of the situation to the International Criminal Court and consideration of the\nestablishment of an ad hoc international tribunal;\n(b) Enact legislation with extraterritorial effect for gross violations of\nhuman rights and, for those States that recognize the principle of universal\njurisdiction, consider how they can contribute to securing accountability for human\nrights violations in the Democratic People's Republic of Korea;\n(c) Support awareness-raising, documentation and other initiatives\nundertaken by civil society organizations and others that contribute to accountability\nfor human rights violations in the Democratic People's Republic of Korea;\n(d) Ensure that the methodology used to document and collect information\nand evidence on human rights violations in the Democratic People's Republic of\nKorea meets international norms and standards, including with regard to criminal\nprocedure and issues of consent, confidentiality and victim and witness protection.\nA/HRC/34/66/Add.1"},{"id":"a-hrc-34-66-add-1-p0085","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"85","seq":84,"section":"VI. Conclusions and recommendations","text":"The United Nations should address the serious human rights situation in the\nDemocratic People's Republic of Korea in a coordinated and unified manner, in line\nwith the Secretary-General's Human Rights Up Front initiative, including by\npromoting the important role of accountability in achieving peace and security."},{"id":"a-hrc-34-66-add-1-p0086","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"86","seq":85,"section":"VI. Conclusions and recommendations","text":"The Human Rights Council and the General Assembly should:\n(a) Sustain their engagement and monitoring of developments in the\nDemocratic People's Republic of Korea with a view to keeping the issue of\naccountability for human rights violations in the country on the agenda, and take\nfurther actions towards accountability at the international level;\n(b) Strengthen OHCHR through additional resources, including its field-\nbased structure in Seoul, to enable the Office to increase its contribution towards\naccountability for human rights violations in the Democratic People's Republic of\nKorea, including by concurrently:\n(i) Undertaking and supporting sensitization of victims and groups\nrepresenting victims on international norms and standards pertaining to\naccountability for human rights violations;\n(ii) Organizing, in collaboration with relevant stakeholders, coordinated\nconsultations of victims and affected communities, in the first instance in\nChina, Japan and the Republic of Korea and other countries outside the\nDemocratic People's Republic of Korea in which they reside, to seek their views\non avenues for accountability;\n(iii) Strengthening current monitoring and documentation efforts in line with\ninternational norms and standards including on consent, and its capacity to\nreceive, preserve and consolidate information and evidence pertaining to the\nhuman rights situation in the Democratic People's Republic of Korea through a\ncentral and independent repository for use in any future accountability\nmechanism and to channel relevant information to United Nations human\nrights mechanisms;\n(iv) Supporting an assessment by international criminal justice experts of\navailable information and evidence, including on the crime base, command\nstructures and linkages, to identify gaps and develop possible investigation and\nprosecution strategies as well as blueprints for suitable international or\ninternationally assisted court models."},{"id":"a-hrc-34-66-add-1-p0087","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"87","seq":86,"section":"VI. Conclusions and recommendations","text":"The Special Rapporteur on the situation of human rights in the Democratic\nPeople's Republic of Korea should:\n(a) Integrate the findings of the present report into his efforts regarding\nhuman rights protection in the country;\n(b) Cooperate with other mandate holders to ensure that accountability\nprocesses duly reflect the needs of groups at risk of marginalization, including persons\nin detention, victims of enforced disappearances and their families and victims of\ngender-based violence."},{"id":"a-hrc-34-66-add-1-p0088","rec_id":"recYzXZ0Byq8lrIa3","symbol":"A/HRC/34/66/Add.1","n":"88","seq":87,"section":"VI. Conclusions and recommendations","text":"Civil society organizations should:\n(a) Continue raising awareness, specifically through regional initiatives and\nprofessional networks, reporting on human rights violations committed in the\nDemocratic People's Republic of Korea and supporting victims in formulating justice\ndemands before relevant mechanisms;\nA/HRC/34/66/Add.1\n(b) Consider innovative initiatives by regional networks, such as mock trials\nand tribunals led by civil society on specific issues or groups of victims, including\nwomen or disappeared persons, to enable discussions on reported violations in the\nDemocratic People's Republic of Korea and means of seeking accountability."},{"id":"a-hrc-40-36-u0000","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":null,"seq":0,"section":null,"text":"Fortieth session\n25 February�22 March 2019\nAgenda item 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-40-36-u0001","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":null,"seq":1,"section":null,"text":"In the present report, the Office of the United Nations High Commissioner for Human\nRights describes the progress made in the implementation of the recommendations made\nby the Human Rights Council in its resolution 34/24 on promoting accountability for\nhuman rights violations in the Democratic People's Republic of Korea, in particular with\nregard to the setting up of, and work done by, a dedicated accountability team of the Office\nof the High Commissioner.","unnumbered":true},{"id":"a-hrc-40-36-p0001","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"1","seq":2,"section":"I. Introduction","text":"The Office of the United Nations High Commissioner for Human Rights (OHCHR)\nsubmits to the Human Rights Council pursuant to its resolution 34/24 on the situation of\nhuman rights in the Democratic People's Republic of Korea. In the report, OHCHR describes\nthe activities it has carried out to implement resolution 34/24, in particular with regard to the\nsetting up of, and work done by, a dedicated accountability team, highlighting the main\nprogress made and the challenges encountered."},{"id":"a-hrc-40-36-p0002","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"2","seq":3,"section":"I. Introduction","text":"The High Commissioner recommends that the Human Rights Council consider\nextending the mandate granted in resolution 34/24 and allocate the resources necessary for\nOHCHR to comprehensively implement its mandate."},{"id":"a-hrc-40-36-p0003","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"3","seq":4,"section":"II. Human Rights Council resolution 34/24","text":"Various United Nations human rights mechanisms, including the Special Rapporteur\non the situation of human rights in the Democratic People's Republic of Korea and the\ncommission of inquiry on human rights in the Democratic People's Republic of Korea (see\nA/HRC/25/63), have made repeated calls and recommendations for accountability for human\nrights violations committed in the country. Such calls for accountability have also been\nechoed by both the General Assembly, in its resolution 73/180, and the Secretary-General\n(see A/70/393, para. 58)."},{"id":"a-hrc-40-36-p0004","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"4","seq":5,"section":"II. Human Rights Council resolution 34/24","text":"In its report, the commission of inquiry, on the basis of its findings that there were\nreasonable grounds to believe that crimes against humanity had been committed and\ncontinued to be committed in the Democratic People's Republic of Korea, made\nrecommendations on pursuing accountability, including by calling upon the Security Council\nto refer the situation to the International Criminal Court or to establish an ad hoc international\ntribunal."},{"id":"a-hrc-40-36-p0005","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"5","seq":6,"section":"II. Human Rights Council resolution 34/24","text":"Pursuant to the recommendations of the commission of inquiry, the Human Rights\nCouncil, in its resolution 25/25, requested OHCHR to establish a field-based structure to\nstrengthen the monitoring and documentation of human rights violations in the Democratic\nPeople's Republic of Korea, including with a view to ensuring accountability for\ninternational crimes, including crimes against humanity. The Council subsequently requested,\nin its resolution 31/18, the High Commissioner to appoint a group of independent experts to\nexplore appropriate approaches for seeking accountability for human rights violations in the\nDemocratic People's Republic of Korea, in particular where such violations amounted to\ncrimes against humanity, and to recommend practical mechanisms of accountability to ensure\ntruth and justice for victims of such crimes."},{"id":"a-hrc-40-36-p0006","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"6","seq":7,"section":"II. Human Rights Council resolution 34/24","text":"In its report to the Human Rights Council (A/HRC/34/66/Add.1), the group of\nindependent experts recommended the adoption of a multi-pronged and comprehensive\napproach to accountability, including measures towards the realization of victims' right to\ntruth, justice, reparations, and guarantees of non-recurrence. Its recommendations included\nthe referral of the situation to the International Criminal Court, the creation of an ad hoc\ntribunal for the Democratic People's Republic of Korea and the prosecution of crimes by\nMember States through the principle of universal jurisdiction."},{"id":"a-hrc-40-36-p0007","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"7","seq":8,"section":"II. Human Rights Council resolution 34/24","text":"In its report, the group of independent experts also recommended that the international\ncommunity enhance its efforts towards preparatory work for future criminal trials. This\nincluded the strengthening of monitoring and documentation efforts by OHCHR and its\ncapacity to receive, preserve and consolidate information and evidence through the creation\nof a central and independent repository as well as supporting the assessment from a criminal\nlaw perspective by international criminal justice experts, of all material available in order to\nidentify gaps and develop possible investigation and prosecution strategies as well as\nblueprints for suitable international or internationally assisted court models. The group of\nindependent experts further recommended that the capacity of OHCHR be strengthened to\nundertake and support sensitization of victims groups on international norms and standards\npertaining to accountability for human rights violations, and to organize, in collaboration\nwith stakeholders, coordinated consultations of victims and affected communities to seek\ntheir views on avenues for accountability."},{"id":"a-hrc-40-36-p0008","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"8","seq":9,"section":"II. Human Rights Council resolution 34/24","text":"Pursuant to the recommendations made by the group of independent experts, the\nHuman Rights Council adopted resolution 34/24."},{"id":"a-hrc-40-36-p0009","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"9","seq":10,"section":"A. Mandate and methods of work","text":"In its resolution 34/24, the Human Rights Council decided to strengthen the capacity\nof OHCHR for two years, including its field-based structure in Seoul, to implement the\nrecommendations of the group of independent experts pertaining to criminal accountability."},{"id":"a-hrc-40-36-p0010","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"10","seq":11,"section":"A. Mandate and methods of work","text":"Specifically, the Human Rights Council mandated OHCHR to strengthen its\nmonitoring and documentation efforts; establish a central information and evidence\nrepository; and have experts in legal accountability assess all information and testimonies\nwith a view to developing possible strategies to be used in any future accountability process."},{"id":"a-hrc-40-36-p0011","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"11","seq":12,"section":"A. Mandate and methods of work","text":"During the period under review, OHCHR undertook specific activities to implement\nits mandate."},{"id":"a-hrc-40-36-p0012","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"12","seq":13,"section":"A. Mandate and methods of work","text":"Firstly, OHCHR strengthened its capacities to implement the relevant\nrecommendations made by the group of independent experts on accountability by recruiting\nstaff with expertise in international criminal law."},{"id":"a-hrc-40-36-p0013","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"13","seq":14,"section":"A. Mandate and methods of work","text":"Secondly, the Office focused on strengthening its monitoring and documentation\nefforts and conducted interviews with persons who had escaped from the Democratic\nPeople's Republic of Korea, with the objective of gathering information pertaining to alleged\ncrimes against humanity. It also engaged closely with civil society organizations, relevant\nentities of the Government of the Republic of Korea, and other stakeholders that had been\ninvolved in the documentation of human rights violations in the Democratic People's\nRepublic of Korea."},{"id":"a-hrc-40-36-p0014","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"14","seq":15,"section":"A. Mandate and methods of work","text":"Thirdly, OHCHR began to design and set up a secure central information and evidence\nrepository."},{"id":"a-hrc-40-36-p0015","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"15","seq":16,"section":"A. Mandate and methods of work","text":"Lastly, and in parallel with the above steps, the newly recruited experts in international\ncriminal law began an analysis, in accordance with criminal evidentiary standards, of the\ninterviews that OHCHR had previously conducted, the information collected by the\ncommission of inquiry, and publicly available information gathered by civil society\norganizations, with a view to incorporating such evidence and information � where requisite\nstandards were met � into its central information and evidence repository.1"},{"id":"a-hrc-40-36-p0016","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"16","seq":17,"section":"B. Establishment of a dedicated accountability team","text":"OHCHR submitted a proposal to the Advisory Committee on Administrative and\nBudgetary Questions outlining a minimum required staffing profile to effectively implement\nthe mandate given by the Human Rights Council in its resolution 34/24. This comprised one\nLegal Officer (P-4) and one Information Management Officer (P-3) in Geneva; one Legal\nOfficer (P-4), one National Legal Officer and a Legal Translator in Seoul; and a home-based\nhigh-level consultant (D-1). Two posts comprising these minimal resource requirements were\nnot approved by the General Assembly in its budgetary decisions of December 2017,\nresulting in a reduced staffing basis for the mandate."},{"id":"a-hrc-40-36-p0017","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"17","seq":18,"section":"B. Establishment of a dedicated accountability team","text":"In recruiting the members of the accountability team, OHCHR encountered some\nlogistic and budgetary obstacles that had a negative impact on the planned implementation\nof the mandate. Despite these difficulties, OHCHR recruited the high-level consultant (with\nexpertise in international criminal law) in April 2018, while the international and national\nlegal officers were appointed in July and August 2018. There were challenges associated with\nthe identification and recruitment of a suitably qualified and experienced Information\nManagement Officer. Work on the design and set-up of the central archive and database\nbegan at the beginning of October 2018."},{"id":"a-hrc-40-36-p0018","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"18","seq":19,"section":"B. Establishment of a dedicated accountability team","text":"In implementing the mandate given by the Human Rights Council, the high-level\nconsultant led and managed the legal aspects of criminal accountability activities, the\nimplementation of which was overseen in Seoul by the international legal officer, with the\nassistance of a national counterpart. The team also conducted interviews with alleged victims\nand other witnesses, analysed information, created an electronic database, organized and\nconducted training sessions for civil society organizations, and identified key areas where\ncooperation with other stakeholders should be strengthened. The team also identified several\nareas where, with the appropriate resources, work on accountability could be materially\nadvanced in the future."},{"id":"a-hrc-40-36-p0019","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"19","seq":20,"section":"A. Strengthening monitoring and documentation efforts","text":"The accountability team contributed to and enhanced the work already being\nundertaken by the OHCHR field-based structure in Seoul. In particular, it ensured that\ninterviews with persons who had fled the Democratic People's Republic of Korea included\nspecific questions to identify elements of crimes and of modes of liability, in addition to the\ndocumentation of human rights violations. The purpose was to strengthen the admissibility\nand probative value of the information and evidence collected by OHCHR for possible future\ncriminal proceedings. The selection of interviewees was also adapted to achieve this\nobjective on the basis of information gathered through questionnaires administered by\nOHCHR to prospective interviewees."},{"id":"a-hrc-40-36-p0020","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"20","seq":21,"section":"A. Strengthening monitoring and documentation efforts","text":"Since the opening of its field-based structure in Seoul in June 2015, OHCHR has\nconducted approximately 300 interviews with alleged victims and witnesses of human rights\nviolations perpetrated in the Democratic People's Republic of Korea. Each month, OHCHR\nwas granted access to up to six escapees held in resettlement centres run by the Government\nof the Republic of Korea, where they are provided with training and support upon their arrival\nto the Republic of Korea. Each interview was conducted within the confines of the\nresettlement centres, for a maximum time of two hours. In some cases, such arrangements\nwere insufficient to gather thorough and detailed information from each individual\ninterviewed, including for the purposes of accountability."},{"id":"a-hrc-40-36-p0021","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"21","seq":22,"section":"A. Strengthening monitoring and documentation efforts","text":"Given the large number of suspected violations, OHCHR and the Government of the\nRepublic of Korea are engaged in an ongoing dialogue on these issues, also in view of the\nimportance of interviewing individuals as soon as possible upon their arrival in the Republic\nof Korea to increase the reliability and accuracy of the information provided."},{"id":"a-hrc-40-36-p0022","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"22","seq":23,"section":"A. Strengthening monitoring and documentation efforts","text":"Given that the probative value of testimonies received in neutral environments is\nfrequently enhanced, OHCHR also conducted interviews with persons from the Democratic\nPeople's Republic of Korea outside official facilities in the Republic of Korea. Identifying\nand locating these persons, and arranging interviews with them while taking into account\nsecurity concerns require dedicated research and are labour-intensive. With the resources\navailable to OHCHR, only limited time and staff could be devoted to this activity.\n2. Collection and analysis of documentary evidence"},{"id":"a-hrc-40-36-p0023","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"23","seq":24,"section":"A. Strengthening monitoring and documentation efforts","text":"Given the difficulties in collecting information from within the Democratic People's\nRepublic of Korea, OHCHR has been pursuing alternative avenues of documentation. It has,\nin particular, sought to establish linkages between alleged crimes and the identification of the\nindividuals responsible, both those who carried out the acts in question and commanders and\nsuperiors responsible for formulating relevant policies, issuing orders or failing to exercise\nproper control over their subordinates."},{"id":"a-hrc-40-36-p0024","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"24","seq":25,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR reviewed open source and other materials in order to identify those holding\npositions of responsibility in the Democratic People's Republic of Korea who may have had\ndirect knowledge of the chain of command and the decision-making processes involved."},{"id":"a-hrc-40-36-p0025","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"25","seq":26,"section":"A. Strengthening monitoring and documentation efforts","text":"In the Republic of Korea, both the Ministry of Unification and the Ministry of Justice\nhave human rights documentation centres focusing on the situation in the Democratic\nPeople's Republic of Korea. The Center for North Korean Human Rights Records,\nestablished under the Ministry of Unification pursuant to the North Korean Human Rights\nAct of 2016, conducts interviews with persons recently arrived in the Republic of Korea from\nthe Democratic People's Republic of Korea. The North Korea Human Rights Documentation\nOffice, established under the Ministry of Justice, collects, archives and analyses the\ninformation gathered by the Center with a view to future prosecutions."},{"id":"a-hrc-40-36-p0026","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"26","seq":27,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR held several meetings with representatives of the above-mentioned\ninstitutions to explain the nature of its work, including pursuant to Human Rights Council\nresolution 34/24, its independent mandates and the importance of cooperation in the pursuit\nof accountability. These meetings provided for exchanges of experience and lessons learned\nin documentation efforts. OHCHR has requested copies of records of both institutions for\nanalysis and eventual inclusion in the central electronic repository, where relevant and\nappropriate, and looks forward to continuing cooperation with these institutions."},{"id":"a-hrc-40-36-p0027","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"27","seq":28,"section":"A. Strengthening monitoring and documentation efforts","text":"Many civil society organizations have conducted interviews and collected information\non suspected crimes against humanity committed in the Democratic People's Republic of\nKorea. Many such organizations have a long history, and have collected a large body of\ninformation and accumulated invaluable expertise. To date, much access of OHCHR to that\ninformation has been limited to publicly available summaries or extracts of interviews."},{"id":"a-hrc-40-36-p0028","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"28","seq":29,"section":"A. Strengthening monitoring and documentation efforts","text":"For a comprehensive analysis conducted in accordance with international criminal law\nstandards, and for the creation of a reliable repository of evidence and information as\nmandated by the Human Rights Council in its resolution 34/24, OHCHR must have broad\naccess to a maximum of the data accumulated. OHCHR has continued to liaise with those\nresponsible for these organizations on possibilities of gaining access to the original and full\nrecords of information gathered by them, including, where possible, the contact details of the\nsources of information. Progress made on this front is encouraging, and OHCHR is optimistic\nthat access to these files will be possible. As OHCHR acquires these original records, it will\nincorporate them into the repository, which will in turn greatly assist in the compilation of\nfiles for accountability processes."},{"id":"a-hrc-40-36-p0029","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"29","seq":30,"section":"A. Strengthening monitoring and documentation efforts","text":"A lack of coordination between organizations and the use of differing methodologies\nof documentation and information collection can have a detrimental impact on the evidentiary\nvalue of information collected. In an effort to maximize the usability and probative value of\nsuch information, OHCHR has begun to provide technical advice to stakeholders in order to\nstrengthen their skills in the collection and documentation of information on suspected\nviolations that meets required legal standards, for accountability purposes. In August 2018,\nfor example, OHCHR conducted a training session on the documentation of crimes under\ninternational law, which comprised a theoretical session on interviewing techniques, crimes\nunder international law and modes of liability, and a practical exercise. A total of 24\nrepresentatives from 13 organizations took part in the training. OHCHR also held a short\ntraining session for investigators of the Government of the Republic of Korea on issues\nregarding the documentation of crimes against humanity."},{"id":"a-hrc-40-36-p0030","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"30","seq":31,"section":"B. Establishment of a central information and evidence repository","text":"While in the immediate term there may be little prospect that those responsible for\ngross human rights violations and crimes under international law in the Democratic People's\nRepublic of Korea will be held to account, a critical function of the accountability team is to\nestablish a central electronic repository of all information and evidence collected for future\nnational and international justice mechanisms (A/HRC/25/63, para. 94 (c)). The\nestablishment of a repository would also facilitate the analysis of information and evidence\ncollected, the identification of gaps, strengths and weaknesses from an accountability\nstandpoint, and strengthen documentation efforts (A/HRC/34/66/Add.1, para. 86)."},{"id":"a-hrc-40-36-p0031","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"31","seq":32,"section":"B. Establishment of a central information and evidence repository","text":"Setting up a central information and evidence repository is a complex task. As a first\nstep, OHCHR has created an electronic database in which it is in the process of storing\ninformation that OHCHR and the commission of inquiry have gathered, and information\npublished and/or made otherwise available by other stakeholders. In entering such data, the\naccountability team carries out, where possible, a preliminary reliability and credibility\nassessment and triangulates such information with other assessed sources."},{"id":"a-hrc-40-36-p0032","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"32","seq":33,"section":"B. Establishment of a central information and evidence repository","text":"Besides functioning as a central archive for information and evidence, the electronic\ndatabase will facilitate the identification of elements of crimes, modes of liability and\npossible perpetrators, thus paving the way to the opening of specific case files and the\nbuilding of criminal cases."},{"id":"a-hrc-40-36-p0033","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"33","seq":34,"section":"B. Establishment of a central information and evidence repository","text":"The database has been specifically designed to ensure that information is handled in\naccordance with the consent of the provider and to protect confidentiality and the security of\nwitnesses and victims. The server is physically located in Geneva so as to guarantee the\nhighest level of cybersecurity and the protection of sources and information contained in it.\nAccess to the database will be provided only to future accountability mechanisms with the\nconsent of the provider, and after any protection and operational concerns are duly considered\nand addressed (A/HRC/25/63, para. 94 (c))."},{"id":"a-hrc-40-36-p0034","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"34","seq":35,"section":"B. Establishment of a central information and evidence repository","text":"As more information is collected and additional analysis performed, the architecture\nof the database will require updates and adjustments in order to ensure that it remains an\neffective tool for any future accountability efforts and/or mechanisms."},{"id":"a-hrc-40-36-p0035","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"35","seq":36,"section":"C. Information analysis and assessment","text":"In its resolution 34/24, the Human Rights Council mandated OHCHR to have experts\nin legal accountability assess all information and testimonies with a view to developing\npossible strategies to be used in any future accountability process. Accordingly, the\npreliminary phase of the assessment conducted by OHCHR focused on the collection and\nclassification of information with the aim of identifying locations, dates, crimes and the\ninvolvement of security agencies and other State actors in possible criminal conduct. A\nsignificant portion of the analysed information is confidential. In conducting this analysis,\nOHCHR is including and giving due consideration to information that may have exculpatory\nvalue."},{"id":"a-hrc-40-36-p0036","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"36","seq":37,"section":"C. Information analysis and assessment","text":"This exercise has proved essential for further in-depth analysis, as it has facilitated\ncross-checking of information, corroboration and the identification of gaps, strengths and\npatterns in evidence. It also has allowed OHCHR to conduct more focused and efficient\ndocumentation efforts and to identify sources of information who could possibly be re-\ninterviewed to obtain additional details."},{"id":"a-hrc-40-36-p0037","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"37","seq":38,"section":"IV. Key findings","text":"The interviews and initial analysis of information undertaken by OHCHR since the\nestablishment of its field-based structure in Seoul have supported the conclusion of the\ncommission of inquiry, namely, that there were reasonable grounds establishing that crimes\nagainst humanity had been committed (A/HRC/25/63, para. 74), especially with regard to the\ncrimes against humanity of imprisonment and other detention-related crimes, such as torture,\nother inhuman acts, enslavement and murder."},{"id":"a-hrc-40-36-p0038","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"38","seq":39,"section":"IV. Key findings","text":"Nearly all individuals interviewed by OHCHR had irregularly crossed the border into\nChina. Many had sought to escape more than once before they eventually succeeded, and\nsome described having been forcibly repatriated to the Democratic People's Republic of\nKorea. Upon being transferred to officials of the Ministry of State Security of the Democratic\nPeople's Republic of Korea (formerly known as State Security Department) at the border,\nthey were detained and interrogated about their activities in China. If the interrogators were\nsatisfied that they had only engaged in trade or other work activities, they would be labelled\nas ordinary criminals and transferred to detention facilities of the Ministry of People's\nSecurity. There they would be interrogated again, sometimes for months, and then sentenced.\nDepending on the assessed gravity of their conduct, sentences ranged from months to years\nin either prison camps (kyohwaso) or labour training camps (rodongdanryondae). Individuals\nthought to have engaged in activities that the authorities classified as political offences (by,\nfor example, contacting Christian organizations or citizens of the Republic of Korea), would\nremain in the custody of the Ministry of State Security and, in some cases, would reportedly\nbe sent to political prison camps (kwanliso)."},{"id":"a-hrc-40-36-p0039","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"39","seq":40,"section":"IV. Key findings","text":"There are reasonable grounds to believe that the majority of these arrests amount to\nimprisonment as a crime against humanity, given what appears to be the systematic\ncommission of such acts against the civilian population. While the Democratic People's\nRepublic of Korea has to some extent amended its criminal procedure laws in the past 15\nyears by introducing elements of fair trial guarantees, the interviewees consistently reported\nto OHCHR that they were not afforded those rights. Fair trial rights, including the right to be\ninformed about charges, access to a lawyer, and the right to be presented before a judge were\neither denied altogether or offered as a mere gesture. People interviewed by OHCHR credibly\ndescribed routine imprisonment for months or years on the sole basis of having exercised\ntheir right, protected under international law, to leave their country of origin. 2 The\ninformation reviewed by OHCHR indicates that, far from being isolated, such detentions\nappear to have been part of a policy implemented in a widespread and systematic manner\nagainst civilians attempting to flee the Democratic People's Republic of Korea."},{"id":"a-hrc-40-36-p0040","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"40","seq":41,"section":"IV. Key findings","text":"There are also reasonable grounds to believe that the crimes against humanity of\nmurder, sexual violence, enslavement, torture and other inhumane acts were committed\nagainst some persons while they were detained. Former detainees interviewed by OHCHR\nconsistently described harsh conditions of detention, in particular widespread\nmalnourishment causing severe health problems among prisoners, and physical and\npsychological violence, including during interrogations by officers of the Ministry of State\nSecurity and the Ministry of People's Security. Several interviewees reported cases of\nprisoners who had died in detention centres from malnutrition, overwork or untreated\ndiseases, or a combination of these factors. Some women reported having been sexually\nassaulted by guards while in detention. The accounts given by former detainees suggests a\ntotal lack of judicial oversight of detention centres and no system for inmates to report abuse."},{"id":"a-hrc-40-36-p0041","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"41","seq":42,"section":"IV. Key findings","text":"The Democratic People's Republic of Korea still prosecutes political crimes labelled\nas \"crimes against the State\" or \"crimes against the nation\". These encompass extremely\nbroad, vague and indeterminate categories of conduct that effectively make the criminal\njustice system subservient to political objectives, including the preservation of the State's\nideology.3"},{"id":"a-hrc-40-36-p0042","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"42","seq":43,"section":"IV. Key findings","text":"In its report, the commission of inquiry, and other sources of evidence, described\nprison camps for political detainees as the harshest in the Democratic People's Republic of\nKorea. The commission cited estimates of the Korean Institute for National Unification,\naccording to which, in 2012, these camps hosted between 80,000 and 120,000 detainees\n(A/HRC/25/63, para. 61). 4 There is almost complete secrecy around these camps. The\nauthorities of the Democratic People's Republic of Korea have repeatedly denied their\nexistence, and the camps operate outside any known legal framework. OHCHR has limited\naccess to first-hand accounts from former political prisoners. Scarcity of information\nconcerning the camps probably stems from the fact that, unlike former regular prisoners\nroutinely interviewed by OHCHR, political prisoners are rarely released. OHCHR\n2 International Covenant on Civil and Political Rights, art. 12 (2). The Democratic People's Republic of\nKorea ratified the Covenant on 14 September 1981, and it entered into force on 14 December the\nsame year. On 25 August 1997, the State notified the Secretary-General that it was withdrawing from\nthe Covenant. The Secretary-General nonetheless still considers the Democratic People's Republic of\nKorea a State party to the Covenant, given that it does not allow for withdrawal (which would be\npossible only if all other States parties agreed to it).\n3 Such as articles 60 to 70 of the Criminal Law of the Democratic People's Republic of Korea (2015),\namended by Decree No. 578 of the Presidium of the Supreme People's Assembly on 22 July 2015.\nSee Kim, Soo-am, The North Korean Penal Code, Criminal Procedures, and their Actual\nApplications (Seoul, Korean Institute for National Unification, 2006), pp. 8�9.\ninterviewed individuals who claimed that some of their relatives had been imprisoned in\npolitical prison camps as recently as 2014. Considering the alarming findings of the\ncommission of inquiry on the allegation of widespread commission of crimes against\nhumanity in political prison camps, OHCHR views it as critical that it continue to pursue all\npossible documentation avenues to ensure the availability of updated and reliable information\non these detention facilities.5"},{"id":"a-hrc-40-36-p0043","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"43","seq":44,"section":"IV. Key findings","text":"Information, including recent accounts by persons interviewed by OHCHR, alleging\narrests and arbitrary detention of people repatriated from China and elsewhere is abundant\nand consistent with both the records held by OHCHR and with those published by civil\nsociety organizations. Within the context of accountability processes, this information\nconstitutes possible evidence of alleged underlying criminal acts. The alleged systematic\nperpetration of crimes in detention centres under the direct authority of the Ministry of State\nSecurity and the Ministry of People's Security also supports the inference that such crimes\nmay be committed pursuant to policies formulated at higher levels and implemented by local\npolitical and administrative authorities. At this stage, more substantive and specific evidence\nis necessary to particularize, at all levels, those who may have been responsible for these\nalleged criminal acts."},{"id":"a-hrc-40-36-p0044","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"44","seq":45,"section":"IV. Key findings","text":"In this regard, a comprehensive understanding of the decision-making processes that\nhave led to the commission of crimes, and of the array of State actors and individuals involved\ntherein, is of crucial importance in establishing liability, including through forms of co-\nperpetration and joint criminal enterprise, particularly in cases involving persons responsible\nfor the commission of crimes other than the primary perpetrator (for instance, political or\nmilitary officers who ordered the commission of crimes or who played a role in their\nplanning). 6 Similarly, understanding the chain of command, operational structures and\nreporting lines in military and civilian organizations is essential to assess the possible\nresponsibility of superiors for failing to prevent or punish the crimes committed by their\nsubordinates.7"},{"id":"a-hrc-40-36-p0045","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"45","seq":46,"section":"IV. Key findings","text":"Gaining access to evidentiary material that sheds light on the above-mentioned issues\nis particularly challenging in the context of the Democratic People's Republic of Korea.\nNonetheless, OHCHR will continue to use all resources available to explore ways to identify,\ncollect and analyse relevant information, including through cooperation with experts,\nscholars and stakeholders. This will be also essential for the identification of individuals who,\nwhile acting remotely from the physical perpetration of alleged crimes, may be among those\nmost responsible for their commission.8"},{"id":"a-hrc-40-36-p0046","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"46","seq":47,"section":"V. Conclusions","text":"The analysis by OHCHR of information currently available confirms there are\nreasonable grounds to believe that numerous crimes against humanity have been\ncommitted in the Democratic People's Republic of Korea, and may be ongoing. As\n5 See also War Crimes Committee of the International Bar Association, Report: Inquiry on Crimes\nagainst Humanity in North Korean Prison Camps, International Bar Association, December 2017.\n6 See International Tribunal for the Prosecution of Persons Responsible for Serious Violations of\nInternational Humanitarian Law Committed in the Territory of Former Yugoslavia since 1991,\nProsecutor v. Radoslav Branin, Case No. IT-99-36-A, Judgement, 3 April 2007, paras. 410�432.\nSee also Manuel J. Ventura, \"The Application of Joint Criminal Enterprise to Complex Top Political\nLeadership Cases Upheld: The Krajisnik Appeal Judgment\", Annotated Leading Cases of\nInternational Criminal Tribunals, vol. 48, 1 November 2015.\n7 See Rome Statute of the International Criminal Court, art. 28.\n8 International criminal justice focuses on those considered most responsible for the crimes falling\nunder the jurisdiction of an international or hybrid court. See for example article 1 of the Law\nestablishing the Extraordinary Chambers in the Courts of Cambodia, 27 October 2004. With regard to\nthe International Tribunals for Rwanda and the former Yugoslavia, see Security Council resolution\n1534 (2004), para. 5. For the International Criminal Court, see the statement of the Prosecutor of the\nInternational Criminal Court, Fatou Bensouda, on the alleged crimes committed by ISIS, 8 April\n2015. The commission of inquiry and the group of independent experts recommended such a focus\nfor the Democratic People's Republic of Korea; see A/HRC/34/66/Add.1, paras. 8 and 75.\nrecommended by the commission of inquiry and the group of independent experts, the\nprosecution of crimes committed in the Democratic People's Republic of Korea through\nthe creation of an ad hoc tribunal or referral to the International Criminal Court should\nremain a priority in the long term. While the conditions may not yet in place for either\noption to materialize, it is imperative to ensure that information is collected and stored\nfor criminal accountability purposes."},{"id":"a-hrc-40-36-p0047","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"47","seq":48,"section":"V. Conclusions","text":"While OHCHR has made some progress in advancing efforts to achieve\naccountability for alleged crimes committed in the Democratic People's Republic of\nKorea, significant work remains to be done to fully meet the objectives set by the\nHuman Rights Council in its resolution 34/24, and to contribute to the eventual\nrealization of justice for victims."},{"id":"a-hrc-40-36-p0048","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"48","seq":49,"section":"V. Conclusions","text":"During the period under review, OHCHR explored various avenues for\naccountability and began to develop tailored strategies to that end. A large amount of\ndocumentation collected for the purposes of monitoring the situation of human rights\nhowever, still needs to be reviewed and analysed from an international criminal law\nperspective. This task is complicated by the lengthy timescale over which such\nwidespread crimes have taken place, and the fact that they have been committed\nthroughout the country. The highly complex command structures of the Democratic\nPeople's Republic of Korea are an additional complicating factor."},{"id":"a-hrc-40-36-p0049","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"49","seq":50,"section":"V. Conclusions","text":"Should the Human Rights Council extend the mandate of the accountability team,\nOHCHR proposes to strengthen � resources permitting � the specialized team and\nconsolidate it within its field-based structure in Seoul, which will be headed by a\npermanent senior official member with extensive experience in international criminal\nlaw. The team would ideally include expertise in a variety of fields and disciplines.\nAdditional staff with expertise in international criminal law would strengthen the\nOffice's capacity to review and analyse documentation collected, oversee and conduct\naccountability-focused interviews, carry out factual and legal analysis, and devise\ndocumentation and investigation strategies. Additional Korean-speaking human rights\nofficers, legal interpreters and legal officers would be required to increase the Office's\ninterviewing capacity and its ability to analyse relevant laws and commentaries of the\nDemocratic People's Republic of Korea, the vast majority of which are not available in\nEnglish or French. Furthermore, a large number of the original records of interviews\ngenerated by civil society organizations that will have to be included in the electronic\nrepository once received are in Korean, requiring Korean-speaking staff to undertake\nanalysis and translation. Lastly, additional resources would also allow OHCHR to\nbroaden its outreach activities, which is critical to increasing potential sources of\ninformation and to strengthen cooperation among the many stakeholders whose work\nis relevant to the accountability project."},{"id":"a-hrc-40-36-p0050","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"50","seq":51,"section":"V. Conclusions","text":"The accountability team would also require a fully dedicated information\nmanagement officer, in addition to a legal officer tasked with overseeing the\npreservation and consolidation of information and evidence in accordance with\ninternational standards, and with responding to any requests for assistance lodged by\nfuture accountability mechanisms. A software developer would also be required to\nupdate, maintain and modify the architecture and analytical features of the central\nelectronic database and repository. These modifications and updates will likely become\nnecessary as the volume of information increases. Lastly, a media officer would be\nvaluable to undertake future outreach activities aimed at keeping Korean and\ninternational audiences informed about the work of the accountability team."},{"id":"a-hrc-40-36-p0051","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"51","seq":52,"section":"V. Conclusions","text":"The experience gained during the period under review shows that, at the present\nstage, owing to the continued lack of access to the Democratic People's Republic of\nKorea, the majority of the work on accountability must be carried out in the Republic\nof Korea. While staff working on criminal accountability must therefore be based in\nSeoul, a small team is required in Geneva, including a dedicated international legal\nofficer and an information management officer. For security reasons, archives and the\nrepository of testimonies and documents gathered by OHCHR should be maintained\nand serviced in Geneva. Moreover, regular interaction with Member States in Geneva\nwill remain critical in continuing to advocate for and advance future strategies on\naccountability."},{"id":"a-hrc-40-36-p0052","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"52","seq":53,"section":"V. Conclusions","text":"These additional resources would allow OHCHR to continue to work both on\ndocumenting and storing information on suspected crimes against humanity, and on\nthe development of accountability strategies for future international and/or nationally\nowned accountability processes."},{"id":"a-hrc-40-36-p0053","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"53","seq":54,"section":"V. Conclusions","text":"In the meantime, in the absence of any commitment to accountability at the\nnational level, OHCHR continues to recommend that the Security Council refer the\nsituation in the Democratic People's Republic of Korea to the International Criminal\nCourt or that an ad hoc international tribunal be established, to make full use of the\ninformation and evidence being collected by OHCHR and to ensure that those most\nresponsible for gross human rights violations that may amount to crimes against\nhumanity are held to account. This would represent an essential step towards\naccountability for crimes against humanity in the Democratic People's Republic of\nKorea and may deter the commission of such acts in the future."},{"id":"a-hrc-40-36-p0054","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"54","seq":55,"section":"VI. Recommendations","text":"On the basis of the activities it has conducted to date pursuant to Human Rights\nCouncil resolution 34/24, OHCHR recommends that the Government of the Democratic\nPeople's Republic of Korea:\n(a) Acknowledge the existence of serious human rights violations, which may\namount to crimes against humanity, take immediate steps to end such violations, and\nensure that independent, impartial investigations are conducted into allegations of such\nviolations;\n(b) Give international humanitarian organizations and human rights\nmonitors immediate access to the country, including to all detention facilities;\n(c) Grant OHCHR access to the country, including to conduct interviews and\ndocumentation activities pursuant to Council resolution 34/24;\n(d) Initiate reform of criminal justice legislation and rule of law institutions,\nincluding the judiciary and law enforcement and corrections systems, in accordance\nwith international human rights norms and standards;\n(e) Ensure that victims of crimes against humanity and their families are\nprovided with adequate, prompt and effective reparation and remedies, including\npublic acknowledgment of the truth of the violations suffered;\n(f) Hold to account all perpetrators of international crimes in national courts\nthrough fair and impartial trials held in accordance with international standards;\n(g) Ratify the Rome Statute of the International Criminal Court."},{"id":"a-hrc-40-36-p0055","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"55","seq":56,"section":"VI. Recommendations","text":"OHCHR recommends that the Government of the Republic of Korea continue\nto facilitate the work conducted by OHCHR pursuant to Human Rights Council\nresolution 34/24, including with regard to access to individuals who have fled the\nDemocratic People's Republic of Korea, and to the collection and analysis of relevant\ntestimony, documentation and information."},{"id":"a-hrc-40-36-p0056","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"56","seq":57,"section":"VI. Recommendations","text":"OHCHR also recommends that the Human Rights Council and the General\nAssembly consider extending the mandate of the dedicated OHCHR accountability\nteam for an additional period of two years to pursue implementation of Council\nresolution 34/24, namely the strengthening of OHCHR monitoring and documentation\nefforts; and consider providing additional resources for OHCHR to continue such work\nas described in the present report."},{"id":"a-hrc-40-36-p0057","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"57","seq":58,"section":"VI. Recommendations","text":"OHCHR calls upon Member States:\n(a) To undertake, where possible, the investigation and prosecution of\npersons suspected of committing international crimes in the Democratic People's\nRepublic of Korea;\n(b) To consider means by which further relevant information under Human\nRights Council resolution 34/24 could be appropriately conveyed to OHCHR;\n(c) To take further steps to ensure accountability for those responsible for\nserious human rights violations in the Democratic People's Republic of Korea at the\nregional or international levels, including through the referral by the Security Council\nof the situation to the International Criminal Court or the creation of an ad hoc\ninternational tribunal."},{"id":"a-hrc-40-36-p0058","rec_id":"rec4xPAP8TEWkUXnU","symbol":"A/HRC/40/36","n":"58","seq":59,"section":"VI. Recommendations","text":"OHCHR calls upon all stakeholders to continue to cooperate with OHCHR in\nthe collection, documentation and preservation of information relating to alleged\nhuman rights violations and crimes against humanity."},{"id":"a-hrc-46-52-p0001","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"1","seq":0,"section":"I. Introduction","text":"The present report is submitted pursuant to Human Rights Council resolution 40/20\non the situation of human rights in the Democratic People's Republic of Korea. In that\nresolution, the Council requested the High Commissioner to submit to the Council at its forty-\nsixth session a full written report on the implementation of the recommendations made by\nthe group of independent experts on accountability aimed at strengthening current monitoring\nand documentation efforts, establishing a central information and evidence repository, and\nhaving experts in legal accountability assess all information and testimonies with a view to\ndeveloping possible strategies to be used in any future accountability process."},{"id":"a-hrc-46-52-p0002","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"2","seq":1,"section":"I. Introduction","text":"The present report describes the activities of the Office of the United Nations High\nCommissioner for Human Rights (OHCHR) to implement Human Rights Council resolutions\n34/24 and 40/20, highlighting the progress made and the challenges encountered. The report\nalso examines, in the light of relevant international legal standards, information gathered by\nOHCHR on human rights violations committed in the Democratic People's Republic of\nKorea. Consistent information continues to confirm that there are reasonable grounds to\nbelieve that numerous crimes against humanity have been committed in the Democratic\nPeople's Republic of Korea and may be ongoing."},{"id":"a-hrc-46-52-p0003","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"3","seq":2,"section":"I. Introduction","text":"The High Commissioner recommends that the Human Rights Council consider\nextending the mandate granted in its resolution 34/24 and extended in its resolution 40/20,\nand that it allocate the resources necessary for OHCHR to implement the mandate."},{"id":"a-hrc-46-52-p0004","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"4","seq":3,"section":"II. Background","text":"In its 2014 report (A/HRC/25/63), the commission of inquiry on human rights in the\nDemocratic People's Republic of Korea concluded that there were reasonable grounds to\nbelieve that crimes against humanity had been committed and continued to be committed in\nthe Democratic People's Republic of Korea. It highlighted that the gravity, scale and nature\nof those violations revealed a State that did not have any parallel in the contemporary world.\nThe commission of inquiry called for action by the entire international community to address\nthe human rights situation in the country, including referral to the International Criminal\nCourt. The crimes against humanity listed by the commission of inquiry entailed\nextermination, murder, enslavement, torture, imprisonment, rape, forced abortion and other\nforms of sexual violence, persecution on political, religious, racial and gender grounds, the\nforcible transfer of populations, enforced disappearance and the inhumane act of knowingly\ncausing prolonged starvation."},{"id":"a-hrc-46-52-p0005","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"5","seq":4,"section":"II. Background","text":"Pursuant to the recommendations of the commission of inquiry, the Human Rights\nCouncil, in its resolution 25/25, requested OHCHR to establish a field-based structure to\nstrengthen monitoring and documentation of the situation of human rights in the Democratic\nPeople's Republic of Korea, ensure accountability, enhance engagement and capacity-\nbuilding, and maintain visibility of the situation of human rights. In 2016, the Council, in its\nresolution 31/18, requested the High Commissioner to appoint a group of independent experts\nto explore appropriate approaches to seek accountability for human rights violations in the\nDemocratic People's Republic of Korea, in particular where such violations amounted to\ncrimes against humanity, and to recommend practical mechanisms of accountability to secure\ntruth and justice for victims."},{"id":"a-hrc-46-52-p0006","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"6","seq":5,"section":"II. Background","text":"In its report to the Human Rights Council (A/HRC/34/66/Add.1), the group of\nindependent experts recommended the adoption of a multi-pronged and comprehensive\napproach to accountability, including measures towards the realization of victims' rights to\ntruth, justice, reparations and guarantees of non-recurrence. Its recommendations included\nreferral of the situation to the International Criminal Court, creation of an ad hoc tribunal for\nthe Democratic People's Republic of Korea, and prosecution of crimes by Member States\nthrough the principle of universal jurisdiction."},{"id":"a-hrc-46-52-p0007","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"7","seq":6,"section":"II. Background","text":"The group of independent experts also recommended that the international community\nenhance its efforts to lay the groundwork for future criminal trials for human rights violations\nin the Democratic People's Republic of Korea. That included strengthening OHCHR through\nadditional resources to enable it to increase its contribution towards accountability for human\nrights violations in the Democratic People's Republic of Korea."},{"id":"a-hrc-46-52-p0008","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"8","seq":7,"section":"II. Background","text":"In its resolution 34/24, the Human Rights Council decided to strengthen, for a period\nof two years, the capacity of OHCHR, including its field-based structure in Seoul, to allow\nthe implementation of relevant recommendations made by the group of independent experts\nin its report aimed at strengthening current monitoring and documentation efforts,\nestablishing a central information and evidence repository, and having experts in legal\naccountability assess all information and testimonies with a view to developing possible\nstrategies to be used in any future accountability process."},{"id":"a-hrc-46-52-p0009","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"9","seq":8,"section":"II. Background","text":"In March 2019, the High Commissioner presented a report to the Human Rights\nCouncil (A/HRC/40/36) describing the progress made in the implementation of the\nrecommendations made in resolution 34/24, in particular the establishment of a dedicated\naccountability team within the OHCHR field-based structure in Seoul. In its resolution 40/20,\nthe Council extended for two years that strengthened capacity."},{"id":"a-hrc-46-52-p0010","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"10","seq":9,"section":"II. Background","text":"In March 2020, the High Commissioner presented an oral update to the Human Rights\nCouncil, pursuant to resolution 40/20.1 She noted that monitoring by OHCHR indicated what\nappeared to be ongoing systematic human rights violations in detention centres in the\nDemocratic People's Republic of Korea, including sexual violence against women and girls.\nShe called on the Council and Member States to engage with OHCHR in supporting possible\nstrategies for accountability, and to provide the necessary support for OHCHR to continue\nthat work."},{"id":"a-hrc-46-52-p0011","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"11","seq":10,"section":"II. Background","text":"United Nations human rights mechanisms, including the Special Rapporteur on the\nsituation of human rights in the Democratic People's Republic of Korea, have continued to\nmake recommendations on accountability for human rights violations committed in the\ncountry. In his most recent report to the General Assembly (A/75/388), the Special\nRapporteur expressed concern that there had been no signs of improvement or progress in\nadvancing justice and accountability for human rights violations. He highlighted the need to\nexplore the full range of possibilities to secure accountability, alongside constructive\nengagement with the Government to find solutions to human rights issues. The Secretary-\nGeneral, in his most recent report to the General Assembly (A/75/271), welcomed the\ncontinued efforts by Member States and other stakeholders to follow up on the findings of\nthe commission of inquiry, including to hold accountable individuals for conduct that may\namount to crimes against humanity."},{"id":"a-hrc-46-52-p0012","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"12","seq":11,"section":"II. Background","text":"Despite those continued calls for accountability, other political priorities with respect\nto the Korean Peninsula over the course of the reporting period have decreased emphasis by\nthe international community on pursuing accountability for human rights violations in the\nDemocratic People's Republic of Korea. The last time OHCHR was invited to brief the\nSecurity Council on the situation of human rights in the Democratic People's Republic of\nKorea was in 2017. Accountability for human rights violations in the Democratic People's\nRepublic of Korea and ending the cycle of impunity are imperative, not only to pursue justice\nand deter future violations, but also to achieve sustainable peace and stability on the Korean\nPeninsula."},{"id":"a-hrc-46-52-p0013","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"13","seq":12,"section":"II. Background","text":"On 28 September 2020, OHCHR sent a note verbale to the Government of the\nDemocratic People's Republic of Korea under the auspices of resolutions 34/24 and 40/20,\ninviting it to submit information on the measures it had taken to implement the\nrecommendations made in the High Commissioner's first written report to the Human Rights\nCouncil in 2019, and welcoming the opportunity to discuss avenues for cooperation and\nexchange of information, including in the area of rule of law reform and related best practices.\nOHCHR also shared the present report with the Government for comments. The Government\nof the Democratic People's Republic of Korea responded that it rejected the report."},{"id":"a-hrc-46-52-p0014","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"14","seq":13,"section":"III. Implementation of Human Rights Council resolutions 34/24","text":"While OHCHR has faced significant constraints, primarily due to the lack of\ncooperation from, and access to, the Democratic People's Republic of Korea, it nevertheless\nmade significant progress towards fulfilling its mandate."},{"id":"a-hrc-46-52-p0015","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"15","seq":14,"section":"III. Implementation of Human Rights Council resolutions 34/24","text":"During the period under review, OHCHR consolidated its core team of dedicated\nexperts on legal accountability, which enhanced its ability to identify, collect and preserve\ninformation and evidence from various sources about human rights violations; to analyse\ninformation collected, notably in the light of international criminal law standards; and to\nstrengthen its electronic repository for the secure storage and management of such\ninformation. OHCHR also strengthened its cooperation with representatives of Governments,\nvictims and their families, civil society organizations and legal experts, including for the\npurposes of information-sharing, capacity-building and exploring accountability strategies.\nThose activities are important investments in future accountability efforts, whether\ninternational, domestic or a combination of both."},{"id":"a-hrc-46-52-p0016","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"16","seq":15,"section":"III. Implementation of Human Rights Council resolutions 34/24","text":"The coronavirus disease (COVID-19) pandemic also presented numerous challenges.\nInterviews with people who have recently arrived in the Republic of Korea from the\nDemocratic People's Republic of Korea are a key source of information about possible\nhuman rights violations committed there. The number of people arriving in the Republic of\nKorea has however significantly decreased, in all probability due to travel restrictions relating\nto the pandemic. The Government of the Republic of Korea provisionally reported that 195\npeople had arrived in the first nine months of 2020, compared to 1,047 in all of 2019.\nMoreover, from March to May 2020, due to the COVID-19 pandemic, interviews with people\nwho had recently arrived in resettlement centres run by the Government of the Republic of\nKorea were suspended."},{"id":"a-hrc-46-52-p0017","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"17","seq":16,"section":"III. Implementation of Human Rights Council resolutions 34/24","text":"Travel restrictions due to COVID-19 significantly delayed the deployment of new\nstaff, while the United Nations regular budget financial situation affected the renewal of\ncontracts for national staff members. Interactions with key stakeholders and planned\ncapacity-building and networking activities were moved online, to the extent practicable;\nothers had to be cancelled or postponed."},{"id":"a-hrc-46-52-p0018","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"18","seq":17,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR continued to interview victims and witnesses of human rights violations to\ncollect information on acts that may give rise to individual or State responsibility, and to\nconduct research on command structures of State entities which may be responsible for such\nacts. Since the opening of the field-based structure in Seoul in 2015, OHCHR has conducted\nover 400 interviews, mostly in-person, with escapees from the Democratic People's Republic\nof Korea who had recently arrived in the Republic of Korea. OHCHR conducted all\ninterviews in a confidential setting, with the free and informed consent of the interviewees."},{"id":"a-hrc-46-52-p0019","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"19","seq":18,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR evaluated the veracity, reliability and credibility of each account provided,\nincluding for internal consistency and coherence, as well as consistency with other accounts\nreceived with respect to similar facts and patterns. Its assessment took into account potential\nbias and the scarcity of available information. Publicly available information and analysis\nfrom civil society organizations was used to further analyse the consistency of the findings.\nOHCHR analysed the information in the light of relevant international criminal law\nstandards, notably the elements constitutive of specific international crimes."},{"id":"a-hrc-46-52-p0020","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"20","seq":19,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR engaged with the Government of the Republic of Korea, both through\nmeetings with officials and formal correspondence, with a view to increasing access to\nnewly-arrived escapees at Government-run resettlement centres. Until February 2020,\nOHCHR did not have access to newly arrived male escapees at the resettlement centres.\nWhile access to male escapees was granted in February, the number of interviews allowed\nwith female escapees was simultaneously reduced by 30 per cent. Due to the pandemic, the\ntime allowed for each interview was shortened from two hours to one hour and thirty minutes.\nOHCHR will continue its dialogue with the Government of the Republic of Korea to facilitate\nincreased, meaningful access to interviewees at the resettlement centres in order to best fulfil\nits mandate."},{"id":"a-hrc-46-52-p0021","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"21","seq":20,"section":"A. Strengthening monitoring and documentation efforts","text":"In 2019, OHCHR also conducted missions to Japan to gather information about\naccountability efforts relating to the Democratic People's Republic of Korea, including\nregarding abductions of Japanese nationals and others and persecution and enforced\ndisappearances of ethnic Koreans and Japanese nationals who migrated to the Democratic\nPeople's Republic of Korea as a result of the \"Paradise on Earth\" campaign.2 OHCHR met\nwith government officials and victims and their families, and supported events organized by\ncivil society organizations. Those missions expanded and strengthened collaboration by\nOHCHR with Japan-based civil society, lawyers and other partners."},{"id":"a-hrc-46-52-p0022","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"22","seq":21,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR continued its efforts to identify escapees living in the Republic of Korea who\nhad held positions of responsibility in the Democratic People's Republic of Korea and may\nhave direct knowledge of chains of command and decision-making processes. OHCHR\ncontinues to engage with different interlocutors to locate and interview such persons in order\nto facilitate the establishment of linkages between alleged crimes and command structures\nand of individual responsibility for such crimes."},{"id":"a-hrc-46-52-p0023","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"23","seq":22,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR also continued to closely analyse publicly available information from\nGovernments, civil society, the media and academia on human rights violations and possible\ncrimes against humanity. In that respect, it worked to maintain and build relationships with\nvictims' groups and other civil society organizations that have gathered large amounts of\ncredible information about the human rights situation in the Democratic People's Republic\nof Korea and which advocate for the rights of victims. OHCHR organized regular meetings\nwith those organizations to share experiences, exchange information and coordinate\naccountability efforts. Systematic interviewing of escapees, review of information available\nin the public domain and outreach to civil society have further increased the amount, quality\nand diversity of information gathered."},{"id":"a-hrc-46-52-p0024","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"24","seq":23,"section":"B. Consolidation of a central information and evidence repository","text":"The central information and evidence repository will be a key resource for any future\nnational or international truth and justice processes. Besides functioning as a central archive\nfor information and evidence, it facilitates the identification of elements of crimes, modes of\nliability and possible perpetrators, thus assisting future accountability mechanisms."},{"id":"a-hrc-46-52-p0025","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"25","seq":24,"section":"B. Consolidation of a central information and evidence repository","text":"In 2020, the repository information and evidence preservation, storage, management\nand processing capabilities were enhanced through a major technological upgrade. The\nrepository now has a flexible and advanced tool allowing data to be migrated into various\nformats compatible with different electronic repositories or databases. The repository\nperforms complex search and correlation functions to analyse trends and patterns, thus\nfacilitating data-driven analysis and assessment. It has a higher level of data protection to\nensure confidentiality and data security to protect witnesses and victims."},{"id":"a-hrc-46-52-p0026","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"26","seq":25,"section":"B. Consolidation of a central information and evidence repository","text":"As at 31 December 2020, over 4,000 files had been preserved in the repository,\nincluding interviews, reports, satellite imagery, maps, court documents, videos, audio\nrecordings and petition letters. That includes all existing OHCHR records, along with the\ncomplete archives of the commission of inquiry. Other relevant materials, including from\nGovernments, academia and open sources, were also uploaded. All information in the\nrepository is tagged and categorized according to parameters including locations, relevant\ngovernment entities and potential crimes, in order to make future analysis more efficient."},{"id":"a-hrc-46-52-p0027","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"27","seq":26,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR continued its outreach to civil society organizations that document human\nrights violations, including possible international crimes, to encourage them to contribute\nmaterial to the repository. Their contributions included testimonies and reports, video and\naudio recordings produced inside the Democratic People's Republic of Korea, and\ninformation on various legal proceedings. In 2020, one organization transferred to OHCHR\n768 petitions it had filed on behalf of victims to the Working Group on Enforced or\nInvoluntary Disappearances, the Working Group on Arbitrary Detention and other special\nprocedures. Technical advice on investigation standards for international crimes was\nprovided to some civil society organizations to facilitate safe collection of relevant\ninformation in a manner that optimizes its potential to constitute probative and admissible\nevidence in future accountability processes."},{"id":"a-hrc-46-52-p0028","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"28","seq":27,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR continues to work with Member States and with other United Nations entities\nto raise the visibility of its work on accountability for human rights violations committed in\nthe Democratic People's Republic of Korea and to promote coordinated action by the\ninternational community. It regularly briefed members of the diplomatic community in the\nRepublic of Korea and in Geneva on its work. In Japan and the Republic of Korea, OHCHR\nmet with governmental institutions dedicated to the documentation and investigation of\nhuman rights violations relating to the Democratic People's Republic of Korea and invited\nthem to contribute information for the repository. OHCHR also continued to engage with\nUnited Nations human rights mechanisms, including the Special Rapporteur on the situation\nof human rights in the Democratic People's Republic of Korea and the Working Group on\nEnforced or Involuntary Disappearances."},{"id":"a-hrc-46-52-p0029","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"29","seq":28,"section":"B. Consolidation of a central information and evidence repository","text":"The repository is a long-term investment in the quest for truth, justice, reparation and\naccountability in the Democratic People's Republic of Korea. By consolidating large\namounts of information from diverse sources in an efficient, user-friendly, secure and stable\nlocation managed by the United Nations, the repository can help to build cases for\naccountability purposes."},{"id":"a-hrc-46-52-p0030","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"30","seq":29,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR recommends that the Human Rights Council continue to provide adequate\nresources for the maintenance and further population of the repository in the future, ensuring\nthat information is gathered and stored according to best international practices. Significant\nwork remains to be done, given the large amount of material on human rights violations and\npossible crimes against humanity in the Democratic People's Republic of Korea that needs\nto be acquired, assessed and preserved in the repository."},{"id":"a-hrc-46-52-p0031","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"31","seq":30,"section":"B. Consolidation of a central information and evidence repository","text":"While not all the information gathered by OHCHR meets specific evidentiary\nstandards for use in criminal proceedings, the analysis of the whole body of information\nserves to provide a holistic picture of the situation in the Democratic People's Republic of\nKorea and the context in which human rights violations take place, indicating where the\nstrongest information and availability of evidence may lie, and contributing to the\nidentification of individuals who may bear criminal responsibility. Prosecutors in\ninternational, hybrid or domestic courts, including those applying extraterritorial or universal\njurisdiction, could potentially rely on such information to assist in investigations and as\nbackground information to guide the collection of new evidence that meets the requisite\nevidentiary standards. Prosecutorial and judicial authorities may be granted access to\ninformation in the repository subject to established procedures of the United Nations. As the\nrepository is an independent and impartial source of information, it also includes information\nwhich may potentially be exculpatory in nature with respect to certain individuals."},{"id":"a-hrc-46-52-p0032","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"32","seq":31,"section":"B. Consolidation of a central information and evidence repository","text":"Credible and comprehensive accountability measures for human rights violations and\npossible crimes against humanity committed in the Democratic People's Republic of Korea\nremain necessary for any sustainable peace process on the Korean Peninsula. In addition to\njudicial accountability mechanisms, information in the repository can be crucial for\ncomplementary non-judicial steps towards the realization of the wider rights of victims,\nincluding measures towards the development of an accurate historical record,\nmemorialization, reparation and truth telling."},{"id":"a-hrc-46-52-p0033","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"33","seq":32,"section":"C. Development of strategies to promote accountability in the Democratic","text":"Working to fulfil its mandate, as set out by the Human Rights Council, OHCHR\nfocused on creating forums for cooperation on accountability issues relating to the\nDemocratic People's Republic of Korea, and provided support and technical advice to\npartners seeking to pursue legal accountability. OHCHR organized awareness-raising\nactivities among stakeholders in the international legal community and civil society on\nidentifying strategies for use by future accountability processes."},{"id":"a-hrc-46-52-p0034","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"34","seq":33,"section":"C. Development of strategies to promote accountability in the Democratic","text":"To that end, in April 2019, OHCHR organized, with government representatives,\nlawyers, academics and civil society organizations, a seminar entitled \"Human rights\ndocumentation and monitoring for the promotion of human rights in the Democratic People's\nRepublic of Korea\", to take stock of progress made and assess how efforts to achieve\naccountability could be advanced."},{"id":"a-hrc-46-52-p0035","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"35","seq":34,"section":"C. Development of strategies to promote accountability in the Democratic","text":"In October 2020, OHCHR hosted an online discussion forum with the Special\nRapporteur on the human rights situation in the Democratic People's Republic of Korea and\nexperts in the fields of criminal accountability, universal jurisdiction, corporate\naccountability, asset tracing, financial crime investigations and victim-centred justice, to\nshare lessons learned and examine possible avenues for accountability. Possible strategies\nwere explored in the areas of criminal, civil and corporate accountability. Participants\nexpressed interest in working together on advancing accountability, in conjunction with civil\nsociety, including victims and their representatives, and the United Nations. They stressed\nthat advocacy and awareness-raising were important complements to judicial accountability\nprocesses and highlighted the independence and impartiality of OHCHR in coordinating\nthose initiatives. Due to the COVID-19 pandemic, OHCHR was required to postpone until\n2021 a follow-up event it had planned to hold in Seoul."},{"id":"a-hrc-46-52-p0036","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"36","seq":35,"section":"C. Development of strategies to promote accountability in the Democratic","text":"During the period under review, OHCHR monitored judicial processes, including\ncriminal and civil cases in the Republic of Korea and civil processes in Japan. In the Republic\nof Korea, two men, former prisoners of war held by the Democratic People's Republic of\nKorea in the early 1950s, filed a civil lawsuit in 2019 against the Government of the\nDemocratic People's Republic of Korea and Chairman Kim Jong Un. In July 2020, a default\njudgment was issued against the defendants, awarding damages equivalent to $17,600 to each\nformer prisoner of war.3 In August 2018, five victims of the Paradise on Earth campaign, four\nwomen and one man, who had escaped from the Democratic People's Republic of Korea\nbetween 2001 and 2003, filed a civil lawsuit in Japan against the Government of the\nDemocratic People's Republic of Korea, seeking compensation equivalent to approximately\n$964,000 for each plaintiff for the infringement of their human rights.4 While such cases are\npositive steps towards a form of accountability, claimants face difficulty in securing\ninformation and evidence, the service and participation of defendants in the judicial process\nand identification of assets which may be seized to satisfy judgments, due principally to the\nlack of cooperation by the Democratic People's Republic of Korea in those cases. OHCHR\ncontinues to monitor those efforts and maintains contact with civil society organizations and\ninternational lawyers specializing in accountability initiatives, including in extraterritorial\nsettings, along with domestic lawyers and victims' groups in Japan, the Republic of Korea\nand elsewhere."},{"id":"a-hrc-46-52-p0037","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"37","seq":36,"section":"C. Development of strategies to promote accountability in the Democratic","text":"OHCHR closely monitored civil proceedings brought in the United States of America\nby the family of Otto Warmbier and met with his family in January 2019.5 In 2018, a court\nin the United States of America issued a default judgment finding the Democratic People's\nRepublic of Korea liable for the hostage-taking, torture and extrajudicial killing of Mr.\nWarmbier and awarding damages in excess of $501 million to his family. In May 2020, the\ncourt ordered three banks to disclose information on accounts holding frozen assets of the\nDemocratic People's Republic of Korea, to examine potential means of securing satisfaction\nof the judgment."},{"id":"a-hrc-46-52-p0038","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"38","seq":37,"section":"C. Development of strategies to promote accountability in the Democratic","text":"Currently, the principal avenue for victims and their families to hold individuals\ncriminally responsible for crimes committed in the Democratic People's Republic of Korea\nremains domestic judicial proceedings. That will remain the case for the foreseeable future\nunless the situation is referred to the International Criminal Court or an ad hoc tribunal or\nother comparable mechanism is established. OHCHR notes that the principles of\nextraterritorial jurisdiction allow Member States to prosecute domestically some human\nrights violations amounting to crimes which took place outside their territory, such as where\nthe victim is a national of the Member State exercising jurisdiction. Gross human rights\nviolations may be prosecuted in the domestic courts of some Member States under principles\nof universal jurisdiction, but in practice, an appropriate nexus to the Member State exercising\njurisdiction is often required as a legal precondition. OHCHR therefore encourages\nprosecutorial bodies and Member States to examine all available legal approaches within\ntheir domestic legal frameworks which may allow the exercise of respective jurisdiction to\ninitiate investigations into possible international crimes, to achieve justice and realize\nvictims' rights to redress and remedy."},{"id":"a-hrc-46-52-p0039","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"39","seq":38,"section":"C. Development of strategies to promote accountability in the Democratic","text":"OHCHR also continued to explore and promote strategies for accountability relating\nto enforced disappearances and abductions. OHCHR analysed evidence of abductions dating\nback to the Korean War and later abductions of foreign nationals, including from Japan and\nthe Republic of Korea, in the 1970s and 1980s. OHCHR also examined the continued refusal\nof the Democratic People's Republic of Korea to provide information on the location and\nfate of many of the missing, and the impact that continues to have on families residing\nprimarily in Japan and the Republic of Korea. Consideration is also being given to whether\nthose crimes, which may be of a continuous nature in relation to a number of victims, might\nfall within the jurisdiction of international criminal tribunals by virtue of that ongoing\ncharacter. OHCHR also introduced civil society organizations in Japan and the Republic of\nKorea, including victims' groups, to experts in international criminal law, who expressed an\ninterest in possible approaches to international criminal tribunals on those issues."},{"id":"a-hrc-46-52-p0040","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"40","seq":39,"section":"C. Development of strategies to promote accountability in the Democratic","text":"Numerous groups representing the families of victims of abductions during and after\nthe Korean War, the Korean Airlines hijacking6 and the Paradise on Earth campaign have\nstressed the urgent need to establish the truth and ensure accountability for perpetrators, as\nmany of the victims and their families are reaching advanced ages. OHCHR notes the cases\nof Arimoto Kayoko and Yokota Shigeru of Japan, who died in 2020 still unaware of the fate\nof their children, believed to have been abducted by the Democratic People's Republic of\nKorea over 40 years before. Their cases illustrate the lifetime suffering of families of victims\nof such enforced disappearances and abductions. OHCHR encourages Member States to\nconsider possible approaches within their domestic judicial systems to examine such cases,\nparticularly where their nationals are victims or there are other relevant connections to the\ncrimes in question."},{"id":"a-hrc-46-52-p0041","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"41","seq":40,"section":"C. Development of strategies to promote accountability in the Democratic","text":"OHCHR engaged with experts on options for the promotion of financial\naccountability, through the tracing and seizure or confiscation of illegal assets of individuals\nor entities responsible for human rights violations in the Democratic People's Republic of\nKorea. OHCHR noted that significant documentation has been collected by various\norganizations on that State's acquisition of foreign capital, including through cyberattacks\nagainst financial and other institutions, and the exportation of raw materials and labour. The\nrole of such activities in enabling human rights violations, including possible crimes against\nhumanity, and the possibilities of asset identification and seizure for appropriate purposes of\nredress, require further consideration by specialized financial investigative experts, among\nothers.\n6 On 11 December 1969, a Korean Airlines aircraft on a domestic flight was hijacked by an agent from\nthe Democratic People's Republic of Korea and flown to the Democratic People's Republic of Korea.\nThirty-nine passengers were eventually returned to the Republic of Korea, but four crew members\nand seven passengers were never returned. Families of the victims who were not returned have faced\ndifficulties in obtaining information about their family members."},{"id":"a-hrc-46-52-p0042","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"42","seq":41,"section":"IV. Key findings","text":"OHCHR continues to collect and analyse information relating to all possible crimes\nagainst humanity identified by the commission of inquiry, including in political prison camps\n(kwanliso) run by the Ministry of State Security7 and in the ordinary prison system run by the\nMinistry of State Security and the Ministry of People's Security. The ordinary prison system\nincludes short-term labour camps (rodongdanryondae), pretrial detention centres\n(kuryujang), holding centres (jipkyulso) and ordinary prisons (kyohwaso). Recent first-hand\naccounts regarding political prisons remain scarce, in all probability because political\nprisoners are rarely released; if they are released, they are closely monitored. OHCHR\ntherefore continues to collect and analyse secondary and open source information on political\nprison camps, which will be of value in future accountability processes."},{"id":"a-hrc-46-52-p0043","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"43","seq":42,"section":"IV. Key findings","text":"Given the scarcity of recent information on the political prison system, OHCHR has\nprioritized analysis of crimes for which it has recently received the most first-hand\ninformation, namely imprisonment, torture and enslavement within the ordinary prison\nsystem. Most of the escapees interviewed by OHCHR were women, many of whom\nexperienced repatriation from China.8 Many of the people who cross the northern frontier in\norder to trade are married women, since they are not assigned full-time work by the State,\nbut increasingly bear the burden of generating income for their families. Women are also\nmore at risk than men of being trafficked into neighbouring States for the purposes of forced\nmarriage and sexual or labour exploitation. In addition, most interviewees both originate from\nand were imprisoned in locations in two provinces along the northern border. That is, in all\nprobability, due to travel restrictions within the Democratic People's Republic of Korea,\nwhich make it difficult for people living in other regions to travel to border areas."},{"id":"a-hrc-46-52-p0044","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"44","seq":43,"section":"IV. Key findings","text":"OHCHR has received information which may suggest some improvement in the\ntreatment of detainees in the ordinary prison system in recent years. However, its analysis\nhas not revealed any significant shift from the finding of the commission of inquiry that the\nGovernment is engaged in a systematic and widespread attack against people considered a\nthreat to the country's political system and leadership, including people who practise religion,\nintroduce influences considered to be subversive, such as foreign films or music, or leave the\ncountry. In furtherance of that policy, it appears that members of the population are\nsystematically imprisoned without due process and are subjected to harsh treatment for\nexercising basic human rights. While in detention, escapees are intentionally subjected to\nphysical and mental suffering as part of the policy to deter and punish those deemed to pose\na political threat."},{"id":"a-hrc-46-52-p0045","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"45","seq":44,"section":"IV. Key findings","text":"The main State organs responsible for administering the ordinary prison system are\nthe Ministry of State Security and the Ministry of People's Security. However, given that\ndecision-making is highly centralized and that there are overlapping lines of authority within\nthe Government of the Democratic People's Republic of Korea, there remain reasonable\ngrounds to believe that officials in superior positions at local, regional and national levels of\nthe Government are aware, or have reason to be aware, that subordinates down to the lowest\nrank of prison guard or similar personnel continue to commit human rights violations which\nmay amount to crimes against humanity. If those violations are found to be perpetrated\npursuant to a policy to inflict such treatment on detainees, such officials may be criminally\nliable either as direct participants, under doctrines of command or superior responsibility, or\nas part of a joint criminal enterprise. In that regard, OHCHR notes that understanding\ndecision-making processes that lead to the commission of crimes remains crucial to\nidentifying responsible individuals. Cooperation and sharing of accurate information,\nincluding by Member States, is therefore essential to OHCHR analysis and to any future\naccountability processes."},{"id":"a-hrc-46-52-p0046","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"46","seq":45,"section":"A. Imprisonment","text":"The interviews that OHCHR conducts with people who have escaped from the\nDemocratic People's Republic of Korea continue to provide reasonable grounds to believe\nthat the crime against humanity of imprisonment is ongoing within the ordinary prison\nsystem."},{"id":"a-hrc-46-52-p0047","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"47","seq":46,"section":"A. Imprisonment","text":"Interviewees whose alleged crimes were considered relatively minor, such as those\nwho crossed into China for short periods, consistently described being held in harsh\nconditions, interrogated by officials of the Ministry of State Security and sent directly to\nrodongdanryondae for up to six months on the basis of an administrative decision without\ntrial."},{"id":"a-hrc-46-52-p0048","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"48","seq":47,"section":"A. Imprisonment","text":"Interviewees whose alleged crimes were considered to be more serious or to have a\npolitical element described being transferred from the custody of the Ministry of State\nSecurity to that of the of the Ministry of People's Security. They were then subjected to\njudicial processes that violated the most basic rights to a fair and public trial. Many were\nconvicted of crimes that constitute the exercise of fundamental human rights, such as the\nright to leave one's country, practise a religion or receive and share information through\ntelephone calls or by accessing media from other countries. Many interviewees told OHCHR\nthat they never saw a lawyer, and most of those who were provided with defence counsel\nsaid that their counsel failed to adequately represent them, sometimes appearing only to\nlecture them before the court hearing or to reconfirm the content of written \"confessions\"."},{"id":"a-hrc-46-52-p0049","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"49","seq":48,"section":"A. Imprisonment","text":"Available information suggests that persons who have left the Democratic People's\nRepublic of Korea and returned, been repatriated or have attempted to leave are\nsystematically subjected to intentional and severe deprivation of fundamental rights within\nthe ordinary prison system, especially if the authorities believe that they were trying to reach\nthe Republic of Korea. Interviewees who were detained for that and other political crimes\ndescribed being treated more harshly than those detained for short stays outside the country\nor for non-political crimes."},{"id":"a-hrc-46-52-p0050","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"50","seq":49,"section":"A. Imprisonment","text":"Information gathered by OHCHR provides reasonable grounds to believe that State\nofficials of the Democratic People's Republic of Korea continue to imprison individuals or\notherwise severely deprive them of their liberty in violation of fundamental rules of\ninternational law, criminalizing the exercise of basic human rights and failing to provide the\nmost basic assurances of a fair trial. Those acts may amount to the crime against humanity\nof imprisonment, if found by a competent court to take place in the context of a widespread\nand/or systematic attack against a civilian population, as indicated by the commission of\ninquiry."},{"id":"a-hrc-46-52-p0051","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"51","seq":50,"section":"B. Torture","text":"OHCHR continued to receive consistent and credible accounts of the systematic\ninfliction of severe physical and mental pain or suffering upon detainees, through the\ninfliction of beatings, stress positions and starvation in places of detention. Such information\nreconfirms the findings of the commission of inquiry and indicates that the crime against\nhumanity of torture continues to take place in the ordinary prison system."},{"id":"a-hrc-46-52-p0052","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"52","seq":51,"section":"B. Torture","text":"Nearly all of the persons interviewed by OHCHR who had experienced detention by\nthe Ministry of State Security and/or the Ministry of People's Security described having been\nbeaten during interrogations and as punishment for minor infractions. One interviewee saw\na woman kicked across a room and severely beaten by officers for hiding \"a few peppers\"\nbecause the prison food tasted bad."},{"id":"a-hrc-46-52-p0053","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"53","seq":52,"section":"B. Torture","text":"One interviewee who served a sentence in a kyohwaso from 2014 to 2016 was told by\nguards that they were \"doing prisoners a favour\" by beating them, as the alternative would\nhave been an extended sentence. One guard told the interviewee that he did not want to beat\nprisoners, but had to follow orders and would be demoted if prisoners tried to run away, so\nhe agreed to be less harsh if they did not try to flee."},{"id":"a-hrc-46-52-p0054","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"54","seq":53,"section":"B. Torture","text":"Several interviewees confirmed the continued use of the \"sitting tight\" tactic of torture\nin pretrial detention. They said that if they moved, spoke or even made unacceptable eye\ncontact with guards while sitting tight, guards would beat them or force other detainees to\nbeat them. Guards would also punish all the detainees in an entire cell by making them all\nperform difficult physical activity, such as a large number of squats. One particularly\negregious punishment was to require a detainee to bang his or her own head against the cell\nbars. An interviewee who experienced that was told by the guard that the sound of her\nbanging her head should fill the cell, and she was forced to bang her head until she fainted.\nThe frequency of breaks to stand up and stretch, or to use the toilet, depended entirely on the\ngoodwill and mood of the guards. Some interviewees mentioned that detainees sometimes\nsoiled themselves while sitting tight because they were not allowed to use the toilet. Those\nconditions add a psychological element to the physical pain of stress positions, demonstrating\nabsolute control over the detainee's physical and mental being. More recent escapees said\nthat they were monitored by closed-circuit television while sitting tight so that they could be\neven more efficiently terrorized."},{"id":"a-hrc-46-52-p0055","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"55","seq":54,"section":"B. Torture","text":"Also consistent with the findings of the commission of inquiry, almost all recent\ninterviewees confirmed to OHCHR that detainees are provided with an inadequate quantity\nof poor-quality food. The quantity may be further reduced as punishment for any perceived\ninfraction or for failing to work well or hard enough. Former detainees described receiving,\nfor example, 200 kernels of corn or a handful of boiled cornmeal three times a day, with little\nelse. Interviewees described their own malnutrition and severe weight loss, and women said\nthat they stopped menstruating. Some detainees had reportedly died of malnutrition."},{"id":"a-hrc-46-52-p0056","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"56","seq":55,"section":"B. Torture","text":"After initial investigation by the Ministry of State Security, detainees who are\ntransferred to the custody of the Ministry of People's Security are apparently allowed to\nreceive additional food from their families. However, interviewees reported that guards\nsometimes took the food for themselves, withheld it from the detainee as punishment, or\ndemanded additional bribes to allow the detainee to receive the food. One interviewee said\nthat she was denied any food brought from the outside as punishment for wanting to appeal\nher sentence. Moreover, detainees who were isolated from their families or whose families\ndid not have the financial means to provide food suffered without supplemental nutrition."},{"id":"a-hrc-46-52-p0057","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"57","seq":56,"section":"B. Torture","text":"Several interviewees mentioned the denial of medical care to detainees, except where\nfamilies provided all supplies and bribed doctors. Some interviewees witnessed other\ndetainees die as a result of the lack of medical care. Interviewees described severe cold and\nappalling hygiene conditions, including the denial of menstrual hygiene products for women."},{"id":"a-hrc-46-52-p0058","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"58","seq":57,"section":"B. Torture","text":"Information provided by a small number of interviewees suggests that since 2014,\nthere may have been some improvement in the physical treatment of detainees in at least\nsome detention facilities. Some interviewees were aware of guards or other officials being\ndisciplined for misconduct, including for beating prisoners. One interviewee told OHCHR\nthat a Ministry of State Security prosecutor came once a month to inspect the facility where\nhe was held in 2019, and on that day, detainees were given soap and haircuts, which they did\nnot otherwise receive, and the heating was turned up until the inspector left. In 2019, a former\nprison guard who had worked in a kyohwaso told OHCHR that beatings had decreased, that\nthe Ministry of People's Security had issued guidelines not to beat prisoners and that he had\nbeen instructed not to do so. He knew of two guards who had been demoted in 2015 and their\nsalary reduced for beating a detainee."},{"id":"a-hrc-46-52-p0059","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"59","seq":58,"section":"B. Torture","text":"Those examples suggest that there have been some efforts to reduce beatings and ill-\ntreatment in at least some locations. However, any such measures are marginal\nimprovements, considering the widespread and systematic nature of imprisonment and\ntorture."},{"id":"a-hrc-46-52-p0060","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"60","seq":59,"section":"B. Torture","text":"Beatings, stress positions, psychological abuse, forced labour, denial of medical care\nand sanitation and hygiene products, and starvation all combine to create an atmosphere of\nsevere mental and physical suffering in detention, exacerbated by extremely poor living\nconditions. Multiple credible accounts of such abuse provide reasonable grounds to believe\nthat officials of the Democratic People's Republic of Korea have inflicted and continue to\nintentionally inflict severe physical and/or mental pain upon detainees in their custody. Those\nacts may amount to the crime against humanity of torture, if found by a competent court to\nhave taken place in the context of a widespread and/or systematic attack against a civilian\npopulation, as indicated by the commission of inquiry."},{"id":"a-hrc-46-52-p0061","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"61","seq":60,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"OHCHR is gravely concerned by credible accounts of forced labour under\nexceptionally harsh conditions within the ordinary prison system, which may amount to the\ncrime against humanity of enslavement."},{"id":"a-hrc-46-52-p0062","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"62","seq":61,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"While international law can allow for hard labour as punishment for crimes when\nissued by a competent court in a fair trial, as long as its implementation is consistent with\nother human rights, the commission of inquiry noted that \"the extraction of forced labour can\namount to enslavement if it is accompanied by aggravating circumstances that effectively\ndestroy the juridical personhood of the victim\".9 Relevant circumstances to a finding of\nenslavement include the degree of control exercised over victims, measures to prevent or\npunish escape, violence and cruel treatment, conditions and intensity of labour and other\nfactors."},{"id":"a-hrc-46-52-p0063","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"63","seq":62,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"Many interviewees described being subjected to hard labour in rodongdanryondae by\nan administrative process without trial. Others were subjected to forced labour in kyohwaso\nafter patently unfair trials. Many were sentenced for \"crimes\" that consisted of exercising\nfundamental human rights, such as leaving one's own country or receiving information from\nother countries.10"},{"id":"a-hrc-46-52-p0064","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"64","seq":63,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"Interviewees described forced labour including construction work, farming, logging,\nmining and similar forms of heavy manual labour. One interviewee served a sentence in a\nkyohwaso in 2014 and was forced to work in agriculture. She described how human beings\nwere used as beasts of burden: \"There was no machine, so seven or eight of us dragged the\ncart that cows normally pull.\" Forced labour also included manufacturing such as knitting,\nmetal fabrication and making false eyelashes and clasps for necklaces. Interviewees were\nalso outsourced to work at State-run enterprises in charge of earning foreign currency and at\nprivate homes, including those of Ministry of State Security and Ministry of People's\nSecurity officials."},{"id":"a-hrc-46-52-p0065","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"65","seq":64,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"The forced labour described by interviewees took place under exceptionally harsh\nconditions, including extremely long working hours, starvation rations, overall poor living\nand hygiene conditions, denial of medical care and frequent beatings for minor infractions\nand failing to meet work quotas. Detainees were also subjected to psychological abuse such\nas extensive self-criticism sessions; having to walk bent over at all times and having to bow\nto guards whenever they passed, or be beaten; study sessions on how not to resist beatings;\nand being forced to dig graves for detainees who had died. There were severe repercussions\nfor anyone trying to escape, including beatings by other detainees at the order of the guards.\nMany interviewees paid bribes for better conditions, less demanding work or to be released,\npointing to rampant corruption and the arbitrary nature of the forced labour system."},{"id":"a-hrc-46-52-p0066","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"66","seq":65,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"In analysing the conditions of forced labour described by interviewees in the light of\nrelevant legal standards, OHCHR notes the degree of control exercised over detainees; their\ntotal lack of freedom of movement; measures taken to deter them from or punish them for\nescaping; inhumane conditions and the use of physical violence and psychological terror; and\nthe possible profiting by State organs and/or individuals from labour performed by detainees.\nThose acts may amount to the crime against humanity of enslavement or \"other inhumane\nacts of a similar character intentionally causing great suffering, or serious injury to body or\nto mental or physical health\",11 if found by a competent court to have taken place in the\n9 \"Report of the detailed findings of the commission of inquiry on human rights in the Democratic\nPeople's Republic of Korea\", para. 1048. Available from\nwww.ohchr.org/EN/HRBodies/HRC/CoIDPRK/Pages/ReportoftheCommissionofInquiryDPRK.aspx.\n10 OHCHR also received reports of individuals who had been subjected to forced labour in pretrial\ndetention.\n11 Rome Statute of the International Criminal Court, art. 7 (1) (k). See also International Criminal Court,\nElements of Crimes, art. 7 (1) (k) (1).\ncontext of a widespread and/or systematic attack against a civilian population as indicated by\nthe commission of inquiry."},{"id":"a-hrc-46-52-p0067","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"67","seq":66,"section":"C. Enslavement and/or \"other inhumane acts\"","text":"In the light of the conditions of forced labour described by interviewees, OHCHR\nintends to continue to examine information on its use in the Democratic People's Republic\nof Korea in the next phase of its work."},{"id":"a-hrc-46-52-p0068","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"68","seq":67,"section":"V. Conclusions","text":"Analysis of available information continues to confirm that there are reasonable\ngrounds to believe that crimes against humanity have been committed and may be\nongoing in the Democratic People's Republic of Korea. OHCHR reiterates that there is\nno statute of limitations for crimes against humanity, and that those responsible for past\nand ongoing crimes should be held accountable. A lasting peace on the Korean\nPeninsula can be achieved only if such violations end and the rights of victims to truth,\njustice, reparations and guarantees of non-recurrence are fulfilled."},{"id":"a-hrc-46-52-p0069","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"69","seq":68,"section":"V. Conclusions","text":"To achieve those aims, prosecution of the alleged international crimes committed\nin the Democratic People's Republic of Korea must remain a priority, whether through\nreferral of the situation to the International Criminal Court or the establishment of an\nad hoc tribunal or other comparable mechanism. At the same time, it is imperative to\nensure that information continues to be collected and preserved to support\naccountability strategies at all levels. That includes domestic processes that may be\nbased on extraterritorial or universal jurisdiction, as well as possible future\ninternational accountability processes. Collecting, analysing and preserving\ninformation will also continue to be useful in support of complementary, non-judicial\nmeasures towards the realization of the rights of victims, such as developing a historical\nrecord, memorialization, reparation and truth-telling exercises."},{"id":"a-hrc-46-52-p0070","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"70","seq":69,"section":"V. Conclusions","text":"While a small number of victims and their families in Japan, the Republic of\nKorea and the United States of America have sought justice in national courts, those\ninitiatives are, to date, limited in scope and hampered by the lack of cooperation from\nthe Democratic People's Republic of Korea. A referral to the International Criminal\nCourt or the creation of an ad hoc tribunal or other comparable mechanism would\nprovide a complementary avenue for accountability, ensuring that those most\nresponsible for human rights violations that may amount to crimes against humanity\ncan be held to account at the international level. Any such approach would stand to\nbenefit from the groundwork being carried out by OHCHR, in particular with respect\nto information-gathering, documentation and awareness-raising."},{"id":"a-hrc-46-52-p0071","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"71","seq":70,"section":"V. Conclusions","text":"The decision of the Human Rights Council to strengthen the capacity of OHCHR,\nincluding its field-based structure in Seoul, by providing resources for a dedicated\naccountability team allows the Office to undertake significant preparatory work toward\naccountability for serious human rights violations perpetrated in the Democratic\nPeople's Republic of Korea, including where they amount to crimes under international\nlaw. The accountability team comprises experts in international criminal law and\ninformation and evidence management, and requires modest resources. The additional\nresources have allowed OHCHR to make significant progress in documenting and\nstoring information about suspected crimes against humanity and other serious\nviolations of human rights, in establishing and populating the information and evidence\nrepository, and in analysing the information that has been gathered from international\ncriminal law perspectives."},{"id":"a-hrc-46-52-p0072","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"72","seq":71,"section":"V. Conclusions","text":"The Human Rights Council should continue to strengthen its support for the\naccountability work of OHCHR. In addition to present staffing levels in Seoul and in\nGeneva, additional dedicated experts in international criminal law, legal interpretation\nand information management would enable fuller delivery on the mandate to\nstrengthen monitoring, documentation and analysis in relation to relevant criminal law\nperspectives."},{"id":"a-hrc-46-52-p0073","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"73","seq":72,"section":"VI. Recommendations","text":"On the basis of the activities it has conducted to date pursuant to resolutions\n34/24 and 40/20, the High Commissioner recommends that the Government of the\nDemocratic People's Republic of Korea:\n(a) Acknowledge the existence of serious human rights violations, which may\namount to crimes against humanity, and take immediate steps to end such violations,\nincluding by demonstrating its willingness and capacity to undertake independent and\nimpartial investigations into allegations of such violations and hold those responsible to\naccount;\n(b) Grant international humanitarian organizations and human rights\nmonitors immediate access to the country, including to all detention facilities;\n(c) Initiate reform of criminal justice legislation and rule of law institutions,\nincluding the judiciary and law enforcement and corrections systems, in accordance\nwith international human rights norms and standards;\n(d) Ensure that victims of serious human rights violations, including those\namounting to crimes against humanity, and their families are provided with adequate,\nprompt, effective and gender-sensitive reparation and remedies, including public\nacknowledgment of the truth of the violations suffered;\n(e) Ratify all relevant international treaties and human rights instruments,\nincluding the Convention against Torture and Other Cruel, Inhuman or Degrading\nTreatment or Punishment and the International Convention for the Protection of All\nPersons from Enforced Disappearance."},{"id":"a-hrc-46-52-p0074","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"74","seq":73,"section":"VI. Recommendations","text":"On the basis of the activities it has conducted to date pursuant to resolutions\n34/24 and 40/20, the High Commissioner recommends that Member States:\n(a) Take further steps to ensure accountability for those responsible for\nserious human rights violations in the Democratic People's Republic of Korea at the\ninternational level, including through the referral by the Security Council of the\nsituation to the International Criminal Court or the creation of an ad hoc international\ntribunal or other comparable mechanism;\n(b) Take steps to ensure that efforts aimed at securing a lasting peace on the\nKorean Peninsula give due priority to the human rights of the people of the Democratic\nPeople's Republic of Korea, restoring the dignity of victims by respecting and\nupholding their rights to truth, justice, reparation and guarantees of non-recurrence;\n(c) Undertake, where possible, the investigation and prosecution of persons\nsuspected of committing international crimes in the Democratic People's Republic of\nKorea, including based on principles of extraterritorial and/or universal jurisdiction;\n(d) Continue to facilitate the work conducted by OHCHR pursuant to Human\nRights Council resolutions 34/24 and 40/20, including with regard to access to\nindividuals who have fled the Democratic People's Republic of Korea, and to the\ncollection and analysis of relevant testimony, documentation and information;\n(e) Take all necessary steps to maintain civic space, in particular with respect\nto victims' groups and other civil society organizations engaged in gathering\ninformation about the human rights situation in the Democratic People's Republic of\nKorea and advocating for the rights of victims of human rights violations;\n(f) Consider means by which further relevant information under Human\nRights Council resolutions 34/24 and 40/20 could be conveyed by States to OHCHR,\nsubject to appropriate conditions."},{"id":"a-hrc-46-52-p0075","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"75","seq":74,"section":"VI. Recommendations","text":"On the basis of the activities it has conducted to date pursuant to resolutions\n34/24 and 40/20, the High Commissioner recommends that the Human Rights Council\nand the General Assembly, acknowledging that a referral to the International Criminal\nCourt or the creation of an ad hoc tribunal or other mechanism may be unlikely in the\nnear future, consider extending the mandate of the dedicated OHCHR accountability\nteam for an additional period of two years to further pursue implementation of\nresolutions 34/24 and 40/20, namely strengthening monitoring and documentation\nefforts by OHCHR, further developing the information and evidence repository and\nbroadening the pursuit of efforts toward accountability for the crimes identified by the\ncommission of inquiry."},{"id":"a-hrc-46-52-p0076","rec_id":"reclgNaRVziEBKGmt","symbol":"A/HRC/46/52","n":"76","seq":75,"section":"VI. Recommendations","text":"On the basis of the activities it has conducted to date pursuant to resolutions\n34/24 and 40/20, the High Commissioner recommends that all stakeholders continue to\ncooperate with OHCHR in the collection, documentation and preservation of\ninformation relating to alleged human rights violations and crimes against humanity\ncommitted in the Democratic People's Republic of Korea."},{"id":"a-hrc-52-64-u0000","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":null,"seq":0,"section":null,"text":"Fifty-second session\n27 February�31 March 2023\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-52-64-u0001","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":null,"seq":1,"section":null,"text":"The present report, submitted to the Human Rights Council pursuant to its resolutions\n49/22 and 46/17, describes the activities of the Office of the United Nations High\nCommissioner for Human Rights in promoting accountability for human rights violations in\nthe Democratic People's Republic of Korea, highlighting the progress made and the\nchallenges encountered. It also examines information the Office of the High Commissioner\nhas gathered on human rights violations committed in the Democratic People's Republic of\nKorea in the light of relevant international legal standards. It concludes with\nrecommendations addressed to the Government of the Democratic People's Republic of\nKorea, other Member States and the Council.","unnumbered":true},{"id":"a-hrc-52-64-p0001","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"1","seq":2,"section":"I. Introduction","text":"The present report is submitted to the Human Rights Council pursuant to its\nresolutions 46/17 and 49/22 on the situation of human rights in the Democratic People's\nRepublic of Korea. It provides an update to the report of the United Nations High\nCommissioner for Human Rights (A/HRC/46/52) and oral update given to the Council at its\nforty-ninth session, in March 2022. In its resolution 46/17, the Council requested the High\nCommissioner to submit to the Council, at its fifty-second session, a full report on the\nimplementation of the recommendations made by the group of independent experts on\naccountability aimed at strengthening current monitoring and documentation efforts,\nestablishing a central information and evidence repository, having experts in legal\naccountability assess all information and testimonies with a view to developing possible\nstrategies to be used in any future accountability process. The Council also requested the\nOffice of the United Nations High Commissioner for Human Rights (OHCHR) to organize a\nseries of consultations and outreach activities with victims, affected communities and other\nrelevant stakeholders with a view to including their views into avenues for accountability.\nThe present report describes the activities of OHCHR in the past two years to implement\nCouncil resolutions 34/24, 40/20, 46/17 and 49/22, highlighting the progress made and the\nchallenges encountered. The report examines, in the light of relevant international legal\nstandards, information gathered by OHCHR on human rights violations committed in the\nDemocratic People's Republic of Korea. OHCHR sought the views of the Government of the\nDemocratic People's Republic of Korea on the implementation of resolution 46/17. In its\nreply, the Government repeated its position that it did not recognize Council resolutions,\nwhich it saw as a product of the policy of \"hostile\" Member States. OHCHR shared the\npresent report with the Government of the Democratic People's Republic of Korea for\ncomments. The Government responded that it rejected the report. OHCHR stands ready to\ncooperate and engage with the Government on improving the situation of human rights in the\nDemocratic People's Republic of Korea."},{"id":"a-hrc-52-64-p0002","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"2","seq":3,"section":"II. Context","text":"The year 2023 marks the tenth anniversary of the establishment by the Human Rights\nCouncil, in its resolution 22/13, of the commission of inquiry on the situation of human rights\nin the Democratic People's Republic of Korea. In its report (A/HRC/25/63), the commission\nconcluded that there were reasonable grounds to believe that crimes against humanity had\nbeen committed and continued to be committed in the Democratic People's Republic of\nKorea. The Council, in its resolution 25/25, requested OHCHR to establish a field-based\nstructure to strengthen monitoring and documentation of the situation of human rights in the\nDemocratic People's Republic of Korea, to ensure accountability, to enhance engagement\nand capacity-building, and to maintain visibility of the situation of human rights. In June\n2015, OHCHR established a field-based structure in Seoul."},{"id":"a-hrc-52-64-p0003","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"3","seq":4,"section":"II. Context","text":"In 2016, the Human Rights Council, in its resolution 31/18, requested the High\nCommissioner to appoint a group of independent experts to explore appropriate approaches\nto seek accountability for human rights violations in the Democratic People's Republic of\nKorea. In its report to the Council (A/HRC/34/66/Add.1), the group of independent experts\nrecommended the adoption of a multi-pronged and comprehensive approach to\naccountability and to strengthen the capacity of OHCHR, including its field-based structure.\nIn its resolution 34/24, the Human Rights Council decided to strengthen, for a period of two\nyears, the capacity of OHCHR, including its field-based structure in Seoul, to allow the\nimplementation of relevant recommendations made by the group of independent experts in\nits report relating to accountability. The Council extended that mandate in March 2019 in its\nresolution 40/20, and again in March 2021, in its resolution 46/17, for a two-year period."},{"id":"a-hrc-52-64-p0004","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"4","seq":5,"section":"III. Implementation of Human Rights Council resolutions 34/24","text":"As stated by the Secretary-General in his report on the situation of human rights in the\nDemocratic People's Republic of Korea (A/77/247), OHCHR remains gravely concerned\nabout the impact of the coronavirus disease (COVID-19) pandemic on the situation of human\nrights in the country. OHCHR expressed concerns that the prolonged closure of the borders\ncoupled with limited access to food, medicines and health care would have a dire impact on\nthe people who were already struggling to meet their basic needs,1 in particular on older\npersons, persons with disabilities and persons in detention. It has not, however, been able to\nindependently verify the disparate consequences of the COVID-19 pandemic and response.\nIn addition to the impact of the pandemic on the fulfilment of basic needs, OHCHR has also\nexpressed concern about increased restrictions on civil and political rights.2 In May 2022, the\nHigh Commissioner addressed a letter to the Government of the Democratic People's\nRepublic of Korea offering support to help it to ensure that COVID-19 response measures\nrespect and protect the human rights of the people in the country (A/77/247, para. 36). At the\ntime of writing, no response had been received. OHCHR has also repeatedly urged the\nGovernment to facilitate the return of United Nations and other international staff to the\ncountry to provide life-saving and essential humanitarian support."},{"id":"a-hrc-52-64-p0005","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"5","seq":6,"section":"A. Strengthening monitoring and documentation efforts","text":"It is crucial for OHCHR to have maximum access to individuals who can provide\naccurate and up-to-date first-hand accounts of the situation of human rights in the Democratic\nPeople's Republic of Korea. During the period under review, OHCHR conducted 110 in-\nperson and remote interviews (52 women and 58 men), with escapees from the Democratic\nPeople's Republic of Korea and other stakeholders in the Republic of Korea and Japan.3"},{"id":"a-hrc-52-64-p0006","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"6","seq":7,"section":"A. Strengthening monitoring and documentation efforts","text":"The OHCHR interview programme continues to be affected by the COVID-19\npandemic.4 Increased restrictions on movement related to the COVID-19 pandemic continue\nto reduce significantly the number of escapees leaving the Democratic People's Republic of\nKorea and arriving in the Republic of Korea.5 It is not known how many people may have\nleft the Democratic People's Republic of Korea to other countries during the pandemic.\nToday, most new arrivals in the Republic of Korea are persons who left the Democratic\nPeople's Republic of Korea several years before the beginning of the pandemic and remained\nin other countries for extended periods. Such persons therefore may not have up-to-date\ninformation on the current situation in the country. Given the lower number of new arrivals\nin the Republic of Korea, OHCHR has explored other means to gather information, including\nby increasing the number of interviews conducted outside resettlement centres, gathering\ninformation from a wider range of sources (including through the use of new technologies)\nand focusing on thematic areas, such as abductions and enforced disappearances, overseas\nforced labour and sexual and gender-based violence."},{"id":"a-hrc-52-64-p0007","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"7","seq":8,"section":"A. Strengthening monitoring and documentation efforts","text":"Interviews with recent arrivals from the Democratic People's Republic of Korea are\nimportant for OHCHR to collect fresh information about the situation on the ground and to\nimplement its mandate effectively. OHCHR has increased its capacity to interview escapees\nand is in regular dialogue with the Ministry of Unification of the Republic of Korea, which\noperates the resettlement centres, to ensure access to individuals in the centres and adequate\ntime with interviewees to conduct confidential, informed, gender-responsive and victim-\ncentred interviews and to gather relevant documentation."},{"id":"a-hrc-52-64-p0008","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"8","seq":9,"section":"A. Strengthening monitoring and documentation efforts","text":"OHCHR continued to identify potential interviewees living outside of the resettlement\ncentres in the Republic of Korea. These interviews also provide OHCHR with an opportunity\nto explain to victims their rights and to provide information on international human rights\nmechanisms. Many escapees face challenges in establishing their new lives, and are focused\non securing access to jobs and education; this leaves them with little time or incentive to\nmake themselves available for interviews that focus on past traumatic experiences. Some\ninterviewees expressed serious concerns about their safety, and the safety of their family\nmembers, friends and associates who remain in the Democratic People's Republic of Korea.6"},{"id":"a-hrc-52-64-p0009","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"9","seq":10,"section":"A. Strengthening monitoring and documentation efforts","text":"Collecting information from previously high-ranking government officials from the\nDemocratic People's Republic of Korea remains a challenge. Persons who may be able to\nprovide critical information on State policies and decision-making processes are reluctant to\nbe identified or to give interviews for safety and privacy reasons, as well as owing to their\nright not to give self-incriminating information in relation to possible human rights\nviolations, including possible international crimes. OHCHR raised these issues with relevant\npartners who conduct interviews, and supported capacity-building activities on related topics,\nand stands ready to assist in developing guidelines in this regard should such partners request\nit."},{"id":"a-hrc-52-64-p0010","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"10","seq":11,"section":"A. Strengthening monitoring and documentation efforts","text":"Reporting by the Democratic People's Republic of Korea under the United Nations\nhuman rights treaties to which it is a party, as well as for universal periodic review, remains\nlimited. Increased engagement with these mechanisms is, potentially, one means to alleviate\nthe lack of information on the situation of human rights in the country and to highlight any\ninitiatives undertaken by the Government to improve it.7 OHCHR stands ready to cooperate\nand engage with the Government in meeting its reporting obligations."},{"id":"a-hrc-52-64-p0011","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"11","seq":12,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR continued to expand its central information and evidence repository\nestablished pursuant to Human Rights Council resolution 34/24, and to analyse the\ninformation collected. Currently, the repository contains records of 517 interviews with\nvictims, witnesses and others. The majority of these interviews are with women. Items stored\nin the repository include original information from civil society organizations (including\nsome led by women), reports, maps, court documents, videos, audio recordings and\ncommunications to United Nations human rights bodies, among other items. The repository\nalso contains an information archive of the work conducted by the commission of inquiry\nand the group of independent experts."},{"id":"a-hrc-52-64-p0012","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"12","seq":13,"section":"B. Consolidation of a central information and evidence repository","text":"The repository is intended to be a central and comprehensive database of information\non human rights violations in the Democratic People's Republic of Korea, some of which\nmay amount to international crimes. Its purpose is to support future accountability initiatives\nby providing access to as much high-quality and well-organized information as possible. The\nrepository also serves to develop and preserve an accurate historical record, which will be\ncrucial for victims in their pursuit of non-judicial accountability measures. OHCHR\npreserves the information collected in a secure and confidential manner and in compliance\nwith United Nations regulations, policies and practices. The repository includes advanced\nanalytical tools that can identify trends and patterns, locate key interviews and visualize data\n,and will also be useful for future accountability measures in assessing the strength of\navailable information and identifying gaps.\n6 See Korea Institute for National Unification, White Paper on Human Rights in North Korea 2021, pp.\n566�69.\n7 The Democratic People's Republic of Korea has submitted: for the Human Rights Committee, the third\nperiodic report was previously due in 2004 but has been overdue since 22 April 2022; for the Committee\non Economic, Social and Cultural Rights, the third periodic report has been overdue since 30 June 2008;\nfor the Committee on the Elimination of Discrimination against Women, the combined second to fourth\nperiodic reports were considered in November 2017; for the Committee on the Rights of Persons with\nDisabilities, the periodic report for the first review cycle was submitted in December 2018; and for the\nCommittee on the Rights of the Child, the sixth and seventh periodic reports were due in October 2022.\nThe Democratic People's Republic of Korea is due to be reviewed during the fourth cycle of the\nuniversal periodic review, in 2024."},{"id":"a-hrc-52-64-p0013","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"13","seq":14,"section":"B. Consolidation of a central information and evidence repository","text":"The lack of access to the Democratic People's Republic of Korea poses unique\nconstraints to pursuing accountability for human rights violations and international crimes,\nespecially in collecting information and populating the repository. There is currently no\nprospect of conducting independent investigations inside the country. Gathering\ndocumentary or physical evidence outside the country remains difficult owing to the\nGovernment's near-total control of information within the country, the repression of\nindependent non-governmental activity, and a comprehensive system of State surveillance\nand harsh punishments for accessing or distributing information not endorsed by the\nGovernment. In addition, secrecy (including on the identity and functions of high-level\nleaders and changes in senior leadership) and the limited number of high-ranking individuals\nwho have left the country make it challenging to link human rights violations and possible\ncrimes to individuals who may be responsible for them."},{"id":"a-hrc-52-64-p0014","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"14","seq":15,"section":"B. Consolidation of a central information and evidence repository","text":"In the Republic of Korea, the Center for North Korean Human Rights Records within\nthe Ministry of Unification interviews most of the newly arrived people from the Democratic\nPeople's Republic of Korea.8 The North Korea Human Rights Documentation Office within\nthe Ministry of Justice maintains the archives of these interviews as well as other\ndocumentation.9 Given the Center's access to recent arrivals, the Documentation Office\narchive is probably the most comprehensive in documenting the situation of human rights in\nthe Democratic People's Republic of Korea. OHCHR continues to engage with both entities\nto seek ways to include this important information in the OHCHR central repository, in line\nwith the applicable legal framework established by the Government of the Republic of Korea.\nIn addition, several civil society organizations have also developed repositories containing\ntheir own interviews, research and analysis. OHCHR is engaging with all the stakeholders to\nsupport their documentation initiatives and to encourage the said organizations to contribute\nto the central repository maintained by OHCHR, which would allow more comprehensive\nevaluation and analysis of the information collected in terms of elements of international\ncrimes and the responsibility of perpetrators."},{"id":"a-hrc-52-64-p0015","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"15","seq":16,"section":"B. Consolidation of a central information and evidence repository","text":"Several civil society organizations contributed to the repository during the period\nunder review. In gathering these resources, OHCHR works with contributors to protect the\nprivacy of victims and witnesses and to ensure their informed consent to the use of their\ninformation. The preservation of the information in a secure and consolidated manner in one\nplace would contribute significantly to the groundwork necessary to advance accountability\nstrategies and initiatives."},{"id":"a-hrc-52-64-p0016","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"16","seq":17,"section":"C. Developing strategies to promote accountability in the Democratic","text":"Owing to the lack of accountability at the domestic level, the commission of inquiry\nrecommended, inter alia, the referral by the Security Council of the situation in the\nDemocratic People's Republic of Korea to the International Criminal Court or the\nestablishment of an ad hoc tribunal (A/HRC/25/63, para. 87). At the time of writing, however,\nno referral had been made. Civil society organizations in the Republic of Korea and Japan\nhave submitted communications to the International Criminal Court on behalf of victims,\nincluding Korean War abductees, prisoners of war , citizens of the Democratic People's\nRepublic of Korea, Japanese abductees, and victims of the \"Paradise on Earth\" campaign.10\nGiven this and other challenges, victims' groups and civil society organizations continue to\npursue other avenues for legal accountability."},{"id":"a-hrc-52-64-p0017","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"17","seq":18,"section":"C. Developing strategies to promote accountability in the Democratic","text":"Another option to ensure criminal accountability in the Democratic People's Republic\nof Korea would be for Member States to pursue investigations and prosecutions based on\nprinciples of extraterritorial and/or universal jurisdiction in legal proceedings observing fair\ntrial and due process guarantees. Practical and legal challenges limit the prospect of\nprosecutions under the principle of universal jurisdiction. Not all States where significant\nnumbers of people from the Democratic People's Republic of Korea reside have established\nuniversal jurisdiction in their national legal systems. Some States that do exercise universal\njurisdiction in their national legal systems require a nexus between the alleged crime and\ntheir jurisdiction � mostly through the presence or residence of a victim or accused in the\nterritory of the prosecuting State concerned. Other challenges include the difficulty involved\nin collecting documentary and physical evidence and the low probability that possible\nperpetrators will travel abroad.11 Despite the challenges, however, the presence of a number\nof potential victims in the Republic of Korea has highlighted the possibility of prosecutions\nthere. The Republic of Korea has a comprehensive legal framework that could potentially\npermit the investigation and prosecution of international crimes committed in the Democratic\nPeople Republic of Korea.12 In its next phase of work, OHCHR will facilitate exchanges\namong Member States, including those that have successfully implemented universal\njurisdiction, to share information and best practices on the possibility of initiating criminal\nprosecutions under the principles of universal jurisdiction and addressing any legal\nconstraints encountered."},{"id":"a-hrc-52-64-p0018","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"18","seq":19,"section":"C. Developing strategies to promote accountability in the Democratic","text":"Some Member States have, either individually or collectively, applied targeted\nsanctions against individuals and entities for their alleged role in human rights violations.\nInitiatives include the Global Magnitsky Sanctions programme in the United States of\nAmerica, the global human rights sanctions regime of the European Union, and the Global\nHuman Rights Sanctions of the United Kingdom of Great Britain and Northern Ireland.13\nSome of these sanctions programmes allow victims and other stakeholders to present\ninformation for the relevant Government to investigate individuals and entities. In Member\nStates where victim participation in unilateral sanctions is possible, victims and other\nstakeholders should be provided with information and support to make informed decisions\nabout their possible participation. Measures should be carefully crafted to ensure they do not\nnegatively affect the enjoyment of rights � including economic, social and cultural rights �\nby a State's population, and minimize any possible negative impact on the human rights of\npersons who may be sanctioned, including their rights to a fair trial, to property and to\nprivacy.14"},{"id":"a-hrc-52-64-p0019","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"19","seq":20,"section":"C. Developing strategies to promote accountability in the Democratic","text":"Another avenue of accountability is the pursuit of civil claims against the Government\nof the Democratic People's Republic of Korea. In the Republic of Korea, civil claims have\nbeen filed by former prisoners of war and victims of abduction during the Korean War, some\nof which resulted in monetary damages being awarded.15 In Japan, five victims (four women\nand one man) of the \"Paradise on Earth\" campaign (see para. 16 above) filed a civil lawsuit\nin 2018 against the Democratic People's Republic of Korea. In March 2022, the Tokyo\nDistrict Court found that it did not have jurisdiction over the claim owing to the statute of\nlimitations. In its decision, however, the Court acknowledged some of the plaintiffs' claims\nas fact, and the case provided a valuable opportunity for plaintiffs to gain public recognition\n11 In successful prosecutions, perpetrators had found refuge in the territory of the State exercising\nuniversal jurisdiction. For an overview of universal jurisdictions cases, see Universal Jurisdiction\nAnnual Review 2022, https://trialinternational.org/latest-post/2021-highlights-in-the-universal-\njurisdiction-annual-review-ujar-released-today/.\n12 See Republic of Korea, Act on Punishment of Crimes Under Jurisdiction of the International Criminal\nCourt, act No. 8719, 21 December 2007), amended by act No. 10577, 12 April 2011.\n13 The sanctions programme in the United States is based on the Global Magnitsky Human Rights\nAccountability Act of 2016 and other authorities. The United Kingdom programme relies on the Global\nHuman Rights Sanctions Regulations 2020 and the Sanctions and Anti-Money Laundering Act 2018,\nand the European Union programme is based on Council Regulation (EU) 2020/1998 of 7 December\n2020.\n14 For a discussion on the impact of unilateral sanctions on human rights, see A/HRC/45/7, paras. 27 and\n38.\n15 See Seoul Central District Court, cases No. 2016 Ga-Dan 5235506, No. 2020 Ga-Dan 5306603 and No.\n2020 Ga-Hap 2804.\nof their experiences.16 Courts in the United States of America have also awarded damages in\ncivil litigation against the Democratic People's Republic of Korea. Serving notice of\nproceedings against the Government of the Democratic People's Republic of Korea,\ngathering evidence and collecting compensation from the Democratic People's Republic of\nKorea present serious challenges to the success of such claims.17"},{"id":"a-hrc-52-64-p0020","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"20","seq":21,"section":"C. Developing strategies to promote accountability in the Democratic","text":"Civil society organizations and relatives of disappeared persons continue to submit\ncases to the Working Group on Enforced or Involuntary Disappearances and the Working\nGroup on Arbitrary Detention. As at May 2022, the Working Group on Enforced or\nInvoluntary Disappearances had transmitted 362 cases (concerning 309 men and 53 women)\nsince 1980 to the Government of the Democratic People's Republic of Korea. None of these\ncases has been resolved.18"},{"id":"a-hrc-52-64-p0021","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"21","seq":22,"section":"IV. Patterns of violations","text":"OHCHR continues to collect and analyse information relating to serious human rights\nviolations committed in the Democratic People's Republic of Korea, some of which may\namount to international crimes. In March 2021, the High Commissioner concluded that there\nare reasonable grounds to believe that crimes against humanity have been committed and\nmay be ongoing in the Democratic People's Republic of Korea (A/HRC/46/52, para. 68).\nOHCHR continues to develop its analysis, aiming to document the State policies of the\nDemocratic People's Republic of Korea, map decision-making processes and identify the\ngovernment entities involved in implementing such policies. OHCHR continues to prepare\nthematic reports and discussion papers on the situation of human rights in the Democratic\nPeople's Republic of Korea.19"},{"id":"a-hrc-52-64-p0022","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"22","seq":23,"section":"A. Enforced disappearances and abductions","text":"Between 2016 and 2022, OHCHR conducted 80 interviews (38 male and 42 female)\nin the Republic of Korea and Japan relating to cases of enforced disappearance and abduction\nin and by the Democratic People's Republic of Korea. The practices of enforced\ndisappearance and abductions in and by the Democratic People's Republic of Korea has two\ndistinct patterns: the first comprises enforced disappearances reportedly committed through\nthe continued practice of arbitrary detention inside the Democratic People's Republic of\nKorea of its nationals; the second comprises the enforced disappearance of foreign nationals,\nmainly between 1950 and the mid-1980s. The latter include abductions of nationals of the\nRepublic of Korea during and after the Korean War, the non-repatriation of prisoners of war,\nand abductions of foreign nationals from China, France, Japan, Lebanon, Malaysia, Romania,\nSingapore and Thailand. The interviews also included victims of the \"Paradise on Earth\"\ncampaign."},{"id":"a-hrc-52-64-p0023","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"23","seq":24,"section":"A. Enforced disappearances and abductions","text":"Enforced disappearance constitutes a unique and integrated series of acts and\nomissions representing a grave threat to life and a continuing violation of various human\nrights, such as those recognized in the International Covenant on Civil and Political Rights.20\nThe systematic practice of enforced disappearance is of the nature of a crime against\nhumanity.21 United Nations human rights bodies have pointed out that the pain and suffering\nexperienced by the relatives and families of disappeared persons can amount to torture or\ninhuman treatment,22 and that this torture is continuous upon those relatives and families.23\nIn this sense, the crime of enforced disappearance continues until the State acknowledges the\ndetention or releases information pertaining to the fate or whereabouts of the disappeared\nperson.24 The victims interviewed by OHCHR, including relatives of forcibly disappeared\npersons, described long-lasting suffering that affected their well-being and resulted in\nconditions that need psychological or medical treatment. A number of the elderly parents of\nthe disappeared have died without knowing the fate or whereabouts of their children."},{"id":"a-hrc-52-64-p0024","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"24","seq":25,"section":"A. Enforced disappearances and abductions","text":"Enforced disappearances also have a negative impact on the enjoyment of economic,\nsocial and cultural rights of the families of the forcibly disappeared. 25 The interviews\nhighlighted the disparate impact of these hardships on women and on the children of\ndisappeared persons. In most cases of enforced disappearance, the person forcibly\ndisappeared was a man, and the main breadwinner of the family; as a consequence, women\nhad to shoulder the entire burden of family care. Families of disappeared persons faced\npoverty. Children, especially elder daughters, were pressured to give up education and work\nto support the family. Interviewees also reported being subjected to social stigmatization and\ndiscrimination. International human rights instruments have recognized that victims of\nhuman rights violations have a right to remedy and redress. Most of the interviewees,\nhowever, described feeling neglected for many years without adequate support and\nprotection, information about their loved ones, or efforts to locate the missing."},{"id":"a-hrc-52-64-p0025","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"25","seq":26,"section":"A. Enforced disappearances and abductions","text":"In 2022, OHCHR carried out a series of consultations with victims' groups and civil\nsociety organizations, including some led by women. OHCHR also sent a written\nquestionnaire to 17 victims' groups and civil society organizations in Japan, the Republic of\nKorea and Thailand, and to the Governments of Japan and the Republic of Korea. The\nconsultations and questionnaire were aimed at gathering information about the ongoing\nsuffering of victims of enforced disappearance and abduction and their families, and to seek\nthe victims' perspectives on truth-seeking, justice mechanisms and reparations."},{"id":"a-hrc-52-64-p0026","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"26","seq":27,"section":"A. Enforced disappearances and abductions","text":"Victims, including families of forcibly disappeared persons, informed OHCHR about\ntheir views and expectations with regard to the realization of their right to truth, justice\n(including accountability) and reparations. Families emphasized the importance of the\ndisclosure of the truth about the fate and whereabouts of forcibly disappeared persons and\ntheir immediate and safe return. Many families hoped to resume family reunions and to\nrestore contacts with relatives in the Democratic People's Republic of Korea. Many seek the\nreturn of the remains of victims who have died. Victims emphasized that many of the forcibly\ndisappeared persons and their families are of advanced age, and there is no time to wait to\nresolve these cases. Interviewees expressed their wish for the Democratic People's Republic\nof Korea to sincerely apologize for its role in enforced disappearances and to take steps\ntowards accountability. Families emphasized the need for criminal prosecutions to hold to\naccount those responsible for enforced disappearances, as well as comprehensive reparation\nprogrammes, including compensation, rehabilitation, restitution, satisfaction, and guarantees\nof non-recurrence."},{"id":"a-hrc-52-64-p0027","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"27","seq":28,"section":"B. Overseas forced labour","text":"During the period under review, OHCHR interviewed 18 men who were allegedly\nsent to work overseas by the Democratic People's Republic of Korea to generate income for\nDisappearance. Japan and the Republic of Korea are parties to the Rome Statute; the Democratic\nPeople's Republic of Korea is not. Japan is a party to the International Convention for the Protection of\nAll Persons from Enforced Disappearance; the Parliament of the Republic of Korea ratified the\nConvention on 8 December 2022.\n22 See for example CCPR/C/113/D/2000/2010, para. 11.7; CCPR/C/119/D/2259/2013, para. 7.8; and\nA/HRC/16/48, para. 39, general comment on the right to the truth in relation to enforced\ndisappearances, para. 4,.\n23 A/HRC/16/48, para. 39, general comment on the right to the truth in relation to enforced\ndisappearances, para. 4.\n24 Ibid., general comment on enforced disappearance as a continuous crime, para. 1.\n25 A/HRC/30/38/Add.5.\nthe State.26 Interviewees described the tight system of government control, in particular that\nexerted by the Ministry of State Security, in coordinating and sending its nationals overseas\nas labourers. Interviewees reported that overseas work was very much sought-after, with\nsongbun27 and bribes determining who had access to such opportunities."},{"id":"a-hrc-52-64-p0028","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"28","seq":29,"section":"B. Overseas forced labour","text":"The former overseas workers interviewed had mostly worked in labour intensive\nsectors, such as construction and logging. They described physically arduous and sometimes\ndangerous work, and long working hours without adequate breaks or holidays, or adequate\nhealth and safety measures in place. Long working hours were reportedly further extended if\nstrict work quotas were not met."},{"id":"a-hrc-52-64-p0029","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"29","seq":30,"section":"B. Overseas forced labour","text":"Interviewees reported having to pay between 80 and 90 per cent of their salary to the\nGovernment of the Democratic People's Republic of Korea. They were able to keep a small\namount for daily necessities, including food and medicine, and sent the remainder back to\nfamily members in the Democratic People's Republic of Korea as remittances. Some reported\nbeing misled about their level of pay and being vulnerable to further extortion by officials of\nthe Democratic People's Republic of Korea present at the workplace. Some reported that they\nreceived only small amounts for daily necessities, while others reported that they were paid\nin vouchers that could supposedly be redeemed for goods upon their return home, but that\nlater proved worthless. Interviewees reported that they would endure the conditions because\nthey could make more money abroad than at home. Moreover, any attempt to organize or\ncomplain about pay, or working or living conditions, exposed workers to the risk of being\nsent back to the Democratic People's Republic of Korea."},{"id":"a-hrc-52-64-p0030","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"30","seq":31,"section":"B. Overseas forced labour","text":"Men sent overseas as labourers described having virtually no freedom of movement,\nwith restrictions on leaving their work sites and having to reside in cramped living quarters\nimposed by the Ministry of State Security officials stationed at the overseas workplaces.\nRestrictions were also placed on access to mobile phones for communicating with family.\nLetters sent home were read and censored by Ministry of State Security officials.\nInterviewees also reported strict restrictions on access to information, including newspapers,\nthe Internet and television while in workers compounds."},{"id":"a-hrc-52-64-p0031","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"31","seq":32,"section":"B. Overseas forced labour","text":"Former overseas workers told OHCHR that, after working three to five years abroad,\nthey had more freedom to leave their compounds and seek freelance work. This often\nconsisted of building and maintenance work for private homes in the local community. A\nsum would still have to be paid to the State, but money made beyond that amount could be\nkept by the worker."},{"id":"a-hrc-52-64-p0032","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"32","seq":33,"section":"B. Overseas forced labour","text":"Some overseas workers escaped from their places of employment and subsisted by\ndoing freelance work; however, this put them at risk of arrest by the host State and forced\nrepatriation to the Democratic People's Republic of Korea, which would likely include\nimprisonment. The COVID-19 pandemic exacerbated their vulnerability, leading many men\nwho had been subsisting abroad for extended periods to migrate to the Republic of Korea for\nsafety. In analysing the conditions and treatment reported by overseas workers, OHCHR is\nconcerned that such conditions may amount to forced labour."},{"id":"a-hrc-52-64-p0033","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"33","seq":34,"section":"C. Female victims of trafficking","text":"OHCHR documented 14 accounts of female victims of trafficking during the period\nunder review. It interviewed women who had been trafficked into neighbouring States, often\nfor marriage or for work. Some of the interviewees had been arrested in the neighbouring\nState, forcibly returned by the neighbouring State's authorities, and imprisoned for having\nleft the Democratic People's Republic of Korea, usually without a trial. These women left\nthe Democratic People's Republic of Korea again after completing their punishment, and\neventually made their way to the Republic of Korea."},{"id":"a-hrc-52-64-p0034","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"34","seq":35,"section":"C. Female victims of trafficking","text":"Interviewees who had been trafficked into neighbouring countries reported living in\nfear that if their origins were discovered, they would be repatriated and imprisoned. Some\nwomen reported having children in the countries where they were trafficked, and some were\nforced to leave behind children of mixed parentage if they were repatriated."},{"id":"a-hrc-52-64-p0035","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"35","seq":36,"section":"C. Female victims of trafficking","text":"OHCHR has consistently expressed concern that the continued forced return to the\nDemocratic People's Republic of Korea exposes people to arbitrary detention, and to the\npersonal and real risk of irreparable harm, such as torture, gender-based violence, including\nsexual violence, and other serious human rights violations, in breach of the principle of non-\nrefoulement, as set forth in article 3 of the Convention against Torture and Other Cruel,\nInhuman or Degrading Treatment or Punishment, entailing an obligation under article 2 of\nthe International Covenant on Civil and Political Rights28 to which States neighbouring the\nDemocratic People's Republic of Korea are a party. There is also a need to alleviate the\nconditions that make people vulnerable to trafficking, and to take action to discourage the\ndemand for trafficked persons.29"},{"id":"a-hrc-52-64-p0036","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"36","seq":37,"section":"A. Consultations","text":"OHCHR continues to organize consultations and outreach activities with victims,\naffected communities and other stakeholders in order to include their views in avenues for\nensuring accountability. Consultation is a crucial element of the human rights-based and\nvictim-centred approach to accountability for human rights violations. Victims and affected\ncommunities must be able to express their views freely during the consultation process so\nthat their experiences, needs and entitlements can be identified and taken into account in the\ndesign and implementation of future accountability processes. OHCHR has used these\nconsultations as an opportunity to inform victims and affected communities about their rights,\nfor example by providing \"one-pagers\" of basic information about international human rights\nlaw and accountability. By building on stakeholders' knowledge, these interactions also\nprovide an opportunity to manage expectations about the feasibility of different approaches\nto accountability."},{"id":"a-hrc-52-64-p0037","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"37","seq":38,"section":"A. Consultations","text":"In April 2022, OHCHR organized a workshop to inform stakeholders about the\nconsultation process and to discuss the way forward. Participants included representatives of\ncivil society organizations (including some led by women) in the Republic of Korea, Japan\nand Thailand, government officials, United Nations human rights experts and diplomatic\nmissions in the Republic of Korea."},{"id":"a-hrc-52-64-p0038","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"38","seq":39,"section":"A. Consultations","text":"OHCHR conducted a series of consultations with victims, civil society organizations\n(including some led by women), academia, domestic and international legal practitioners,\nand other stakeholders. Stakeholders are encouraged to provide input through surveys and\nwritten questionnaires, focus groups, in-depth interviews and roundtables. In particular, focus\ngroup discussions have been conducted with specific groups, including victims of enforced\ndisappearance, relatives of abductees and prisoners of war and female escapees. In addition\nto victims' groups, future consultations will be held with members of the judiciary,\nprosecutors, legal practitioners, academia and government representatives. Key findings\nfrom the consultations on stakeholders' views on avenues for accountability, including\njudicial and non-judicial measures, will be published in 2023."},{"id":"a-hrc-52-64-p0039","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"39","seq":40,"section":"A. Consultations","text":"The lack of access to the Democratic People's Republic of Korea limits consultations\nto a small pool of victims and families outside the country. These consultations do not, indeed\n28 See Human Rights Committee general comment No. 31 (2004), para. 12. On the application of the\nprinciple of non-refoulement in cases of human trafficking, see also communication No. 2288/2013\n(CCPR/C/114/D/2288/2013), paras. 7.2�7.5.\n29 Protocol to Prevent, Suppress and Punish Trafficking in Persons, Especially Women and Children,\nsupplementing the United Nations Convention against Transnational Organized Crime, art. 9, paras. 4\nand 5.\ncannot, engage the full range of victims and affected communities. OHCHR will continue to\nseek opportunities to broaden the pool of victims and their families in these consultations."},{"id":"a-hrc-52-64-p0040","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"40","seq":41,"section":"B. Capacity-building","text":"During the period under review, OHCHR continued to provide capacity-building\nactivities to victims' groups, civil society organizations (including some led by women),\ngovernment officials of the Republic of Korea, and students. The aim of such activities is to\nsupport stakeholders in gathering and documenting information relating to human rights\nviolations and possible crimes against humanity in the Democratic People's Republic of\nKorea, and to maximize the usefulness of such information for any future accountability\nprocesses."},{"id":"a-hrc-52-64-p0041","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"41","seq":42,"section":"B. Capacity-building","text":"Capacity-building activities for civil society organizations included workshops on\npossible pathways to accountability before national and international jurisdictions; rights of\nvictims and the need for consultations with them; and information about unilateral sanctions\nregimes linked to human rights violations. OHCHR facilitated discussions on the role of civil\nsociety organizations in promoting accountability for human rights violations. OHCHR also\norganized a workshop on victims' rights under international law, and provided examples of\nvictims' consultations in accountability measures in other States. It also delivered training\nsessions on basic standards and evidence preservation for judicial accountability processes,\nand demonstrated the functionality of the OHCHR central repository so that partners may\nbetter understand the benefits of contributing to it."},{"id":"a-hrc-52-64-p0042","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"42","seq":43,"section":"B. Capacity-building","text":"OHCHR contributed to capacity-building programmes organized by partners,\nincluding presentations on the work of OHCHR, engagement with United Nations human\nrights mechanisms, and victims' rights under international law for female escapees from the\nDemocratic People's Republic of Korea now living in the Republic of Korea. Presentations\nwere given on the situation of human rights in the Democratic People's Republic of Korea\nand the role of the United Nations human rights system to law students and youths."},{"id":"a-hrc-52-64-p0043","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"43","seq":44,"section":"B. Capacity-building","text":"OHCHR delivered training sessions for Government officials of the Republic of\nKorea who engage with people from the Democratic People's Republic of Korea and\ndocument the situation of human rights there. Topics included international criminal law,\nmethodologies of verification and analysis in human rights monitoring, international\nstandards on fair trial rights and due process guarantees, global practices for documenting\nhuman rights violations at the international and domestic levels, and supporting and\npromoting human rights, including gender perspectives. OHCHR also held regular\nroundtables throughout the period under review with civil society organizations and other\nstakeholders to provide updates on the work of the Office and to facilitate the sharing of\ninformation. These programmes have stimulated discussions on important matters of law and\npolicy and enhanced the capacity of stakeholders to gather and analyse high-quality human\nrights information and increase its possible utility in future accountability processes."},{"id":"a-hrc-52-64-p0044","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"44","seq":45,"section":"B. Capacity-building","text":"Outreach activities will be central to consolidating existing relationships by engaging\nwith a broader range of stakeholders. OHCHR will continue its capacity-building activities\nand develop communities of practice among experts in the field of accountability who can\nprovide substantive and technical training on relevant topics. OHCHR will continue its\nawareness-raising initiatives to sensitize victims' groups on international norms and\nstandards pertaining to accountability for human rights violations."},{"id":"a-hrc-52-64-p0045","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"45","seq":46,"section":"VI. Conclusions","text":"Despite the challenges it faces, OHCHR continues to gather information that is\nconsistent with the findings of the commission of inquiry that serious human rights\nviolations and possible international crimes continue in the Democratic People's\nRepublic of Korea. OHCHR continues to analyse the information available on these\nviolations and possible crimes, including their disparate impact on men, women, boys\nand girls. This work includes analysis of the structure and organization of the\nGovernment of the Democratic People's Republic of Korea and its lack of respect for\nits human rights obligations."},{"id":"a-hrc-52-64-p0046","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"46","seq":47,"section":"VI. Conclusions","text":"For the reasons given above, the prospects for criminal accountability for human\nrights violations and possible international crimes in the Democratic People's Republic\nof Korea remain modest. Fresh, creative strategies are needed to address this matter.\nPossible avenues for criminal accountability, including universal jurisdiction in the\nRepublic of Korea, where a large number of potential victims reside, have been\ndescribed in the present report."},{"id":"a-hrc-52-64-p0047","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"47","seq":48,"section":"VI. Conclusions","text":"Member States, including the Republic of Korea, should consider fundamental\nquestions regarding the role of different government institutions in information-\ngathering, the purpose and objectives of their information-gathering activities, and\nstrategies required to prosecute high- or low-ranking perpetrators. Under international\nlaw, States have a clear obligation to prosecute those responsible for international\ncrimes, such as crimes against humanity, in legal proceedings with fair trial and due\nprocess guarantees. While gathering information, States must respect the due process\nand fair trial rights of perpetrators, including the right against self-incrimination, and\nthe rights of victims to redress. This balance, and the fact that amnesties for crimes\nagainst humanity are impermissible, should be taken into consideration when\ndeveloping comprehensive policies."},{"id":"a-hrc-52-64-p0048","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"48","seq":49,"section":"VI. Conclusions","text":"Given the nature and gravity of the alleged crimes, it remains crucial for\nOHCHR to continue to independently gather and preserve information for future use\naccording to established methodologies. As statutes of limitations do not apply to crimes\nagainst humanity, the information collected and preserved could be used in\nprosecutions at any point in the near or distant future. Interviews have indicated that\nthat monitoring and reporting may even have a deterrent effect on potential violations."},{"id":"a-hrc-52-64-p0049","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"49","seq":50,"section":"VI. Conclusions","text":"Victims have the right to justice and to full and adequate reparations. Moreover,\nefforts should continue to consult victims themselves about what accountability means\nto them and what meaningful redress would look like. The consultations currently being\nconducted by OHCHR are an important means to allow victims and other stakeholders\nto participate in the process of finding pathways for accountability. Its work in\ninterviewing victims and other stakeholders and in gathering information about the\nsituation of human rights in the Democratic People's Republic of Korea is also part of\na broader, victim-centred and gender-sensitive approach to accountability. By\nrecording victims' accounts, information is preserved for collective memory and can\nprovide some measure of redress by offering victims the opportunity to tell their stories."},{"id":"a-hrc-52-64-p0050","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"50","seq":51,"section":"VI. Conclusions","text":"The commission of inquiry documented patterns of human rights violations\ngoing back decades. Many victims of human rights violations and possible international\ncrimes in the Democratic People's Republic of Korea are of an advanced age. It is\nessential that the full range of available options for redress that could bring some\nsatisfaction to victims during their lifetime is explored. In accordance with the Basic\nPrinciples and Guidelines on the Right to a Remedy and Reparation for Victims of\nGross Violations of International Human Rights Law and Serious Violations of\nInternational Humanitarian Law, 30 victims not only have the right to equal and\neffective access to justice but also to adequate, effective and prompt reparation for harm\nsuffered. In particular, OHCHR proposes some possible ways forward with respect to\nreparation."},{"id":"a-hrc-52-64-p0051","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"51","seq":52,"section":"VI. Conclusions","text":"Compensation may be pursued through civil litigation and administrative\nprocedures wherever victims live. OHCHR seeks to facilitate the identification of best\npractices and challenges and the sharing of information and strategies among victims,\ncivil society organizations and legal experts. Trust funds for victims of human rights\nviolations and possible international crimes are also potential means of providing\ncompensation."},{"id":"a-hrc-52-64-p0052","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"52","seq":53,"section":"VI. Conclusions","text":"Satisfaction can include truth processes, the recovery and return of remains to\nvictims' families, and apologies from relevant authorities, among other measures. Truth\n30 General Assembly resolution 60/147, annex.\nprocesses can take the form of public hearings of victims, and memorialization\ninitiatives. Without prejudice to the obligation of the State responsible for the violations\nto provide victims with reparation, other States can act to protect the rights of victims;\nfor example, the Truth and Reconciliation Commission of the Republic of Korea has\nexamined human rights violations by the Democratic People's Republic of Korea on\nbehalf of victims now living in the Republic of Korea.31 Other positive developments\ninclude online databases to visualize sites of human rights violations using satellite\nimagery, \"online museums\", efforts to establish physical museums (such as the National\nMemorial for Abductees during the Korean War, in the Republic of Korea), and efforts\nsuch as those in Niigata Prefecture (Japan) to cultivate a grove of trees in memory of\npersons who departed under the \"Paradise on Earth\" campaign."},{"id":"a-hrc-52-64-p0053","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"53","seq":54,"section":"VI. Conclusions","text":"The Democratic People's Republic of Korea should firstly provide guarantees of\nnon-repetition, including through reforms to its security and justice apparatus. The\nharm caused by human rights violations in the Democratic People's Republic of Korea\nmay, however, be prolonged in countries where people from the Democratic People's\nRepublic of Korea resettle, through discrimination, stigmatization and lack of support.\nRelevant guarantees of non-repetition could include action to ensure access to\neducation, employment and participation in public and political life for persons from\nthe Democratic People's Republic of Korea wherever they live."},{"id":"a-hrc-52-64-p0054","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"54","seq":55,"section":"VI. Conclusions","text":"Rehabilitation includes the provision of necessary medical, psychological, social\nand legal support to victims."},{"id":"a-hrc-52-64-p0055","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"55","seq":56,"section":"VI. Conclusions","text":"The work of OHCHR in pursuing accountability for human rights violations and\npossible international crimes in the Democratic People's Republic of Korea remains\ncrucial. In this respect, the commitment of the Human Rights Council to providing long-\nterm sustainable support, including through the allocation of adequate resources, for\nthat work, including that of the OHCHR field-based structure in Seoul, is vital."},{"id":"a-hrc-52-64-p0056","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"56","seq":57,"section":"VII. Recommendations","text":"The High Commissioner recommends that the Government of the Democratic\nPeople's Republic of Korea:\n(a) Acknowledge the existence of serious human rights violations, which may\namount to crimes against humanity or other international crimes, and take immediate\nsteps to end such violations, including by demonstrating its willingness and capacity to\nundertake independent and impartial investigations into allegations of such violations\nand to hold those responsible to account;\n(b) Grant international humanitarian organizations and human rights\nmonitors immediate access to the country, including to all detention facilities;\n(c) Initiate reform of criminal justice legislation and rule of law institutions,\nincluding the judiciary and law enforcement and corrections systems, in accordance\nwith international human rights norms and standards;\n(d) Ensure that victims of serious human rights violations, including those\namounting to international crimes, and their families are provided with adequate,\nprompt, effective and gender-sensitive reparation and remedies, including public\nacknowledgment of the truth of the violations suffered;\n(e) Ratify all relevant international treaties and human rights instruments,\nincluding the Convention against Torture and Other Cruel, Inhuman or Degrading\nTreatment or Punishment and the International Convention for the Protection of All\nPersons from Enforced Disappearance."},{"id":"a-hrc-52-64-p0057","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"57","seq":58,"section":"VII. Recommendations","text":"The High Commissioner recommends that Member States:\n(a) Take further steps to ensure accountability for those responsible for\nserious human rights violations in the Democratic People's Republic of Korea at the\ninternational level, including through the referral by the Security Council of the\nsituation to the International Criminal Court or the creation of an ad hoc international\ntribunal or other comparable mechanism;\n(b) Take steps to ensure that efforts aimed at securing a lasting peace on the\nKorean Peninsula give due priority to the human rights of the people of the Democratic\nPeople's Republic of Korea, restoring the dignity of victims by respecting and\nupholding their rights to truth, justice, reparation and guarantees of non-recurrence;\n(c) Undertake, where possible, investigations into and the prosecution of\npersons suspected of committing international crimes in the Democratic People's\nRepublic of Korea, including on the basis of the principle of extraterritorial and/or\nuniversal jurisdiction;\n(d) Continue to facilitate the work conducted by OHCHR pursuant to Human\nRights Council resolutions 46/17 and 49/22, including with regard to access to\nindividuals who have fled the Democratic People's Republic of Korea, and to the\ncollection and analysis of relevant testimony, documentation and information;\n(e) Take all steps necessary to maintain civic space, in particular with respect\nto victims' groups and other civil society organizations engaged in gathering\ninformation about the situation of human rights in the Democratic People's Republic\nof Korea and advocating for the rights of victims of human rights violations;\n(f) Consider means by which further relevant information under Human\nRights Council resolutions 46/17 and 49/22 could be conveyed by States to OHCHR,\nsubject to appropriate conditions."},{"id":"a-hrc-52-64-p0058","rec_id":"recNdg7R5ytkg5iSC","symbol":"A/HRC/52/64","n":"58","seq":59,"section":"VII. Recommendations","text":"The High Commissioner recommends that the Human Rights Council consider\nextending the mandate of the dedicated OHCHR accountability team for an additional\nperiod of two years to further pursue the implementation of Council resolutions 34/24,\n40/20, 46/17 and 49/22, namely by strengthening monitoring and documentation efforts\nby OHCHR, further developing the information and evidence repository, and\nbroadening the pursuit of efforts toward accountability for the crimes identified by the\ncommission of inquiry."},{"id":"a-hrc-58-61-u0000","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":null,"seq":0,"section":null,"text":"Fifty-eighth session\n24 February�4 April 2025\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General","unnumbered":true},{"id":"a-hrc-58-61-u0001","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":null,"seq":1,"section":null,"text":"In the present report, submitted to the Human Rights Council pursuant to its\nresolutions 52/28 and 55/21, the United Nations High Commissioner for Human Rights\ndescribes the activities of the Office of the High Commissioner in promoting accountability\nfor human rights violations in the Democratic People's Republic of Korea, highlighting the\nprogress made and the challenges encountered. The High Commissioner also examines\ninformation that the Office of the High Commissioner has gathered on human rights\nviolations committed in the Democratic People's Republic of Korea in the light of relevant\ninternational legal standards. The High Commissioner concludes with recommendations\naddressed to the Government of the Democratic People's Republic of Korea and other\nMember States.","unnumbered":true},{"id":"a-hrc-58-61-p0001","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"1","seq":2,"section":"I. Introduction","text":"The present report is submitted to the Human Rights Council pursuant to its\nresolutions 52/28 and 55/21 on the situation of human rights in the Democratic People's\nRepublic of Korea. In its resolution 52/28, the Council requested the United Nations High\nCommissioner for Human Rights to submit to the Council, at its fifty-eighth session, a full\nreport on the implementation of the recommendations made by the group of independent\nexperts on accountability aimed at strengthening current monitoring and documentation\nefforts, establishing a central information and evidence repository, and having experts in legal\naccountability assess all information and testimonies with a view to developing possible\nstrategies to be used in any future accountability process. The Council also requested the\nOffice of the United Nations High Commissioner for Human Rights (OHCHR) to continue\nto organize a series of consultations and outreach activities with victims, affected\ncommunities and other relevant stakeholders with a view to including their views into\navenues for accountability."},{"id":"a-hrc-58-61-p0002","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"2","seq":3,"section":"I. Introduction","text":"In the present report, which covers the period from 1 November 2022 to 31 October\n2024, the High Commissioner describes the activities undertaken by OHCHR � including its\nfield-based structure in Seoul � during the reporting period to implement the Council\nmandate, highlighting the progress made and the challenges encountered. The High\nCommissioner examines, in the light of relevant international legal standards, information\ngathered by OHCHR on patterns of human rights violations committed in the Democratic\nPeople's Republic of Korea, with a particular focus on freedom of expression and the right\nto food, as well as efforts by OHCHR to strengthen, institutionalize and further advance its\nwork on accountability and the consultations process. OHCHR shared the present report with\nthe Government of the Democratic People's Republic of Korea for factual comments. No\nresponse was received from the Government of the Democratic People's Republic of Korea."},{"id":"a-hrc-58-61-p0003","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"3","seq":4,"section":"A. Strengthening monitoring and documentation","text":"During the period under review, OHCHR conducted 175 interviews with escapees\n(112 women and 63 men) from the Democratic People's Republic of Korea, victims of human\nrights violations, and families and relatives of victims. OHCHR also interviewed former\nhigh-ranking officials providing critical information about State policies, structures and\ndecision-making processes."},{"id":"a-hrc-58-61-p0004","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"4","seq":5,"section":"A. Strengthening monitoring and documentation","text":"In addition to interviews, OHCHR also held 122 consultations with 229 stakeholders\n(127 women and 102 men) and 39 organizations on their views regarding truth, justice and\nreparations. Those consultations significantly expanded the engagement of OHCHR with\nvictim-led groups, young people, researchers and other information providers."},{"id":"a-hrc-58-61-p0005","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"5","seq":6,"section":"A. Strengthening monitoring and documentation","text":"The efforts of OHCHR to strengthen monitoring and documentation are influenced by\nthe number and type of escapees leaving the Democratic People's Republic of Korea, who\nare a prime source of information on the human rights situation in the country. In August\n2023, the Democratic People's Republic of Korea partially reopened its borders, which had\nremained closed since the start of the coronavirus disease (COVID-19) pandemic. However,\nmovement within the country and freedom to leave the country remain restricted. During the\nperiod under review, the number of people arriving in the Republic of Korea from the\nDemocratic People's Republic of Korea has significantly decreased compared with\npre-pandemic figures. The Government of the Republic of Korea reported that 181 escapees\n(159 women and 22 men) had arrived in the first nine months of 2024 and 196 escapees had\narrived in 2023, compared with the arrival of 1,047 escapees in 2019."},{"id":"a-hrc-58-61-p0006","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"6","seq":7,"section":"A. Strengthening monitoring and documentation","text":"During the period under review, OHCHR observed a demographic shift among the\nescapees arriving in the Republic of Korea, reflecting new modes and routes of escape. Prior\nto the pandemic, a majority of escapees were women who had been trafficked into\nneighbouring States. During the reporting period, an increasing number of men who had been\nsent overseas as labourers to generate income for the State and who later escaped from their\nworkplaces arrived. In the same period, OHCHR interviewed a small number of escapees\nwho fled directly from the Democratic People's Republic of Korea to the Republic of Korea\nacross the demilitarized zone and the sea."},{"id":"a-hrc-58-61-p0007","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"7","seq":8,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR continues to strengthen its central repository of information and evidence to\nensure its relevance, usefulness and accessibility in future accountability initiatives. Given\nthe nature and scale of the violations, documentation of possible international crimes and the\nconsolidation, management and preservation of information lay the groundwork to support\naccountability efforts, including future investigations and prosecution of alleged perpetrators,\nin a timely manner. The information collected, analysed and stored in the repository also\nsupports human rights analysis and reporting, maintenance of a historical record of crimes\nand violations, and documentation of the experiences of victims for use in truth-telling or\nother non-judicial measures."},{"id":"a-hrc-58-61-p0008","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"8","seq":9,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR populates the central repository with interview material and other\ninformation it gathers directly, as well as original documents from the Democratic People's\nRepublic of Korea, analytical reports, academic articles, satellite imagery and any other\nmaterial that could be relevant in future investigations. The information is securely preserved,\ncategorized and easily manageable."},{"id":"a-hrc-58-61-p0009","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"9","seq":10,"section":"B. Consolidation of a central information and evidence repository","text":"The volume of the information preserved doubled during the reporting period, as the\ncentral repository was also augmented by materials provided by civil society organizations,\nacademic sources, victims and government entities. That included a number of original\ndocuments, such as official orders and guidelines for law enforcement authorities,\nphotographs taken inside the Democratic People's Republic of Korea, transcripts of\ninterviews with victims conducted by partner organizations, court documents, and petitions\nsubmitted to United Nations and national human rights mechanisms."},{"id":"a-hrc-58-61-p0010","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"10","seq":11,"section":"B. Consolidation of a central information and evidence repository","text":"Each item is reviewed by OHCHR, assessed for credibility and tagged with relevant\nmetadata (such as information on the provider, any identified victims and perpetrators, the\nscope of informed consent and other details). The Office also tags the item to related human\nrights violations according to a standardized list used globally by OHCHR, as well as to\npossible international crimes, such as those established in the Rome Statute of the\nInternational Criminal Court."},{"id":"a-hrc-58-61-p0011","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"11","seq":12,"section":"B. Consolidation of a central information and evidence repository","text":"The consolidation of information in the central repository has supported OHCHR to\nprecisely identify interviews that specifically raise possible international crimes and to\nidentify excerpts from interviews that indicate constitutive elements of international crimes.\nIt has also facilitated the identification of potential evidentiary gaps that require the gathering\nof additional information and evidence. Regular coordination with United Nations\ninvestigative bodies1 has allowed the incorporation of global best practices and the deepening\nof expertise on digital tools and electronic evidence management."},{"id":"a-hrc-58-61-p0012","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"12","seq":13,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR will continue working with partners to expand the contents of the repository\nwith relevant information, including information gathered from victims and escapees by\npartner organizations. To that end, OHCHR is engaging with partners to ensure appropriate\ninformed consent is secured from information providers to allow their information to be\nshared with the Office for preservation in the repository and possible future sharing with\ninvestigative, prosecutorial and judicial authorities. OHCHR is also working with partners to\npromote safeguards for the psychosocial well-being and mental health of victims and\nwitnesses during interviews and documentation."},{"id":"a-hrc-58-61-p0013","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"13","seq":14,"section":"B. Consolidation of a central information and evidence repository","text":"Several civil society organizations maintain databases of information, including\ninterview material and other data relating to human rights in the Democratic People's\n1 Those exchanges are conducted in accordance with Human Rights Council resolution 52/28, para. 13.\nRepublic of Korea. In accordance with its mandate, OHCHR actively supports coordination\nand standardization of monitoring methodologies among all these actors."},{"id":"a-hrc-58-61-p0014","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"14","seq":15,"section":"B. Consolidation of a central information and evidence repository","text":"In addition, the Center for North Korean Human Rights Records of the Ministry of\nUnification is a government body of the Republic of Korea that conducts investigations and\ncollects and records related data in accordance with the provisions of the North Korean\nHuman Rights Act of the Republic of Korea."},{"id":"a-hrc-58-61-p0015","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"15","seq":16,"section":"B. Consolidation of a central information and evidence repository","text":"OHCHR observes that the proliferation of separate human rights databases maintained\nby different stakeholders highlights the need for coordination to streamline information-\ngathering activities and ensure consistency in documentation and storage of collected\ninformation."},{"id":"a-hrc-58-61-p0016","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"16","seq":17,"section":"C. Current strategies to promote accountability","text":"The primary responsibility for accountability for human rights violations, some of\nwhich may amount to international crimes, rests with the Democratic People's Republic of\nKorea. However, given the gravity, scale and seriousness of the violations and the inability\nor unwillingness of the State to pursue accountability, the United Nations commission of\ninquiry on human rights in the Democratic People's Republic of Korea recommended, among\nother things, the referral by the Security Council of the situation to the International Criminal\nCourt or the establishment of an international tribunal.2 The group of independent experts on\naccountability,3 the Special Rapporteur on the situation of human rights in the Democratic\nPeople's Republic of Korea4 and OHCHR5 have consistently reiterated that a referral of the\nhuman rights situation in the Democratic People's Republic of Korea to the International\nCriminal Court should be a priority."},{"id":"a-hrc-58-61-p0017","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"17","seq":18,"section":"C. Current strategies to promote accountability","text":"OHCHR liaises with other national and international mechanisms to identify\nstrategies for accountability in accordance with international law standards.6 In February\n2024, the OHCHR field-based structure in Seoul leveraged those connections to host a\nconference marking the tenth anniversary of the report of the commission of inquiry on\nhuman rights in the Democratic People's Republic of Korea and exploring ways forward to\nadvance accountability. More than 150 participants attended, representing civil society,\ndiplomatic missions, experts, students, victims and escapees. Experts and practitioners,\nincluding national prosecutorial authorities, reparations specialists, documentation\nspecialists, criminal lawyers and heads of international investigative mechanisms shared their\nexperiences from around the globe in dealing with the past and ensuring accountability for\ngross human rights violations and crimes. Discussions focused on domestic approaches to\naccountability for international crimes, victims' perspectives on accountability, reparations\nand other non-judicial approaches to accountability, and current international trends to\nadvance accountability for international crimes.7"},{"id":"a-hrc-58-61-p0018","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"18","seq":19,"section":"C. Current strategies to promote accountability","text":"OHCHR has consistently called upon Member States to take steps to facilitate\ninvestigations and prosecutions of people suspected of committing international crimes in the\nDemocratic People's Republic of Korea, including on the basis of the principle of\nextraterritorial or universal jurisdiction. 8 Despite inaction by the Democratic People's\nRepublic of Korea in pursuing criminal accountability and a lack of progress to this end at\nthe international level, important steps have been taken in other States to pursue judicial and\nnon-judicial forms of accountability. No criminal prosecutions have taken place to date, in\npart due to limited travel outside the country by high-ranking State officials who may bear\nresponsibility. Furthermore, in certain national legal systems, the exercise of universal\njurisdiction requires a nexus between the alleged crime and their jurisdiction � mostly\nthrough the presence or residence of a victim or accused in the territory of the prosecuting\nState concerned. The central repository of OHCHR contains information gathered with the\naim of facilitating any future criminal proceedings. OHCHR stands ready to cooperate with\ncompetent judicial authorities of Member States in providing relevant information from the\nrepository upon request and in line with rules, regulations and policies of the United Nations."},{"id":"a-hrc-58-61-p0019","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"19","seq":20,"section":"C. Current strategies to promote accountability","text":"While no criminal prosecutions have taken place to date, victims' groups and civil\nsociety organizations have filed civil claims in different domestic jurisdictions against the\nDemocratic People's Republic of Korea, seeking damages for human rights violations. In the\nRepublic of Korea, civil claims have been filed by former prisoners of war, victims of\nabduction during the Korean War and victims of the so-called Paradise on Earth campaign.9\nSome of these lawsuits resulted in monetary damages being awarded.10 In May 2023, the\nSeoul Central District Court ruled in favour of three male prisoners of war from the Republic\nof Korea, ordering the Democratic People's Republic of Korea and its President, Kim Jong\nUn, to pay each victim 50 million won.11 However, separate proceedings to enforce the\njudgments and collect the awarded compensation are still pending as at the time of writing\nthe present report. In September 2024, the Seoul Central District Court ruled in favour of five\nplaintiffs (three women and two men), ethnic Koreans who had been moved from Japan to\nthe Democratic People's Republic of Korea as part of the Paradise on Earth campaign and\nlater escaped to the Republic of Korea. The Court ordered the Government of the Democratic\nPeople's Republic of Korea to pay each plaintiff 100 million won.12"},{"id":"a-hrc-58-61-p0020","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"20","seq":21,"section":"C. Current strategies to promote accountability","text":"Civil claims have encountered challenges with regard to serving notice of proceedings\nagainst the Government of the Democratic People's Republic of Korea, gathering evidence\nand collecting compensation. In one relevant development, a federal court in the United\nStates of America ruled in November 2023 that more than $2.2 million of assets seized under\nsanctions and held in a New York bank account should be paid to the family of Otto\nWarmbier in partial payment of damages awarded in 2018.13"},{"id":"a-hrc-58-61-p0021","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"21","seq":22,"section":"C. Current strategies to promote accountability","text":"In Japan, the Tokyo High Court ruled in October 2023 that Japanese courts had\njurisdiction in a case relating to human rights violations suffered by victims of the Paradise\non Earth campaign.14 The Court found that Japan had jurisdiction as \"place of result ... of\ncontinuing tort\", reversing an earlier decision that Japanese courts did not have jurisdiction.\nThe case was returned to the lower Tokyo District Court for re-examination. The case was\ninitially brought in 2018 by five victims (four women and one man) of the campaign who\nlater escaped from the Democratic People's Republic of Korea and returned to Japan. One of\n8 A/HRC/46/52, para. 74 (c); and A/HRC/52/64, para. 57 (c).\n9 The Paradise on Earth campaign of the Government of the Democratic People's Republic of Korea\nfrom 1959 to 1984 resulted in the movement of ethnic Koreans living in Japan (and some of their\nspouses who were Japanese nationals) to the Democratic People's Republic of Korea based on false\npromises of a better life. See OHCHR, \"These Wounds Do Not Heal\": Enforced Disappearance and\nAbductions by the Democratic People's Republic of Korea (Geneva, 2023), paras. 22 and 44.\n10 See Seoul Central District Court, cases No. 2016 Ga-Dan 5235506, No. 2020 Ga-Dan 5306603,\nNo. 2020 Ga-Hap 2804 and No. 2020 Ga-Hab 3531.\n11 See Seoul Central District Court, case No. 2020 Ga-Dan 5229294.\n12 Yoo Cheong-mo, \"Ex-Korean Japanese who escaped from N. Korea win damages suit against\nPyongyang\", Yonhap News Agency, 12 September 2024.\n13 United States District Court for the Southern District of New York, Warmbier v. Bank of N.Y. Mellon,\n1:22-CV-09468 (LAK), Opinion, 23 October 2023. For the original claim, see United States District\nCourt for the District of Columbia, Warmbier v. Democratic People's Republic of Korea, 356\nF. Supp. 3d 30.\n14 Kawasaki et al. (Case number: 2018 (wa) No. 26750, 2022 (ne) No. 1972).\nthe plaintiffs passed away before the decision was rendered and another plaintiff passed away\nin February 2024."},{"id":"a-hrc-58-61-p0022","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"22","seq":23,"section":"C. Current strategies to promote accountability","text":"In May 2024, The Hague Court of Appeal in the Kingdom of the Netherlands upheld\na decision by prosecutors that proceedings would not be launched against two unnamed firms\nfor purchasing ships allegedly produced in Poland using victims of forced labour sent abroad\nas overseas workers by the Government of the Democratic People's Republic of Korea. The\nCourt found insufficient evidence of a direct link between the companies and the alleged\ncrimes. Although the case did not move forward, it raised awareness of alleged exploitation\nof overseas workers from the Democratic People's Republic of Korea and the need for due\ndiligence in connection with goods and services that may be produced using forced labour."},{"id":"a-hrc-58-61-p0023","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"23","seq":24,"section":"C. Current strategies to promote accountability","text":"OHCHR monitors progress of those cases and engages with the victims' groups and\norganizations."},{"id":"a-hrc-58-61-p0024","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"24","seq":25,"section":"C. Current strategies to promote accountability","text":"OHCHR has also organized capacity-building workshops to facilitate the exchange of\nknowledge and experience among victims' groups and organizations, including best practices\nand the practical and legal challenges of such efforts."},{"id":"a-hrc-58-61-p0025","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"25","seq":26,"section":"C. Current strategies to promote accountability","text":"Other jurisdictions have considered cases relating to the human rights situation in the\nDemocratic People's Republic of Korea. For example, the European Court of Human Rights\nfound, in 2024, that the Russian Federation had violated the Convention for the Protection of\nHuman Rights and Fundamental Freedoms (European Convention on Human Rights) by\ndetaining a man from the Democratic People's Republic of Korea and transferring him to the\ncustody of officials of the Democratic People's Republic of Korea, after which he\ndisappeared.15 The Court found that the Russian Federation had put the man at real risk of\ndeath or ill-treatment in the Democratic People's Republic of Korea in violation of his right\nto life, the prohibition of torture, and his right to liberty and security of person. In assessing\nthe risks of death and ill-treatment, the Court cited reports by international bodies attesting\nto grave human rights violations in the Democratic People's Republic of Korea and indicating\nthat:\n(i) persons are routinely detained and subjected to torture, forced labour and other\nill-treatment for exercising their rights, such as the freedom to leave their own country;\n(ii) North Koreans who defect and are forcibly repatriated are deemed traitors of the\ncountry and can be subjected to more than five years of `reform through labour';\n(iii) leaving that country without permission constitutes the crime of treason against\nthe nation and is punishable by death; and (iv) religious groups are severely\nsuppressed and persons caught exercising their religious rights are subjected to harsh\npunishments.16\nIn particular, the Court referred to the 2021 report of the High Commissioner to the Human\nRights Council on accountability,17 noting the prevalence of torture and other forms of cruel,\ninhumane and degrading treatment in the prison system of the Democratic People's Republic\nof Korea. The Court also noted the grave concern of OHCHR about credible accounts of\nforced labour under exceptionally harsh conditions within the ordinary prison system, which\nmay amount to the crime against humanity of enslavement. The Court awarded 30,000 in\ndamages to the man, his designee or his heirs.18"},{"id":"a-hrc-58-61-p0026","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"26","seq":27,"section":"C. Current strategies to promote accountability","text":"OHCHR also welcomes the steady growth in initiatives focused on non-judicial forms\nof accountability, especially truth-seeking, memorialization and education. In May 2024, the\nGovernment of the Republic of Korea unveiled memorials on Seonyu Island and Hong Island\nin remembrance of five high-school students reportedly abducted by the Democratic People's\nRepublic of Korea in 1977 and 1978. In June 2024, an exhibition space was established at\nthe War Memorial of Korea in Seoul to raise awareness of prisoners of war who have not\nbeen repatriated. A number of cultural activities and events were held in Seoul to\ncommemorate and recognize victims of enforced disappearance and other human rights\nviolations by the Democratic People's Republic of Korea. Civil society organizations have\nalso organized several memorialization events in the Republic of Korea, Japan and other\ncountries to raise awareness and to remember victims of gross human rights violations in the\nDemocratic People's Republic of Korea."},{"id":"a-hrc-58-61-p0027","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"27","seq":28,"section":"C. Current strategies to promote accountability","text":"The Truth and Reconciliation Commission of the Republic of Korea 19 issued\nsignificant decisions relating to enforced disappearance by the Democratic People's Republic\nof Korea during the reporting period. As at October 2024, the Commission had recognized\n236 Korean War abductees and \"restored the honour\" of hundreds of post-war abductees who\nexperienced human rights violations after their return to the Republic of Korea, such as illegal\ndetention, ill-treatment during the investigation process and continuous surveillance.20 In\nAugust 2024, the Commission determined that 17 ethnic Koreans who had previously lived\nin Japan had been deceived by the Democratic People's Republic of Korea and Chongryon,21\ncausing them to move to the Democratic People's Republic of Korea in connection with the\nParadise on Earth campaign. The Commission called upon the Democratic People's Republic\nof Korea to issue a formal apology and ensure the safety and freedom of movement of the\nvictims."},{"id":"a-hrc-58-61-p0028","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"28","seq":29,"section":"C. Current strategies to promote accountability","text":"Those efforts highlight the need for Member States to support accountability for\nviolations in and by the Democratic People's Republic of Korea, including violations that\ntook place beyond their borders. In particular, Member States can support civil claims and\nother domestic initiatives by taking steps such as the review and amendment of domestic\nlegislation, the provision of legal aid and psychosocial support to victims, initiatives to\namplify victims' voices, and awareness-raising in relation to the accountability options\navailable to victims. Both the Secretary-General and the Special Rapporteur on the situation\nof human rights in the Democratic People's Republic of Korea have reiterated the role that\nStates can play to promote victim-centred justice, as well as the urgency of such approaches\ngiven the long-running nature of violations and the advanced age of many victims.22"},{"id":"a-hrc-58-61-p0029","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"29","seq":30,"section":"C. Current strategies to promote accountability","text":"Some Member States, individually or collectively, continue to apply targeted\nsanctions against individuals and entities for their alleged role in human rights violations in\nthe Democratic People's Republic of Korea. 23 In December 2022, the United States\nDepartment of the Treasury announced that it had designated the Ministry of State Security\nBorder Guard General Bureau of the Democratic People's Republic of Korea for sanctions\nrelated to human rights violations.24 In July 2024, the European Union announced financial\nsanctions and a travel ban against the Minister of State Security, the third State official of the\nDemocratic People's Republic of Korea to be listed under its human rights sanctions\nregime.25 While targeted sanctions26 against individuals for gross human rights violations\nmay provide a useful tool for accountability, international human rights law requires that the\nfundamental rights of sanctioned persons be respected, including due process rights.\n19 The Truth and Reconciliation Commission of the Republic of Korea is a government body mandated\nto establish facts related to various human rights violations.\n20 Republic of Korea, Truth and Reconciliation Commission, fact-finding investigation and decision\nstatus, available at https://www.jinsil.go.kr/fnt/bbm/bbs/selectBoardArticleView.do?nttId=317491 (in\nKorean).\n21 The General Association of Korean Residents in Japan, also known as Chosen Soren.\n22 A/79/277, paras. 48 and 49; and A/79/235, paras. 30�40.\n23 For example, the sanctions programme in the United States is based on the Global Magnitsky Human\nRights Accountability Act of 2016 and Executive Order 13687 of 2 January 2015, available at\nhttps://www.federalregister.gov/documents/2015/01/06/2015-00058/imposing-additional-sanctions-\nwith-respect-to-north-korea. The United Kingdom of Great Britain and Northern Ireland programme\nrelies on the Global Human Rights Sanctions Regulations 2020 and the Sanctions and Anti-Money\nLaundering Act 2018, and the European Union programme is based on Council Decision (CFSP)\n2020/1999 of 7 December 2020.\n24 United States Department of the Treasury, \"Treasury sanctions over 40 individuals and entities across\nnine countries connected to corruption and human rights abuse\", 9 December 2022.\n25 European Commission, \"EU sanctions tracker\", available at\nhttps://data.europa.eu/apps/eusanctionstracker/subjects/168392;\nhttps://data.europa.eu/apps/eusanctionstracker/subjects/128253; and\nhttps://data.europa.eu/apps/eusanctionstracker/subjects/128246.\n26 Furthermore, sanctions that are not against individuals should be carefully crafted to ensure they do\nnot negatively affect the enjoyment of rights by a State's population."},{"id":"a-hrc-58-61-p0030","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"30","seq":31,"section":"III. Patterns of violations","text":"Since the establishment of its field-based structure in Seoul, OHCHR has conducted\nhundreds of interviews with victims of gross human rights violations committed in the\nDemocratic People's Republic of Korea. Interview records stored in the OHCHR repository\ncover 1,018 victims 27 of human rights violations, some of which could amount to\ninternational crimes.28 Approximately 55 per cent of the identified victims are women."},{"id":"a-hrc-58-61-p0031","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"31","seq":32,"section":"III. Patterns of violations","text":"During the reporting period, OHCHR analysed and observed patterns of violations on\nthe right to freedom of expression and the right to food. Previously identified patterns of\nviolations include imprisonment, torture, enslavement, other inhumane acts, enforced\ndisappearance and abductions, overseas forced labour and trafficking.29 Overall, the most\ncommon violation indicated by escapees interviewed by OHCHR is arbitrary arrest and\ndetention. Many people interviewed by OHCHR are women who previously left the\nDemocratic People's Republic of Korea, often as victims of trafficking in persons, and were\nrepatriated and detained. Therefore, most of the interviewees who provided information\nabout human rights violations in detention are women."},{"id":"a-hrc-58-61-p0032","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"32","seq":33,"section":"III. Patterns of violations","text":"More than half of the victims identified in interviews were reportedly subjected to\nhuman rights violations in places of detention. For men and women victims, the most\nfrequently reported violations in detention were forced labour, torture, inhumane conditions\nof detention and a lack of adequate food. The most commonly mentioned places of detention\nwere facilities of the Ministry of State Security in the provinces near the northern border.\nSome facilities of the Ministry of Social Security30 were also mentioned. OHCHR analysis\nhas identified 295 individuals who reported being detained following repatriation to the\nDemocratic People's Republic of Korea from neighbouring countries. Typically, persons\nsubjected to forcible repatriation are initially received by the Ministry of State Security and\nmay be transferred to the Ministry of Social Security after initial screening or certain other\ncircumstances. Those perceived by authorities as having attempted to reach the Republic of\nKorea are often charged with political crimes and treated more harshly than other detainees,\nincluding torture and ill-treatment, arbitrary detention, detention in political prison camps\nand, in some cases, the death penalty. Because of those real and well-documented risks of\ngross human rights violations, the High Commissioner has consistently highlighted the\nundeniable, compelling need for international protection of persons at risk of repatriation. He\nhas called for Member States to scrupulously observe the principle of non-refoulement, to\nrefrain from forcibly repatriating people to the Democratic People's Republic of Korea and\nto provide them with the required protections and humanitarian support.31"},{"id":"a-hrc-58-61-p0033","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"33","seq":34,"section":"III. Patterns of violations","text":"OHCHR has prioritized the analysis of information according to objective criteria,\nincluding recurrence and gravity of the violations and related crimes, the strength of existing\ninformation and appropriate access to the victims. Analysis of information gathered by\nOHCHR provides reasonable grounds to believe that international crimes may have been\ncommitted over a period of several decades and continue to be committed in the Democratic\nPeople's Republic of Korea. 32 However, analysis has also highlighted that further\ninvestigations are necessary to address gaps in information and to link violations and related\ncrimes to specific individuals who may be directly involved or who may bear command\nresponsibility."},{"id":"a-hrc-58-61-p0034","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"34","seq":35,"section":"III. Patterns of violations","text":"OHCHR issued two thematic reports during the reporting period documenting\npatterns of ongoing gross human rights violations, some of which may amount to crimes\nagainst humanity. In the first, it examined enforced disappearances, including abductions, by\nthe Democratic People's Republic of Korea.33 That report was based on various sources of\ninformation, including 80 interviews conducted by OHCHR between 2016 and 2022 with 38\nmen and 42 women victims of enforced disappearance. Those included relatives of forcibly\ndisappeared persons, escapees from the Democratic People's Republic of Korea and nationals\nof other States who had been abducted to the Democratic People's Republic of Korea and\nwho had eventually escaped. In the second report, OHCHR addressed the practice of forced\nlabour inside the country and overseas.34 The report was based on 183 interviews conducted\nby OHCHR between June 2015 and May 2023 with victims and witnesses of forced labour\nwho had fled the Democratic People's Republic of Korea and currently lived in the Republic\nof Korea. In both reports, OHCHR highlighted the disparate impact of those violations and\npossible crimes on men, women, boys and girls."},{"id":"a-hrc-58-61-p0035","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"35","seq":36,"section":"III. Patterns of violations","text":"OHCHR has also amassed a significant amount of information relating to historical\nhuman rights violations and possible international crimes. Examples include violations\nduring and shortly after the Korean War, information about political prison camps over\nseveral decades and information about the severe intergenerational harm caused by the\nfamine of the 1990s."},{"id":"a-hrc-58-61-p0036","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"36","seq":37,"section":"III. Patterns of violations","text":"The Democratic People's Republic of Korea is obliged under international law to\ninvestigate, prosecute and punish with appropriate penalties those responsible for gross\nhuman rights violations, in particular those amounting to international crimes, including\ndirect or indirect perpetrators and those who may bear superior responsibility. Furthermore,\nthe Convention on the Non-Applicability of Statutory Limitations to War Crimes and Crimes\nagainst Humanity, to which the Democratic People's Republic of Korea is a party, establishes\nthat such crimes are not subject to any statute of limitations. The Convention also establishes\nthat criminal liability may attach to \"representatives of the State authority\" as direct or\nindirect perpetrators of war crimes and crimes against humanity, as well as \"representatives\nof the State authority who tolerate their commission\".35"},{"id":"a-hrc-58-61-p0037","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"37","seq":38,"section":"A. Freedom of expression","text":"OHCHR is gravely concerned about extreme restrictions on access to information and\nthe suppression of freedom of expression in the Democratic People's Republic of Korea.\nInvasive surveillance and arbitrary arrests and detention to stifle freedom of expression\ncarried out by the Ministry of Social Security and the Ministry of State Security are well\ndocumented.36 OHCHR interviewed 136 individuals who described surveillance and control\nover ordinary citizens. They described the recent intensification of such repression, including\nthrough the introduction of new laws and the operation of ad hoc government task forces\nknown as Sangmu. Credible sources have reported that the creation and operation of Sangmu\nand similar organizations involve directives from the State's top leadership and are based on\ndecisions by the Central Committee of the Workers' Party of Korea. One of the most\nfrequently mentioned organizations is the 109 Sangmu, which is responsible for cracking\ndown on illegal videos, including foreign media content. Reportedly established in February\n2004, its operations have continued and intensified in recent years. Sangmu groups reportedly\ncomprise an alliance of various agencies of the State and the Workers' Party of Korea,\nincluding: the Propaganda and Agitation Department of the Workers' Party of Korea, the\nOffice of the Prosecutor, the Ministry of State Security, the Ministry of Social Security and\nlocal people's committees and youth leagues. OHCHR interviewees also reported that courts\nwere enforcing those laws and policies. Interviewees told OHCHR that 109 Sangmu\nfrequently wiretapped telephones and electronic devices, conducted warrantless home\nsearches and confiscated unauthorized videos, publications, radios and USB drives. Men and\nwomen who had been arbitrarily arrested by 109 Sangmu said that they had been beaten and\nverbally abused during interrogations. Interviewees also told OHCHR that individuals\nconsidered `criminals' for accessing or distributing prohibited content were often subjected\nto public trials reportedly designed to intimidate the population and received disproportionate\npunishments, including in a few cases execution by firing squad."},{"id":"a-hrc-58-61-p0038","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"38","seq":39,"section":"A. Freedom of expression","text":"In furtherance of restrictions on freedom of expression and access to information,\nseveral laws were enacted between 2020 and 2023 to strengthen control and surveillance, as\nwell as to impose harsher punishments for infractions. Those include the Law on Protecting\nthe Pyongyang Cultural Language (enacted on 18 January 2023), the Law on Rejecting\nReactionary Thought and Culture (enacted on 4 December 2020) and the Youth Education\nGuarantee Law (enacted on 29 September 2021). The Law on Protecting the Pyongyang\nCultural Language and the Law on Rejecting Reactionary Thought and Culture have\nintensified punishments for violations, even extending to the death penalty.37 The Secretary-\nGeneral in his reports has noted a significant escalation in the repression of the right to\nfreedom of expression under those laws and raised concerns regarding the legitimacy and\nproportionality of the punishments, which do not comply with international human rights\nstandards.38"},{"id":"a-hrc-58-61-p0039","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"39","seq":40,"section":"A. Freedom of expression","text":"The Democratic People's Republic of Korea has a duty to protect the right to freedom\nof expression and access to information enshrined in article 19 of the International Covenant\non Civil and Political Rights. Moreover, under international human rights law, the State's\nrestrictions on the exercise of those rights for the protection of national security or public\norder should not undermine the rights themselves.39 Such measures must conform to the\nprinciple of proportionality and must be the least intrusive means among those that could\nachieve the same protective function.40 Article 17 of the Covenant states that no one shall be\nsubjected to arbitrary or unlawful interference with their privacy, family, home or\ncorrespondence. The Human Rights Committee has clarified that surveillance, whether\nelectronic or otherwise, as well as the interception of telephonic, telegraphic and other forms\nof communication, including wiretapping and recording of conversations, should be\nprohibited. Furthermore, searches of a person's home should be limited to the collection of\nnecessary evidence and should not result in harassment.41"},{"id":"a-hrc-58-61-p0040","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"40","seq":41,"section":"B. Right to food","text":"Among the human rights violations described by interviewees, violations of the right\nto food are strikingly consistent. Nearly all interviewees who had lived through the severe\nfamine of the 1990s told OHCHR of dire suffering after the collapse of the public distribution\nsystem of food. Almost all escapees, regardless of when they had left the country, mentioned\nhunger and a lack of food during interviews with OHCHR. Many cite hunger as one of their\nreasons for leaving the country. Some escapees said that they had undertaken exceptionally\ndangerous escapes so that their families would have \"one less mouth to feed\"."},{"id":"a-hrc-58-61-p0041","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"41","seq":42,"section":"B. Right to food","text":"Nearly all interviewees who had experienced detention in the country reported severe\ndeprivation of food as one of the worst aspects of their experience in detention. They\ndescribed receiving extremely small quantities of food and of quality so low that it was not\nfit for human consumption. Interviewees experienced those severe violations of the right to\nadequate food at all types of detention facilities run by the Ministry of State Security and the\nMinistry of Social Security. The Secretary-General42 and OHCHR43 have expressed grave\nconcern that violations of the right to adequate food for persons in detention may have\nworsened during the COVID-19 pandemic."},{"id":"a-hrc-58-61-p0042","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"42","seq":43,"section":"B. Right to food","text":"Violations of the right to food are also particularly salient among interviewees who\nescaped during or after the COVID-19 pandemic. They described observing widespread\nhunger in some communities. They also described government policies, such as State\ncentralization of production and distribution of food, making it harder for the general public\nto purchase food in markets (jangmadang) and from private individuals. Those centralized\npolicies, such as rules that rice and other staples could only be purchased at government\nshops, imposed further State control over the population, made food less accessible and\nintroduced restrictions on private commercial activities that made it impossible to earn\nincome to buy food."},{"id":"a-hrc-58-61-p0043","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"43","seq":44,"section":"B. Right to food","text":"The consistent lack of adequate food in the Democratic People's Republic of Korea\nhas resulted in serious long-term and intergenerational physical and mental harm to a\nsignificant portion of the population. The impact has been most severe on persons in\nvulnerable situations, including persons with disabilities, older persons, individuals in\ndetention, children, and women and girls, especially those who are pregnant and lactating.44\nThe International Covenant on Economic, Social and Cultural Rights, to which the\nDemocratic People's Republic of Korea is a party, obligates States to take the necessary steps\nto ensure for everyone under their jurisdiction access to the minimum essential food that is\nsufficient, nutritionally adequate and safe, to ensure their freedom from hunger.45 In addition,\nin situations in which persons are unable, for reasons beyond their control, to enjoy the right\nto adequate food by the means at their disposal (for example, due to natural or other disasters),\nStates have the obligation to fulfil that right directly by providing food. 46 Finally, the\nCovenant requires States to take steps to the maximum of their available resources to ensure\nthe availability and accessibility of necessary food, including by seeking international\nsupport.47 Information gathered by OHCHR indicates a manifest failure by the Democratic\nPeople's Republic of Korea to fulfil those obligations to safeguard the right to adequate food,\nand State policies appear to have exacerbated severe hunger.48"},{"id":"a-hrc-58-61-p0044","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"44","seq":45,"section":"A. Victims' and other stakeholders' views on accountability","text":"Pursuant to its mandate under Human Rights Council resolution 52/28, OHCHR\ncontinues to conduct consultations and outreach activities with victims, affected communities\nand other relevant stakeholders to ensure that their perspectives and views are integrated into\naccountability initiatives. Those consultations are essential as they serve to legitimize\naccountability efforts, empower and recognize the voices of victims, and inform the design\nof a victim-centred accountability framework."},{"id":"a-hrc-58-61-p0045","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"45","seq":46,"section":"A. Victims' and other stakeholders' views on accountability","text":"In the light of the total lack of access to, and cooperation from, the Democratic\nPeople's Republic of Korea, OHCHR consulted with victims and other stakeholders in a\nnumber of Member States. Consultations prioritized victims' personal safety, their informed\nconsent, inclusivity, a gender balance and confidentiality. To sensitize participants and allow\nthem to express informed opinions, OHCHR provided capacity-building activities (as\ndescribed below) and published information notes in English, Japanese and Korean on key\nconcepts of human rights and accountability."},{"id":"a-hrc-58-61-p0046","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"46","seq":47,"section":"A. Victims' and other stakeholders' views on accountability","text":"The consultations offered a unique opportunity to better understand the views,\nconcerns and perspectives of the different communities of victims and build trust with them.\nA total of 229 persons (127 women and 102 men) and 39 organizations were consulted. That\nincluded victims of gender-based violence, including sexual violence, former political\nprisoners, former prisoners in detention centres, former members of the Workers' Party of\nKorea, former State officials of the Democratic People's Republic of Korea, and victims of\nenforced disappearance, including families of forcibly disappeared persons, and young\nescapees. OHCHR also consulted academics, legal practitioners, teachers at schools for\n44 A/79/277, paras. 8�12.\n45 Committee on Economic, Social and Cultural Rights, general comment No. 12 (1999), para. 14.\n46 Ibid., para. 15.\n47 International Covenant on Economic, Social, and Cultural Rights, art. 2 (1).\n48 A/79/277, paras. 8�12. See also the conference room paper on the detailed findings of the commission\nof inquiry on human rights in the Democratic People's Republic of Korea, para. 1213.\nescapees and activists assisting escapees, Special Rapporteurs and commissioners of the\ncommission of inquiry."},{"id":"a-hrc-58-61-p0047","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"47","seq":48,"section":"A. Victims' and other stakeholders' views on accountability","text":"The victims consulted expressed a diverse range of accountability priorities, driven\nby the wide array of human rights violations that they had suffered, as well as other challenges\nsuch as stigma and discrimination where they now reside. Almost all stakeholders\nemphasized the importance of prosecuting those responsible for crimes, but many expressed\ndeep concerns about the legal complexity and limited likelihood of bringing perpetrators to\njustice before national and international criminal courts. Victims and civil society\norganizations pursuing civil lawsuits expressed their determination to expand those efforts\nbut underlined the need for legal aid to support them, as well as concerted efforts by the\ninternational community to allow for the enforcement of judicial awards of monetary\ncompensation."},{"id":"a-hrc-58-61-p0048","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"48","seq":49,"section":"A. Victims' and other stakeholders' views on accountability","text":"During the consultations, victims underlined specific concerns that should inform\nfuture interactions. Participants highlighted the reluctance of female escapees to speak about\ngender-based violence, including sexual violence, due to social stigma. They also expressed\nconcern about the breakdown of families separated due to escape from the Democratic\nPeople's Republic of Korea or subsequent repatriation of women who had children in\nneighbouring countries. Many escapees regretted the politicization of the issue of human\nrights and felt that that resulted in a reluctance among young people to engage on the issue.\nLastly, stakeholders reiterated concerns about discrimination against escapees within their\ncommunities and challenges to integration."},{"id":"a-hrc-58-61-p0049","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"49","seq":50,"section":"A. Victims' and other stakeholders' views on accountability","text":"Victims of torture, trafficking, gender-based violence, including sexual violence, and\nformer prisoners of political prison camps or other detention facilities emphasized the\nimportance of psychological support to help them treat and overcome the trauma of severe\nhuman rights violations. They stressed the need for psychological counsellors who fully\nunderstood the situation of escapees and the need to raise awareness among escapees who\nmay perceive psychological care negatively. A number of families of forcibly disappeared\npersons, some of whom had waited for almost seven decades for information about their\nloved ones, informed OHCHR that their priority was to learn the fate and whereabouts of\ntheir loved ones as a matter of urgency."},{"id":"a-hrc-58-61-p0050","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"50","seq":51,"section":"A. Victims' and other stakeholders' views on accountability","text":"Some escapees, particularly women, called for apologies from all those responsible,\nincluding from the Democratic People's Republic of Korea and other States in which\nviolations had occurred, for the harm that they had suffered as a means of restoring their\nhonour. They felt that when perpetrators of human rights violations apologized, it was a\nguarantee that they would no longer inflict harm on victims or their families. Some victims\nalso requested official apologies from perpetrators and proposed the creation of a system for\nperpetrators to formally seek forgiveness from victims."},{"id":"a-hrc-58-61-p0051","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"51","seq":52,"section":"A. Victims' and other stakeholders' views on accountability","text":"Several victims reported that their suffering and status as victims of violations had not\nbeen recognized, while they suffered stigma because of perceived links with the Democratic\nPeople's Republic of Korea. They underlined the need to establish historical facts through\nfact-finding and truth-telling initiatives. The vast majority of victims consulted also called\nfor memorialization and commemoration initiatives that would particularly engage the\nyounger generation to ensure that victims and their suffering were acknowledged and not\nforgotten. Continued visibility of the human rights situation in the Democratic People's\nRepublic of Korea, as well as human rights education for escapees, were consistently raised."},{"id":"a-hrc-58-61-p0052","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"52","seq":53,"section":"A. Victims' and other stakeholders' views on accountability","text":"OHCHR will continue the consultation process in furtherance of its mandate, to ensure\nthat accountability pathways are victim-centred, with victims' voices continually conveyed\nand amplified."},{"id":"a-hrc-58-61-p0053","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"53","seq":54,"section":"B. Capacity-building and outreach activities","text":"OHCHR links the human rights community and escapee-led organizations with global\nactors, expert practitioners and other resources. OHCHR leverages that role to provide\ncapacity-building activities to civil society organizations, government actors and the\ndiplomatic community. For example, training sessions on interviewing methodologies and\nconcepts and trends in international law enhanced the practical knowledge of partners and\nimproved their ability to promote the needs of victims while gathering information that will\nbe relevant and useable for accountability purposes at any point in the future. Outreach to\nMember States aims to increase the likelihood that competent national authorities will be\nready, willing and able to pursue investigations and prosecutions whenever these are feasible."},{"id":"a-hrc-58-61-p0054","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"54","seq":55,"section":"B. Capacity-building and outreach activities","text":"In August 2023, OHCHR held an international conference in Seoul in connection with\nthe launch of its report on enforced disappearances by the Democratic People's Republic of\nKorea. At the event, OHCHR introduced efforts and mechanisms that had been set up to\nsearch for victims of enforced disappearance in other contexts. It brought together experts,\npractitioners, civil society organizations and families of forcibly disappeared persons to share\nthe lessons learned and experiences on initiatives in pursuing truth and justice for the victims\nof enforced disappearance. To further raise awareness, OHCHR then partnered with student\nactivists to hold a public art exhibition in Seoul in December 2023. The exhibition included\nyoung artists who worked directly with victims to create art interpreting the crime of enforced\ndisappearance. OHCHR also conducted five visits to Japan during the reporting period that\nincluded workshops and training sessions on the legal framework regarding enforced\ndisappearances and international abductions."},{"id":"a-hrc-58-61-p0055","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"55","seq":56,"section":"B. Capacity-building and outreach activities","text":"The efforts of OHCHR to further empower partners included training workshops by\ninternational experts on relevant topics, such as practitioners involved in universal\njurisdiction cases. OHCHR has offered practical advice on submitting petitions and engaging\nwith the special procedures of the Human Rights Council and has organized round-table\nmeetings to assist victims' groups and civil society organizations in facilitating their\nunderstanding and engagement with United Nations human rights mechanisms. Examples\ninclude a meeting with a member of the Committee on the Elimination of Discrimination\nagainst Women, a presentation and discussion by a former member of the Working Group\non Enforced or Involuntary Disappearances and a round table with a member of the Working\nGroup on Arbitrary Detention. Subsequently, in July 2024, a victims' organization submitted\n290 cases of Japanese missing persons to the Working Group on Enforced or Involuntary\nDisappearances."},{"id":"a-hrc-58-61-p0056","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"56","seq":57,"section":"B. Capacity-building and outreach activities","text":"OHCHR continued to provide numerous lectures and talks upon request on topics\nrelating to human rights in the Democratic People's Republic of Korea and accountability.\nThat included a lecture series on the lasting significance of the commission of inquiry, which\nraised awareness among nearly 800 students at 13 universities in the Republic of Korea."},{"id":"a-hrc-58-61-p0057","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"57","seq":58,"section":"V. Conclusions","text":"OHCHR continues to gather information on gross human rights violations and\npossible international crimes that are ongoing in the Democratic People's Republic of\nKorea and on the disparate impact of such violations on men, women, boys and girls.\nOHCHR is gravely concerned about the widespread impunity and total absence of\ncriminal accountability for human rights violations that may amount to international\ncrimes. It urges the Democratic People's Republic of Korea to take immediate action to\nprevent and address those violations. Ensuring accountability for those responsible is\ncrucial and the rights of victims to truth, justice, reparations and guarantees of non-\nrecurrence must be upheld."},{"id":"a-hrc-58-61-p0058","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"58","seq":59,"section":"V. Conclusions","text":"It remains crucial for OHCHR to continue to independently gather and preserve\ninformation for future use. Centralization of information is the foundation for robust\nand effective accountability processes. A key aim of that work by OHCHR is to be able\nto support accountability efforts, including future investigations and prosecutions in a\ntimely and efficient fashion. Some of the information gathered by the Office relates to\npossible crimes committed decades ago. In dealing with that vast time frame, many\nperpetrators and victims may have passed away. Nevertheless, documenting that\ninformation remains critical for historical record and collective memory."},{"id":"a-hrc-58-61-p0059","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"59","seq":60,"section":"V. Conclusions","text":"The United Nations advocates for a holistic approach to accountability, as truth,\njustice, reparation and guarantees of non-recurrence are interlinked integral\ncomponents of any comprehensive accountability effort. Notably, consultations by\nOHCHR have highlighted the need for efforts to encompass the full range of judicial\nand non-judicial accountability mechanisms. Consultations highlight the views of\nvictims and stakeholders that accountability must be victim-centred and multifaceted,\nand efforts must start now. To achieve that may require the direction of energies of the\nUnited Nations, Member States and civil society organizations to help secure\nreparations and some degree of justice within victims' lifetimes. Member States should\nmaintain their commitment to complementary strategies that help deliver justice for\nthe victims. That includes exploring innovative approaches, such as establishing a\nregister of victims as well as creating mechanisms to fund reparations."},{"id":"a-hrc-58-61-p0060","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"60","seq":61,"section":"V. Conclusions","text":"Despite the lack of access to the Democratic People's Republic of Korea, the work\nof OHCHR on human rights appears to be known within the country. Sources informed\nOHCHR that security actors received some training in human rights and that treatment\nof persons in detention had slightly improved, reportedly because of international\nscrutiny."},{"id":"a-hrc-58-61-p0061","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"61","seq":62,"section":"VI. Recommendations","text":"The High Commissioner reiterates the recommendations made in his previous\nreports. The High Commissioner recommends that the Government of the Democratic\nPeople's Republic of Korea:\n(a) Acknowledge the existence of gross human rights violations, including\nthose which could amount to international crimes, take immediate steps to end such\nviolations, and investigate, prosecute and bring to justice those alleged of having\ncommitted human rights violations within fair trials;\n(b) Grant international humanitarian organizations and human rights\nmonitors immediate access to the country, including to all detention facilities;\n(c) Initiate reform of criminal justice legislation and rule of law institutions,\nincluding the judiciary and law enforcement and corrections systems, in accordance\nwith international human rights norms and standards;\n(d) Ensure that victims of gross human rights violations, including those\namounting to international crimes, and their families are provided with adequate,\nprompt, effective and gender-sensitive reparations, including public acknowledgment\nof the truth of the violations suffered;\n(e) Declare an immediate moratorium on the use of the death penalty\nfollowed, at the earliest opportunity, by its abolition and ensure that, pending its\nabolition, the death penalty is imposed only for the most serious crimes, defined under\ninternational human rights law as crimes of extreme gravity involving an intentional\nkilling, and in a manner consistent with other requirements of the International\nCovenant on Civil and Political Rights;\n(f) Ensure that any surveillance systems in place fully comply with the human\nrights standards of legality, necessity, proportionality and legitimacy of objectives\npursued, avoid their use as instruments of political oppression and ensure that they are\nsubject to effective judicial review;\n(g) Ratify all relevant international treaties and human rights instruments,\nincluding the Convention against Torture and Other Cruel, Inhuman or Degrading\nTreatment or Punishment and the International Convention for the Protection of All\nPersons from Enforced Disappearance."},{"id":"a-hrc-58-61-p0062","rec_id":"recBme0CBp75YznOj","symbol":"A/HRC/58/61","n":"62","seq":63,"section":"VI. Recommendations","text":"The High Commissioner recommends that Member States:\n(a) Take further steps to ensure accountability for those responsible for gross\nhuman rights violations in the Democratic People's Republic of Korea at the\ninternational level, including through the referral by the Security Council of the\nsituation to the International Criminal Court;\n(b) Take steps to ensure that efforts aimed at securing a lasting peace on the\nKorean Peninsula give due priority to human rights and restoring the dignity of all\nvictims by respecting and upholding their rights to truth, justice, reparation and\nguarantees of non-recurrence;\n(c) Carry out, where possible, investigations into and the prosecution of\npersons suspected of committing international crimes in the Democratic People's\nRepublic of Korea, including on the basis of the principle of extraterritorial and/or\nuniversal jurisdiction and by engaging and providing information to the central\nrepository;\n(d) Support initiatives to implement non-judicial approaches to\naccountability, such as reparations, truth-seeking and memorialization, to provide\ntangible redress for victims, including by establishing a registry of victims and creating\nmechanisms to fund reparations, including compensation for harm suffered;\n(e) Continue to facilitate the work of OHCHR in fulfilling the mandates of\nthe Human Rights Council, including with regard to access to individuals who have fled\nthe Democratic People's Republic of Korea, and to the collection and analysis of\nrelevant testimony, documentation and information."},{"id":"a-hrc-60-58-u0000","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":0,"section":null,"text":"Sixtieth session\n8 September�3 October 2025\nAgenda items 2 and 4\nAnnual report of the United Nations High Commissioner\nfor Human Rights and reports of the Office of the\nHigh Commissioner and the Secretary-General\nHuman rights situations that require the Council's attention","unnumbered":true},{"id":"a-hrc-60-58-u0001","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":1,"section":null,"text":"The present report is submitted pursuant to Human Rights Council resolution 55/21.\nIt provides an update on the situation of human rights in the Democratic People's Republic\nof Korea since 2014 and a stocktaking of the implementation of the recommendations of the\ncommission of inquiry on human rights in the Democratic People's Republic of Korea, along\nwith conclusions and recommendations.","unnumbered":true},{"id":"a-hrc-60-58-p0001","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"1","seq":2,"section":"I. Introduction","text":"The present report is submitted pursuant to Human Rights Council resolution 55/21,\nin which the Council requested the United Nations High Commissioner for Human Rights to\nsubmit a comprehensive report containing an update on the situation of human rights in the\nDemocratic People's Republic of Korea since 2014, when the report of the commission of\ninquiry on human rights in the Democratic People's Republic of Korea was published, and\ntake stock of the implementation of the commission's recommendations. The report covers\nthe period from 1 January 2014 to 31 May 2025. The report should be read in conjunction\nwith previous reports submitted by the High Commissioner and the Secretary General since\n2014, and with thematic reports published by the Office of the United Nations High\nCommissioner on Human Rights (OHCHR) on the situation in the country (see annex). Since\nJune 2015, OHCHR has maintained a field-based structure in Seoul, as recommended by the\ncommission of inquiry1 and mandated by the Council.2"},{"id":"a-hrc-60-58-p0002","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"2","seq":3,"section":"I. Introduction","text":"In preparing the present report, OHCHR consulted widely with victims, civil society\norganizations and thematic experts and reviewed their public reports; engaged with Member\nStates; and conducted interviews with 314 victims and witnesses who had left the country\nduring the reporting period. The Office thanks the interviewees, those who facilitated\ninterviews and those who provided other information. All information received has been\nstored in the mandated OHCHR central repository. In response to a request for input, the\nGovernment of the Democratic People's Republic of Korea rejected resolution 55/21 but\nreferred OHCHR to the State's input for its examination, in November 2024, under the\nuniversal periodic review. Unless otherwise stated, information in the present report was\ndrawn from first-hand information gathered and assessed by OHCHR in accordance with the\nOHCHR monitoring methodology and public reports of the United Nations (see annex).\nReports from other sources have been taken into consideration to corroborate the information."},{"id":"a-hrc-60-58-p0003","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"3","seq":4,"section":"II. Context","text":"On 17 February 2014, the commission of inquiry made its report public. Despite\nrejecting the mandate and report of the commission, the Government initially showed\nincreased willingness to engage with the international community to address human rights\nconcerns. This included the holding of family reunions, engaging on the issue of Japanese\nabductees, proposing high-level meetings with the High Commissioner and the Special\nRapporteur on the situation of human rights in the Democratic People's Republic of Korea,\nextending invitations to the High Commissioner to conduct a country visit, opening dialogue\nwith OHCHR on technical assistance and ratifying an optional protocol to the Convention on\nthe Rights of the Child. These positive developments were short-lived; a number were\nreversed after the inclusion of an item on human rights in the Democratic People's Republic\nof Korea in the Security Council agenda in December 2014."},{"id":"a-hrc-60-58-p0004","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"4","seq":5,"section":"II. Context","text":"Following the assumption of office by Kim Jong Un as Head of State in December\n2011, escapees reported a sense of hope for an improved situation in the country, with the\nnew leader promising in April 2012 that citizens would not have to \"tighten their belts\" again\nand setting forth a new national policy of advancing economic development in parallel with\nnuclear development (\"Byungjin\" policy). Fairly quickly however, from mid-2013, purges\nin the Government and the military started (reportedly resulting, inter alia, in several\nexecutions), and further repressive measures were introduced. By the decade's end, the\nGovernment's control over all aspects of citizen's lives was the most absolute in decades.\nThis increase in control accelerated during the coronavirus disease (COVID-19) pandemic\nclosures. Surveillance technology has assisted in increasing this control, and there has been\na marked increase in the past seven years in the adoption of laws, policies and procedures\nthat provide a legal framework for repression.\n1 A/HRC/25/63, para. 94 (c).                                                                     GE.25-12015\n2 See, among others, resolutions 25/25 and 55/21."},{"id":"a-hrc-60-58-p0005","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"5","seq":6,"section":"II. Context","text":"In addition, the State's isolation deepened, including with the imposition of\ninternational sanctions, the most recent of which were adopted in 2017.3 Starting in 2019,\nafter the failure to reach an agreement in negotiations with the United States of America, the\nState took steps to sever links with the Republic of Korea and the broader international\ncommunity. The reinforcement of the State's border with China, which started some years\nearlier, intensified from 2020 in response to the COVID-19 pandemic. The number of\nindividuals crossing that border without authorization decreased significantly over the\ndecade. 4 At the same time, the flow of information into the country was dramatically\nrestricted. The State has not returned to pre-pandemic levels of interaction with the outside\nworld."},{"id":"a-hrc-60-58-p0006","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"6","seq":7,"section":"II. Context","text":"From 2014, exports and imports were increasingly constrained by international\nsanctions, which, by 2017, affected all major export sectors. State sources of income included\ntrade in sanctioned and unsanctioned goods and services, wages from overseas workers and,\nreportedly, proceeds from cybercrime. The Government embarked on large-scale public\nspending on housing and factories, seeking to reduce disparities between urban and rural\ndevelopment. By 2021, the State acknowledged that economic goals were not being met.5\nLimited private commercial activity had allowed citizens to provide for themselves and their\nfamilies, where State-assigned jobs provided inadequate wages or rations, or in many cases,\nnone at all. Over the decade, the Government increasingly limited private enterprise by law\nand in practice, most notably by severely limiting private trade in grain and medicine. Rather\nthan reverting to the comprehensive public distribution system of the past, the Government\nbecame the retailer of grain and medicine in the country. With the partial lifting of the border\nclosure in mid-2023, imports, particularly from China, rose."},{"id":"a-hrc-60-58-p0007","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"7","seq":8,"section":"II. Context","text":"The State reported military spending of 15.6�15.9 per cent of the national budget\nduring the decade,6 with heavy investment in new weapons and related technology. During\nthe reporting period � except the 2018�2019 period of international summits � the State\nengaged in high levels of testing of nuclear, missile and other military technology. During\nthe periods 2016�2017 and 2020�2023, it conducted three nuclear tests, tested new ballistic\nand cruise missiles, launched satellites and unveiled submarines and ships, with a peak in\n2022. In 2025, the State confirmed it had sent soldiers to the Russian Federation under a\nmutual defence treaty in the context of the latter's conflict with Ukraine.7 Transfers of\nmunitions to the Russian Federation have been reported since 2023.8"},{"id":"a-hrc-60-58-p0008","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"8","seq":9,"section":"II. Context","text":"This high level of military spending contributed to a worsening of the security\nsituation on the Korean Peninsula. While an inter-Korean agreement to lower tensions was\nreached in 2015, the subsequent two years were marked by continued nuclear tests and\nsuccessive Security Council sanctions, which constrained the economy and had an impact on\nthe humanitarian situation in the country. The series of international summits in 2018 and\nearly 2019 resulted in a dramatic drop in tensions and several conciliatory actions.9 While\nthe summits addressed issues such as separated families, human rights issues were otherwise\nnot addressed. The rapprochement ended in 2020, with a return to missile testing by the\nGovernment and joint military exercises by the Republic of Korea and the United States. In\n2024, the Government of the Democratic People's Republic of Korea abandoned the long-\nheld policy goal of reunification.\n3 See Security Council resolutions 2270 (2016), 2321 (2016), 2371 (2017), 2375 (2017) and 2397\n(2017).\n4 See https://unikorea.go.kr/eng_unikorea/relations/statistics/defectors/.\n5 See www.ncnk.org/resources/publications/kju_8th_party_congress_speech_summary.pdf/file_view.\n6 See http://kcna.co.jp/item/2025/202501/news24/20250124-04ee.html.\n7 See https://kcnawatch.org/newstream/1745791650-244094225/wpk-central-military-commission-\nhighly-praises-combat-sub-units-of-armed-forces-of-dprk-for-performing-heroic-feats-in-operations-\nto-liberate-kursk-area-of-russian-federation/.\n8 See, for example, https://press.un.org/en/2024/sc15945.doc.htm.\n9 See A/73/308."},{"id":"a-hrc-60-58-p0009","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"9","seq":10,"section":"A. Civic space and fundamental freedoms","text":"Over the past 10 years, the Government continued to exercise total control over the\npopulation and severely restrict the enjoyment of fundamental rights and freedoms, leaving\npeople unable to fully make their own political, social or economic decisions. Significant\nchanges were made in governance, leadership and oversight structures in that direction."},{"id":"a-hrc-60-58-p0010","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"10","seq":11,"section":"A. Civic space and fundamental freedoms","text":"Although the Government has committed to protecting freedom of opinion and\nexpression, criticism of the Government and behaviour not conforming to Government\nideology are considered political acts or threats to national security and result in serious\nrepercussions. Since 2015, the Government has adopted several laws or amendments to laws,\nincluding the amendment of 2015 to the Criminal Law, the Law on Rejecting Reactionary\nThought and Culture (2020), the Youth Education Guarantee Law (2021) and the Law on\nProtecting the Pyongyang Cultural Language (2023), that criminalize access to unauthorized\nforeign information and prohibit the consumption or dissemination of information (through,\nfor example, publications, music and movies) from \"hostile\" nations and the use of linguistic\nexpressions that do not conform with prescribed socialist ideology and culture. These laws\nraise serious concerns of unlawful restrictions on the right to freedom of opinion and\nexpression. They also provide for severe punishments, including the death penalty, for\nprotected speech. The application of the death penalty under these laws is broader than for\nintentional killings or \"anti-State\" crimes under other legislation, and contrary to the right to\nlife."},{"id":"a-hrc-60-58-p0011","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"11","seq":12,"section":"A. Civic space and fundamental freedoms","text":"Crackdowns against foreign information reportedly intensified from 2018 and became\nharsher from 2020, resulting in several public executions. Despite restrictions that were in\nplace even before the COVID-19 pandemic, people could bribe authorities to avoid\npunishments for consuming unauthorized media. However, with more advanced surveillance\ntechnology and greater determination to prohibit the use or dissemination of foreign media,\nauthorities are cracking down on such cases more rigorously. The Government has organized\npublic trials and public executions to instil fear in the population and as a deterrent."},{"id":"a-hrc-60-58-p0012","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"12","seq":13,"section":"A. Civic space and fundamental freedoms","text":"A government task force (Group 109), comprising officials from security agencies,\nthe Office of the Prosecutor and the Workers' Party of Korea, increasingly carried out\ninspections of computers, radios and televisions and house searches without prior notice or\nwarrants, aimed at finding \"anti-socialist\" materials. The Government justifies these\nmeasures as necessary to curb \"anti-socialist\" behaviour and to protect national security.\nEscapees reported that prior to the COVID-19 pandemic, people arrested for consuming\nforeign media were released after receiving \"revolutionary\" education. However, penalties\nhave become increasingly severe in recent years. Reports suggest that the population\ncontinues to consume information that is prohibited under domestic law, despite the growing\nrisks."},{"id":"a-hrc-60-58-p0013","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"13","seq":14,"section":"A. Civic space and fundamental freedoms","text":"The use of mobile phones has grown substantially since 2014, with potentially 50 to\n80 per cent of the population owning a mobile phone by 202210 and access to cellular\nnetworks in almost all areas of the country. Although mobile applications are limited to those\nauthorized by the Government, mobile phones have been useful for communication, market\nactivities, digital payments, weather reports and gaming. Access to the Internet is almost\ntotally unavailable to the public. A tightly controlled national intranet is available, primarily\nfor research institutions and government officials."},{"id":"a-hrc-60-58-p0014","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"14","seq":15,"section":"A. Civic space and fundamental freedoms","text":"All media is controlled by the Government and any independent news or opinion piece\ncontrary to the State's official position is treated as \"counter-revolutionary\" and as a\npunishable crime under the country's broadcasting and publishing laws. There are no\nindependent civil society organizations in the country. People are required to join one of the\norganizations affiliated with the Workers' Party of Korea, such as the women's union, whose\nrole is to propagate government ideology, undertake surveillance and mobilize the public for\n10 Martyn Williams and Natalia Slavney, \"Twenty years of mobile communications in North Korea\",\n38 North (15 November 2022).\ngovernment-initiated construction, farming and labour. Every person is required to\nparticipate in weekly self-criticism sessions, primarily aimed at collective surveillance and\nindoctrination."},{"id":"a-hrc-60-58-p0015","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"15","seq":16,"section":"A. Civic space and fundamental freedoms","text":"Elections are held every four to five years for the Supreme People's Assembly and for\nlocal people's assemblies. However, these are mostly symbolic, with more than 99 per cent\nvoter turnout and no independent candidates. There is often a single candidate seeking\nelection. In August 2023, the Government amended the Law on the Election of Deputies to\nPeople's Assemblies at All Levels to allow multiple candidates to stand for deputies'\npositions in local elections, but the local elections held in November 2023 still had single\ncandidates for the positions."},{"id":"a-hrc-60-58-p0016","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"16","seq":17,"section":"A. Civic space and fundamental freedoms","text":"Freedom of movement in the country is more restricted now as compared to a decade\nago, when thousands of people were crossing international borders without permission.11 In\nresponse to those crossings, in 2014 the Government started reinforcing its international\nborder control, including with shoot-on-sight orders during the COVID-19 pandemic. A\ntravel permit system controls all travel between provinces; obtaining permits often requires\nbribes or personal connections. International travel remains severely restricted and\nunauthorized travel is a punishable crime."},{"id":"a-hrc-60-58-p0017","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"17","seq":18,"section":"A. Civic space and fundamental freedoms","text":"Women and girls who leave the country are often vulnerable to trafficking for forced\nmarriage, forced labour and sexual exploitation, and to abuse and violence. Those with no\nlegal status rarely seek help even if abused, particularly for fear of repatriation. COVID-19\npandemic restrictions in China exacerbated their vulnerabilities, as they were unable to access\nessential services such as medical care or public transport, or meet daily needs, without\nofficial identification, highlighting the need for better protection."},{"id":"a-hrc-60-58-p0018","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"18","seq":19,"section":"A. Civic space and fundamental freedoms","text":"The Constitution of the Democratic People's Republic of Korea formally refers to\nreligion as a possible \"pretext for drawing in foreign forces or for harming the State or social\norder\" (art. 68). Restrictions on religious activities have not softened over the past decade.\nSince 2018, crackdowns against shamanism and other practices, such as predicting the future\nand identifying burial sites for religious purposes, have intensified. For example, in 2018 a\nman from South Hamgyong Province was sentenced to life imprisonment for identifying such\nburial sites. Contact with Christians outside the country has led to severe punishment upon\nrepatriation."},{"id":"a-hrc-60-58-p0019","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"19","seq":20,"section":"B. Justice and rule of law","text":"In its oral statement for its examination in 2024 under the universal periodic review,\nthe Government's delegation reported that the Government had enacted or amended laws\nrelating to the treatment of persons deprived of liberty and fair trial guarantees, including\nwith regard to rights to access to legal representation and appeal, and accountability for\nmisconduct by public officials, in order to align with international human rights standards.12\nDespite the reported legislative changes, arrests without warrant, proper investigation or\nevidence persist, as do fair-trial concerns. Most trials are brief, with detainees routinely\ndenied meaningful access to defence counsel and presumed guilty before the conclusion of\nformal investigations, and judicial decisions are often based on coerced confessions. The\nWorkers' Party of Korea regularly intervenes in trials. However, escapees have reported that\njudges increasingly acknowledge detainees as individuals, addressing them by name rather\nthan by number. Crimes considered \"anti-State\" or \"threats to national security\" carry the\ndeath penalty and continue to be vaguely defined, allowing the misapplication and misuse of\nthese charges for political purposes."},{"id":"a-hrc-60-58-p0020","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"20","seq":21,"section":"B. Justice and rule of law","text":"Former detainees reported that torture and other forms of ill-treatment in detention\nfacilities had continued since 2014. Many reported that they had witnessed deaths in\ndetention, primarily as a result of torture and ill-treatment, overwork, malnutrition and\nsuicide. Reportedly, officials regularly falsified documents to record deaths as natural or\nresulting from pre-existing medical conditions. Severe lack of food and medical care was\n11 See https://unikorea.go.kr/eng_unikorea/relations/statistics/defectors/.\n12 A/HRC/58/11, paras. 71, 83 and 84; and https://webtv.un.org/en/asset/k1s/k1siu17x8h (01:53:20).\nreportedly common in the detention facilities, especially during the COVID-19 pandemic,\nwhen several detainees died from malnutrition, as they were unable to receive food from their\nfamilies. Former detainees reported that the harsh conditions and violence in detention\nfacilities were intended to serve as a deterrent to committing crimes in the future."},{"id":"a-hrc-60-58-p0021","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"21","seq":22,"section":"B. Justice and rule of law","text":"At least 12 foreign nationals were detained by the Government during the reporting\nperiod. Of those, six nationals of the Republic of Korea, who have been detained in the\ncountry since 201313 without consular access or information on their status or whereabouts,\nhave not yet been released. In November 2024, the Working Group on Arbitrary Detention\nconcluded that the detention of three nationals of the Republic of Korea was arbitrary and\nviolated their rights; it recommended that they be released immediately and provided with\nreparations.14"},{"id":"a-hrc-60-58-p0022","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"22","seq":23,"section":"B. Justice and rule of law","text":"A notable aspect of the past decade is the reporting by escapees of nominal\nimprovements in the treatment of detainees during the judicial process and in detention\nfacilities, including a slight decrease in violence by guards. Former detainees reported that\nlaw enforcement officials had demonstrated more awareness of the standards for the\ntreatment of persons deprived of liberty and their conditions of detention. In that regard, they\nreported that procedures had been established for detainees to file complaints about\nmistreatment or abuse of power by junior officials to senior government and party officials,\nclosed-circuit televisions (CCTVs) had been installed in detention facilities, and senior\nofficials were required by law to carry out regular inspections of detention facilities. The\nGovernment reported that it had enacted the Law on the Treatment of Reform Institution\nInmates in May 2022, setting standards for the treatment of detainees and providing for the\nmonitoring of misconduct committed by guards. OHCHR had requested, but not yet received,\na copy of that law as at the time of writing. Despite these changes, filing complaints against\nofficials reportedly remains dangerous, with many detainees fearing retribution. Conditions\nregarding food, sanitation and healthcare have reportedly not improved."},{"id":"a-hrc-60-58-p0023","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"23","seq":24,"section":"B. Justice and rule of law","text":"Information on political prison camps is very limited. However, OHCHR monitoring,\nincluding satellite imagery, shows the continued operation of at least four political prison\ncamps, following closures and expansions of different facilities over the decade. The\nGovernment has denied the existence of these facilities; however, it confirmed that people\nwho commit \"anti-State\" offences are detained in \"reform institutions\" and kept separate\nfrom ordinary prisoners. 15 Political prison camps are the site of severe human rights\nviolations, including enforced disappearance, forced labour, summary execution and\nstarvation. Family members of those accused of crimes are also incarcerated, through \"guilt\nby association\", although this practice has reportedly been less rigorously applied in recent\nyears. While people are generally detained for life in these camps, there are some reports of\nchildren and grandchildren of accused persons being released and sentences being shortened."},{"id":"a-hrc-60-58-p0024","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"24","seq":25,"section":"B. Justice and rule of law","text":"The application of the death penalty has significantly expanded since 2015, with at\nleast six new laws16 expanding such application, including for offences, such as those relating\nto drug trafficking and \"anti-State\" propaganda, that do not meet the threshold requirement\nunder international law of \"most serious crimes\".17 In 2014 and 2015, several senior officials\nwere reportedly executed for \"anti-State acts\". While this trend subsequently decreased,\nescapees reported that, from 2020, executions increased for the distribution of unauthorized\nmedia, drug-related crimes, economic crimes, prostitution, pornography, trafficking in\npersons and murder. The Government has claimed that the death penalty is used for \"crimes\nagainst the State\" and \"extremely serious crimes that were unpardonable\", and is not imposed\non persons who were under 18 years of age at the time of committing the offence or on\npregnant women.18 Several interviewees reported witnessing public executions over the past\ndecade. The Government reported that public executions were an exception, used in cases of\n\"heinous\" murder without remorse, in cases where the criminal had committed repeated\ncrimes, causing serious harm to others, and in cases where the victim's family requested such\nan execution.19 Since 2020, public executions have reportedly been undertaken for cases\ninvolving, inter alia, the distribution foreign media and the violation of epidemic prevention\nlaws. Executions are reportedly carried out by firing squad after trials that do not meet fair\ntrial standards."},{"id":"a-hrc-60-58-p0025","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"25","seq":26,"section":"B. Justice and rule of law","text":"Despite some government campaigns, corruption has deeply infiltrated governance,\nincluding the judiciary, since at least 2014. Bribery has become essential in practice for\ncitizens, who must resort to it to defend their legal rights and avoid being charged with\nviolations. The criminalization of fundamental rights, such as to move, to communicate and\nto earn a living, has given officials significant leverage to demand bribes. Detention and\njudicial processes are heavily influenced by an individual's ability to pay bribes, thus\nexposing poor and vulnerable individuals to severe rights violations if they are unable to pay.\nAlmost all former senior officials interviewed by OHCHR admitted that accepting bribes was\nunavoidable, owing to low State salaries and an obligation to generate income for their State\norganization. At the same time, given the restrictions imposed by the State over its\npopulation, reducing corruption would further restrict the limited possibilities, often\naccessible only through bribes, for people to travel, seek employment or avoid harsh\ntreatment."},{"id":"a-hrc-60-58-p0026","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"26","seq":27,"section":"B. Justice and rule of law","text":"Throughout the past decade, repatriated individuals were subjected to serious human\nrights violations, including arbitrary detention, torture, ill-treatment, enforced disappearance\nand sexual and gender-based violence. Many were separated from their children. Escapees\nallegedly intending to flee to the Republic of Korea were treated as committing serious crimes\nagainst the State and thus subjected to particularly harsh punishment. Former government\nofficials revealed to OHCHR that special arrest teams were dispatched to capture and\nrepatriate escapees from other countries. Punishments for illegal border crossing have\nincreased since 2020; suspects who intended to defect are sentenced to a minimum of five\nyears in prison. After the partial opening of the borders in 2023, hundreds of people were\nrepatriated from China, at variance with its non-refoulement obligations."},{"id":"a-hrc-60-58-p0027","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"27","seq":28,"section":"B. Justice and rule of law","text":"During the period under review, there was no resolution on the issue of enforced\ndisappearance and abductions. According to reports, disappearances in the country, and cases\nof abduction, of foreign nationals continue to remain unresolved, despite continued\ninvestigations in the countries of origin. The victims are aging and some of their family\nmembers have passed away. In the Stockholm Agreement of 2014, the Government of the\nDemocratic People's Republic of Korea agreed to conduct investigations on all nationals of\nJapan in the country, including abductees, but in 2016 it announced that it would halt those\ninvestigations. Since then, the Democratic People's Republic of Korea has reverted to its\nclaim that the abductions issue had been resolved.20 The Working Group on Enforced or\nInvoluntary Disappearances has regularly raised concerns about the scale of enforced\ndisappearance in the country. By 2025, it had communicated 450 cases to the Government,21\ninvolving, inter alia, abductions of foreign nationals, including of the Republic of Korea and\nof Japan; former prisoners of war; repatriated persons; victims of the 1969 Korean Air Lines\nhijacking; and victims of the Paradise on Earth campaign. The Working Group has noted that\nthe Government had failed to provide substantive information to clarify those cases.22"},{"id":"a-hrc-60-58-p0028","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"28","seq":29,"section":"B. Justice and rule of law","text":"During the period under review,23 three reunions of families separated by the Korean\nWar were held, involving 526 families.24 The United Nations has regularly called for more\nfamily reunions and long-term contact options to reduce the anguish for these families. The\n18 A/HRC/58/11, para. 87.\n19 A/HRC/58/11, para. 87; and https://webtv.un.org/en/asset/k1s/k1siu17x8h (02:06:38).\n20 A/HRC/58/11, para. 123.\n21 See A/HRC/57/54.\n22 A/HRC/54/22, para. 72.\n23 February 2014, October 2015 and August 2018.\n24 See https://reunion.unikorea.go.kr/reuni/home/pds/reqststat/list.do?mid=SM00000129 (in Korean).\nGovernment of the Democratic People's Republic of Korea has not agreed to video calls. Of\nthe 134,291 people listed by the Republic of Korea in its registry of separated families, 97,350\nhave died. Of the remaining 36,941, more than 65 per cent are over 80 years old.25 This\nunderlines the urgency and tragedy of the current situation."},{"id":"a-hrc-60-58-p0029","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"29","seq":30,"section":"C. Development and economic, social and cultural rights","text":"Since the 1990s, informal markets (jangmadang) have provided a means for economic\nopportunities for livelihoods, particularly for married women in the Democratic People's\nRepublic of Korea. The Government tolerated those markets and facilitated their expansion\nuntil 2020, after which private commercial activities were labelled \"anti-socialist behaviour\"\nand thus limited. While informal markets remain in operation, reports suggest that the\nGovernment has reduced their operating hours, made it more difficult to obtain authorization\nto trade, and reduced the volume of goods being traded, thereby reducing any viable\nopportunities for livelihoods for many families."},{"id":"a-hrc-60-58-p0030","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"30","seq":31,"section":"C. Development and economic, social and cultural rights","text":"Unless serving in the military, all men and unmarried women are required to work at\nState-owned workplaces, with any absence punishable by law. These workplaces often pay\npoorly, if at all. Many of these companies were not operating, or were operating at a low\ncapacity, during the past decade due to a lack of electricity and raw materials as a result of\nsanctions. To survive, employees pay a certain amount to be absent from their workplaces\nand engage in other money-making activities. Married women who are exempted from State-\nassigned jobs are often targeted for mobilization for government projects. In late 2023, the\nGovernment increased the salary of workers and public officials by as much as 50 times the\nprevious rate. As most workers receive none or very little of their wage entitlement, this\nsalary increase is likely to have scant impact on living standards."},{"id":"a-hrc-60-58-p0031","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"31","seq":32,"section":"C. Development and economic, social and cultural rights","text":"Forced labour has become deeply institutionalized over the past decade, through\nforced mobilizations in the prison system, in the military, in \"shock brigades\", in\nneighbourhood watch units and other community groups, in the school system and among\noverseas workers. The large prison population is required to carry out physically demanding\ntasks, such as paving roads, cutting trees and harvesting crops, or work in other physically\ndemanding sectors, such as manufacturing and construction. Former detainees reported being\nforced to produce goods for export, such as wigs, fake eyelashes and hats. Shock brigades\nare forced mobilizations for specific tasks, usually in physically demanding and hazardous\nsectors, such as mining and construction. Workers join shock brigades to increase their\nchances of becoming party members or to improve their social status. Shock brigade\nmembers often come from poorer families. In recent years, the Government has used\nthousands of orphans and street children for labour in coal mines and other hazardous\nenvironments, where they work long hours. Deaths are reportedly frequent during these\nmobilizations; however, rather than providing health and safety measures, the Government\npublicly glorifies deaths as a sacrifice to the leader. In its resolution 2397 (2017), the Security\nCouncil required the repatriation, by 2019, of all nationals of the Democratic People's\nRepublic of Korea who were working overseas. While this reduced their numbers, such\noverseas workers, including in the information technology, construction and hospitality\nsectors, are still deployed, reportedly as \"students\". There are no credible reported figures of\nthe number of overseas workers from the Democratic People's Republic of Korea who\ncurrently remain abroad."},{"id":"a-hrc-60-58-p0032","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"32","seq":33,"section":"C. Development and economic, social and cultural rights","text":"Education remains free and compulsory from primary to secondary level, with nearly\nuniversal enrolment rates. Students are, however, required to make monetary contributions\nfor books, supplies and facility upkeep, which prevents children from lower-income families\nfrom regularly attending school. A focus on political ideology remains a central feature of\neducation and has been further strengthened in recent years. Young people have reported that\nthey no longer see the value in studying and attending universities, as education does not\nguarantee a better life. The Government has stated that it aims to make education more\n25 See https://unikorea.go.kr/books/whitepaper/whitepaper/white_2025/index.html#p=1 (in Korean).\nmodern and technology-based;26 however many schools lack electricity and other basic\nservices and facilities."},{"id":"a-hrc-60-58-p0033","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"33","seq":34,"section":"C. Development and economic, social and cultural rights","text":"In the 2024 Global Hunger Index, the Democratic People's Republic of Korea ranked\n118th out of 127 States. The indicators used to calculate the score reflected extremely\nalarming rates of undernourishment, serious levels of child wasting and moderate child\nmortality rates in the country.27 Chronic food insecurity persisted during the decade due to\ninadequate domestic production, floods and natural disasters, lack of arable land, insufficient\nState investment in agriculture and, to a certain extent, sanctions. The country has been facing\nintergenerational undernourishment since the collapse of its public distribution system in the\n1990s, which reduced food accessibility and weakened the Government's ability to provide\nfood. Over 40 per cent of the population in the Democratic People's Republic of Korea was\nundernourished.28 Almost all the people OHCHR interviewed mentioned not having adequate\nfood, and that detainees and older persons faced severe food insecurity. Eating three meals\nper day is a luxury for most people in the country. Within the family, women receive less and\nworse quality food. The COVID-19 pandemic worsened food insecurity; the senior\nleadership warned of a food crisis, and many escapees reported that there was a severe lack\nof food (including in Pyongyang) and that people had died of hunger between 2021 and 2023."},{"id":"a-hrc-60-58-p0034","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"34","seq":35,"section":"C. Development and economic, social and cultural rights","text":"During the past decade, the Government did not provide rations through its public\ndistribution system, except to select groups, such as veterans with disabilities, soldiers and\nsenior officials. Since 2015, several laws have been amended to centralize grain procurement,\nmanagement and distribution. Since 2020, the Government has centralized grain\nmanagement to stabilize prices, leading to an increase in subsidized public grain shops and a\ndrastic reduction in private grain sellers in markets. These measures have strengthened the\nGovernment's control of food production, management and distribution."},{"id":"a-hrc-60-58-p0035","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"35","seq":36,"section":"C. Development and economic, social and cultural rights","text":"The Government states that medical care is free, and publicizes new hospitals.\nAccounts from escapees reveal that access to essential health services is limited and depends\non one's ability to pay. Hospital patients are required to bring their own drugs, medical\nsupplies, fuel and food to receive treatment. COVID-19 exacerbated the shortages in the\nhealth system. A 2022 law centralized the distribution of medicines and imposed strict\npunishments for illegal sales. This has affected much of the population who had relied on\nmedicine sold privately in markets."},{"id":"a-hrc-60-58-p0036","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"36","seq":37,"section":"C. Development and economic, social and cultural rights","text":"National immunization rates in the country exceeded 96 per cent before the\nCOVID-19 pandemic, but dropped to below 42 per cent by mid-2021. In 2022, no children\nor pregnant women received routine vaccinations, due to a lack of stock. An estimated\n500,000 children missed routine immunizations during COVID-19. In 2023 and 2024, the\nGovernment, supported by United Nations Children's Fund (UNICEF), conducted a\nnationwide catch-up vaccination campaign for mothers and children who had missed\nvaccinations during the pandemic."},{"id":"a-hrc-60-58-p0037","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"37","seq":38,"section":"C. Development and economic, social and cultural rights","text":"A feature of the decade has been the Government's focus on large-scale housing and\nmanufacturing projects, announcing plans in 2021 to build 50,000 new apartments in\nPyongyang by 2025. In 2024, the \"20�10\" rural development initiative was launched to build\n20 new factories annually in rural counties for the next 10 years to enhance regional\neconomies, improve living standards and address rural-urban disparities. In the past, similar\ninfrastructure projects raised serious human rights concerns, including the use of forced\nlabour, lack of workplace health and safety and forced evictions."},{"id":"a-hrc-60-58-p0038","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"38","seq":39,"section":"D. Equality and non-discrimination","text":"OHCHR interviews reveal that discrimination based on songbun, a system of\nclassification of people based on State-assigned social class and birth,29 continued to be\n26 See https://www.ncnk.org/resources/publications/kimjongun_2019_newyearaddress.pdf/file_view.\n27 See https://www.globalhungerindex.org/korea-dpr.html.\n28 See https://openknowledge.fao.org/server/api/core/bitstreams/b08bed4d-75d3-4dfe-8ef1-\nce806bc11229/content and https://www.wfp.org/countries/democratic-peoples-republic-korea.\n29 A/HRC/25/63, paras. 32, 33 and 37.\npervasive during the past decade, despite Government claims that the concept does not\nexist.30 The system of resident registration and movement restrictions is also discriminatory,\nas it reserves residence in Pyongyang, or even visits to the city, for political elites. The stark\ndifferences in the socioeconomic indicators between rural and urban regions reflect this\nsocioeconomic discrimination."},{"id":"a-hrc-60-58-p0039","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"39","seq":40,"section":"D. Equality and non-discrimination","text":"In December 2016, the State ratified the Convention on the Rights of Persons with\nDisabilities. This was followed by an official visit from the Special Rapporteur on the rights\nof persons with disabilities, in 2017 � the only visit ever to the Democratic People's Republic\nof Korea by a Special Rapporteur. A new law on the protection and promotion of the rights\nof persons with disabilities was adopted in 2023. About six per cent of citizens have\ndisabilities, with more women than men living with disabilities. OHCHR noted some\nimprovements in the protection of the rights of persons with disabilities. For example, in the\npast, persons with disabilities were expelled to rural areas from cities, whereas now they can\nlive in Pyongyang and other cities. The Government, in its initial report to the Committee on\nthe Rights of Persons with Disabilities,31 outlined several policies and structural reforms to\nprotect and promote the rights of persons with disabilities. Despite these commitments,\nsignificant gaps remain. Persons with disabilities continue to face stigmatization and\ndiscrimination. Inclusive education is limited, with low enrolments of children with\ndisabilities. Little infrastructure is accessible, including public buildings built recently."},{"id":"a-hrc-60-58-p0040","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"40","seq":41,"section":"D. Equality and non-discrimination","text":"Children are subjected to various forms of forced labour, ideological indoctrination\nand chronic malnutrition. Students are regularly mobilized for farm work during the planting\nand harvest season, without any compensation. The Government has claimed that forced\nlabour is forbidden and that student work on farms is for educational purposes, noting that a\n2016 law on the implementation of educational programmes prevents the forced mobilization\nof school children outside of the educational programme. 32 Children lack access to\nindependent information, and their rights to freedom of opinion and expression are not\nrespected. Children under the age of 5 face chronic food insecurity, with malnutrition rates\nconsistently over 40 per cent for the past decade. In 2023, UNICEF reported that in some\nprovinces, over 4 per cent of children screened at treatment facilities were affected by severe\nor moderate acute malnutrition.33 During the COVID-19 pandemic, there were reports that\nincreased food shortages had led to a rise in the number of children in street situations."},{"id":"a-hrc-60-58-p0041","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"41","seq":42,"section":"D. Equality and non-discrimination","text":"The Government has held that that gender equality has long been achieved, citing\nconstitutional and legal guarantees.34 In practice, gender discrimination is deeply rooted in\nState institutions, education, employment and the private sphere. Women are\nunderrepresented in leadership, public institutions and senior positions in the Workers' Party\nof Korea. With the national decrease in childbirth, the role of women has been shaped in\nrecent years as the \"mother hero\": women are encouraged to have more children and are cast\nsolely as caregivers, which limits women's full economic and social participation."},{"id":"a-hrc-60-58-p0042","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"42","seq":43,"section":"D. Equality and non-discrimination","text":"The exemption of married women from State employment allows them to engage in\nprivate commercial activities. During the past decade, married women have been shouldering\nthe dual responsibility of domestic care and household economic activities. While this has\nbrought welcome economic empowerment to women, it has left them vulnerable to abuse by\nauthorities, as private commercial activities are not fully legal. Women were hit hardest\nduring the COVID-19 pandemic, as the Government placed restrictions on private markets,\ntheir main source of income."},{"id":"a-hrc-60-58-p0043","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"43","seq":44,"section":"D. Equality and non-discrimination","text":"Most women interviewed by OHCHR reported that domestic violence against women\nand girls was widespread, but was largely unreported due to cultural stigma and inadequate\nlegal protection. Authorities typically fail to investigate these incidents, perceiving them as\nprivate matters. The findings of the 2017 Multiple Indicator Cluster Survey indicated that\naround 10 per cent of women and 8 per cent of men believed there were justifications for\nmen to beat women.35 In 2017, the Committee on the Elimination of Discrimination against\nWomen recommended that the Government eliminate discriminatory stereotypes and\npatriarchal attitudes about gender roles.36"},{"id":"a-hrc-60-58-p0044","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"44","seq":45,"section":"D. Equality and non-discrimination","text":"OHCHR has documented cases of sexual and gender-based violence by law\nenforcement officials. Over the past decade, as more women engaged in commercial\nactivities in informal markets, they faced increased inspections and exploitation by officials\nunder threats of detention, fines, bribes and sexual violence. Women usually remained silent\nto avoid worsening their situation and were unaware of complaint procedures, which were\nnot victim-centred or efficient. In detention facilities, women were not provided with\nessential gender-specific healthcare services and hygiene materials, which violated their\nsexual and reproductive rights. Reports indicate that strip searches and invasive cavity\nsearches continued in places of detention after repatriation; such practices could constitute\ngender-based violence and, in some cases, torture. Authorities demanded sexual favours in\nexchange for better food and less demanding jobs. Detainees reported that the treatment of\npregnant women in detention had improved in the past years, although they still faced\ninadequate medical care, malnutrition and unsanitary conditions."},{"id":"a-hrc-60-58-p0045","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"45","seq":46,"section":"D. Equality and non-discrimination","text":"OHCHR lacks sufficient information about the lives of lesbian, gay, bisexual,\ntransgender, intersex and queer persons to assess their situations."},{"id":"a-hrc-60-58-p0046","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"46","seq":47,"section":"IV. Accountability","text":"The commission of inquiry drew a number of conclusions and made detailed\nrecommendations on accountability for systematic, widespread and gross human rights\nviolations perpetrated in the country that it had identified; in many instances, the violations\nconstituted crimes against humanity.37 OHCHR and the group of experts on accountability\nfor human rights violations in the Democratic People's Republic of Korea, established by the\nHuman Rights Council in its resolution 31/18, followed up on the implementation of the\nrecommendations."},{"id":"a-hrc-60-58-p0047","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"47","seq":48,"section":"IV. Accountability","text":"The Government has the obligation to investigate and prosecute serious human rights\nviolations, in particular those amounting to crimes against humanity, and to provide effective\nremedies to victims. OHCHR is not aware of any accountability measures taken by the State\nduring the past decade. OHCHR has continued to document patterns of ongoing gross human\nrights violations, some of which may amount to crimes against humanity.38"},{"id":"a-hrc-60-58-p0048","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"48","seq":49,"section":"IV. Accountability","text":"The primary responsibility for ensuring accountability for international crimes rests\nwith the State. The High Commissioner has called on the Government to investigate and\nprosecute individuals responsible for alleged crimes against humanity; to accede to the Rome\nStatute of the International Criminal Court; and to ensure that victims of such crimes, and\ntheir families, are provided with adequate, prompt and effective reparation. Applicable\ninternational law establishes that such crimes are not subject to any statute of limitations or\namnesty and that criminal liability may attach to representatives of the State authority as\ndirect or indirect perpetrators of such crimes, including for the failure to act upon\nsubordinates' unlawful conduct."},{"id":"a-hrc-60-58-p0049","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"49","seq":50,"section":"IV. Accountability","text":"Given the gravity, scale and seriousness of the violations, and the State's inability or\nunwillingness to pursue accountability, OHCHR continues to monitor and document\nviolations and possible crimes and preserve information and evidence in its mandated central\nrepository. It has urged the international community to take steps to assume responsibility\nfor ensuring accountability. Accountability efforts over the past decade by victims, civil\nsociety and the international community have included the collection and analysis of\ninformation; criminal and civil litigation; the adoption of universal jurisdiction legislation by\nsome Member States; communications to the Office of the Prosecutor of the International\nCriminal Court under article 15 of the Rome Statute; reparations measures; support for\n35 See https://www.unicef.org/dprk/media/156/file/MICS.pdf.\n36 CEDAW/C/PRK/CO/2-4, para. 24.\n37 See A/HRC/25/63.\n38 See A/HRC/46/52.\nvictims; and engagement with United Nations human rights mechanisms. Such positive steps\nto pursue both judicial and non-judicial forms of accountability have been reported regularly\nby the OHCHR."},{"id":"a-hrc-60-58-p0050","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"50","seq":51,"section":"V. Conclusions","text":"Information gathered by OHCHR shows that, despite the isolated steps taken,\nthe human rights situation in the Democratic People's Republic of Korea has not\nimproved overall since 2014 and, in many instances, has degraded. Since 2014, control\nby the Government over its citizens has tightened increasingly. Under laws, policies and\npractices introduced since 2015, citizens have been subjected to increased surveillance\nand control in all parts of life. As one escapee told OHCHR: \"To block the people's eyes\nand ears, they strengthened the crackdowns. It was a form of control aimed at\neliminating even the smallest signs of dissatisfaction or complaint.\" No other population\nis under such restrictions in today's world."},{"id":"a-hrc-60-58-p0051","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"51","seq":52,"section":"V. Conclusions","text":"The majority of the 19 recommendations made by the Commission of Inquiry to\nthe State have not been implemented. Accountability for human rights violations is\nminimal and accountability for international crimes remains non-existent. The\nprofound institutional reform recommended by the Commission has not materialized.\nPolitical prison camps continue to operate. The fate of the hundreds of thousands of\ndisappeared persons, including abducted foreign nationals, remains unknown.\nMeetings of separated families have not been held in the past seven years.\nCommunication and the sending of remittances between separated families is now\nextremely difficult. Citizens continue to be subjected to unremitting propaganda by the\nState. Freedom of religion continues to be extremely curtailed, particularly for\n\"superstitious activity\". Discrimination continues to pervade society, including through\nthe system of songbun, which determines people's lives even before they are born. The\nGovernment's claim that gender equality has long been achieved masks serious\nproblems, including sexual and gender-based violence in the public and private spheres.\nThe right to food continues to be violated, with State policies exacerbating hunger,\nwhich has been a constant feature of people's lives over the past decade."},{"id":"a-hrc-60-58-p0052","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"52","seq":53,"section":"V. Conclusions","text":"In some areas referred to in the report of the commission of inquiry, the situation\nhas become markedly worse. The death penalty is more widely allowed by law and\nimplemented in practice. There have been significant regressions regarding freedom of\nexpression and access to information, with the implementation of severe new\npunishments, including the death penalty, for a range of acts, including the sharing of\nforeign media. The general surveillance of the population is more pervasive, aided by\nadvances in technology. People are less able to bribe their way out of arbitrary\npunishments. Forced labour in many forms has increased over the decade, particularly\nin shock brigades. The right to freely leave, return and move inside one's own country\nhas become more limited with the reinforcement of international border control and a\nmore comprehensive internal permit system. In the second half of the reporting period,\npeople's ability to provide for themselves eroded with the return of State control of the\neconomy, closing key aspects of the nascent market economy, such as the ability of many\nto trade in local markets. With few other sources of income, the results are devastating\nfor people's enjoyment of economic, social and cultural rights."},{"id":"a-hrc-60-58-p0053","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"53","seq":54,"section":"V. Conclusions","text":"In limited areas, OHCHR has received reports of isolated improvements. Several\nlaws have been enacted or amended, reportedly strengthening fair trial guarantees and\nprotection against ill-treatment of persons deprived of liberty. The country engaged\nwith the international human rights system, ratified two more human rights treaties,\ncomplied with some treaty bodies' reporting obligations, engaged in the universal\nperiodic review, sought technical assistance from OHCHR and accepted the visit of a\nthematic special rapporteur in 2017. However, the disconnect between the State's\ninternational obligations and the lives of its citizens remains stark."},{"id":"a-hrc-60-58-p0054","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"54","seq":55,"section":"V. Conclusions","text":"Recommendations made by the commission of inquiry to the international\ncommunity have been only partially implemented. The human rights situation in the\nState remains on the agenda of the Security Council, which establishes the link between\nhuman rights and peace and security on the Korean Peninsula. Much has been achieved\nin the form of preparation for future judicial accountability processes, judgments in\ncivil cases in third-State jurisdictions, truth-telling, memorialization and long-overdue\nmovement towards reparations measures for victims. To date, the situation in the\ncountry has not been referred to the International Criminal Court. The OHCHR\npresence in Seoul is well established, with strong mandates on human rights and\naccountability, and OHCHR has reported regularly over the decade. Forced\nrepatriations continue, despite the real risks of serious human rights violations. Inter-\nKorean dialogue (including person-to-person contact), and investments in peace efforts,\nfluctuated, with the current situation possibly at the lowest level of the past decade."},{"id":"a-hrc-60-58-p0055","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"55","seq":56,"section":"V. Conclusions","text":"The human rights landscape cannot be divorced from the broader isolation that\nthe State is currently pursuing. In 2025, the country remains more closed and isolated\nthan at almost any other time in its history. The flow of people into and out of the State\nis curtailed, Internet is not accessible and there is a blackout on most information\nemanating from abroad. While trade and exchanges with some countries have\nexpanded, the country is, overall, far less connected with the broader international\ncommunity. Links with the Republic of Korea have been almost entirely severed, and\nthe long-standing national policy of peaceful reunification abandoned. The presence\nand support of the United Nations has been significantly reduced, with no international\nstaff allowed back into the country since 2020."},{"id":"a-hrc-60-58-p0056","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"56","seq":57,"section":"VI. Recommendations","text":"The current trajectory in the Democratic People's Republic of Korea will bring\nmore suffering to a population that has endured much for decades. To this end, the\nHigh Commissioner makes the following proposals to complement the hundreds of\nspecific recommendations addressed to the Government by United Nations human\nrights mechanisms, including the commission of inquiry, over the past decade."},{"id":"a-hrc-60-58-p0057","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"57","seq":58,"section":"VI. Recommendations","text":"The State has voluntarily ratified five core human rights treaties. International\nhuman rights law provides the road map for improving the situation in the country.\nMoving to end violations, including the intense repression of fundamental freedom, is\nessential to unlocking the potential of the people of the country, most importantly the\nyounger generation."},{"id":"a-hrc-60-58-p0058","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"58","seq":59,"section":"VI. Recommendations","text":"The gravity of the situation requires accountability, including for violations of\nhuman rights that amount to international crimes. This is primarily the task of the\nState. Small steps have been taken in legal frameworks towards holding State officials,\nparticularly in the justice sector, accountable, but much more is needed."},{"id":"a-hrc-60-58-p0059","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"59","seq":60,"section":"VI. Recommendations","text":"Peace is closely linked with human rights, particularly on the Korean Peninsula.\nThe Government has stated its security concerns and the impact of sanctions. However,\npeace requires de-escalation and dialogue. The State's current extreme isolation is a\nmajor barrier to efforts to improve the lives of its people. In today's highly\ninterconnected world, this situation is an anomaly. Isolation needs to give way to\nengagement."},{"id":"a-hrc-60-58-p0060","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"60","seq":61,"section":"VI. Recommendations","text":"Immediate steps that would build momentum and provide credibility include:\n(a) Ending the system of political prison camps and guilt by association;\n(b) Ending the use of the death penalty;\n(c) Restarting family connections, including meetings;\n(d) Ending torture and ill-treatment in places of detention;\n(e) Providing information on persons who have been abducted or forcibly\ndisappeared by the State;\n(f) Distributing information about human rights to the population;\n(g) Inviting the High Commissioner and other human rights mechanisms to\nvisit the country;\n(h) Accepting OHCHR technical assistance on upholding rights in detention."},{"id":"a-hrc-60-58-p0061","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"61","seq":62,"section":"VI. Recommendations","text":"The international community has a role to play towards the goals of improving\nthe human rights situation, ending isolation and furthering peace. This requires efforts\nfrom third States, particularly those with the capacity to influence and that maintain\nrelations with the Democratic People's Republic of Korea. The links between peace and\nhuman rights on the Korean Peninsula need to be addressed in a holistic manner,\nincluding with regard to the negative impact of sanctions on the enjoyment of human\nrights of the population. Accountability for international crimes and the rights of\nvictims to effective remedies must be pursued, including through a referral to the\nInternational Criminal Court and by other States under accepted principles of\nuniversal jurisdiction, in accordance with international standards. States must fully\nrespect the principle of non-refoulement and consistently refrain from carrying out\nforcible repatriations in the light of the real risk of serious human rights violations."},{"id":"a-hrc-60-58-p0062","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":"62","seq":63,"section":"VI. Recommendations","text":"These recommendations are made to improve the almost sui generis human\nrights situation in the Democratic People's Republic of Korea and to give the people\nhope for a path towards a future of greater freedom in equality and rights. Interviews\nconducted by OHCHR reveal a strong desire for change, particularly among young\npeople. The international community has a shared responsibility to keep the situation\nin focus, to pursue every opportunity to ensure accountability and to work towards\nsustainable improvements by which all citizens can fulfil their aspirations and enjoy the\nfull spectrum of human rights and fundamental freedoms."},{"id":"a-hrc-60-58-u0064","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":64,"section":"Annex","text":"Documents submitted by the United Nations High\nCommissioner for Human Rights and the Secretary-General,\nor issued by human rights mechanisms, on the situation in\nthe Democratic People's Republic of Korea","unnumbered":true},{"id":"a-hrc-60-58-u0065","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":65,"section":"Annex","text":"Reports of the Secretary General on the situation of human rights in the Democratic People's\nRepublic of Korea: A/79/277, A/78/212, A/77/247, A/76/242, A/75/271, A/74/268,\nA/73/308, A/72/279, A/71/439, A/70/393, and A/69/639","unnumbered":true},{"id":"a-hrc-60-58-u0066","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":66,"section":"Annex","text":"Reports of the High Commissioner for Human Rights on promoting accountability in the\nDemocratic People's Republic of Korea, and on the role and achievements of the Office of\nthe United Nations High Commissioner for Human Rights with regard to the situation of\nhuman rights in the Democratic People's Republic of Korea: A/HRC/58/61, A/HRC/52/64,\nA/HRC/46/52, A/HRC/40/36, and A/HRC/31/38","unnumbered":true},{"id":"a-hrc-60-58-u0067","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":67,"section":"Annex","text":"Reports of the Special Rapporteur on the situation of human rights in the Democratic People's\nRepublic of Korea to the Human Rights Council and to the General Assembly: A/HRC/58/65,\nA/79/235, A/HRC/55/63, A/78/526, A/HRC/52/65, A/77/522, A/HRC/49/74, A/76/392,\nA/HRC/46/51, A/75/388, A/HRC/43/58, A/74/275/Rev.1, A/HRC/40/66, A/73/386,\nA/HRC/37/69, A/72/394, A/HRC/34/66, A/71/402, A/HRC/31/70, A/70/362, A/HRC/28/71,\nA/69/548, and A/HRC/26/43","unnumbered":true},{"id":"a-hrc-60-58-u0068","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":68,"section":"Annex","text":"Annual Reports of the Working Group on Enforced or Involuntary Disappearances: 2024\npara. 65-66 A/HRC/57/54, 2023 para. 72-73 A/HRC/54/22*, 2022 para. 52-54\nA/HRC/51/31, 2021 para. 77-79 A/HRC/48/57, 2020 para. 15, A/HRC/45/13, 2019 para. 60,\nA/HRC/42/40, 2018 para. 90-92 A/HRC/39/46, 2017 para.74-76, A/HRC/36/39, 2016\npara. 88, A/HRC/33/51, 2015 para. 66, A/HRC/30/38, 2014 para. 72, A/HRC/27/49","unnumbered":true},{"id":"a-hrc-60-58-u0069","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":69,"section":"Annex","text":"Annual Reports of the Working Group on Arbitrary Detention: 2020 A/HRC/45/16, 2019\nA/HRC/42/39, 2018 A/HRC/39/45, 2016 A/HRC/33/50, Opinion No. 59/2024 concerning\nChun-gil Choi, Kook-kie Kim and Jung-wook Kim (Democratic People's Republic of Korea)\npara.19 A/HRC/WGAD/2024/59 (2025)","unnumbered":true},{"id":"a-hrc-60-58-u0070","rec_id":"recvHCxw7qUn8ck5o","symbol":"A/HRC/60/58","n":null,"seq":70,"section":"Annex","text":"Committee on the Rights of Persons with Disabilities: Report of the State Party\nCRPD/C/PRK/1 (2018), Replies of the State Party to the List of Issues CRPD/C/PRK/RQ/1\n(2024), List of Issues CRPD/C/PRK/Q/1 (2022)","unnumbered":true},{"id":"a-hrc-61-55-u0000","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":0,"section":null,"text":"Summary\nThe present report of the Special Rapporteur on the situation of human rights in the\nDemocratic People’s Republic of Korea, Elizabeth Salmón, is submitted pursuant to Human\nRights Council resolution 58/17. In the report, the Special Rapporteur provides an update on\nthe overall political and human rights situation, analyses the progress made in the\nimplementation of recommendations made during the universal periodic review and proposes\nfurther monitoring.","unnumbered":true},{"id":"a-hrc-61-55-u0001","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":1,"section":null,"text":"* The present report was submitted to the conference services for processing after the deadline for\ntechnical reasons beyond the control of the submitting office.\n** The annex to the present document is reproduced as received, in the language of submission only.","unnumbered":true},{"id":"a-hrc-61-55-p0001","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"1","seq":2,"section":"I. Introduction","text":"The Democratic People’s Republic of Korea has engaged with some international\nhuman rights mechanisms to certain extent. The country has participated in four cycles of the\nuniversal periodic review of the Human Rights Council and has supported hundreds of\nrecommendations. Despite those engagements with United Nations human rights\nmechanisms, the United Nations High Commissioner for Human Rights, in 2025, assessed\nthat the overall human rights situation over the past 10 years had showed no improvement\nand, in many instances, had degraded, despite some isolated steps taken.1 In the present\nreport, the Special Rapporteur proposes ways to better use the recommendations emanating\nfrom the universal periodic review to improve the realization of human rights of people in\nthe State."},{"id":"a-hrc-61-55-p0002","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"2","seq":3,"section":"II. Current political and human rights situation","text":"The assistance provided by the Democratic People’s Republic of Korea to the Russian\nFederation, including the deployment of an estimated 14,000 military personnel to the\nconflict between the Russian Federation and Ukraine, has further strengthened the military\nand economic ties between the two countries. After assuming office in June 2025, the new\nadministration of the President of the Republic of Korea, Lee Jae Myung, suspended the\nloudspeakers that had been broadcasting negative messages and urged individuals to refrain\nfrom sending leaflets across the border. The President emphasized the need for reopening\ndialogue, pursuing “peaceful coexistence” 2 on the Korean Peninsula and placing\nreunification as the ultimate goal. On 28 July, the Democratic People’s Republic of Korea\ndescribed its stance on inter-Korean relations as follows: “there can be no change in our\nState’s understanding of the enemy”. 3 At the General Assembly in October 2025, the\nDemocratic People’s Republic of Korea, criticizing military exercises conducted by Japan,\nthe Republic of Korea and the United States of America, stated that “we will never give up\nnuclear, which is our State law, national policy and sovereign power, as well as the right to\nexistence”.4 During the visit of the President of the United States, Donald Trump, to the\nRepublic of Korea in October 2025, a meeting with the Democratic People’s Republic of\nKorea was reportedly considered but did not take place. The new Prime Minister of Japan,\nTakaichi Sanae, in November 2025, stated that she had conveyed her desire to hold a summit\nwith the Democratic People’s Republic of Korea to solve the abductions issue.5 In 2025, an\ninitiative of a group of States Members of the United Nations, the Multilateral Sanctions\nMonitoring Team,6 issued two reports, one on military cooperation 7 and the other on the\ncybersecurity threats posed by the Democratic People’s Republic of Korea.8"},{"id":"a-hrc-61-55-p0003","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"3","seq":4,"section":"II. Current political and human rights situation","text":"The Democratic People’s Republic of Korea continues to emphasize that it is\nimproving the living standards of its people. On food production, the law on account\nsettlement and income distribution in farms, adopted in 2025, is focused on “raising the zeal”\nof farmers with the goal of incentivizing production and building trust that harvests will be\nfairly allocated.9 The State media also reported in November that the planned construction of\nthousands of rural dwellings has been successfully completed in Ryanggang Province. 10\nPrevious such efforts involved the use of forced labour of mobilized people without safety\nmeasures or adequate rest. Strict control of the population and surveillance have continued\nand been further strengthened. Reportedly, since 2024, closed-circuit television (CCTV)\ncameras have been replaced with newer ones with facial recognition functions, and the rate\nof installation of such cameras has increased. 11 Freedom of movement remains severely\nrestricted, and escaping from the State is nearly impossible. In 2025, only 224 escapees\n(198 women and 26 men) arrived in the Republic of Korea.12 On 26 January 2026, Tokyo\nDistrict Court ordered the Democratic People’s Republic of Korea to compensate victims of\nthe Paradise on Earth campaign."},{"id":"a-hrc-61-55-p0004","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"4","seq":5,"section":"II. Current political and human rights situation","text":"The United Nations human rights mechanisms have continued to address human rights\nissues in the Democratic People’s Republic of Korea. In July 2025, the Special Rapporteur\nconducted her first official visit to Japan and visited Tokyo, Niigata and Osaka. She held\ndiscussions with various actors and victims on the issue of enforced disappearances as part\nof the human rights violations committed by the Democratic People’s Republic of Korea that\nextend beyond its borders. The Special Rapporteur submitted a report to the General\nAssembly on transnational repression by the Democratic People’s Republic of Korea through\nthe historical abduction and enforced disappearances of foreign nationals, the deployment of\nmilitary personnel to the armed conflict between the Russian Federation and Ukraine, the\ndispatch of overseas workers and cyberthreat activities, including repression of escapees.13\nOn 25 March 2025, the outcome of the review of the Democratic People’s Republic of Korea\nfor the fourth cycle of the universal periodic review was adopted by the Human Rights\nCouncil. 14 On 25 September 2025, the Council held an enhanced interactive dialogue to\ndiscuss the situation of human rights over the past 10 years in the Democratic People’s\nRepublic of Korea. At the dialogue, the Special Rapporteur highlighted the aggravated impact\nof human rights violations on women and the countless efforts made to pursue diverse forms\nof justice over the past 10 years. On 11 and 12 August 2025, the Committee on the Rights of\nPersons with Disabilities reviewed the initial report of the Democratic People’s Republic of\nKorea submitted pursuant to the Convention on the Rights of Persons with Disabilities.15 A\ndelegation from Pyongyang, consisting of officials from the Central Committee of the Korea\nFederation for the Protection of Persons with Disabilities, the Ministry of Foreign Affairs,\nthe Presidium of the Supreme People’s Assembly and the Ministry of Public Health,\nparticipated in a constructive dialogue with the Committee on the Rights of Persons with\nDisabilities."},{"id":"a-hrc-61-55-p0005","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"5","seq":6,"section":"II. Current political and human rights situation","text":"In addition, the Democratic People’s Republic of Korea participated in the thirtieth\nConference of the Parties to the United Nations Framework Convention on Climate Change,\nheld in Belém, Brazil, and, in a statement made on 11 November 2025, emphasized its efforts\nto address natural disasters, including through forest restoration work. 16 The State also\nsupported recommendations on climate change and on early recovery, disaster preparedness\nand risk mitigation emanating from the fourth cycle of the universal periodic review. 17 The\nState has worked on education and awareness-raising on climate change and mitigation\nstrategies. Deforestation is one of the key causes of frequent floodings in the State, however,\nfarmers have relied on private plots in the mountains for cultivating food for their own\nconsumption and generating a small income. The Government has reportedly strengthened\nthe ban on private cultivation, as part of its agricultural reform to control the production of\ngrains and also to support the restoration of forests, however, such measures are making\nfarmers’ lives more difficult.18"},{"id":"a-hrc-61-55-p0006","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"6","seq":7,"section":"II. Current political and human rights situation","text":"On 6 November 2025, the Special Rapporteur, together with four other mandate\nholders, sent a joint letter19 to the Democratic People’s Republic of Korea on a decree issued\nto grant amnesty to those who had been convicted of committing “crimes against the\ncountry”. The mandate holders asked for details on the implementation of the decree, stating\nthat the release of political prisoners had been continually recommended by the\nUnited Nations human rights mechanisms and that, if implemented, the decree could be a\npositive step."},{"id":"a-hrc-61-55-p0007","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"7","seq":8,"section":"III. Participation of the Democratic People’s Republic of Korea","text":"The universal periodic review, established in 2006, is an intergovernmental\nmechanism, and a process driven by States, through which the human rights record of all\nStates is examined every four and a half years. The review procedure is conducted on the\nbasis of information from various sources, including the State under review, the\nUnited Nations system, national human rights institutions, civil society organizations and\nregional intergovernmental organizations. The review of each State results in specific\nrecommendations by States to the State under review to enhance the promotion and\nprotection of human rights. The State under review takes a position on each recommendation,\nexpressing its support of them or noting (not supporting) them, in line with paragraph 32 of\nthe annex to Human Rights Council resolution 5/1."},{"id":"a-hrc-61-55-p0008","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"8","seq":9,"section":"III. Participation of the Democratic People’s Republic of Korea","text":"The Democratic People’s Republic of Korea has been reviewed under the universal\nperiodic review process four times, in 2009, 2014, 2019 and 2024. In 2009, of the\n167 recommendations received from 44 countries, the State initially “rejected”\n50 recommendations and did not take a position on the other recommendations. In 2014,\nbefore the second cycle, the State published its position on the remaining\n117 recommendations from the first cycle as an annex to its national report for the second\ncycle. The State “accepted 81, partially accepted 6, noted 15 and rejected 15”.20 In 2014, the\nState “accepted” 114 recommendations and “rejected” 153 of the 267 recommendations\nmade by 83 countries. In 2019, the State received a total of 266 recommendations from\n87 countries.21 Of those, it “accepted” 135 and “rejected” 131 recommendations. In 2024, the\nState received 294 recommendations from 86 countries and “accepted”\n143 recommendations, “partially accepted” 7 and “rejected” 144.22"},{"id":"a-hrc-61-55-p0009","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"9","seq":10,"section":"IV. Monitoring and implementation of universal periodic review","text":"The Democratic People’s Republic of Korea has indicated its position on individual\nhuman rights issues through its national reports, statements made during the universal\nperiodic review and by “accepting”, “rejecting” or “partially accepting” recommendations\nand providing explanations. That itself provides information to the international community\non what specific human rights issues the State is prioritizing. While it is regrettable that the\nState has “rejected” many recommendations relevant to serious human rights violations, it is\nimportant for the international community to continue to raise certain human rights concerns,\neven if they do not enjoy support from the State.23"},{"id":"a-hrc-61-55-p0010","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"10","seq":11,"section":"IV. Monitoring and implementation of universal periodic review","text":"There are challenges in monitoring the implementation of recommendations made\nduring the universal periodic review. Firstly, when the State lacks the political will to monitor\nand implement recommendations or to seek international cooperation, it is challenging for\nthe international community to assess progress. This results in repeated recommendations in\nmultiple review cycles – in some cases because no progress has been made and in other cases\nbecause it is unclear whether the recommendations are being implemented. Secondly, some\nrecommendations supported in the context of the universal periodic review are too generic,\nmaking it difficult to objectively monitor their implementation. In this regard, the Special\nRapporteur has attempted to break down the recommendations supported by the Democratic\nPeople’s Republic of Korea and to propose measurable benchmarks and specific actions,\nusing human rights indicators,24 which the State can use to monitor and report on progress in\nimplementing the recommendations that they committed to implement. This approach can\nserve as a guide for other States and international organizations to track progress in a State’s\nimplementation of the supported recommendations. Thirdly, examining selected\nrecommendations indicates contradictions in the position of the Democratic People’s\nRepublic of Korea concerning specific rights. While general recommendations were\nsupported, more specific recommendations on the same rights or issues were in most cases\nnot supported for varying reasons. This underscores the importance of making specific and\nactionable recommendations to clarify their content and objective, as well as the\ncommitments that the State under review, in this case the Democratic People’s Republic of\nKorea, commits to undertake."},{"id":"a-hrc-61-55-p0011","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"11","seq":12,"section":"IV. Monitoring and implementation of universal periodic review","text":"To inform the present report, the Special Rapporteur made a call for submissions and\nreceived several submissions from civil society organizations, which have been reflected\nherein. 25 In section IV, the Special Rapporteur uses illustrative recommendations made\nduring the third and fourth cycles of the universal periodic review, focusing on four thematic\nissues (the right to life, the right to freedom of movement, the right to food and the right to\nwork) and one specific group (persons with disabilities). 26 The Special Rapporteur refers to\nthe tables of human rights indicators developed by the Office of the United Nations High\nCommissioner for Human Rights.27 The Special Rapporteur proposes that the Democratic\nPeople’s Republic of Korea integrate the indicators into its implementation efforts, prepare a\nmidterm report on the implementation of recommendations and include relevant data in its\nnational report for the fifth review cycle. The selected rights represent key human rights\nissues, both long-standing and more recently aggravated. Rights such as the right to life and\nthe right to freedom of movement are rights that normally do not enjoy support from the\nDemocratic People’s Republic of Korea. However, there are some areas where the\nGovernment is open to engagement in the areas of its supported recommendations. The right\nto food is a long-standing issue in which the State has consistently shown interest. The right\nto work has increasingly received attention from the international community, due to\nconcerns of forced labour. The rights of persons with disabilities are group rights that the\nState has been relatively open to discussing, offering an important opportunity to address\nequality and non-discrimination in the country."},{"id":"a-hrc-61-55-p0012","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"12","seq":13,"section":"A. Right to life","text":"To help to monitor progress towards the protection of the right to life guaranteed by\narticle 6 of the International Covenant on Civil and Political Rights, four key attributes can\nbe assessed: (a) no arbitrary deprivation of life; (b) no involuntary or enforced disappearances\nof individuals; (c) basic health and nutrition; and (d) safeguards in the application of the death\npenalty. In these areas, recommendations made to the Democratic People’s Republic of\nKorea during the third and fourth cycles of the universal periodic review were primarily\nfocused on health and nutrition and the application of the death penalty.\n1.        No arbitrary deprivation of life"},{"id":"a-hrc-61-55-p0013","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"13","seq":14,"section":"A. Right to life","text":"The Democratic People’s Republic of Korea received two recommendations related\nto the arbitrary deprivation of life during the third cycle of the universal periodic review and\ntwo recommendations during the fourth cycle. However, it did not support any of the\nrecommendations, including those on abolishing political prison camps and releasing all\npolitical prisoners."},{"id":"a-hrc-61-55-p0014","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"14","seq":15,"section":"A. Right to life","text":"According to the High Commissioner, several escapees reported that “they had\nwitnessed deaths in detention primarily as a result of torture and ill-treatment, overwork,\nmalnutrition and suicide”.28 In the context of the Democratic People’s Republic of Korea,\ntherefore, the conditions of detention are relevant to the arbitrary deprivation of life. During\nthe third cycle of the universal periodic review, the State supported the recommendation to\ngrant immediate, free and unimpeded access to international humanitarian organizations to\nprovide assistance to the most vulnerable groups, including prisoners. 29 The State’s support\nto that recommendation was significant, as it could be interpreted as meaning that it\nconsidered prisoners among the most vulnerable groups. However, the international\nhumanitarian organizations had to leave the country during the coronavirus disease\n(COVID-19) pandemic, owing to the related border restrictions, and there was no progress\nmade with the recommendation."},{"id":"a-hrc-61-55-p0015","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"15","seq":16,"section":"A. Right to life","text":"Notably, during the fourth cycle of the universal periodic review, the Democratic\nPeople’s Republic of Korea supported two recommendations related to conditions of\ndetention for the first time, to ensure that conditions in detention facilities are in compliance\nwith its obligations for the humane treatment of persons and to guarantee appropriate\nconditions of detention for minors, ensuring that detention conditions are in line with\ninternational standards.30"},{"id":"a-hrc-61-55-p0016","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"16","seq":17,"section":"A. Right to life","text":"The High Commissioner reported nominal improvements in the treatment of detainees\nover the past 10 years. 31 During the fourth cycle of the universal periodic review, the\nDemocratic People’s Republic of Korea stated that a newly enacted law on the treatment of\ninmates in reform institutions in 2022 guaranteed the legal rights of inmates and ensured\naccess to a library, adequate hygiene and physical exercises based on the United Nations\nStandard Minimum Rules for the Treatment of Prisoners (the Nelson Mandela Rules).32 The\nSpecial Rapporteur takes note of such efforts and reiterates that the importance of the\nenvironmental conditions of detention, such as light, ventilation, temperature, sanitation,\nnutrition, drinking water, access to open air and physical exercise, personal hygiene,\nhealthcare and adequate personal space, should be respected.33 The delegation stated that the\nallegation of violence against inmates by law enforcement officials was utterly groundless,\nalthough it explained that sanctions were imposed, including confinement to their cell, if\ninmates broke the rules."},{"id":"a-hrc-61-55-p0017","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"17","seq":18,"section":"A. Right to life","text":"The Special Rapporteur proposes that the Democratic People’s Republic of Korea\nmonitor and report on the progress in the implementation of the two supported\nrecommendations and that the international community encourage the State to follow up by\nproviding data for the following indicators:\n(a)    Number and proportion of law enforcement officials formally investigated for\nphysical and non-physical abuse or crime;\n(b)    Number and proportion of formal investigations of law enforcement officials\nresulting in disciplinary action or prosecution;\n(c)    Number of female custodial and support staff trained in gender-sensitive and\nhuman rights standards (e.g. United Nations Rules for the Treatment of Women Prisoners\nand Non-custodial Measures for Women Offenders (the Bangkok Rules) per female inmate;\n(d)     Data on the adoption of regulations or official policies regarding the use of\nnon-invasive screening methods as an alternative in places of detention;\n(e)    Number and proportion of detained or imprisoned persons accommodated in\nfacilities that meet the legally stipulated standards for environmental conditions;\n(f)    Number of monitoring visits conducted by independent bodies, including the\nUnited Nations human rights mechanisms and the International Committee of the Red Cross,\nto places of detention during the period from November 2024 to the fifth cycle of the\nuniversal periodic review;\n(g)    Number and proportion of prisoners convicted of “anti-State crimes” who have\nbeen released during the reporting period and the number remaining in detention at the end\nof the period;\n(h)      Number of deaths in custody during the reporting period attributed to\nmalnutrition, communicable diseases and noncommunicable diseases.\n2.        Enforced or involuntary disappearances of individuals"},{"id":"a-hrc-61-55-p0018","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"18","seq":19,"section":"A. Right to life","text":"The Democratic People’s Republic of Korea received three recommendations related\nto enforced disappearances of individuals during the third cycle of the universal periodic\nreview and eight recommendations during the fourth cycle, however, it did not support any\nof them. Enforced or involuntary disappearances constitute a series of acts and omissions\nrepresenting a grave threat to life and other rights guaranteed by the Covenant. Enforced\ndisappearances and abductions in and perpetrated by the Democratic People’s Republic of\nKorea are a long-standing concern well documented by the United Nations. Approximately\n100,000 people from the Republic of Korea are estimated to have been kidnapped and\nrelocated from the Republic of Korea during the Korean war, and 19,409 prisoners of war of\n41,971 missing soldiers have not been repatriated, according to the Government of the\nRepublic of Korea. A total of 93,340 ethnic Korean people living in Japan and their Japanese\nspouses 34 “returned” to the Democratic People’s Republic of Korea on the basis of false\npromises of a better life. Hundreds of people from the Republic of Korea, Japan and other\nnations were also abducted and disappeared, mainly during the period between the 1960s and\nthe 1980s. The Government of the Republic of Korea officially recognizes 516 of its citizens\nas post-war abductees. Eleven people who were on the Korean Air Lines flight YS-11 that\nwas hijacked on 11 December 1969 have never been returned. Abductees from Japan also\nremain unaccounted for. Seven citizens of the Republic of Korea continue to be detained in\nthe Democratic People’s Republic of Korea."},{"id":"a-hrc-61-55-p0019","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"19","seq":20,"section":"A. Right to life","text":"While the Democratic People’s Republic of Korea did not support recommendations\non enforced disappearances, it supported recommendations on cooperation with the\ninternational community, including the recommendation to increase its engagement with the\ninternational community, particularly with United Nations bodies, human rights mechanisms\nand other stakeholders to further promote and protect human rights through constructive\ndialogue, consultation and cooperation.35"},{"id":"a-hrc-61-55-p0020","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"20","seq":21,"section":"A. Right to life","text":"One of the human rights mechanisms, the Working Group on Enforced or Involuntary\nDisappearances, has regularly raised concerns about enforced disappearance in and\nperpetrated by the Democratic People’s Republic of Korea. The Government has not sent\nsubstantive responses, and currently there are 477 outstanding cases, including abductions of\nforeign nationals.36 To monitor progress in increasing engagement with the human rights\nmechanisms, the Special Rapporteur suggests that the State provide data for the following\nindicators:\n(a)    Number of cases communicated by the Working Group on Enforced or\nInvoluntary Disappearances responded to by the State during the reporting period;\n(b)    Number of cases clarified with relevant Member States.\n3.        Health and nutrition"},{"id":"a-hrc-61-55-p0021","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"21","seq":22,"section":"A. Right to life","text":"The Democratic People’s Republic of Korea supported all 12 recommendations in the\narea of health and nutrition during the third cycle of the universal periodic review and\nsupported all 24 recommendations during the fourth cycle. The high number of\nrecommendations made by the States demonstrates the significant interest of the international\ncommunity in the right to health and right to food in the State. It also indicates the openness\nof the State to engage on these rights."},{"id":"a-hrc-61-55-p0022","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"22","seq":23,"section":"A. Right to life","text":"During the third cycle of the universal periodic review, the State supported a\nrecommendation on reducing infant mortality and malnutrition rates. 37 The last time that the\ncountry published infant and maternal mortality rates was in 2017, 38 supported by the\nUnited Nations Children’s Fund (UNICEF). Not publishing such data since then is itself a\nserious concern. The estimated infant mortality ratio generated by the United Nations in 2019\nwas 14.299 per 1,000 live births. Despite the support of the recommendation, the estimated\ninfant mortality rate in 2023 increased slightly (14.536).39 The maternal mortality ratio was\nestimated to be 67 per 100,000 live births in 2023, also slightly increasing, from 66 in 2020. 40"},{"id":"a-hrc-61-55-p0023","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"23","seq":24,"section":"A. Right to life","text":"During the fourth cycle, the Democratic People’s Republic of Korea again supported\na recommendation in this area, to reduce the preventable infant and maternal mortality ratios\nto less than half of the present level within the next four years. 41"},{"id":"a-hrc-61-55-p0024","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"24","seq":25,"section":"A. Right to life","text":"This is a measurable and outcome-oriented recommendation. When reporting for the\nnext cycle, the State is encouraged to collect and report on progress made with specific data\non infant and maternal mortality ratios disaggregated by province and by location in urban\nor rural area. To facilitate the data collection, the Special Rapporteur recommends that the\nState carry out a nationwide survey on social rights with the support of United Nations\nagencies. In its national report for the fourth cycle of the universal periodic review, the State\nreported that it had set the target of “reducing the mortality of newborns for 1,000 live births\nto less than 6 and that of under-5 children to less than 12”.42 These types of measurable\nrecommendations underline the necessity for the State first to generate the current data as a\nbaseline, then to identify the target and a road map for implementing the recommendation.\nThese measurable recommendations also demonstrate the importance of the other States\nmaking specific recommendations so that clear targets can be identified and monitored."},{"id":"a-hrc-61-55-p0025","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"25","seq":26,"section":"A. Right to life","text":"In this regard, the Special Rapporteur proposes that the Democratic People’s Republic\nof Korea monitor and report on the process of the two supported recommendations through\nindicators including the following:\n(a)    Proportion of children under 5 years of age and pregnant and lactating women\nwho regularly receive nutrition supplement programmes, such as school meals and fortified\nblended foods;\n(b)   Proportion of births attended by skilled health personnel (see also Sustainable\nDevelopment Goal indicator 3.1.2);\n(c)     Maternal mortality ratio (see also Sustainable Development Goal target 3.1);\n(d)   Proportion of health facilities that have available safe drinking water and\nadequate sanitation and hygiene (see also Sustainable Development Goal indicators 6.1.1 and\n6.2.1).\n4.        Death penalty"},{"id":"a-hrc-61-55-p0026","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"26","seq":27,"section":"A. Right to life","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea did not support any of the 13 recommendations on the death penalty.\nDuring the fourth cycle, however, the State supported two of the recommendations related to\nthe death penalty for the first time, while it did not support 11 other recommendations,\nincluding on a moratorium on application of the death penalty. It supported the\nrecommendations to reduce the number of crimes punishable by the death penalty and to\nrestrict the death penalty to crimes that meet the threshold of most serious crimes under\ninternational law.43"},{"id":"a-hrc-61-55-p0027","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"27","seq":28,"section":"A. Right to life","text":"During the review by the Human Rights Committee of the State’s initial report\nsubmitted pursuant to the International Covenant on Civil and Political Rights, in 2001, the\nCommittee welcomed the reduction of the number of criminal offences punishable by the\ndeath penalty from 33 to 5, as well as the readiness further to review the issue of capital\npunishment with a view to its abolition in the Democratic People’s Republic of Korea.44 It is\nregrettable that the State has increased the number of criminal offences punishable by death,\ndemonstrating regression in the implementation of its commitment to protect the right to life.\nSince 2020, the State has also enacted several laws imposing the death penalty for several\ncrimes. The Criminal Law, as amended on 17 May 2022, enumerates 11 crimes carrying the\ndeath penalty: plotting to overthrow the State (art. 61), acts of terrorism (art. 62), treason\nagainst the State (art.63), insulting the dignity of the Republic (art. 64), sabotage (art. 65),\nacts of hostility to a foreigner (art. 69), treason against the nation (art. 70), illegal harvesting\nof opium poppy (art. 234), illegal manufacturing of narcotics (art. 235), smuggling or selling\nnarcotic drugs (art. 237) and deliberate brutal murder (art. 305). On 24 December 2023, the\nState further amended its Criminal Law to add death penalty provisions for five additional\noffences: anti-State propaganda or agitation (art. 66), illegal manufacturing of weapons or\nammunition (art. 80), illegal use of weapons or ammunition (art. 81), illegal manufacturing\nor storage of explosives (art. 117) and illegal use or transfer of explosives (art. 118). The\nHuman Rights Committee has clarified that States Parties may not transform into a capital\noffence any offence that, upon ratification of the Covenant or at any time thereafter, did not\nentail the death penalty.45 Therefore, adding crimes that are punishable by death after the\nratification of the Covenant is a violation of a State’s international commitments. There are\nalso reports that executions have been carried out for death penally cases applied under the\nnew articles of the Criminal Law.46"},{"id":"a-hrc-61-55-p0028","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"28","seq":29,"section":"A. Right to life","text":"In its national report for the fourth cycle of the universal periodic review, the\nDemocratic People’s Republic of Korea indicated that only those who gravely violated a\nperson’s right to life out of extremely mean motive are committed to death penalty. 47 Some\nof the crimes punishable by the death penalty do not meet the criteria of “the most serious\ncrimes” for which the death penalty may be applied under article 6 (2) of the Covenant. The\nterm “the most serious crimes” must be read restrictively and applied only to crimes of\nextreme gravity, involving intentional killing.48 The Special Rapporteur received information\nthat public execution has also been reintroduced. During the dialogue with the State during\nthe fourth cycle, the Government admitted that public execution is used in exceptional cases 49\nand did not support recommendations to abolish public executions. 50 The Special Rapporteur\nwould like to remind the Democratic People’s Republic of Korea that public executions are\ncontrary to article 7 of the Covenant, which prohibits torture or cruel, inhuman or degrading\ntreatment or punishment.51"},{"id":"a-hrc-61-55-p0029","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"29","seq":30,"section":"A. Right to life","text":"In this context, to implement the two supported recommendations, the Special\nRapporteur recommends that the Democratic People’s Republic of Korea monitor and report\non indicators including the following:\n(a)    Number of criminal offences removed from crimes punishable by the death\npenalty, in particular those criminal offences that were not punishable by the death penalty\nat the time of ratification of the International Covenant on Civil and Political Rights, in 1981,\nand that do not meet the criteria of “the most serious crimes” involving intentional killing;\n(b)    Number of convicted persons on death row, disaggregated by factors including\nage, sex and the crimes for which they were convicted;\n(c)    Number and method of executions under the death penalty disaggregated by\nage, gender and region."},{"id":"a-hrc-61-55-p0030","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"30","seq":31,"section":"B. Right to freedom of movement","text":"To monitor progress made towards the protection of the right to freedom of\nmovement, four key elements should be monitored, as set out in article 12 of the International\nCovenant on Civil and Political Rights: (a) freedom of movement within the territory;\n(b) freedom to return to the country; (c) freedom to choose one’s residence; and (d) freedom\nto leave the country."},{"id":"a-hrc-61-55-p0031","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"31","seq":32,"section":"B. Right to freedom of movement","text":"During the third and fourth cycles, a few recommendations, primarily regarding\nfreedom of movement within the territory and freedom to leave the country were made.\n1.        Freedom of movement within the territory and freedom to leave the country"},{"id":"a-hrc-61-55-p0032","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"32","seq":33,"section":"B. Right to freedom of movement","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported three recommendations on freedom of movement both within\nthe territory and to leave the country. Despite its support for those recommendations, the\nState further restricted movement within the country through the use of travel permits,\nhindering people’s informal commercial activities, and further strengthened its international\nborder control by expanding fences and guard posts, particularly since the COVID-19\npandemic. The practice of requiring a travel permit, administrative permission and an exit\nvisa restricts a person’s ability to freely move, which is in contravention of article 12 of the\nCovenant.52"},{"id":"a-hrc-61-55-p0033","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"33","seq":34,"section":"B. Right to freedom of movement","text":"Despite the retrogressive action between the third and fourth cycles of the universal\nperiodic review, the Democratic People’s Republic of Korea supported a similar\nrecommendation during the fourth cycle, to ensure freedom of movement for all individuals. 53\nThe State did not support, however, more specific recommendations, including to amend the\ncriminal code and other legislation to remove the requirement for permission to travel abroad\nand within the country. 54 This demonstrates the importance of providing specific\nrecommendations, as they clarify the Government’s position on the right and identify where\nthe obstacles for implementation lie."},{"id":"a-hrc-61-55-p0034","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"34","seq":35,"section":"B. Right to freedom of movement","text":"To monitor progress and implementation of the supported recommendation, the\nSpecial Rapporteur recommends that the Democratic People’s Republic of Korea provide\ninformation on the binding order issued to the Ministry of State Security and the Ministry of\nPeople’s Security that no person is to be arrested or detained solely for attempting to leave\nthe country for contacting relatives abroad. She also recommend that the State monitor and\nreport on indicators including the following:\n(a)     Number of prisoners who have been forcibly repatriated from China and other\ncountries and who have been detained as prisoners under charges of committing crimes\nagainst the State;\n(b)    Number of criminal offences for unauthorized movement inside the country\nand unauthorized exits that have been removed from the Criminal Law;\n(c)     Number of travel permits applied, approved and rejected and the reasons\ntherefor, disaggregated by the region, gender and age of the requestor.\n2.        Freedom to choose one’s residence"},{"id":"a-hrc-61-55-p0035","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"35","seq":36,"section":"B. Right to freedom of movement","text":"There were no recommendations made on the freedom to choose one’s residence\nduring the third or fourth cycles of the universal periodic review. People in the Democratic\nPeople’s Republic of Korea are not allowed to freely choose their place of residence. Forced\nrelocation of families to rural areas is used as a coercive political tool for punishing those\nwho are against the leadership. Freedom to choose one’s residence is an important part of the\nright of freedom of movement and needs to be addressed.\n3.        Freedom to return to the country"},{"id":"a-hrc-61-55-p0036","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"36","seq":37,"section":"B. Right to freedom of movement","text":"There were no recommendations made regarding the freedom to return to the country\nduring the third or fourth cycles of the universal periodic review. In the Democratic People’s\nRepublic of Korea, those who leave the country without authorization can be considered\ntraitors and face severe punishment upon return. Their families are often subjected to stricter\nsurveillance or to discriminatory treatment. As a result, those who escaped the country are\nnot only unable to return to the country, but also unable to communicate with their family\nmembers remaining in the State. This has resulted in the second cycle of separated families,\nin addition to the families separated by the Korean war in 1950. It is important that\nrecommendations on freedom to return to the country without repercussions are also\nsuggested to highlight the issue of separated families. The reunification of families should\ncontinue to be placed at the top of the agenda in international forums."},{"id":"a-hrc-61-55-p0037","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"37","seq":38,"section":"C. Right to food","text":"To monitor progress towards the realization of the right to food, the following\nattributes could be monitored: (a) nutrition; (b) food availability; and (c) food accessibility.\nArticle 11 of the International Covenant on Economic, Social and Cultural Rights recognizes\nthe right to an adequate standard of living, including adequate food, clothing and housing,\nand to the continual improvement of living conditions."},{"id":"a-hrc-61-55-p0038","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"38","seq":39,"section":"C. Right to food","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported 15 recommendations on the right to food (9 on food, 55 2 on\nnutrition56 and 5 on cooperation with the international organizations on food and nutrition 57)\nand noted 4. During the fourth cycle, similarly, the State supported 15 recommendations\n(8 on food, 58 2 on nutrition 59 and 4 on international cooperation, including to strengthen\ncooperation with international organizations in the fields of health, education, nutrition and\nfood security,60) and noted 4.61 The recommendations on international cooperation included\nproviding United Nations agencies with unhindered access to vulnerable populations, 62\nhowever, they have not yet been able to return to the country.\n1.        Nutrition"},{"id":"a-hrc-61-55-p0039","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"39","seq":40,"section":"C. Right to food","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported recommendations on specific measures and actions to further\nreduce the infant and child mortality and malnutrition and on measures to combat food\ninsecurity and malnutrition. 63 The implementation of Sustainable Development Goal\ntarget 3.2, on the mortality rate among children under 5 years of age, which is one of the\nstrongest indicators to measure people’s access to health services and nutrition, has not\nimproved.64 The Government reported on the reduction in the prevalence of malnutrition\namong children under 5 years of age as a “remarkable improvement”.65 The national average\nfor stunting, 66 as estimated by the United Nations, indeed rapidly decreased, from\n25.7 per cent in 2021 to 16.6 per cent in 2024,67 which is a positive step. During the fourth\ncycle, the State supported recommendations on children’s nutrition and disease management,\nincluding to continue taking measures to improve the management of children’s nutrition and\ndiseases.68 The Government also reported on its efforts to improve people’s diet by increasing\nthe variety of foods.69 The improvement in the rate of stunting and the Government’s efforts\nto increase the variety of food is a positive sign for implementing the supported\nrecommendations on children’s nutrition. The Special Rapporteur encourages the State to\nmonitor and report on developments in this area."},{"id":"a-hrc-61-55-p0040","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"40","seq":41,"section":"C. Right to food","text":"The Democratic People’s Republic of Korea should organize the next national survey\nfocused on social rights and monitor and report on indicators including the following:\n(a)   Proportion of the targeted population covered by nutrition supplement\nprogrammes;\n(b)     Number of people provided with food and medical assistance by international\norganizations;\n(c)    Proportion of the population that was brought above the minimum level of\ndietary energy consumption during the reporting period;\n(d)   Preventable deaths of newborns and children under 5 years of age (see also\nSustainable Development Goal target 3.2).\n2.        Food availability"},{"id":"a-hrc-61-55-p0041","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"41","seq":42,"section":"C. Right to food","text":"During the third cycle of the universal periodic review, no recommendations were\nmade specifically on food availability. During the fourth cycle, the Democratic People’s\nRepublic of Korea supported a recommendation, to increase budget allocations to the\nagricultural sector and continue efforts to ensure sustained food security in the country. 70"},{"id":"a-hrc-61-55-p0042","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"42","seq":43,"section":"C. Right to food","text":"The prevalence of undernourishment increased, from 34.3 per cent of the population\nin the period 2004–2006 to 45.5 per cent in the period 2020–2022, according to\nUnited Nations estimates.71 In its national report for the fourth cycle of the universal periodic\nreview, the Government reiterated its objective of becoming self-sufficient in food in the near\nfuture and highlighted its efforts to increase agricultural production. The progress is not clear\nyet and there has not been a positive report on achieving food security yet."},{"id":"a-hrc-61-55-p0043","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"43","seq":44,"section":"C. Right to food","text":"To implement the supported recommendations, the Special Rapporteur recommends\nthat the Democratic People’s Republic of Korea monitor and report on indicators including\nthe following:72\n(a)  Data on food insecurity, disaggregated by province, sex, wealth quintiles and\nmembership in vulnerable groups, such as persons with disabilities, older persons and\nprisoners;\n(b)     Share of public budget expenditure on strengthening domestic agricultural\nproduction;\n(c)   Agriculture orientation index 73 for government expenditures (see also\nSustainable Development Goal indicator 2.a.1);\n(d)   Average income of small-scale food producers by sex (see also Sustainable\nDevelopment Goal indicator 2.3.2);\n(e)    Proportion of per capita availability of major food items sourced through\ndomestic production, import and food aid.\n3.        Food accessibility"},{"id":"a-hrc-61-55-p0044","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"44","seq":45,"section":"C. Right to food","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported five recommendations on food accessibility, 74 and during the\nfourth cycle, it supported four recommendations on food accessibility, including to ensure\nthat access to food in the country is free from discrimination and that public distribution of\nfood covers persons in marginalized and vulnerable situations,75 and a recommendation to\nredouble efforts to ensure food.76"},{"id":"a-hrc-61-55-p0045","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"45","seq":46,"section":"C. Right to food","text":"Between the third and fourth cycles of the universal periodic review, the Government,\non the one hand, restricted people’s informal market activities, largely carried out by women,\nwhich has resulted in lost economic accessibility to food. The Government, on the other hand,\nhas strengthened the control of staple grains by centralizing their sales at the State-run shops.\nDespite the supported recommendations, the Government-led food distribution system\ncontinued to be discriminatory, and those who did not have money, particularly those in rural\nareas, persons with disabilities, people in detention facilities and women, struggled to gain\naccess to food."},{"id":"a-hrc-61-55-p0046","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"46","seq":47,"section":"C. Right to food","text":"The State committed itself to providing access to food free from discrimination and\nto ensuring food security. To monitor and implement the supported recommendations, the\nSpecial Rapporteur encourages the Democratic People’s Republic of Korea to monitor and\nreport on indicators including the following:\n(a)     Prevalence of undernourishment (see also Sustainable Development Goal\nindicator 2.1.1);\n(b)   Prevalence of stunting among children under five (see also Sustainable\nDevelopment Goal indicator 2.2.1);\n(c)     Share of household consumption of major food items for targeted population\ngroups met through publicly assisted programmes;\n(d)    Proportion of the population who can afford sufficient staple grains sold at the\nState-run shops, particularly in rural areas;\n(e)    Proportion of children under 5 years of age, pregnant and lactating women,\nolder persons, persons with disabilities and prisoners who have been provided with sufficient\nand adequate food by the Government;\n(f)    Proportion of prisoners who have received the minimum nutritional standard\nfor rations for every place of detention."},{"id":"a-hrc-61-55-p0047","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"47","seq":48,"section":"D. Right to work","text":"To monitor progress towards the realization of the right to work and related rights,\nfour attributes should be monitored: (a) access to decent and productive work; (b) just and\nsafe working conditions; (c) training, upgrading skills and professional development; and\n(d) protection from forced labour and unemployment. Under article 6 of the International\nCovenant on Economic, Social and Cultural Rights, States Parties recognize the right to work,\nwhich includes the right of everyone to the opportunity to gain his or her living by work\nwhich he or she freely chooses or accepts, and should take appropriate steps to safeguard this\nright."},{"id":"a-hrc-61-55-p0048","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"48","seq":49,"section":"D. Right to work","text":"During the third and fourth cycles of the universal periodic review, the State did not\nsupport the majority of recommendations related to the right to work. It did not support two\nstructural recommendations, to join the International Labour Organization and to ratify its\nconventions. It also did not support six recommendations related to the protection of forced\nlabour. However, during the fourth cycle, it indicated an openness to consider the possibility\nof joining the International Labour Organization, by its support of two relevant\nrecommendations.77\n1.        Access to decent and productive work"},{"id":"a-hrc-61-55-p0049","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"49","seq":50,"section":"D. Right to work","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported one recommendation on strengthening its legislation to amend\ndiscriminatory provisions against women, in particular on access to employment. 78 During\nthe fourth cycle, no similar recommendation was suggested by States. In the State, married\nwomen are exempt from State-assigned jobs, which enables them to engage in informal\nmarkets to earn a living. However, since the COVID-19 pandemic, women have not been\nable to make money in the further restricted markets and have been prevented from equally\nand fully participating in the formal labour system. The principle of equal access to decent\nand productive work should be applied to everyone, regardless of their family background,\nincluding women, persons with disabilities and farmers.\n2.        Just and safe working conditions"},{"id":"a-hrc-61-55-p0050","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"50","seq":51,"section":"D. Right to work","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea did not support a recommendation to end inadequately paid labour. 79\nDuring the fourth cycle, however, the State supported one recommendation concerning just\nand safe working conditions, to take appropriate legal measures to ensure that all workers,\nboth within and outside the country, have access to a legal framework that provides fair and\nsafe working conditions in accordance with international human rights standards. 80"},{"id":"a-hrc-61-55-p0051","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"51","seq":52,"section":"D. Right to work","text":"In the State, most of the State-assigned jobs do not pay salaries, rations or in-kind\nsupport. Even when renumeration is provided, it is usually insufficient to sustain a family. In\nOctober 2023, the Government increased workers’ salaries, however, even after the increase,\nsalaries remained insufficient, particularly with rising food prices. This is also related to the\ncontrol of grain sales, as the Government reportedly pays salaries through payment cards and\nobliges workers to purchase food only at State-owned grain shops."},{"id":"a-hrc-61-55-p0052","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"52","seq":53,"section":"D. Right to work","text":"On 29 May 2025, the State adopted the Labour Management Act and consolidated the\nrules of labour management system by which the State determines the labour needs and\nassigns all citizens to workplaces. The Act stipulates that institutions, enterprises and\norganizations that use mobilized labour are to guarantee conditions of work, living conditions\nand conditions of labour protection according to regulations, pay remuneration to their\nemployees based on work performance and guarantee medical treatment (arts 22 and 23).\nWhile improvement of labour conditions has not yet been reported, the State is encouraged\nto monitor and report on the implementation of such laws including through the following\nindicators:\n(a)    Proportion of employees who receive remuneration according to the pay scale,\nas provided for in articles 37 and 38 of the Labour Law, disaggregated by sex and age;\n(b)     Amendments to the system of State-assigned jobs whereby working people\nmay choose occupations in accordance with their wishes and talents, as provided for in\narticle 5 of the Labour Law.\n3.        Training, upgrading skills and professional development"},{"id":"a-hrc-61-55-p0053","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"53","seq":54,"section":"D. Right to work","text":"There have been no relevant recommendations suggested in this area. The Democratic\nPeople’s Republic of Korea reported that, to ensure that students received education suited\nto their characteristics and the economic and geographical features of the particular region,\nover 100 vocational schools had been newly established, in 2023, in 17 fields, such as\nelectronics, forestry and the garment industry.81 This is a positive development step, however,\nthe Special Rapporteur is concerned that students continue to receive educations suited to the\neconomic and geographical features of the particular region and not based on an individual’s\nfree choice. This could reinforce disparities and discrimination among the population based\non the regions in which they reside. The State is encouraged to report on how such vocational\ntraining contributes to an individual’s right to engage in work and to pursue a freely chosen\noccupation without discrimination.\n4.        Protection from forced labour and unemployment"},{"id":"a-hrc-61-55-p0054","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"54","seq":55,"section":"D. Right to work","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea did not support any recommendation on forced labour, but it supported\none recommendation on child labour.82 More recommendations were suggested in this area\nduring the fourth cycle: 10 recommendations to end all instances of forced labour. None of\nthose recommendations were supported by the Government, which considered all allegations\nof forced labour to be “conspiratorial propaganda”83 and mentioned that child labour was\n“strictly forbidden” by the Constitution.84 To support its claim on forced labour and child\nlabour, the State is strongly recommended to report the details of how it has ensured free\nchoice and acceptance, the scale of remuneration, including of overseas workers, labour in\ndetention, non-military related labour during military conscription and the work mobilization\nof both adults and children."},{"id":"a-hrc-61-55-p0055","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"55","seq":56,"section":"E. Rights of persons with disabilities","text":"To monitor progress towards the fulfilment of the rights of persons with disabilities,\nmonitoring four elements thereof will be useful: (a) equality before the law and protection of\nperson; (b) direct or indirect discrimination by public and private actors nullifying or\nimpairing access to adequate standard of living, health or education; (c) direct or indirect\ndiscrimination by public and private actors nullifying or impairing equality of livelihood\nopportunities; (d) special measures, including for participation in decision-making. The\nDemocratic People’s Republic of Korea ratified the Convention on the Rights of Persons\nwith Disabilities in 2016."},{"id":"a-hrc-61-55-p0056","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"56","seq":57,"section":"E. Rights of persons with disabilities","text":"During the third cycle of the universal periodic review, the State supported a total of\n17 recommendations related to the rights of persons with disabilities. Four of them were\nstructural recommendations to incorporate the principles and requirements of the Convention\ninto its legislation and policies and to develop collaboration between the National Committee\nfor the Protection of Persons with Disabilities and the relevant national institutions of other\ncountries in the region. 85 During the fourth cycle, the State supported a total of\n27 recommendations related to the rights of persons with disabilities, a significantly higher\nnumber of recommendations, as well as a higher acceptance rate compared with other rights.\nIt supported six structural recommendations on continuing to improve legislation to ensure\nthe protection of the rights of socially vulnerable groups, including persons with disabilities, 86\nand two recommendations on deepening international exchanges and cooperation with the\nCommittee on the Rights of Persons with Disabilities. 87 It supported a further eight general\nrecommendations on continuing efforts to promote the rights of persons with disabilities. 88\nThe high acceptance rate during both cycles reflects the Government’s openness to work on\nissues on the rights of persons with disabilities. However, the Government noted a\nrecommendation calling for revising the legal terminology on persons with disabilities to\naddress discrimination.\n1.        Equality before the law and protection of person"},{"id":"a-hrc-61-55-p0057","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"57","seq":58,"section":"E. Rights of persons with disabilities","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported recommendations to protect the rights of persons with\ndisabilities 89 and expand the measures designed to uplift the well-being of persons with\ndisabilities.90 During the fourth cycle, the State supported two recommendations in this area\nincluding to further increase attention and input in support of specific groups including\npersons with disabilities, older persons and children.91"},{"id":"a-hrc-61-55-p0058","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"58","seq":59,"section":"E. Rights of persons with disabilities","text":"The Constitution and article 4 of the Labour Law mandate that “able-bodied citizens”\nparticipate in social labour according to their abilities as a contribution to the State. Persons\nwith disabilities tend to be considered not to be able to fully contribute to the State and face\nstigma and discrimination."},{"id":"a-hrc-61-55-p0059","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"59","seq":60,"section":"E. Rights of persons with disabilities","text":"To monitor and implement the supported recommendations, the Special Rapporteur\nencourages the Democratic People’s Republic of Korea to carry out and report on indicators\nincluding the following:\n(a)    Number of close consultations conducted with persons with disabilities, and\nthe proportion of them involved in consultation, including persons with intellectual and/or\npsychosocial disabilities and persons of short stature, in all stages of the design,\nimplementation and monitoring of disability-related laws and policies;92\n(b)    Number of complaints received on cases of direct and indirect discrimination\nagainst persons with disabilities and the number of complaints investigated and adjudicated.\n2.        Access to adequate standards of living, health and education"},{"id":"a-hrc-61-55-p0060","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"60","seq":61,"section":"E. Rights of persons with disabilities","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported all recommendations in this area, including on ensuring the\naccessibility of essential services for all, including those with disabilities, 93 on well-being,94\non education, food and health95 and on access to housing.96 During the fourth cycle, the State\nsupported 10 recommendations that related specifically to this area. They included three on\nenhancing access to healthcare and nutrition,97 including to guarantee access to appropriate\nand affordable healthcare, particularly for children, persons with disabilities, women and\nprisoners, especially in rural areas, and to enhance access to free and quality basic education\nand to address malnutrition, particularly among marginalized groups such as women,\nchildren and persons with disabilities, four on enhancing access to quality education,98 and\none on enhancing the provision of government facilities and services for persons with\ndisabilities, to continue to enhance the provision of government facilities and services for\nchildren, older persons and persons with disabilities. 99"},{"id":"a-hrc-61-55-p0061","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"61","seq":62,"section":"E. Rights of persons with disabilities","text":"In the State, the forced relocation of persons with certain disabilities by the State to\nremote areas and the institutionalization of persons with intellectual disabilities continue to\nbe reported. Most of infrastructure, in particular in remote areas, is not accessible for persons\nwith disabilities. There are a limited number of specialized schools, but they are focused on\nproviding vocational training."},{"id":"a-hrc-61-55-p0062","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"62","seq":63,"section":"E. Rights of persons with disabilities","text":"To monitor and implement the supported recommendations, the Special Rapporteur\nencourages the Democratic People’s Republic of Korea to monitor and report on indicators\nincluding the following:\n(a)     Proportion of public buildings with facilities for persons with physical\ndisabilities;\n(b)    Proportion of health facilities that have a core set of relevant essential\nmedicines available and affordable on a sustainable basis (see also Sustainable Development\nGoal indicator 3.b.3);\n(c)     Proportion of persons with disabilities with access to assistive devices;\n(d)     Number of government-funded programmes covering medical treatment,\ntherapy, assistive devices and rehabilitation services for persons with disabilities and the\nproportion of coverage."},{"id":"a-hrc-61-55-p0063","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"63","seq":64,"section":"E. Rights of persons with disabilities","text":"Regarding access to quality education for children with disabilities, the Ministry of\nEducation launched pilot programmes, which is a positive step. Building on the pilot\nprogrammes, the Special Rapporteur encourages the State to report on indicators including\nthe following:\n(a)     Gross enrolment ratio for secondary and higher education among persons with\ndisabilities;\n(b)    Number of inclusive education pilot classrooms, including for children with\nintellectual and psychosocial disabilities;\n(c)     Number of training programmes on inclusive education for teachers;\n(d)    Number of nationwide inclusive awareness-raising campaigns, including on\nthe available welfare and health services for persons and children with disabilities.\n3.     Equality of livelihood opportunities"},{"id":"a-hrc-61-55-p0064","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"64","seq":65,"section":"E. Rights of persons with disabilities","text":"During the third and fourth cycles of the universal periodic review, there were no\nrecommendations directly addressing this issue. This is concerning, as persons with\ndisabilities are assigned to special “light labour” workplaces on the basis of their level of\ndisability and capacity, which does not provide them with a choice of livelihood\nopportunities. This system prevents integration and further strengthens stigmatization.\n4.     Special measures, including for participation in decision-making"},{"id":"a-hrc-61-55-p0065","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"65","seq":66,"section":"E. Rights of persons with disabilities","text":"During the third cycle of the universal periodic review, the Democratic People’s\nRepublic of Korea supported two recommendations in this area, to enable the inclusion of\npersons with disabilities in devising and implementing strategies to mitigate climate\nchange100 and to adopt measures to allow for their wider participation in society. 101 During\nthe fourth cycle, it supported four recommendations on participation in public activities,\nincluding to continue to take measures to provide persons with disabilities with an\nenvironment and conditions conducive to their participation in public activities,102 and two\nrecommendations to support mobility, including to guarantee the social inclusion of persons\nwith disabilities by providing adequate assistive or mobility devices and ensuring\naccessibility to all necessary services.103"},{"id":"a-hrc-61-55-p0066","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"66","seq":67,"section":"E. Rights of persons with disabilities","text":"The Committee on the Rights of Persons with Disabilities expressed its concern that\nthere is no information on persons with disabilities who hold decision-making positions or\npublic office.104 There is also no information that meaningful consultations are held with the\nrepresentatives of the diversity of persons with disabilities, including intellectual and/or\npsychosocial disabilities, in making decisions on issues relevant to persons with disabilities."},{"id":"a-hrc-61-55-p0067","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"67","seq":68,"section":"E. Rights of persons with disabilities","text":"In order to implement the supported recommendations, the Democratic People’s\nRepublic of Korea is encouraged to monitor and report on indicators including the following:\n(a)    Number and proportion of persons with disabilities with access to positive\naction or preferential treatment measures to facilitate their participation in public activities,\nsuch as financial assistance, mobility assistance and training;\n(b)    Number and proportion of community-based services and accessible public\ntransport passes that remove permit-based barriers to local movement."},{"id":"a-hrc-61-55-p0068","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"68","seq":69,"section":"V. Conclusion and recommendations","text":"By the nature of the universal periodic review, as well as the principles of\ninternational human rights law, the State has the primary responsibility to implement\nthe recommendations emanating from the universal periodic review. All States are\naccountable for progress or lack thereof in implementing those recommendations.\nThere are several human rights areas that the Democratic People’s Republic of Korea\nhas committed to improving by supporting the related recommendations. For instance,\nthe State could review the application of the death penalty and report on the progress\nto reduce the number of crimes punishable by death. It can also conduct a thorough\nreview of what constitutes crimes against State, including cases involving individuals\nforcibly repatriated from third countries, and release prisoners charged with crimes\nagainst the State in a phased manner."},{"id":"a-hrc-61-55-p0069","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"69","seq":70,"section":"V. Conclusion and recommendations","text":"The United Nations, and particularly the United Nations country team and\nagencies operating in the State, can play a key role in assisting in the implementation of\nthe recommendations, through capacity-building, technical assistance and material\nsupport, in consultation with the Government. For example, the Government is\nencouraged to further work towards improving the treatment of detainees and the\nconditions of detention, including through technical assistance from the Office of\nUnited Nations High Commissioner for Human Rights and reports thereon. Despite\nefforts made by the Government on agriculture, food production and distribution,\npeople continue to face extreme difficulties in access to nutritious food. This can be an\narea where the United Nations country team can work together with the State, including\nthrough supplemental nutrition and medical assistance programmes, as well as the\nprovision of technical assistance on agricultural production and equal distribution\npractices. Many of the indicators related to the right to food and health are also\nreflected in the Sustainable Development Goals that the Democratic People’s Republic\nof Korea has committed to implement. The State can also apply for financial and\ntechnical assistance through Voluntary Fund for Financial and Technical Assistance in\nthe Implementation of the Universal Periodic Review. 105 The Special Rapporteur\nrecommends that the Democratic People’s Republic of Korea immediately facilitate the\nreturn of the international staff of United Nations agencies to the country and provide\naccess to the country. The United Nations and other actors are encouraged to use the\nuniversal periodic review recommendations in developing their strategic planning\nframework for sustainable development and their country programmes. United Nations\nagencies and programmes must ensure that human rights are central to humanitarian\nand development cooperation programmes in the Democratic People’s Republic of\nKorea."},{"id":"a-hrc-61-55-p0070","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":"70","seq":71,"section":"V. Conclusion and recommendations","text":"The Democratic People’s Republic of Korea has accepted only one visit from a\nspecial procedure mandate holder, namely the Special Rapporteur on the rights of\npersons with disabilities in 2017. The Committee on the Rights of Persons with\nDisabilities provided several recommendations in 2025, yet no significant progress in\nthe area of the rights of persons with disabilities has been reported. In the absence of\nindependent national human rights institutions or civil society, no independent\nmonitoring has taken place since 2017. The Special Rapporteur strongly encourages the\nState to demonstrate a good gesture of engagement by extending an invitation to experts\nfrom United Nations human rights bodies, ideally at least one mandate holder per year,\nto monitor its human rights issues on a regular basis. On efforts to improve human\nrights and implement recommendations supported during the universal periodic\nreview, the Special Rapporteur recommends that the Democratic People’s Republic of\nKorea use the human rights indicators suggested in the present report to track its\nprogress and report on the development through a midterm report and in its national\nreport for the fifth cycle of the universal periodic review. Selected recommendations\nand indicators are compiled in the annex to the present report. The Special Rapporteur\nrecommends that other States take any opportunity to follow up on the universal\nperiodic review recommendations in their engagement with the Democratic People’s\nRepublic of Korea, including through sharing technical support and lessons learned.\nShe also encourages States to make specific recommendations in the context of the\nuniversal periodic review and to continue to monitor progress in those areas."},{"id":"a-hrc-61-55-u0072","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":72,"section":"Annex","text":"No arbitrary deprivation of life\n130.68    Ensure that conditions in detention facilities are in   Number and proportion of law enforcement officials\ncompliance with its obligations for the humane          formally investigated for physical and non-physical\ntreatment of persons.                                   abuse or crime.\nNumber and proportion of formal investigations of\nlaw enforcement officials resulting in disciplinary\naction or prosecution.\nNumber of female custodial and support staff trained\nin gender-sensitive and human rights standards (e.g.\n“United Nations Rules for the Treatment of Women\nPrisoners and Non-custodial Measures for Women\nOffenders (the Bangkok Rules”) per female inmates.\n130.69    Guarantee appropriate conditions of detention for      Data on the adoption of regulation or official policies\nminors, ensuring that detention conditions are in line regarding the use of non-invasive screening methods\nwith international standards.                          as an alternative in places of detention.\nNumber and proportion of detained or imprisoned\npersons accommodated in facilities that meet the\nlegally stipulated standards for environmental\nconditions.\nNumber of monitoring visits conducted by\nindependent bodies, including the United Nations\nhuman rights mechanisms and the International\nCommittee of the Red Cross, to places of detention\nduring the period from November 2024 to the fifth\ncycle of the universal periodic review.\nNumber and proportion of prisoners convicted of\n“anti-State crimes” who have been released during\nthe reporting period, and the number remaining in\ndetention at the end of the period.\nNumber of deaths in custody during the reporting\nperiod attributed to malnutrition, communicable\ndiseases, and non-communicable diseases.\nEnforced or Involuntary Disappearances of\nindividuals\n130.30    Increase its engagement with the international          Number of cases communicated by the Working\ncommunity, particularly with United Nations bodies,     Group on Enforced or Involuntary Disappearances\nhuman rights mechanisms and other stakeholders to       responded to by the State during the reporting\nfurther promote and protect human rights through        period.\nconstructive dialogue, consultation and cooperation.\nNumber of cases clarified with relevant Member\nStates.\nHealth and nutrition\n130.130   Reduce the preventable infant and maternal mortality Proportion of children under 5 years of age, and\nratios to less than half of the present level within the pregnant and lactating women who regularly receive\nnext four years.                                         nutrition supplement programmes such as school\nmeals and fortified blended foods.","unnumbered":true},{"id":"a-hrc-61-55-u0073","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":73,"section":"Annex","text":"Proportion of births attended by skilled health\npersonnel (see also Sustainable Development Goal\nindicator 3.1.2).\nMaternal mortality ratio (see also Sustainable\nDevelopment Goal target 3.1).\nProportion of health facilities that have available safe\ndrinking water and adequate sanitation and hygiene\n(see also Sustainable Development Goal indicators\n6.1.1 and 6.2.1).\nDeath penalty\n130.65    Reduce the number of crimes punishable by the          Number of criminal offences removed from crimes\ndeath penalty.                                         punishable by the death penalty, in particular those\ncriminal offences that were not punishable by the\ndeath penalty at the time of ratification of the\nInternational Covenant on Civil and Political Rights\nin 1981 and that do not meet the criteria of “the most\nserious crimes” involving intentional killing.\n130.66    Restrict the death penalty to crimes that meet the     Number of convicted persons on death row\nthreshold of most serious crimes under international   disaggregated by factors including age, sex and the\nlaw.                                                   crimes for which they were convicted.\nNumber and methods of executions under the death\npenalty disaggregated by age, gender and region.","unnumbered":true},{"id":"a-hrc-61-55-u0074","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":74,"section":"Annex","text":"Freedom of movement within the territory and to\nleave the country\n130.85    Ensure freedom of movement for all individuals.        Number of prisoners who have been forcibly\nrepatriated from China and other countries and who\nhave been detained as prisoners under charges of\ncommitting crimes against the State.\nNumber of criminal offences for unauthorized\nmovement inside the country and unauthorized exits\nthat have been removed from the Criminal Law.\nNumber of travel permits applied, approved and\nrejected and the reasons therefor, disaggregated by\nthe regions, gender and age of the requestor.\nNutrition\n130.118   Continue taking measures to improve the                Proportion of the targeted population covered by\nmanagement of children’s nutrition and diseases.       nutrition supplement programmes.\nNumber of people provided with food and medical\nassistance by international organizations.\nProportion of the population that was brought above\nthe minimum level of dietary energy consumption\nduring the reporting period.\n130.40    Strengthen cooperation with international              Preventable deaths of newborns and children under 5\norganizations in the fields of health, education,      years of age (see also Sustainable Development Goal\nnutrition and food security.                           target 3.2).","unnumbered":true},{"id":"a-hrc-61-55-u0075","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":75,"section":"Annex","text":"Food availability\n130.108   Increase budget allocations to the agricultural sector Data on food insecurity disaggregated by provinces,\nand continue efforts to ensure sustained food security sex, wealth quintiles and membership in vulnerable\nin the country.                                        groups such as persons with disabilities, older\npersons and prisoners.\nShare of public budget expenditure on strengthening\ndomestic agricultural production.\nAgriculture orientation index for government\nexpenditures (see also Sustainable Development\nGoal indicator 2.a.1).\nAverage income of small-scale food producers by\nsex (see also Sustainable Development Goal\nindicator 2.3.2).\nProportion of per capita availability of major food\nitems sourced through domestic production, import\nand food aid.\nFood accessibility\n130.110   Ensure that access to food in the country is free from Prevalence of undernourishment (see also\ndiscrimination and that public distribution of food    Sustainable Development Goal indicator 2.1.1).\ncovers persons in marginalized and vulnerable\nPrevalence of stunting among children under five\nsituations.\n(see also Sustainable Development Goal Indicator\n2.2.1).\nShare of household consumption of major food items\nfor targeted population groups met through publicly\nassisted programmes.\nProportion of the population who can afford\nsufficient staple grains sold at the State-run shops\nparticularly in rural areas.\nProportion of children under 5 years of age, pregnant\nand lactating women, older persons, persons with\ndisabilities and prisoners who have been provided\nwith sufficient and adequate food by the\nGovernment.\nProportion of prisoners who have received the\nminimum nutritional standards for rations for every\nplace of detention.","unnumbered":true},{"id":"a-hrc-61-55-u0076","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":76,"section":"Annex","text":"Just and safe working conditions\n130.92    Take appropriate legal measures to ensure that all    Proportion of employees who receive remuneration\nworkers, both within and outside the country, have    according to the pay scale as provided for in articles\naccess to a legal framework that provides fair and    37 and 38 of the Labour Law disaggregated by sex\nsafe working conditions in accordance with            and age.\ninternational human rights standards.\nAmendments to the system of State-assigned jobs\nwhereby “working people may choose occupations\nin accordance with their wishes and talents,” as\nprovided for in article 5 of the Labour Law.","unnumbered":true},{"id":"a-hrc-61-55-u0077","rec_id":"recEDz6CHpXPbGwLs","symbol":"A/HRC/61/55","n":null,"seq":77,"section":"Annex","text":"Equality before the law and protection of person\n130.192   Further increase attention and input in support of        Number of close consultations conducted with\nspecific groups including persons with disabilities,      persons with disabilities, and the proportion of them\nolder persons and children.                               involved in consultation, including persons with\nintellectual and/or psychosocial disabilities and\npersons of short stature, in all stages of the design,\nimplementation and monitoring of disability-related\nlaws and policies.\nNumber of complaints received on cases of direct\nand indirect discrimination against persons with\ndisabilities and the number of complaints\ninvestigated and adjudicated.\nAccess to adequate standard of living, health and\neducation\n130.128   Guarantee access to appropriate and affordable         Proportion of public buildings with facilities for\nhealthcare, particularly for children, persons with    persons with physical disabilities.\ndisabilities, women and prisoners, especially in rural\nProportion of health facilities that have a core set of\nareas.\nrelevant essential medicines available and affordable\non a sustainable basis (see also Sustainable\nDevelopment Goal indicator 3.b.3).\nProportion of persons with disabilities with access to\nassistive devices.\nNumber of government-funded programmes\ncovering medical treatment, therapy, assistive\ndevices and rehabilitation services for persons with\ndisabilities and the proportion of coverage.\n130.191   Continue to enhance the provision of government\nfacilities and services for children, older persons and\npersons with disabilities.\n130.143   Enhance access to free and quality basic education,       Gross enrolment ratio for secondary and higher\nand address malnutrition, particularly among              education among persons with disabilities.\nmarginalized groups such as women, children and\nNumber of pilot classrooms of inclusive education,\npersons with disabilities.\nincluding for children with intellectual and\npsychosocial disabilities.\nNumber of training programmes on inclusive\neducation for teachers.\nNumber of nationwide inclusive awareness-raising\ncampaigns, including on the available welfare and\nhealth services for persons and children with\ndisabilities.\nSpecial measures, including for participation in\ndecision making\n130.194   Continue to take measures to provide persons with         Number and proportion of persons with disabilities\ndisabilities with an environment and conditions           accessing positive action or preferential treatment\nconducive to their participation in public activities.    measures to facilitate their participation in public\nactivities such as financial assistance, mobility\nassistance and training.\nNumber of proportion of community-based services,\naccessible public transport passes that remove\npermit-based barriers to local movement.","unnumbered":true}]});